insert into institution_policy_items (policy_item_id, category, item_kind, key, label, description, value_type, sort_order) values
  ('attr_support_summary', '支援制度属性', 'attribute', 'support_summary', '支援制度の所見', '公開情報・内部資料から読み取った、この機関の支援制度の特徴 (3行以内)。機関詳細ページの冒頭に出す。', 'text', 1105)
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, confirmed_at, evaluator) values
  ('inst_catalog_c030bad12839', 'attr_support_summary', 'established', '九州大学は「本学では、『大学発ベンチャー』の公式の認定は行っていない」とガイドライン脚注iで明言しており、称号も認定委員会も置かず、株式取得・施設貸付・名称使用をそれぞれ個別に申請・審査する方式をとる。エクイティは「成果活用事業者への支援に伴い取得する株式等の取扱に関する規程」と「個別研究プロジェクトに係る出資に関する規程」の2本立てで、いずれも学術研究・産学官連携本部長への申請→産学官連携戦略会議のもとの専門家会議→戦略会議審議→総長決定という同一経路を通る。支援期間は制度ごとに別で、ライセンス優遇は起業後5〜6年目まで（協議で延長可）、施設貸付は原則5年以内、対象は「起業時点で本学に在籍」が要件で退職・卒業後も継続するが、ベンチャーからの離職で対象から外れる。', '調査エージェントの所見。根拠は各項目のセルを参照。', 'inferred', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_support_summary', 'established', 'SU支援規程（2024年11月制定、2026年6月改正）が定義・支援条件・申請・支援内容・期間3年・変更届・年次報告・取消・免責までを1本で通しており、2026年4月適用の支援審査会要項で研究本部長を委員長とする審査会が加わって、審査会→研究推進機構運営会議→学長決定という経路が固まっている。対価設計が突出しており、株式等取扱規程が知財ライセンスや施設・設備提供の対価として株式・新株予約権・新株予約権付社債を取得する審査（発明審査委員会）と決裁（学長・役員会）、価額評価、インサイダー取引防止までを整えている。弱いのは人材と資金で、EIRは配置を進める段階、経営人材の紹介は記載がなく、独自VC・PoCファンドは構想段階、取消後の称号返付や表示削除の処理と規程の改廃主体も条文に書かれていない。', '調査エージェントの所見。根拠は各項目のセルを参照。', 'inferred', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_support_summary', 'established', '認定から取消しまでを1本の規則で通しており、認定5年（更新は初回5年・以降1年）、審査は未来創造イノベーション推進本部長が委員長の大学発ベンチャー審査委員会、決定は学長、退職等から起業まで3年以内という形が条文で読み取れる。年次の事業報告書提出と解散・破産等の報告、取消し時の称号記返付と事業使用禁止まで書き込まれている一方、代表者や資本構成の変更届は明文がない。
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, source_url, confirmed_at, evaluator) values
  ('inst_catalog_c030bad12839', 'pol_cert_update', 'established', '優遇措置は起業後5〜6年目まで、協議により延長可', '「大学発ベンチャーに対するライセンス等の対価の優遇措置に関するガイドライン」（平成31年3月1日実施）4．優遇措置を講じる期間に「起業後5〜6年目までの大学発ベンチャーに対して実施する。ただし、当該大学発ベンチャーの経営状況を十分に勘案して、協議により期間を延長することができる」と定める。認定制度自体を置かないため「認定期間」ではなく優遇措置の適用期間として規定され、更新審査という手続き名ではなく「協議」による延長。要件の再確認手続きは明文化されていない。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_title_restriction', 'established', '名称使用は許可制・誤認表示禁止・ロゴ写真は使用不可', 'e教員ハンドブック「産学連携」章の名称使用申請（p.96）。企業等から「九州大学の名称使用に関する許可申請書」を提出させ、関係教員への確認・精査のうえ許可の可否を決定する。基本的な考え方として、本学との共同研究等の成果である事実を表示するものであること、誇大又は事実と異なる表示により消費者や社会に誤認を与えないこと、本学と製造販売業者を明確に区分し本学が製造物責任法上の責任を負わない表示とすること、原則として製品そのものには表示できないこと、本学の施設・教職員の写真・画像・ロゴ等は使用しないことを列挙。認定を行わないため称号そのものは存在しない。', 'official', 'https://www.kyushu-u.ac.jp/f/43082/%E7%94%A3%E5%AD%A6%E9%80%A3%E6%90%BA.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_cancellation', 'established', '参画教職員の離職で優遇対象から除外・称号返付規定なし', '優遇措置ガイドライン脚注iiiに「起業時点で参画していた本学の教職員（又は学生）が当該大学発ベンチャーを離職した場合は、当該大学発ベンチャーを優遇措置の対象から除外する」と明記。称号を付与しないため称号返付・表示削除・営業利用停止の条項はない。施設側では国立大学法人九州大学不動産貸付細則第6条が一時使用許可の取消事由（秩序をみだし公益を害する恐れ、申請書の虚偽、許可書の使用条件違反）を定めるが、通常の貸付についての取消条項は置かれていない。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_report_change', 'unknown', null, '優遇措置ガイドライン、成果活用事業者株式等取扱規程（H26規程124）、個別研究プロジェクト出資規程（R6規程15）、不動産貸付細則（H16細則32）のいずれにも、支援対象企業側の年次報告・代表者や所在地や資本構成の変更届・解散時報告の定めは見当たらなかった。大学側では利益相反マネジメントとして職員に毎年度1回の定期自己申告（産学官連携活動の有無、連携先からの経済的利益、連携先のエクイティ保有状況）を課すが、これは職員の義務であり企業の報告義務ではない。ギャップファンドには終了後1か月以内の実施結果報告があるが助成事業固有の報告。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_support_request', 'established', '認定を置かず支援ごとに個別申請・個別審査', '認定制度を持たないため、支援ごとに独立した申請・審査経路を持つ。株式等取扱規程第4条は住所・代表者名、事業化しようとする研究開発成果の概要、支援対象及び申出理由、対価とする株式等の内容を書面で学術研究・産学官連携本部長あてに提出させる。出資規程第4条も同様の書面申請。不動産貸付細則第4条は不動産貸付願（別記様式第1号）を部局長に提出し部局長が総長へ許可申請。名称使用は「九州大学の名称使用に関する許可申請書」。起業相談は申込フォーム提出後、受付判断、コーディネーターとの二者面談、必要に応じ外部専門家との三者面談。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/254/1/2014kitei124.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_facility_registration', 'established', '創業準備含む施設貸付可・原則5年以内・登記可否未確認', '国立大学法人九州大学不動産貸付細則（H16細則32、最終改正R6細則1）第2条第1項第5号ニが、貸付を許可する範囲として「別に定めるところにより、本学の研究成果を活用した事業（創業準備を含む。）を行う中小企業者又は個人にその事業の用に供するため本学の施設を使用させることが必要と認められる場合」を明記。第5条第3項で貸付期間は原則5年以内（事業用定期借地権設定契約等の場合は別途）、第7条第1項ただし書で同号ニの場合は算定額から4割以内を減額できる。商業登記（本店登記）の可否についての記載は同細則にも公開ページにもなく未確認。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/1043/1/2004saisoku032.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_vc_connection', 'established', 'VC等が外部審査員・協力機関にVC23社', 'AMED「橋渡し研究プログラム（大学発医療系スタートアップ支援プログラム）」採択のお知らせ（2024年10月）に、JST事業PARKSで構築した人材プールと併せて「強力なベンチャーキャピタルネットワーク」を活用する旨と、協力機関としてVC23社が記載されている。e教員ハンドブック産学連携章（p.95）の大学発ベンチャー事業シーズ育成支援プログラム概略図にも「VC等の専門家からなる外部審査員による助言・評価を受け、起業へ向けたステップアップを図る」と明記。金融機関個別との紹介導線を定めた規程は未確認。', 'official', 'https://www.kyushu-u.ac.jp/ja/notices/view/2765', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_eir', 'unknown', null, '学術研究・産学官連携本部（AiRIMaQ）の起業相談ページ、スタートアップ共創基金ページ、九大OIP株式会社紹介ページ、九大OIP自社サイトを開いたが、客員起業家（EIR）・起業家メンターの招聘制度を定めた記載は確認できなかった。検索結果には100%子会社である九大OIP株式会社がEIRを募集しているとする外部の求人・記事情報が出るが、大学または同社の公式ページ本文では裏付けが取れていない。近い制度としてはPARKSのプレCxO人材紹介がある（pol_cxo_pool参照）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_cxo_pool', 'established', 'プレCXO人材マッチング・400人以上のCxO人材プール', 'スタートアップ共創基金ページの支援メニューに「プレCXO人材マッチング」があり、経営人材不足を大学発スタートアップの課題として、起業を希望する研究者に事業化推進人材を外部から「プレCXO」として紹介し、マッチング後は一定期間研究者と共に事業化検証に従事すると説明。規模については、AMED大学発医療系スタートアップ支援プログラム採択のお知らせに「JST事業PARKSで構築した400人以上の事業化推進人材/CxO人材プール」と記載されている。', 'official', 'https://airimaq.kyushu-u.ac.jp/startupkikin/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_ip_equity', 'established', '株式等での対価支払申出は原則受入・上場時10%以内', '優遇措置ガイドライン3．(1)「ライセンス等の対価としての株式等を取得」に「対象となる大学発ベンチャーから、ライセンス等の対価として株式等による支払いの申し出を受けた場合、原則として上記申し出を受け入れる」と明記。5．留意事項(1)で、本学が保有する株式等のシェアは上場時点の議決権ベースで10%以内となるよう留意し、新株予約権か無議決権株式とすることが望ましいとする。受入れの根拠規程は成果活用事業者株式等取扱規程（H26規程124）第2条第2号が「株式等」を株式及び新株予約権と定義し、第3条で受入れの基準を定める。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'pol_fund_investment', 'established', '個別研究プロジェクト出資規程あり・原則現物出資', '「九州大学における個別研究プロジェクトに係る出資に関する規程」（令和6年度九大規程第15号、令和6年7月1日制定）第1条が国立大学法人法第22条に基づく出資と規定。第2条で対象を教育研究施設管理等事業者、成果活用促進事業者、指定国立大学研究成果活用事業者の3類型に限定。第3条で出資は原則として現物出資（知的財産の対価、教育研究施設及び設備の使用料、受託研究費・共同研究費等）とする。第4条第6項で総長が文部科学大臣決定の認可基準に定める手続及び産学官連携戦略会議の議を経て出資事項を決定し、文部科学大臣へ申請する。大学VC設立やLP出資、指定ファンドの規程は未確認。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/4510/1/2024kitei015.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_regulation_owner', 'established', '大学規程（九大規程・九大細則の体系）', '国立大学法人九州大学が定める学内規程。成果活用事業者株式等取扱規程は「平成26年度九大規程第124号」（制定平成27年3月31日、最終改正令和6年7月1日＝令和6年度九大規程第14号）、個別研究プロジェクト出資規程は「令和6年度九大規程第15号」、不動産貸付細則は「平成16年度九大細則第32号」。学校法人規程やハイブリッドではなく、九州大学規則集（規則・規程・細則）の体系に一元的に置かれている。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/254/1/2014kitei124.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_review_body', 'established', '産学官連携戦略会議のもとの専門家会議', '成果活用事業者株式等取扱規程第4条第2項に「学術研究・産学官連携本部長は、前項の申出について、審査するため、九州大学産学官連携戦略会議規程（令和3年度九大規程第157号）第8条に基づき、産学官連携戦略会議のもとに、専門家会議を置く」と規定。同条第4項で専門家会議が事業者の資力その他の事情を勘案して審査し産学官連携戦略会議に報告、第5項で産学官連携戦略会議が審議する。申請の受理主体は学術研究・産学官連携本部長。認定委員会は存在しない。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/254/1/2014kitei124.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_equity_decider', 'established', '総長（産学官連携戦略会議の審議を経て決定）', '成果活用事業者株式等取扱規程第4条第6項「総長は、産学官連携戦略会議の審議を経て、当該成果活用事業者への支援の対価の全部又は一部を株式等で収納することについて決定する」。第5条は取得後の議決権について、原則不行使とし、不行使により発行会社の経営に著しい影響を与える可能性がある場合は総長が行使すると定める。第7条で株式等の管理・売却等は「別に定める」とされ、処分の決裁者は同規程本文では特定されていない。出資規程第4条第6項も同様に総長が決定し文部科学大臣へ申請する。', 'official', 'https://www.kyushu-u.ac.jp/ja/university/information/rule/rulebook/pdf/254/1/2014kitei124.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_amendment_decider', 'unknown', null, '九州大学役員会規則（平成16年度九大規則第4号）を確認したところ、第2条で役員会は総長及び理事で組織すると定めるが、第3条が列挙する総長が役員会の議を経なければならない事項は、中期目標についての意見、国立大学法人法により文部科学大臣の認可又は承認を要する事項、予算の作成及び執行並びに決算、学部・学府・研究院その他重要な組織の設置又は廃止、その他役員会が定める重要事項の5号で、「規則の制定又は改廃」の号は置かれていない。株式等取扱規程・出資規程の附則も改正番号のみで決裁主体を示さず、規程レベルの制定改廃決裁者は公開情報からは特定できなかった。', 'official', 'https://www1.g-reiki.net/kyushu-u/reiki_honbun/u437RG00000004.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_post_grad_limit', 'established', '関連性で判断（起業時点で在籍・離職で除外）', '優遇措置ガイドライン脚注iiiが対象者を「起業の時点で本学の教職員であって、起業後に本学を退職した場合や他大学に異動した場合を含む。学生が起業後に卒業した場合も同様とする」と定義し、退職後・卒業後の年数による期限を置いていない。判定基準は起業時点で本学に在籍していたか否かで、その後の退職・卒業・他大学異動は対象から外さない。ただし同脚注ただし書により、起業時点で参画していた教職員（又は学生）が当該ベンチャーを離職した場合は対象から除外される。退職後に新たに起業する場合を対象とする規定はない。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_renewal_rule', 'established', '更新可（審査あり）・経営状況を勘案し協議で延長', '優遇措置ガイドライン4．優遇措置を講じる期間の但書「当該大学発ベンチャーの経営状況を十分に勘案して、協議により期間を延長することができる」。届出のみで自動更新される仕組みではなく、経営状況の勘案という実質判断を伴う協議を経る点で審査ありの更新に当たる。再申請を要する旨や更新回数の上限の定めはない。認定制度がないため「認定の更新」ではなく優遇措置適用期間の延長として規定されている。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_naming', 'established', '称号なし（規程上の呼称は大学発ベンチャー）', '優遇措置ガイドライン脚注iに「本学では、『大学発ベンチャー』の公式の認定は行っていない」と明記されており、称号の付与自体を行わない。文書上の呼称としては、同ガイドラインおよびe教員ハンドブック産学連携章（大学発ベンチャー創出、大学発ベンチャー事業シーズ育成支援プログラム）が「大学発ベンチャー」を用いる一方、スタートアップ共創基金の公開ページは「大学発スタートアップ」を用いる。規程上の定義語は「成果活用事業者」（株式等取扱規程第1条）。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_support_period', 'established', '支援ごとに別に定める（優遇5〜6年・貸付5年）', '称号を付与しないため称号期間という概念がなく、支援ごとに期間が別に定められている。ライセンス等の対価の優遇措置は起業後5〜6年目まで（優遇措置ガイドライン4．、協議により延長可）。実施許諾契約期間は5年から10年程度が目安（同3．(3)）。不動産の貸付期間は一時使用を除き原則5年以内（不動産貸付細則第5条第3項）。大学発ベンチャー事業シーズ育成支援プログラムの助成期間は7か月程度（e教員ハンドブック産学連携章p.95）。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_support_contents', 'established', '起業相談・起業家教育・ギャップファンド・プレCXO紹介・ライセンス優遇・施設貸付', 'e教員ハンドブック産学連携章「大学発ベンチャー創出」（p.95）が支援を4本柱で列挙する。1．起業家教育（ロバート・ファン／アントレプレナーシップ・センターQREC等との連携）、2．学内教職員および学生等からの起業相談、3．起業前支援（学内ギャップファンドプログラムの推進、外部専門家との連携支援）、4．起業後支援（各種優遇支援、一般支援、外部専門家との連携支援）。これにスタートアップ共創基金の事業化検証資金・プレCXO人材マッチング・座学セミナー・メンタリング、優遇措置ガイドラインのライセンス対価優遇と株式等での対価受入と知財譲渡、不動産貸付細則の施設貸付が加わる。', 'official', 'https://www.kyushu-u.ac.jp/f/43082/%E7%94%A3%E5%AD%A6%E9%80%A3%E6%90%BA.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c030bad12839', 'attr_source_docs', 'established', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf・https://www.kyushu-u.ac.jp/ja/university/…', '1本目は「大学発ベンチャーに対するライセンス等の対価の優遇措置に関するガイドライン」（平成31年3月1日実施）で、認定を行わない旨、対象者、優遇内容、期間、留意事項が集約された事実上の制度正本。2本目は「九州大学における成果活用事業者への支援に伴い取得する株式等の取扱に関する規程」（平成26年度九大規程第124号）で、申請・審査・総長決定の経路が定められる。3本目は「九州大学における個別研究プロジェクトに係る出資に関する規程」（令和6年度九大規程第15号）で、現物出資の対象と手続きを定める。補助資料としてe教員ハンドブック産学連携章と不動産貸付細則がある。', 'official', 'https://airimaq.kyushu-u.ac.jp/_cms_dir/uploads/2022/08/venture_guideline.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_cert_update', 'established', '支援期間3年以内・再申請で延長可・年次事業報告で継続確認', 'SU支援規程第5条第3項「支援期間は、前条第3項に規定する支援の決定通知日から起算して3年を超えない範囲で、学長が必要と認める期間とする」。同条第4項が「支援期間の延長等を行うための申請」としての再申請を妨げないと規定。要件の再確認は第7条第1項の年次事業報告書（翌年6月末日まで）と、第8条の取消事由第1号（定義・支援条件に該当しなくなったとき）で担保されている。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_title_restriction', 'established', '製品・サービスの品質を保証しない旨を明記、使用停止規定なし', 'SU支援規程第9条（免責）第2項「本学は、九工大発スタートアップの製品、サービス等の内容及び品質を保証しない」。同条第1項は支援を受けたことにより企業または第三者に生じた損失・損害について本学が義務・責任を負わない旨を定める。一方、投資推奨や経営状態の保証との誤認防止に触れた条項、称号・ロゴの使用範囲を限定する条項、使用停止・返付を命じる条項は規程本文に見当たらない。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_cancellation', 'established', '取消事由7項目を規定、取消後の称号返付・表示削除の規定なし', 'SU支援規程第8条（支援の決定の取消し）「学長は、九工大発スタートアップの長から支援の取消しの申出があった場合又は九工大発スタートアップが次の各号のいずれかに該当する場合は、支援決定後、当該支援の決定を取り消すことができる」として、定義・条件に該当しなくなったとき、事業報告書未提出、解散等の報告、社会的信用の失墜、事業実態の消滅、活動存続が危ぶまれるとき、その他不適当と認めるときの7号を列挙。取消後の称号返付、表示削除、営業利用停止の処理は規定されていない。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_report_change', 'established', '毎年6月末までの事業報告書・変更届出・解散等の即時報告', 'SU支援規程第7条第1項「支援期間内において毎年度、当該年度の翌年6月末日までに、事業報告書（別記様式第3号）を学長に提出しなければならない」。第7条第2項は解散、破産、民事再生、会社更生、不正競争防止法違反等の場合に直ちに学長へ報告することを義務づける。第6条（申請内容の変更）は「第4条第1項に規定する申請に記載した内容に変更が生じたときは、速やかに学長に書面により届け出なければならない」と定め、申請書の企業名・代表者・添付の履歴事項全部証明書の記載事項の変更が対象になる。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_support_request', 'unknown', null, '［自動検証で否認: 株式等取得審査の根拠が施設使用細則ページに無い］元の主張(established): 認定とは別に施設使用申請・株式等取得審査が個別に必要。SU支援規程第4条の支援申請（別記様式第1号）は認定と支援決定を一体で行うが、個別の支援メニューはそれぞれ別手続を持つ。インキュベーション施設使用細則第2条は「インキュベーション施設使用申請書」により管理運営責任者へ申請すると定める。株式等取扱規程は第4条で発明審査委員会の審査、第5条で学長が役員会の議を経て決定するとし、支援決定とは別の審査経路を置いている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_facility_registration', 'unknown', null, '［自動検証で否認: 3年以内等の期間は規程本体になく別文書の内容］元の主張(established): インキュベーション施設に3年以内・有償で入居可、商業登記の規定なし。九州工業大学インキュベーション施設規程（平成15年12月3日制定）第3条は入居資格8区分を列挙し、第8号に「九工大発スタートアップ」を明記。同施設使用細則第4条は入居期間を3年以内とし、規程第3条第1項第1号該当者は特別の事由により最大9年、その他の該当者は最大2年の延長を認める。第8条・第9条で光熱水料と施設使用費の負担義務があり、細則第10条で使用料は月額・別表による。規程・細則とも商業登記、本店、本店所在地、登記に関する条項は置いていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: IUVとの協定情報がこのページに記載なし］元の主張(established): VC・北九州市・IUV等と連携協定、社会連携講座も設置。KYUTECH REPORT「イノベーション創出により目指す未来」に、ベンチャーキャピタルによる社会連携講座の設置と包括連携協定の締結、北九州市およびGZキャピタル株式会社との三者による「ロボット技術等の社会実装に向けた連携協定」（2024年2月）が記載されている。2025年11月4日には株式会社インターユニバーシティ・ベンチャーズと大学発スタートアップ育成・支援に関する協定を締結。ただしSU支援規程第5条第1項の支援内容および2025年3月1日公表の支援メニューには、VC・金融機関への紹介は列挙されていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_eir', 'drafting', 'EIR等の支援人材を配置推進中、制度化は未公表', 'KYUTECH REPORT「イノベーション創出により目指す未来」に「未来思考実証センターではPoCテクニシャン、EIR等の支援人材の配置を進めていきます」と記載され、配置を進行中の段階であることが示されている。EIR（客員起業家）の募集要項、任用規程、招聘手続を定めた公開文書は確認できず、SU支援規程第5条第1項の支援内容にも起業家人材の招聘・紹介は列挙されていない。', 'official', 'https://www.kyutech.ac.jp/kyutechreport/innovation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_cxo_pool', 'unknown', null, 'SU支援規程第5条第1項の支援内容7号、2025年3月1日公表の支援メニュー、未来思考実証センターのスタートアップ支援ページ、KYUTECH REPORTのいずれにも、経営人材（CEO/CXO候補）の人材プール、紹介、マッチングに関する記載を確認できなかった。公開情報からは制度の有無を判断できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_ip_equity', 'established', '知財実施権の対価を株式・新株予約権・新株予約権付社債で取得可', '「国立大学法人九州工業大学における大学発スタートアップの支援として実施する収益を伴う事業の対価として取得する株式等取扱規程」第2条第5号が「株式等」を株式、新株予約権および新株予約権付社債と定義。同条第8号は対象となる支援事業を「ライセンス等、施設・設備の提供、その他学長が特に必要と認めた事業」と規定。第3条第1号で対象を国立大学法人法第34条の4第1項の成果活用事業者に限定。第4条第3号は価額を必要に応じ外部専門家の意見を聴取して公正かつ客観的に評価すると定める。2025年3月1日公表の支援メニューでは対価の詳細は検討中とされている。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64511', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'pol_fund_investment', 'drafting', '独自VC・PoCファンドの運用を目指す段階', 'KYUTECH REPORT「イノベーション創出により目指す未来」に「独自のVCやPOCファンド運用を目指す」との記載があり、構想段階にとどまる。現時点の資金支援はPARKS事業のGAPファンド活用が中心で、大学自身の出資規程、認定VCへのLP出資、指定ファンド、大学出資会社を定めた公開規程は確認できなかった。株式等取扱規程は支援の対価として株式等を取得する枠組みであり、大学からの出資を定めるものではない。', 'official', 'https://www.kyutech.ac.jp/kyutechreport/innovation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_regulation_owner', 'established', '大学規程（国立大学法人九州工業大学のSU支援規程）', '認定制度の根拠は「国立大学法人九州工業大学における大学発スタートアップの支援に関する規程」で、第1条が「本規程は、国立大学法人九州工業大学（以下「本学」という。）における大学発スタートアップの支援に必要な事項を定めることを目的とする」と規定。国立大学法人が定める大学規程であり、学校法人規程や研究機関独自規程との併存はない。附則により令和6年11月1日施行、令和8年6月19日改正（令和8年4月1日適用）。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_review_body', 'established', '九州工業大学発スタートアップ支援審査会＋研究推進機構運営会議', '「九州工業大学発スタートアップ支援審査会要項」第1条が審査会の名称を定め、第2条で「大学発スタートアップの支援申請に関すること」を審議事項とする。第3条の構成は研究本部長（委員長）、研究副本部長、産学イノベーションセンター長、未来思考実証センター長、同センター社会実装推進部門長、本部長が推薦する者若干名。第6条で委員の3分の2以上の出席により成立し、出席委員の過半数で決し可否同数のときは委員長が決する。SU支援規程第4条第2項は学長が研究推進機構運営会議の議を経て支援の可否を決定すると定める。要項は令和8年6月19日施行・令和8年4月1日適用。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/115401', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_equity_decider', 'established', '学長（役員会の議を経て決定、発明審査委員会が審査）', '株式等取扱規程第5条は取得について学長が役員会の議を経て決定すると定める。第4条は職務発明規程第13条に定める発明審査委員会が審査を行うとし、同条第3号で価額の評価方法を規定。処分についても第11条で株式等の売却を学長が役員会の議を経て決定、第9条で新株予約権の行使を学長が役員会の議を経て決定するとしている。第7条は管理責任者を会計事務責任者とし、第12条でインサイダー取引防止のため関係職員等の保有状況を調査し利益相反委員会へ報告する仕組みを置く。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64511', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_amendment_decider', 'unknown', null, 'SU支援規程は第10条（雑則）で「本規程に定めるもののほか、九工大発スタートアップの支援に関し必要な事項は、別に定める」とするのみで、制定改廃の決定主体を明示していない。株式等取扱規程第14条も同様の留保にとどまる。大学規則集の索引画面からは規則等の制定改廃手続を定めた規程を特定できなかった。なお支援審査会要項は令和8年6月19日裁定で起案者が研究本部長と記載されている。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_post_grad_limit', 'not_started', '規定なし（第2条に退職・卒業後の期限条項なし）', 'SU支援規程第2条は九工大発ベンチャーを、本学で達成された研究成果に基づく特許や新たな技術・ビジネス手法を事業化する目的で新規に設立されたもの、設立の日から5年を経過する日までに共同研究を実施したもの、同じく5年以内に本学から技術移転等を受けたもの、本学の教職員・学生等が設立者となるか設立に深く関与したもの、これらに準ずる資格を有するものの5号で定義する。5年の起算点は設立日であり、退職・卒業からの経過年数を基準とする条項は置かれていない。第5号の準用規定が受け皿になり得るが、年限の定めはない。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_renewal_rule', 'established', '更新不可・再申請（延長は第4条の審査をやり直し）', 'SU支援規程第5条第4項「前項の規定は、九工大発スタートアップの長による再申請（支援期間の延長等を行うための申請）を妨げない」。更新のための簡略手続や届出制は置かれておらず、期間延長は第4条第1項の支援申請書を再提出し、支援審査会の審査と研究推進機構運営会議の議を経て学長が可否を決定する経路をたどる。支援期間は第5条第3項により1回あたり3年以内。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_naming', 'established', '独自名称（九工大発スタートアップ、母集団は九工大発ベンチャー）', 'SU支援規程第2条は「九工大発ベンチャー」を広い母集団として定義し、そのうち第3条の支援条件を満たして第5条の支援決定を受けた企業を「九工大発スタートアップ」と定義する二層構造をとる。第5条第1項第1号は支援内容として「「九工大発スタートアップ」の称号及びロゴを使用させること」と規定。称号は大学名の略称を冠した独自名称であり、大学発ベンチャー・大学発スタートアップという一般名称をそのまま称号としては用いていない。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_support_period', 'established', '称号期間と同じ（支援決定通知日から3年以内）', 'SU支援規程第5条第1項は称号・ロゴの使用を支援内容の第1号として他の支援メニューと並べて規定し、第5条第3項が支援期間全体を「支援の決定通知日から起算して3年を超えない範囲で、学長が必要と認める期間」と一本で定める。称号の使用期間だけを別に定める条項はなく、称号期間と支援期間は一致する。ただし施設入居は使用細則第4条で別に期間と延長要件を定めており、実際の利用期間は個別手続で決まる。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_support_contents', 'established', '称号ロゴ・広報・施設入居・設備使用・知財実施権・KyuTechコラボ入会', 'SU支援規程第5条第1項が支援内容を7号で列挙する。称号およびロゴの使用、インキュベーション施設等の使用に関する優遇措置、研究設備等の使用に関する優遇措置、知的財産権または研究成果等の実施権の許諾に関する優遇措置、九州工業大学産学連携推進会の入会に関する優遇措置、広報誌・ホームページ等における広報、その他学長が必要と認めること。2025年3月1日公表の支援メニュー資料は同じ6項目を対価付きで整理し、産学連携推進会をKyuTechコラボと表記。称号・ロゴ使用と広報協力は無料、施設入居・施設設備使用・知財実施権許諾・KyuTechコラボ入会は支払いの一部を新株予約権の取得に代える等の柔軟な対応を想定（詳細は検討中）としている。', 'official', 'https://www.ccr.kyutech.ac.jp/themes/innovation/f_venture/files/shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_be0174a565d7', 'attr_source_docs', 'established', 'https://bap.jimu.kyutech.ac.jp/publishes/64748・https://bap.jimu.kyutech.ac.jp/publishes/64511・https://www.ccr.kyutech.a…', '1本目はSU支援規程本文で、定義・支援条件・申請と決定・支援内容と期間・変更届・事業報告・取消・免責を一通り含む正本。2本目は株式等取扱規程で、支援事業の対価として株式・新株予約権・新株予約権付社債を取得する際の審査、決定、管理、行使、売却の手続を定める。3本目は社会実装本部未来思考実証センターが令和7年3月1日に公表した支援メニュー資料で、各支援内容の対価設定と検討中の範囲を明示している。認定の審査体制を読む場合は支援審査会要項（publishes/115401）を併読する。', 'official', 'https://bap.jimu.kyutech.ac.jp/publishes/64748', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_cert_update', 'established', '認定5年・更新可（初回5年、2回目以降1年）', '「大学発ベンチャーの認定及び支援に関する規則」第4条第2項で認定期間を5年間とし更新申請ができると定める。第3項で更新後の期間を初回5年間、2回目以降1年間と区分。第4項で更新申請手続は第5条第1項の新規申請の例によるとし、第5条第2項により学長が大学発ベンチャー審査委員会の議を経て可否を決定する。要件の再確認は第10条第1項第1号（第4条第1項の申請要件に該当しなくなったときは取消し）で担保。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_title_restriction', 'established', '免責条項あり・取消後は称号使用の事業利用を禁止', '同規則第6条で学長が称号記により「北陸先端科学技術大学院大学発ベンチャー」の称号を授与。第7条（本学の法的責任）で認定と称号授与は本学に何ら法的責任を生じさせるものではないと明記。第10条第3項で取消通知を受けた者は速やかに称号記を返付し、通知日以後は認定及び称号を受けていた事実を事業に使用してはならないと定める。品質保証・投資推奨・経営状態の保証と誤認させない旨を名指しした条項は置かず、第7条の免責条項で処理している。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_cancellation', 'established', '取消5事由・称号記返付・取消後の事業使用禁止', '同規則第9条で代表者からの認定解除・称号返付の申出を認め、学長が認めて文書通知し審査委員会へ報告。第10条第1項で取消事由を5号列挙（申請要件不該当、買収・統廃合で法人格の同一性が保たれないとき、社会的信用の失墜、第8条の報告未提出または同条第2項該当、学長が保持させることを適当でないと認めるとき）し、審査委員会の議を経て学長が取り消す。第2項で文書通知、第3項で称号記の返付と事業使用の禁止。第12条第4項で解除・取消時は支援を打ち切る。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_report_change', 'established', '年次事業報告書と解散等の報告を義務化・変更届は明文なし', '同規則第8条第1項で認定大学発ベンチャーの代表者は毎年度、自社の決算日から3か月以内に事業報告書及び収支決算書を学長に提出しなければならないと定める。第2項で解散、破産手続開始決定、民事再生手続開始決定、会社更生手続開始決定、不正競争防止法違反の有罪確定、その他法令違反処分の確定に該当するときは代表者又は清算人が速やかに学長へ報告する義務を課す。代表者・所在地・資本構成の変更届に相当する条文は本規則に置かれていない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_support_request', 'established', '認定とは別にVBL利用許可の申請・審査が必要', '同規則第12条第1項第1号でベンチャー・ビジネス・ラボラトリー（VBL）の利用を支援として掲げ、第2項で支援を行うときは本学における関係規則等によるとして、VBL利用規則に基づく利用許可の手続へ委ねている。認定制度ページ（大学発ベンチャーの認定）も「認定された大学発ベンチャーはJAIST-VBLの利用申請が可能」と記載し、認定と施設利用の申請を分けている。認定申請の窓口は共創活動推進課イノベーション創出支援係。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_facility_registration', 'established', 'VBL入居中に限りVBL住所で本店登記を許容', '同規則第12条第1項第2号が、VBLの利用が許可された場合において利用許可期間内に限り認定大学発ベンチャーの登記住所を当該施設の住所とすることを認めると明記。あわせて登記申請前に登記申請書の写しを本学へ提出し、VBL退去時には登記住所を変更したことを示す書面を提出する義務を課す。第4条第1項第1号は起業準備段階でも認定決定後6月以内に商業登記が完了する見込みであれば申請できるとしており、施設利用と商業登記が接続している。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_vc_connection', 'established', 'TeSH経由でVC9機関・地銀等29機関に接続', 'JSTプロジェクトデータベースのTech Startup HOKURIKU（TeSH、体系的番号JPMJSF2318）に、主幹機関が北陸先端科学技術大学院大学と金沢大学、事業化推進機関が金沢大学100%出資のベンチャーキャピタルと地域ベンチャーキャピタル5社を含む計9機関、協力機関が3県の自治体・外郭団体・地銀・経済団体など29機関と記載。JAISTは主幹機関として事務局を担う。ただし認定規則側にVC・金融機関の紹介条項は置かれていない。', 'official', 'https://projectdb.jst.go.jp/grant/JST-PROJECT-23014677/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_eir', 'unknown', null, '認定規則第12条の支援事業にEIR・起業家メンターの記載はなく、未来創造イノベーション推進本部サイトのベンチャー・ビジネスの育成ページと産学官連携サービス一覧、認定制度ページ、TeSHのGAPファンドプログラムページ、JSTプロジェクトデータベースのいずれにも客員起業家（EIR）制度の記載を確認できなかった。新株予約権取得規則第4条に「スタートアップ推進室」の名称が出るが、同室の支援メニューを示す公開ページには到達できなかった。制度の不存在を明示した文書は見ていない。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_cxo_pool', 'unknown', null, '認定制度ページの支援メニューはVBLの実験室8室・研究員室6室・ディスカッションルームの利用と「ベンチャー・ビジネス設立に向けた必要に応じたサポート」までで、経営人材（CEO/CXO候補）の紹介・マッチングの記載がない。ベンチャー・ビジネスの育成ページ、TeSHのGAPファンドプログラムページ、JSTプロジェクトデータベースにも人材プールの記載を確認できなかった。認定規則第12条第1項第3号の「その他学長が必要と認めること」が包括条項として残るため、不存在とは断定していない。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_ip_equity', 'established', 'ライセンス等の対価として新株予約権を取得可', '「新株予約権の取得に関する規則」第1条で、科学技術・イノベーション創出の活性化に関する法律に基づき、本学が所有する知的財産等のライセンス、施設の利用、その他の支援業務の対価として新株予約権を取得すると定める。第2条で「ライセンス」を知的財産権の譲渡・実施権設定・研究成果物の譲渡貸与、「施設の利用」をVBL及び産学官連携推進センターの利用と定義し、相手方は認定済み又は認定予定の大学発ベンチャー。株式そのものを取得する規定は置かれていない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000429.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'pol_fund_investment', 'not_started', '出資・ファンド組成の規程なし・株式取得も規定なし', '例規集の共創活動推進課分野の規則一覧（全49件）を通読したが、出資、ファンド組成、認定VC、LP出資に関する規程はなく、株式等に関するものは「新株予約権の取得に関する規則」と「新株予約権の管理に関する規則」の2本のみ。取得規則も対価は新株予約権に限り、株式取得の規定を置かない。TeSHの事業化推進機関に入るVCは金沢大学100%出資VCと地域VC5社で、JAIST自身の出資会社ではない。', 'official', 'https://public1.legalcrud.com/jaist/aggregate/field/result/field7.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_regulation_owner', 'established', '大学規程（国立大学法人の学内規則）', '認定制度の根拠は「国立大学法人北陸先端科学技術大学院大学における大学発ベンチャーの認定及び支援に関する規則」（令和2年12月23日制定、令和7年10月1日規則第105号改正まで反映）で、国立大学法人が自ら定める学内規則として例規集の共創活動推進課分野に収録されている。学校法人の寄附行為や別法人の規程ではない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_review_body', 'established', '大学発ベンチャー審査委員会（委員長は推進本部長）', '同規則第3条第1項で認定の審査のため「大学発ベンチャー審査委員会」を置く。第2項の委員構成は、研究を担当する理事、未来創造イノベーション推進本部長、産学官連携推進センター長、学長が指名する産学官連携推進センターの教授又は准教授、副理事（研究担当）、その他委員長が必要と認めた者。第3項で委員長は未来創造イノベーション推進本部長。第6項で委員の過半数の出席で成立、第7項で出席委員の過半数により議決。第8項で学外有識者の意見聴取ができる。事務は第13条により共創活動推進課。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_equity_decider', 'established', '学長（新株予約権審査会の議を経て決定）', '「新株予約権の取得に関する規則」第3条で対象企業が学長に申し込み、学長が審査会に付議する。第4条の審査会は未来創造イノベーション推進本部長、スタートアップ推進室長、同室の教授等、共創活動推進課長ほかで構成し、第6条で本部長が委員長、2分の1以上の出席で成立、過半数で決議して学長に報告。第5条の審議事項は取得の可否、経済条件、譲渡の可否、譲渡価格。第7条で学長が可否を決定し契約書を取り交わして取得する。処分（譲渡）も同じ経路。', 'official', 'https://public1.legalcrud.com/jaist/act/110000429.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_amendment_decider', 'unknown', null, '認定規則本体に制定改廃の決裁主体を定める条文はなく、第14条は「この規則に定めるもののほか必要な事項は、別に定める」とするだけで主体を書いていない。役員会規則第3条の審議事項は中期目標の意見、文部科学大臣の認可・承認事項、予算・決算、重要組織の設置廃止、その他役員会が定める重要事項の5号で、規則の制定改廃は明記されていない。組織運営規則にも制定改廃権者の条文はなく、第5条が学長の業務総理を定めるにとどまる。附則は規則番号のみで決裁主体を示していない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000003.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_post_grad_limit', 'established', '3年以内（退職等から起業までの期間）', '認定規則第2条第3号で、本学の教職員及び学生が発起人又は設立時に取締役相当となるなどして起業した企業等を大学発ベンチャーとし、ただし書で「教職員及び学生が退職等の後に起業した場合については、退職等から起業までの期間が3年以内のものに限る」と定める。認定制度ページの対象企業等の説明も同じ3年以内を掲げている。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_renewal_rule', 'established', '更新可（審査あり）・初回5年、2回目以降1年', '認定規則第4条第2項で認定期間5年間の更新を申請でき、第3項で更新後の認定期間は初回5年間、2回目以降1年間と定める。第4項で更新の申請手続は第5条第1項の新規申請の例によるとし、第5条第2項により学長が大学発ベンチャー審査委員会の議を経て可否を決定するため、届出のみではなく審査を伴う。認定制度ページも「5年間（更新あり：初回5年間、2回目以降は1年間）」と記載。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_naming', 'established', '大学発ベンチャー（北陸先端科学技術大学院大学発ベンチャー）', '認定規則の題名が「大学発ベンチャーの認定及び支援に関する規則」で、第2条が「大学発ベンチャー」を定義し、第6条で学長が称号記により「北陸先端科学技術大学院大学発ベンチャー」の称号を授与すると定める。スタートアップの語を併記した称号は用いていない。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_support_period', 'established', '支援ごとに別に定める（認定日から3年以内）', '認定規則第12条第3項で「認定大学発ベンチャーの支援期間は、第5条第2項の規定により認定した日から3年を超えない範囲で学長が必要と認める期間とする」と定め、第4条第2項の認定期間5年間とは別枠で、案件ごとに学長が期間を決める構成。第4項で認定の解除・取消しがあったときは支援を打ち切る。VBLの入居も最長3年で、認定制度ページの記載と一致する。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_support_contents', 'established', 'VBL実験室・研究員室の利用・VBL住所での商業登記・その他学長が認める支援', '認定規則第12条第1項が支援を3号で列挙し、第1号がベンチャー・ビジネス・ラボラトリーの利用、第2号が利用許可期間内に限るVBL住所での登記、第3号が「その他学長が必要と認めること」。認定制度ページはVBLの実験室8室（クリーンルーム、バイオハザード室）、研究員室6室、ディスカッションルーム（2F定員16名、3F定員8名）を最長3年・低料金で利用できるとし、あわせて設立に向けたサポートを挙げる。資金・人材・VC紹介のメニューは列挙されていない。', 'official', 'https://www.jaist.ac.jp/ricenter/venturebusiness/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_656caf0f3d72', 'attr_source_docs', 'established', 'https://public1.legalcrud.com/jaist/act/110000373.html・https://www.jaist.ac.jp/ricenter/venturebusiness/venture/・https:…', '1本目が認定・支援の本体規程で、定義、審査委員会、認定期間と更新、称号、報告義務、取消し、支援事業と支援期間まで通しで読める。2本目が運用側の公式ページで、申請書類、募集期間、窓口（共創活動推進課イノベーション創出支援係）、VBLの部屋数、認定8社の一覧と認定期間を掲載。3本目が対価としての新株予約権取得の規程で、対象、審査会の構成、学長の決定、譲渡の扱いを定める。', 'official', 'https://public1.legalcrud.com/jaist/act/110000373.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_cert_update', 'established', '支援決定は期限なし・郵便受けは3年上限で再申請可', '関連スタートアップ支援規程（令和8年4月1日施行）には支援決定の有効期間・更新審査の条項がなく、第8条（支援決定の取消し）で第2条の要件を満たさなくなった場合に機構長が取り消す形で要件を事後確認する構造。個別支援である貸出用郵便受け使用細則第5条は「原則として3年間を上限とする。ただし、再申請を妨げない」と定め、更新ではなく再申請の扱い。第9条（事業報告）が決算後の年次報告を求め、継続確認の材料となる。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_title_restriction', 'not_started', '称号付与なし・使用制限条項なし', '関連スタートアップ支援規程を第1条から第11条まで通読したが、称号・呼称を付与する規定がなく、支援決定型のため称号の使用範囲・使用停止や、品質保証・投資推奨・経営状態保証と誤認させない旨の条項も置かれていない。関連する規律は第4条（支援の要件）第3号「本学への名誉棄損等のおそれがないこと」と、第8条（支援決定の取消し）第2号「本学の社会的信用を失墜させる行為」による事後的な取消のみ。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_cancellation', 'established', '第7条の解除と第8条の4事由による機構長の取消', '関連スタートアップ支援規程第7条（支援決定の解除）は申請者が任意の様式で全部または一部の解除を申し出て機構長が認めると定める。第8条（支援決定の取消し）は①第2条の要件を満たさなくなったとき②本学の社会的信用を失墜させる行為③企業活動の実態が消滅したとき④その他機構長が継続不適当と認めるとき、の4事由を列挙。称号返付や表示削除の規定はないが、貸出用郵便受け使用細則第9条第2項が使用終了時の速やかな住所変更登記を義務づけ、同細則第7条が取消・使用中止の事由を定める。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_report_change', 'established', '決算後3か月以内の事業報告・解散等の即時報告', '関連スタートアップ支援規程第9条（事業報告）は代表者に決算日から3か月以内の事業報告書及び収支決算書の機構長宛提出を義務づける。あわせて会社法に定める解散、破産宣告、民事再生手続、会社更生手続、不正競争防止法に定める罰則刑の確定については代表者または清算人が速やかに報告する。代表者・所在地・資本構成の変更届は規程本体に規定がなく、貸出用郵便受け使用細則第8条が使用内容の変更を変更希望月初日の30日前までの書面申請・許可制としている。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_support_request', 'established', '機構長への申請と本部会議の議を経た可否決定', '関連スタートアップ支援規程第5条（支援申請）で第3条第1号（設備の貸与）または第2号（登記住所の許可）の支援を受ける者が別記様式の申請書を機構長に提出し、第6条（支援決定）で機構長が学術研究・イノベーション戦略企画本部会議の議を経て可否を決定する。称号認定と支援が分離しておらず、支援ごとの個別申請・審査が制度の中心。事務は第10条により研究推進部産学連携課が処理。貸出用郵便受けは細則第3条で使用希望月初日の60日前までの申請を要する。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_facility_registration', 'established', 'IMO棟・BizCAFEの郵便受けを登記住所に利用可', '関連スタートアップ支援規程第3条（支援の内容）第1号が学術研究・イノベーション推進機構の管理設備等の貸与、第2号が貸与設備の設置場所を登記住所とすることの許可を定める。貸出用郵便受け使用細則（令和8年7月1日施行）はIMO及びBizCAFE千葉大学店の貸出用郵便受けを対象とし、第9条第1項で商業・法人登記の住所地とする場合の事前申請・許可、第5条で原則3年上限・再申請可、第10条で月額1万円（消費税別）の年度一括前納を定める。居室貸与の学内制度は公開情報では確認できなかった。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_vc_connection', 'established', '千葉銀行と共同ファンド設立・包括連携協定で接続', '千葉大学は2025年7月1日に千葉銀行、ちばぎんキャピタルと「ちばグロースアカデミア投資事業有限責任組合」を組成（総額5億円、大学と千葉銀行が有限責任組合員、ちばぎんキャピタルが無限責任組合員）。大学の公式発表は2005年締結の千葉銀行との包括連携協定に基づく施策と位置づけ、国立大学が銀行グループ設立ファンドへ出資するのは国内初としている。千葉大スタートアップ・ラボのサイトは千葉銀行支援のDemo Day、ちばぎん研究開発助成制度、中小機構FASTAR、千葉市C-CAP、GTIEへの接続を掲載。', 'official', 'https://www.chiba-u.jp/news/contribution/fand_0702.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_eir', 'established', 'EIR（客員起業家）の公募・機構に2名在籍', '千葉大学学術研究・イノベーション推進機構が受入組織となり、2025年2月28日からEIR人材（客員起業家）を副業・フリーランス人材マッチングプラットフォーム経由で公募（募集2名予定、契約は2025年5月から6か月以上）。EIRは学内の技術シーズを探索し、自らが創業者候補として研究者に伴走する人材と定義され、会社設立後は広報支援や認知拡大等のサポート業務も予定と記載。千葉大スタートアップ・ラボのメンバーページにEIR2名（うち1名は2025年10月にURAからEIRへ職位変更）が掲載されている。', 'official', 'https://startup-lab.chiba-u.jp/member/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_cxo_pool', 'unknown', null, '千葉大スタートアップ・ラボのトップページ、支援メニューページ、メンバーページを通読したが、関連スタートアップへ経営人材（CEO/CXO候補）を紹介・マッチングする千葉大学独自の制度は確認できなかった。掲載されているのはEIR2名とビジネス＆テクノロジーアドバイザー6名の個人紹介で、制度としての説明文はない。EIR公募は大学が創業者候補を受け入れる仕組みで、既存スタートアップへのCXO紹介とは目的が異なる。大学発スタートアップCxO候補募集サイトはGTIEを含む9プラットフォームの共同運営だが、参加大学一覧に千葉大学の記載を確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_ip_equity', 'established', 'ライセンス供与等の対価としての株式・新株予約権取得', '国立大学法人千葉大学大学発ベンチャー企業等から対価として取得する株式等取扱規程（平成31年4月1日制定・施行）第2条第3項が「株式等」を株式及び新株予約権と定義し、第3条が取得対象の対価として研究成果に係るライセンス供与等の対価、その他本学の収益を伴う事業の対価を列挙する。第2条第4項の「大学発ベンチャー企業等」は、研究成果等をもとに起業、共同研究を実施、技術移転・出資等の支援を受けている企業のいずれかに該当するもの。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000228.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'pol_fund_investment', 'established', '出資規程あり・千葉銀行系ファンドにLP出資', '国立大学法人千葉大学における出資に関する規程（令和6年7月1日制定・施行）第5条（出資の範囲）が、認定特定研究成果活用支援事業者である株式会社の株式と、同事業者である投資事業有限責任組合の持分に出資範囲を限定する。第3条第2項で資金運用管理委員会の確認後、経営戦略会議、経営協議会及び役員会の議を経て学長が決定し、第9条で半期ごとの運用報告を求める。実例として2025年7月にちばグロースアカデミア投資事業有限責任組合へ出資（総額5億円）。大学100%出資の株式会社千葉大学コネクトも公式発表に記載。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000230.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_regulation_owner', 'unknown', null, '［自動検証で否認: 細則の根拠は第3条1号、第11条委任という記述は誤り］元の主張(established): 大学規程（国立大学法人千葉大学の学内規程）。支援の根拠は国立大学法人千葉大学関連スタートアップ支援に関する規程（令和8年4月1日制定・施行）で、大学の規程集に収載された学内規程。株式等取扱規程（平成31年）、出資に関する規程（令和6年）も同じ規程集の学内規程であり、学校法人規程や別法人の規程ではない。運用の細目は同規程第11条（雑則）の委任を受けて機構長が定める細則（学術研究・イノベーション推進機構貸出用郵便受け使用細則）に置く二層構成。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_review_body', 'established', '学術研究・イノベーション戦略企画本部会議（決定は機構長）', '関連スタートアップ支援規程第6条で機構長が「学術研究・イノベーション戦略企画本部会議の議を経て」支援の可否を決定する。正式名称は国立大学法人千葉大学学術研究・イノベーション推進機構学術研究・イノベーション戦略企画本部会議で、同会議規程（平成26年10月1日制定）第2条の審議事項は研究及びイノベーション推進に係る全学的取組みの企画立案、機構の組織・制度、本部の横断的事項、機構長が必要と認めた事項、教員人事及び高度特定専門員人事。構成員は機構長、副機構長、研究担当副学長ほか、議長は機構長。株式等の取得は別に株式等取扱委員会が審査する。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000429.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_equity_decider', 'established', '学長（株式等取扱委員会の審査を経て決定）', '大学発ベンチャー企業等から対価として取得する株式等取扱規程は第5条・第9条で株式等取扱委員会を置き、株式等の取得及び処分の最終決裁者を学長と定める。大学自身が資金を出す出資については、出資に関する規程第3条第2項により資金運用管理委員会の確認を受けた後、経営戦略会議、経営協議会及び役員会の議を経て学長が決定し、第7条・第8条で財務担当理事が資金運用責任者として運用する。対価としての株式取得と、大学からの出資で審査体が分かれている。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000228.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_amendment_decider', 'unknown', null, '関連スタートアップ支援規程は第11条（雑則）で「この規程に定めるもののほか、必要な事項は機構長が別に定める」と細目を機構長へ委任するのみで、規程自体の制定改廃を決める主体の条項がない。株式等取扱規程と出資に関する規程にも改廃条項は確認できなかった。規程集内で規則等の制定手続を定める規程を特定できず、公開情報からは決裁主体を確定できない。なお細則レベル（貸出用郵便受け使用細則）は同規程第11条の委任により機構長が定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_post_grad_limit', 'established', '規定なし（現役学生・現職教職員等が要件）', '関連スタートアップ支援規程第2条（定義）の7類型のうち、第4号は「本学での取組と深い関連があり、現役の学生が関係して設立したもの」、第5号は「本学の教職員等（教職員・ポスドク）が設立したもの」で、退職・卒業後何年以内という期限の定めがない。年数要件は第2号「創業者の持つ技術やノウハウを事業化するために、設立5年以内に本学と共同研究等を行ったもの」、第3号「既存事業を維持・発展させるため、設立5年以内に本学から技術移転等を受けたもの」という設立後年数の別軸のみ。第6号（本学が組織的に関係し深い関連があると認めたもの）と第7号（学長が特に必要と認めたもの）の包括規定で個別判断の余地は残る。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_renewal_rule', 'established', '期限なし（郵便受けは3年上限・再申請可）', '関連スタートアップ支援規程には支援決定の有効期間と更新の条項がなく、第8条の取消事由に該当しない限り決定が継続する構造。個別支援の貸出用郵便受けは使用細則第5条が「原則として3年間を上限とする。ただし、再申請を妨げない」と定め、更新手続ではなく再申請の扱い。使用内容の変更は同細則第8条により変更希望月初日の30日前までの書面申請と許可を要する。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_naming', 'established', '独自名称（千葉大学関連スタートアップ）', '支援規程の題名と第2条の定義が「関連スタートアップ」で、千葉大スタートアップ・ラボの公開一覧も「千葉大学関連スタートアップ一覧」として一貫してこの呼称を用いており、同一覧ページには大学発ベンチャー・大学発スタートアップの語が現れない。一方、株式等取扱規程（平成31年制定）は第2条第4項で「大学発ベンチャー企業等」の語を用いており、新旧の規程で呼称が異なる。称号として付与する制度ではなく、大学側が一覧に掲載する形。', 'official', 'https://startup-lab.chiba-u.jp/startup/chiba-university-startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_support_period', 'established', '支援ごとに別に定める（郵便受けは3年上限）', '関連スタートアップ支援規程は称号を付与せず、支援決定の期間も定めていない。期間は個別支援の細則側にあり、貸出用郵便受け使用細則第5条が原則3年間を上限として再申請可、第10条が使用料の1年度分一括前納と、取消・変更時の月割返還（1月未満は1月として計算）を定める。支援内容ごとに細則で期間を設計する構造で、称号期間と支援期間を対応させる考え方をとっていない。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_support_contents', 'established', '設備貸与・登記住所許可・成長支援相談・GAPファンド・EIR', '関連スタートアップ支援規程第3条（支援の内容）は①学術研究・イノベーション推進機構が管理する設備等の貸与②貸与設備の設置場所を登記住所とすることの許可③企業成長支援に関する相談への対応④その他機構長が必要と認める事項の4号。千葉大スタートアップ・ラボのサイトはこれに加えて、スタートアップなんでも相談、なのはなコンペ、GTIE GAPファンド エクスプロールコース（最大6000万円・3年間）、千葉県革新的スタートアップ成長促進事業、中小機構FASTAR、千葉市アクセラレーションプログラムC-CAP、Research Studio、EIR、ビジネス＆テクノロジーアドバイザーを掲載。', 'official', 'https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c6d191a944c4', 'attr_source_docs', 'unknown', null, '［自動検証で否認: URL自体は妥当、ただし第11条委任の記述は誤り］元の主張(established): https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001552.html・https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00001556.html・https://www1.g-reiki.net/chiba-u/reiki_honbun/w149RG00000228.html。制度の中心は国立大学法人千葉大学関連スタートアップ支援に関する規程（令和8年4月1日施行）、その第11条の委任を受けた学術研究・イノベーション推進機構貸出用郵便受け使用細則（令和8年7月1日施行）、株式・新株予約権の取得を定める大学発ベンチャー企業等から対価として取得する株式等取扱規程（平成31年4月1日制定）の3本。大学からの出資は出資に関する規程、審査体は学術研究・イノベーション戦略企画本部会議規程が根拠。支援メニューの運用実態は千葉大スタートアップ・ラボのサイトで確認できる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_cert_update', 'established', '5年・更新可、更新時も審査委員会審査（学生は在学期間まで）', '名古屋大学発ベンチャー称号授与規程第6条第2項で「称号授与の期間は，授与した日から5年とし，更新することができる」。同条第4項で更新申請は第5条第2項から第4項を準用し、総長が審査委員会へ付託して審査する初回と同じ手続を踏む。学生ベンチャーは同条第3項で在学期間が上限、退学等で取消し。要件の再確認は第9条第1項第1号（第3条の申請資格に該当しなくなったとき）が担う。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_title_restriction', 'established', '品質保証目的の使用禁止・広告使用は事前届出・使用停止あり', '同規程第7条第1項で「当該企業の製品，サービス等の内容及び品質を保証するために称号を使用してはならない」。第7条第2項で広告・宣伝に称号を用いる場合は事前に総長へ届出、不適当と認めるときは審査委員会の議を経て使用停止。第11条第1項で大学は製品・サービスの品質を保証しないと免責、第2項で授与・取消により生じた損害の賠償義務を負わない。投資推奨や経営状態の保証を名指しで禁じる条項は置かれていない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_cancellation', 'established', '取消3事由・称号記の返付・取消後の事業利用禁止', '同規程第9条第1項の取消事由は、第3条の申請資格に該当しなくなったとき、大学または当該企業の社会的信用を失墜する行為を行ったとき、称号を保持させることが適当でないと総長が認めるときの3つ。いずれも審査委員会の議を経て総長が取消す。第2項で「速やかに称号記を返付」し、取消日以後は称号を授与されていた事実を事業に使用してはならないと規定。第10条で取消しをホームページ等で公表できる。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_report_change', 'established', '毎年6月末までに活動内容報告書（変更届の明文なし）', '同規程第8条第1項で「毎年6月末日までに，別に定める活動内容報告書により，その前年度における活動内容を総長に報告しなければならない」と年次報告を義務づけ。第8条第2項で学生ベンチャーは学術研究・産学官連携推進本部から四半期に1回以上の指導・助言を受ける。代表者・所在地・資本構成の変更届や解散時報告を定めた条文は規程本文に見当たらず、第14条の雑則で「別に定める」に委ねられている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_support_request', 'established', '施設入居は別途入居審査会の書面審査・ヒアリング', '認定とは別に施設入居の個別審査がある。名古屋大学インキュベーション施設サイトの入居案内で、称号授与済みかつ設立10年以内を条件に、インキュベーション施設入居審査会の書面審査とヒアリング（申請責任者は本学教員）を経て学内会議で認可と明記。称号授与規程第7条第2項は広告・宣伝での称号使用に事前届出を課す。機器の技術支援は企業区分別の料金体系で、認定を条件とする別審査ではない。', 'official', 'https://incubation.aip.nagoya-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_facility_registration', 'established', 'インキュベーション施設・全室で本店登記と郵便受け可', '称号授与規程第12条第1号で学内に施設を確保して貸付、第2号で1月以上の長期貸付をした施設を所在地とする商業登記を認め、退去時は登記場所を変更したことを示す書面の提出を義務づけ、第3号で郵便物等の収受の便宜。名古屋大学インキュベーション施設サイトはSpace A〜Cの全室で登記・住所と郵便ポストが使えると記載。入居は原則2年、更新（要審査）2年＋1年で最長5年、資格は称号授与済み・設立10年以内。', 'official', 'https://incubation.aip.nagoya-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_vc_connection', 'established', '産学官連携推進本部が紹介・仲介、機構傘下VCと広域ファンド', '称号授与規程第12条第5号で「学術研究・産学官連携推進本部による他企業等への紹介又は仲介を行うこと」を支援に列挙。VC・金融機関を名指しした条項ではない。実体としては東海国立大学機構の出資会社Tokai Innovation Institute傘下のCentral Japan Innovation Capital、名古屋大学・東海地区大学広域ベンチャーファンド、Tongaliの支援者（メンター）紹介が接続経路になっており、Tongaliの紹介対象には投資の専門家が含まれる。', 'official', 'https://www.thers.ac.jp/news/2024/11/20241107-tii.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_eir', 'established', 'Tongaliによる支援者（メンター）紹介', 'Tongali（東海地区5大学のアントレプレナーシップ教育・起業支援）の起業・ベンチャー支援ページに、バイオからIT、投資の専門家まで多様な経験と知識を持つ支援者（メンター）を紹介するメニューが掲載されている。称号授与規程と東海国立大学機構規則集の公開分には、客員起業家（EIR）の名称で起業家人材を招聘する制度は見当たらず、規程上の制度ではなくプログラム上の支援として運用されている。', 'official', 'https://tongali.net/x/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_cxo_pool', 'unknown', null, '学術研究・産学官連携推進本部の起業支援ページ、東海国立大学機構スタートアップ支援ポータルの「スタートアップ各種支援」一覧、Tongaliの起業・ベンチャー支援ページのいずれにも、CEO・CXO候補の人材プールやマッチングのメニューは掲載されていない。称号授与規程第12条第8号が「その他総長が必要と認めた支援」を残しているため、制度として無いとは断定できない。', 'official', 'https://www.spo.thers.ac.jp/all_support', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_ip_equity', 'established', '実施料の現金支払に代え株式・新株予約権を取得可', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則（令和2年4月1日機構細則第61号、令和5年4月1日改正施行）第2条第2項で、現金支払の免除・軽減に代えて「当該成果活用事業者の発行した株式又は新株予約権を取得することができる」と規定。第3条で議決権付株式は発行済株式総数の半数未満に制限し既保有時の算定式も置く。第4条で議決権は行使しない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010858.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'pol_fund_investment', 'unknown', null, '［自動検証で否認: 広域ファンド・日本VC・BNVの記載がnews記事にない］元の主張(established): 機構出資会社傘下VC（CJIC）と東海5大学広域ファンド。東海国立大学機構の2024年11月7日お知らせで、機構の出資子会社である株式会社Tokai Innovation Instituteが100%出資して株式会社Central Japan Innovation Capital（2024年11月1日設立、資本金15百万円）を設立したと公表。投資対象はディープテック領域のスタートアップ。別に名古屋大学・東海地区大学広域ベンチャーファンドがあり、東海5大学に由来するベンチャーへ日本ベンチャーキャピタルが1号、Beyond Next Venturesが令和元年度から2号として投資している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_regulation_owner', 'established', 'ハイブリッド（認定は大学規程、株式・COIは機構規程）', '認定の根拠である名古屋大学発ベンチャー称号授与規程は平成28年7月19日規程第22号で、名古屋大学の規程として制定されている。一方、知的財産権等の運用又は処分に伴う株式等の取扱細則、利益相反マネジメント規程、兼業・兼職に関する規程は国立大学法人東海国立大学機構の規程・細則で法人側が定める。認定は大学規程、資本と利益相反は機構規程という二層構造。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_review_body', 'established', '名古屋大学発ベンチャー審査委員会（総長が付託）', '称号授与規程第4条で「名古屋大学発ベンチャー審査委員会」を置くと規定。第5条で企業代表者が総長へ申請し、総長が審査委員会に審査を付託、委員会が審査結果を報告、総長が認定・不認定を決定する。委員会に関する事項は「別に定める」とされ、機構規則集の公開分に名古屋大学分の審査委員会細則は見当たらない（岐阜大学大学発ベンチャー審査委員会細則のみ存在）。事務は第13条で学術研究・産学官連携推進本部イノベーション・アントレプレナーシップ推進室。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_equity_decider', 'established', '売却・新株予約権行使は経理責任者、議決権は財務担当理事', '東海国立大学機構株式等管理事務取扱細則（令和2年4月1日機構細則第58号）第4条で株式の売却は経理責任者が行い、第6条で新株予約権の行使も経理責任者が行う。第5条は機構が取得した株式の議決権は行使しないと定め、例外的な取扱いは財務を担当する理事が決定する。第3条で出納責任者等が銘柄ごとに株式等管理台帳を整備。取得そのものの決裁者を名指しした条文は同細則にも株式等取扱細則にも置かれていない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010787.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_amendment_decider', 'established', '総長（規程は総長が定めると規則に関する規程で明記）', '名古屋大学における規則に関する規程（令和2年4月1日制定、令和6年11月29日改正）第5条第1項で「規程は，本学又は部局の管理運営，教育研究等に関する事項について，総長が定めるものをいう」と定義。称号授与規程は規程第22号であるため改廃決裁者は総長。細則は第6条で総長又は部局の長が定める。審議機関の関与は同規程本文には書かれていない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010897.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_post_grad_limit', 'established', '1年以内（在職6年以上／在学2年以上が前提）', '名古屋大学発ベンチャー称号申請ページの申請資格で、過去の職員は本学に6年以上在職し、退職から称号授与に係る企業の設立までの期間が1年以内、過去の学生は本学に2年以上在学し、卒業等から企業設立までの期間が1年以内と明記。称号授与規程第3条第1項第3号は「過去に役員，職員又は学生であった者」のうち「別に定める者」とだけ書き、年数はこの申請ページ側の別定めで規定されている。', 'official', 'https://www.aip.nagoya-u.ac.jp/venture/nu-venture-application', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_renewal_rule', 'established', '更新可（審査あり）・5年ごとに審査委員会審査', '称号授与規程第6条第2項で授与日から5年、更新することができると規定。第6条第4項で「期間を更新しようとする企業の代表者は，総長に申請しなければならない」とし、当該申請の審査は第5条第2項から第4項（総長が審査委員会へ付託、委員会が審査、総長が決定）を準用する。届出のみの更新ではなく初回と同じ審査を通す。学生ベンチャーは第6条第3項で在学期間が上限。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_naming', 'established', '大学発ベンチャー（名古屋大学発ベンチャー／同学生ベンチャー）', '称号授与規程第2条で称号は「名古屋大学発ベンチャー」と、現在の学生が設立者または設立に深く関与する場合の「名古屋大学発学生ベンチャー」の2種類。第6条第1項で名古屋大学発ベンチャー称号記（別記様式第1号）または名古屋大学発学生ベンチャー称号記（別記様式第2号）の交付をもって授与する。スタートアップの語は称号名には使われていない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_support_period', 'established', '支援ごとに別に定める（施設は最長5年・更新審査あり）', '称号授与規程第12条は支援を列挙するのみで支援期間を定めていない。施設は名古屋大学インキュベーション施設側で原則2年、更新（要審査）2年＋1年の最長5年と定め、入居資格は称号授与済みかつ設立10年以内。称号期間は第6条で5年・更新可。したがって称号期間と支援期間は連動せず、支援ごとに別の期間と審査が置かれている。', 'official', 'https://incubation.aip.nagoya-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_support_contents', 'established', '施設貸付・商業登記・郵便収受・ロゴ使用・紹介仲介・広報・イベント案内', '称号授与規程第12条各号の列挙。(1)本学内に施設を確保し貸付、(2)1月以上の長期貸付をした施設を所在地とする商業登記の承認、(3)郵便物等の収受の便宜、(4)ロゴ使用権（称号授与企業であることを示す用途のみ）、(5)学術研究・産学官連携推進本部による他企業等への紹介・仲介、(6)本学主催イベント・広報誌での広報、(7)ベンチャー支援関係イベントの案内、(8)その他総長が必要と認めた支援。別途、スタートアップ準備資金、GAPファンドプログラム、モノづくりベンチャー活動支援金が資金支援として公開されている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ad192eae70e9', 'attr_source_docs', 'established', 'https://public1.legalcrud.com/thers_ac/act/110001334.html・https://www.aip.nagoya-u.ac.jp/venture/nu-venture-application…', '読む順序は、(1)名古屋大学発ベンチャー称号授与規程（称号・審査委員会・使用制限・取消・年次報告・支援の本体）、(2)名古屋大学発ベンチャー称号申請ページ（退職卒業後1年以内などの申請資格の別定めと提出書類）、(3)東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則（知財実施料に代わる株式・新株予約権の取得と持株制限）。施設の実務条件は名古屋大学インキュベーション施設サイトが持つ。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110001334.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_cert_update', 'unknown', null, '大学発ベンチャーの認定・称号制度そのものが公開情報に見当たらない。社会連携センターPLATのアントレプレナーシップ教育ページ、産官学連携・研究支援サイト（MRCS）のメニュー、知的財産ポリシー全文のいずれにも認定の記載がない。大学基本情報の規程ページで公開されているのは名城大学学則・大学院学則・学位規程のみで、認定期間や更新審査、要件再確認を定める規程を確認できない。', 'official', 'https://www.meijo-u.ac.jp/about/outline/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_title_restriction', 'unknown', null, '称号制度が公開されていないため、品質保証・投資推奨・経営状態保証と誤認させない旨の条項や、称号の使用範囲・使用停止を定めた文書を確認できない。知的財産ポリシー（平成16年6月11日制定、令和7年4月1日施行、全3ページ）にも称号や表示に関する条項はなく、PLATの起業支援ページ、MRCSの産官学連携メニューにも記載がない。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_cancellation', 'unknown', null, '認定制度が公開されていないため、取消事由・称号返付・表示削除・営業利用停止を定めた条項を確認できない。大学基本情報の規程ページで公開されているのは学則・大学院学則・学位規程のみ。知的財産ポリシーにも取消に関する条項はない。', 'official', 'https://www.meijo-u.ac.jp/about/outline/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_report_change', 'unknown', null, '認定制度が公開されていないため、年次報告や代表者・所在地・資本構成の変更届、解散時報告を求める規定を確認できない。MRCSが掲げる産官学連携メニュー（受託研究・共同研究・学術コンサルティング、共同研究実績、奨学寄附金、知的財産、LED共同研究センター、NanoTerasu、分析センター、産官学連携Q&A）にも該当する届出の記載がない。', 'official', 'https://sangaku.meijo-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_support_request', 'unknown', null, '［自動検証で否認: shakeの予約申込詳細がM-STUDIO文書に記載なし］元の主張(established): 施設・機器ごとの個別申込制、Fab機器は事前講習が条件。起業活動拠点ものづくりスペースM-STUDIOの利用ルールで、打ち合わせエリア等の拠点利用は原則予約不要、Fab機器の利用は事前申込制で職員滞在時のみ可、3Dプリンター（熱溶解式・光造形式）、レーザーカッター、UVプリンター、3Dスキャナーは事前の利用者講習受講とライセンス取得が必要と定める。社会連携ゾーンshakeのプロジェクトルームは予約申込書のメール送付で申し込む。認定を前提とせず、支援ごとに個別の申込で運用されている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_facility_registration', 'not_started', '施設は無償利用可、営利目的利用は禁止で登記制度なし', 'M-STUDIO利用ルールは利用可能者を「本学の学生/教職員」「Tongaliプロジェクトによるプログラム参加者」「企業・自治体・NPOの方で本学とプロジェクトにて連携する方」に限定し、Fab機器の注意事項で「販売目的での施設利用は禁止です」と明記する。＜利用に際しての制限事項＞の第2号は「営利を目的に利用するとき」を利用制限事由に挙げる。スペースや設備利用は無料だが、商業登記を認める制度の記載はない。', 'official', 'https://plat.meijo-u.ac.jp/assets/documents/%E5%88%A9%E7%94%A8%E6%A1%88%E5%86%85M-STUDIO.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_vc_connection', 'not_started', 'VC・金融機関への紹介制度なし', 'PLATのアントレプレナーシップ教育ページが列挙する支援（正課3科目、EXPLORER・HackU・iMPACT・DONUTS等の正課外、MEIJO STARTUP CLUB等のコミュニティ、M-STUDIO・shake）にVC・金融機関・自治体・外部支援機関への紹介導線はない。MRCSの産官学連携メニューにも紹介制度はない。Tongaliの起業・ベンチャー支援は資金調達支援を掲げるが、名古屋大学・東海地区大学広域ベンチャーファンドと「東海広域5大学」を冠するスタートアップ準備資金の枠組み。', 'official', 'https://plat.meijo-u.ac.jp/entrepreneurship/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_eir', 'not_started', '客員起業家制度なし、研究員制度は教員の派遣のみ', 'MRCSの研究員制度ページに置かれているのは在外研究員と国内研究員で、いずれも本学教員が国外・国内の機関で研究するための派遣制度。客員起業家・起業家メンター・起業家人材の招聘に関する記載はない。PLATのアントレプレナーシップ教育ページの支援列挙にもEIRはなく、アクセラレーションプログラムDRAFTはメンターとのマッチングによる3か月の伴走にとどまる。', 'official', 'https://sangaku.meijo-u.ac.jp/support/researchers', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_cxo_pool', 'not_started', '経営人材の紹介制度なし、メンター伴走のみ', 'PLATのアントレプレナーシップ教育ページが列挙する支援にCEO・CXO候補の紹介やマッチングはない。アクセラレーションプログラムDRAFTはメンターへのアイデア提示→メンターマッチ→3か月の実行という構成で、支援内容はメンタリング、shakeプロジェクトルームの3か月無償利用、PLATネットワークへの接続であり、経営人材の派遣・就任は含まれない。', 'official', 'https://plat.meijo-u.ac.jp/draft', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_ip_equity', 'established', '知財の実施許諾対価として新株予約権・株式の受領可', '名城大学知的財産ポリシー（平成16年6月11日制定、令和7年4月1日施行）3.(2)「スタートアップへの知的財産のライセンス」に「スタートアップの多くは、手元資金が乏しいことに配慮して、知的財産権の実施許諾や権利の移転等の対価として、新株予約権や株式を受け取ることを選択肢の一つとする」と明記。同項は本学知財を活用して起業したスタートアップへの優先的な実施許諾・権利移転を原則とし、独占的通常実施権の許諾など専有的な実施への配慮も定める。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'pol_fund_investment', 'not_started', '大学ファンド・出資制度なし', 'MRCSの産官学連携メニューにも、PLATの起業支援メニューにも、大学VC・LP出資・指定ファンド・大学出資会社に関する記載がない。知的財産ポリシーが定めるのは知財の対価としての新株予約権・株式の受領までで、大学からの出資は規定していない。Tongaliの起業・ベンチャー支援が挙げる名古屋大学・東海地区大学広域ベンチャーファンド、同2号ファンド、東海広域5大学ベンチャー起業支援スタートアップ準備資金は、いずれも名称のとおり別大学群を対象とする枠組み。', 'official', 'https://tongali.net/x/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_regulation_owner', 'unknown', null, '認定規程そのものが公開情報に見当たらない。大学基本情報の規程ページで公開されているのは名城大学学則・名城大学大学院学則・名城大学学位規程のみで、産学連携・知的財産・ベンチャー・兼業・利益相反の規程本文は公開されていない。知的財産ポリシーは「名城大学知的財産ポリシー」として大学名義で定められているが、認定規程の主体（大学規程か学校法人規程か）を判断する根拠にはならない。', 'official', 'https://www.meijo-u.ac.jp/about/outline/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_review_body', 'unknown', null, '認定の審査主体を定めた文書を確認できない。参考として、知的財産の窓口は学術研究支援センターに置く技術移転・知財管理担当者で、発明届は発明評価小委員会および学術研究審議委員会で審査すると知的財産のページに記載がある。起業支援の窓口は社会連携センター（事務室は天白キャンパス タワー75）。いずれも大学発ベンチャーの認定審査を担う旨の記載はない。', 'official', 'https://sangaku.meijo-u.ac.jp/collaboration/ipr', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_equity_decider', 'unknown', null, '知的財産ポリシー3.(2)は対価として新株予約権や株式を受け取ることを選択肢の一つとすると定めるだけで、取得・処分の決裁者を書いていない。同ポリシー5.「知的財産権の管理と活用のための体制・組織」は学術研究支援センターに技術移転・知財管理担当者を置くまでの規定で、決裁権限の定めはない。株式取扱いに関する規程は公開されていない。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_amendment_decider', 'unknown', null, '知的財産ポリシー6.「進展する情勢への適応」は「国内外の知的財産制度や社会の変化を踏まえて、本ポリシーを、適宜、見直して改訂することとする」と定めるのみで、改廃を決める主体を明記していない。附則は平成16年6月11日施行と令和7年4月1日施行の2本。他の規程本文が公開されていないため、制定改廃の決裁者を確認できない。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_post_grad_limit', 'unknown', null, '認定制度が公開されておらず、退職・卒業後の起業をいつまで対象にするかの規定を確認できない。公開されている支援は在学生か年齢で対象を切っており、EXPLORERは学生、DRAFTはU35（35歳未満）、M-STUDIOの利用可能者は本学の学生・教職員、Tongaliプログラム参加者、本学と連携する企業・自治体・NPO。卒業後の年数で線を引く記載はない。', 'official', 'https://plat.meijo-u.ac.jp/assets/documents/%E5%88%A9%E7%94%A8%E6%A1%88%E5%86%85M-STUDIO.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_renewal_rule', 'unknown', null, '認定制度が公開されていないため、更新の可否や方法（審査あり／届出のみ／再申請）を定めた規定を確認できない。大学基本情報の規程ページで公開されているのは学則・大学院学則・学位規程のみで、知的財産ポリシーにも認定の更新に関する条項はない。', 'official', 'https://www.meijo-u.ac.jp/about/outline/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_naming', 'unknown', null, '大学発ベンチャー・大学発スタートアップいずれの称号も公開情報に見当たらない。知的財産ポリシーは2.(2)「スタートアップの起業に必要な権利の確立」、3.(2)「スタートアップへの知的財産のライセンス」と「スタートアップ」の語で統一し、PLATは「起業」「アントレプレナーシップ」を用いるが、いずれも称号ではなく一般名詞としての用法。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_support_period', 'unknown', null, '［自動検証で否認: EXPLORER3か月の記載が原文になし］元の主張(established): 支援ごとに別に定める。EXPLORER・DRAFTとも3か月。称号制度がないため称号期間との対比はできない。支援期間はプログラムごとに定められており、EXPLORERベーシックは3か月の短期集中型、アクセラレーションプログラムDRAFTはメンターマッチ後に3か月の実行期間とshakeプロジェクトルームの3か月無償利用。M-STUDIOは利用時間（月曜〜金曜の12時00分〜20時00分）の定めのみで、利用期間の定めはない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 活動費・チーム数等の数値が原文に記載なし］元の主張(established): EXPLORER・DRAFT・M-STUDIO・shake・知財の優先実施許諾。PLATのアントレプレナーシップ教育ページとMRCSの掲載内容から。EXPLORERはベーシック（3か月短期集中）とアドバンスト（約5チームに各10万円程度の活動費、M-STUDIO利用、専門家メンタリング、月1回のピッチ会）。DRAFTはU35対象で3か月のメンター伴走とshakeプロジェクトルームの無償利用。M-STUDIOはFab機器を無料で使え材料費のみ自己負担。知的財産ポリシー3.(2)はスタートアップへの優先的な実施許諾と独占的通常実施権への配慮を定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_c8343bcae1a5', 'attr_source_docs', 'established', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf・https://plat.meijo-u.ac.jp/entrepreneurship/・https…', '1本目は名城大学知的財産ポリシー（令和7年4月1日施行、全3ページ）で、スタートアップへの優先的実施許諾と新株予約権・株式による対価受領を定める唯一の一次規程。2本目は社会連携センターPLATのアントレプレナーシップ教育ページで、起業支援メニューの列挙元。3本目はM-STUDIO利用ルールで、利用可能者の範囲と営利目的利用の制限を定める唯一の施設規程。認定規程は公開されていない。', 'official', 'https://sangaku.meijo-u.ac.jp/wp/wp-content/uploads/2025/09/IP_1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_cert_update', 'established', '一定期間の認定、期間経過・成長で卒業', '「国立がん研究センター発ベンチャー」ページに「一定期間認定しています」「設立または認定から一定期間が経過したベンチャー企業や、十分な成長を遂げた企業については、センター発ベンチャーとしての認定を卒業する」と明記。ただし認定年数、更新の可否、更新審査、要件の再確認手続は公開されていない。同ページの卒業一覧では2015年9月・10月認定の2社が2025年7月2日・2026年4月9日卒業と記載されており、運用上の認定期間は約10年。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_title_restriction', 'unknown', null, '認定ページは「認定ロゴマークを作成しました」と記すのみで、称号・ロゴの使用範囲、使用条件、使用停止、品質保証や投資推奨・経営状態の保証と誤認させない旨の条項は公開されていない。情報公開ページの規程一覧（役員報酬規程、業務方法書、会計規程、法人文書管理規程など13件）にも、法人文書ファイル管理簿（令和7年度）にもベンチャー認定規程は掲載がなく、条文を確認できない。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_cancellation', 'unknown', null, '認定の取消事由、称号・ロゴの返付、表示削除、営業利用停止の規定は公開情報になし。認定ページにあるのは「卒業」の運用と卒業日のみで、取消の記載はない。NCC SAP募集要項9.(2)は補助事業の「採択取り消し」6事由（必要書類の不提出、付与条件の不充足、公募要件の不充足など）を定めるが、これは支援課題の採択取消であって称号の取消ではない。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_report_change', 'unknown', null, '認定ベンチャーに対する年次報告、代表者・所在地・資本構成の変更届、解散時報告の規定は公開情報になし。NCC SAP募集要項7.(4)は支援課題に半年ごとの書面による支援継続審査と、複数年支援の場合は年ごとの対面進捗審査を課し、9.(1)は他の競争的資金に採択された場合の事務局報告を求めるが、これは支援課題の義務で認定制度の報告義務とは別。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/libs/files/startup_r7_v2_requirements_260121.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_support_request', 'established', '共同研究審査委員会・SAP評価委員会など支援ごとに別申請', '産学連携・知財戦略課Q&Aは、共同研究の開始には共同研究取扱規程を踏まえた共同研究審査委員会の審査が必要と記載。NCC SAP募集要項7.(1)は「NCC SAPが事務局となる評価委員会」が選考基準を勘案して採択すると定める。中央病院の医療系ベンチャー等相談は、所定の相談申請フォーマット提出→事前相談（無料）→本相談（有料）実施可否の審議、という手順を公開。いずれも称号認定とは別建ての申請・審査。', 'official', 'https://www.ncc.go.jp/jp/ncch/division/clinical_research_support/research_management/ncch_venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_facility_registration', 'not_started', 'スタートアップ専用ラボ・貸室なし', 'NCC SAPよくあるご質問に「現時点ではこのプログラム専用のラボ設備はご用意できていません。使用を希望される場合には、NCC内のラボと交渉することになります」と明記。施設・実験機器の利用は共同研究契約を締結した場合に内容次第で可能で、費用も契約締結時に実施内容に従って個別決定とされる。センター内での商業登記（本店登記）の受入れに関する公開情報はなし。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/faq/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_vc_connection', 'established', 'NCC VIPでUTECと協働、VC・製薬企業とのマッチング', '2021年3月11日プレスリリースは、東京大学エッジキャピタルパートナーズ（UTEC）と共同でNCC Venture Incubation Programを2021年4月から開始し、UTECの経営支援機能を相補的に活用、ベンチャーキャピタル・製薬会社・医療機器メーカー等とのマッチング機会を作り、開始後半年から1年以内にピッチングイベントを開催すると記載。NCC SAP募集要項7.(3)はJETRO海外展開プログラムとTMC主催J-ACTでの米国投資家向けピッチを掲げる。', 'official', 'https://www.ncc.go.jp/jp/information/pr_release/2021/0311/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_eir', 'established', 'NCC SAPの起業家レジデント制度、VIPのレジデントタイプ', '「NCC SAPとは」は、CXO人材・グローバル資金調達・カンパニークリエーションの課題を「日本型カンパニークリエーションモデル、企業家レジデント制度、海外展開支援の3つの取り組み」で解決すると記載。2021年3月11日プレスリリースは、NCC VIPの教育プログラムを共同研究タイプと、ベンチャーメンバーをセンターの職員として雇用する「レジデントタイプ」に分けて実施すると記載。募集要項や運用要領は非公開。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/about/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_cxo_pool', 'established', 'サイエンス系CXO人材の整備を事業目的に明記', '「NCC SAPとは」は整備項目の3として「サイエンスのバックグラウンドを持つCXO人材」を掲げ、日本型カンパニークリエーションモデル・企業家レジデント制度・海外展開支援の3つの取り組みで解決するとする。2021年3月11日プレスリリースはNCC VIPで「開発に関するノウハウや人材等の提供」を行うと記載。個別のCEO/CXO候補紹介・マッチングの要項や人材プール名簿は公開されていない。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/about/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_ip_equity', 'established', '認定ベンチャーの新株予約権・株式を取得保有（活性化法34条の5）', '組織COI情報公開に「NCCは、ARC Therapies株式会社を法人発ベンチャーとして認定しており、科学技術・イノベーション創出の活性化に関する法律第34条の5第1項及び第2項を根拠として、同社の発行した新株予約権、株式等を取得・保有する」（開始日2024年9月28日）と記載。ただし実施許諾の対価として取得したかは非公表。NCC SAP募集要項9.(3)は伴走支援の成功報酬として新株予約権を想定した仕組みの導入を検討中と記す。', 'official', 'https://www.ncc.go.jp/jp/about/disclosere/COI.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'pol_fund_investment', 'not_started', '出資行為なし、自前ファンド・出資会社の公表なし', '組織COI情報公開（更新日2026年5月11日）に「NCCによる出資行為について 現在、企業に対して出資行為を行っておりません。」と明記。同ページが根拠に挙げる科学技術・イノベーション創出の活性化に関する法律第34条の5は株式・新株予約権の取得の根拠としてのみ使われており、認定VC・LP出資・指定ファンド・出資会社の設置に関する公開情報はない。業務方法書にも出資に関する条項はない。', 'official', 'https://www.ncc.go.jp/jp/about/disclosere/COI.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_regulation_owner', 'established', '研究機関規程（国立研究開発法人国立がん研究センター）', '認定制度は国立研究開発法人国立がん研究センターが単独で運用し、大学・学校法人は関与しない。2021年3月11日プレスリリース用語解説3は「国立がん研究センターの役職員が成し得た知的財産権や研究成果等を活用するために設立したベンチャーからの申請に対し、ベンチャー認定委員会に諮問の上…『国立がん研究センター発ベンチャー』と認定される」と記載。規程本体は情報公開ページの規程一覧に掲載がなく、名称・条文は非公開。', 'official', 'https://www.ncc.go.jp/jp/information/pr_release/2021/0311/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_review_body', 'established', 'ベンチャー認定委員会、事務局は産学連携・知財戦略課', '2021年3月11日プレスリリース用語解説3が「ベンチャー認定委員会に諮問の上」と明記。法人文書ファイル管理簿（令和7年度）には2021年度から2025年度まで毎年度「ベンチャー認定委員会」の委員会議事要旨が登録され、作成・保存部署は産学連携・知財戦略室（2024年度以降は産学連携・知財戦略課）、保存期間20年とされている。委員構成・定足数・審査基準は非公開。', 'official', 'https://www.ncc.go.jp/jp/about/org/joho/R7kanribo.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_equity_decider', 'unknown', null, '株式・新株予約権の取得や処分を誰が決裁するかは公開情報になし。組織COI情報公開は保有の事実と法的根拠（科学技術・イノベーション創出の活性化に関する法律第34条の5第1項及び第2項）のみを示し、決裁機関に触れていない。業務方法書にも株式・出資に関する条項はなく、情報公開ページの規程一覧にも該当規程がない。', 'official', 'https://www.ncc.go.jp/jp/about/disclosere/COI.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_amendment_decider', 'unknown', null, '認定規程の制定改廃を決める主体は公開情報になし。業務方法書は「理事長を頂点とした意思決定ルールの明確化」「理事長の意思決定を補佐する理事会の設置」を掲げるのみで、規程の制定改廃手続を定めていない。情報公開ページの規程一覧にもベンチャー認定関係の規程はなく、改廃条項を確認できない。', 'official', 'https://www.ncc.go.jp/jp/about/org/joho/gyomuho.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_post_grad_limit', 'unknown', null, '認定対象は「センターの役職員が創出した知的財産権や研究成果等を活用するために設立されたベンチャー企業」とされるのみで、退職後・卒業後何年以内の起業まで対象にするかの記載はない。2015年の初期認定2社も在職中の分野長が関与する企業として紹介されており、退職者による起業の扱いは公開情報になし。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_renewal_rule', 'unknown', null, '認定は「一定期間」とされ、期間経過や十分な成長で「卒業」する運用のみが公表されている。更新の可否、更新時が審査か届出か、再申請できるかはいずれも公開情報になし。卒業した2社について再認定や再申請の記載もない。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_naming', 'established', '独自名称「国立がん研究センター発ベンチャー」', '称号は「国立がん研究センター発ベンチャー」で、大学発ベンチャー・大学発スタートアップの語は使わない。認定企業であることを示す認定ロゴマークを作成・掲載。認定企業は凜研究所、Jmees、Surg storage、ARC Therapies（旧Sustainable Cell Therapeutics）、DELISPECTの5社、卒業企業はノイルイミューン・バイオテックと朝日サージカルロボティクス（旧A-Traction）の2社を実名で一覧掲載。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_support_period', 'established', '支援ごとに別に定める（称号は一定期間、SAPは2〜3年）', '称号は「一定期間」の認定。NCC SAP募集要項6は支援期間をS0最長2年、S1原則2年（ステージゲートでGoの場合最長3年）、S2最長2年と支援区分ごとに定め、半年ごとの評価で途中中止もあり得るとする。2021年3月11日プレスリリースはNCC VIPを原則4月1日から翌3月31日までの1年間のプログラムと記載。研究設備の利用や実施許諾は共同研究契約・ライセンス契約で別途期間を定める。', 'official', 'https://www.ncc.go.jp/html/ncce/sap/libs/files/startup_r7_v2_requirements_260121.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_support_contents', 'established', '設備利用・知財許諾・シーズ開発支援・ロゴ使用・研究費・伴走支援・教育・海外展開', '認定ページは「研究設備の利用、知的財産権の実施許諾、シーズ開発支援等」と認定ロゴマークの使用を挙げる。NCC SAP募集要項6・7は、委託研究費の配分（S0最大年1,000万円、S1最大年3,000万円、S2最大年1億5,000万円、間接経費は直接経費の10％以内）、プロジェクトマネージャー複数名による伴走支援と月1回の面談、メンターネットワーク、月2回6〜7か月の教育プログラム、JETRO海外展開プログラムとTMC主催J-ACT、AMEDのシーズDB（BRIDGE）登録を挙げる。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_18402bd4d9e6', 'attr_source_docs', 'established', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html・https://www.ncc.go.jp/html/ncce/sap/libs/files/startup_r7_v2_re…', '1本目が認定制度の唯一の公式説明ページで、認定要件の概略、支援内容、認定ロゴマーク、認定5社・卒業2社の一覧と卒業日を掲載。2本目が令和7年度第2回公募の募集要項で、支援ステージ・支援額・支援期間・伴走支援・教育プログラム・海外展開支援・採択取消・成功報酬（新株予約権）の検討を記載。3本目が組織COI情報公開で、新株予約権・株式の保有と法的根拠、出資行為を行っていない旨を明記。', 'official', 'https://www.ncc.go.jp/jp/cras/chizai/venture/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_cert_update', 'established', '有効期間5年、申請により5年延長、延長も委員会審査', 'ベンチャー支援規程（令4規程第1号）第5条「その有効期間は認定の日から５年間とする。なお、有効期間については、申請に基づく延長が可能なものとし、その有効期間はさらに５年とする」。第4条第1項が「認定又は認定期間の延長を希望する者」を同一の申請手続に置き、第2項から第4項で理事長がベンチャー審査委員会に諮問し、委員会の審査と必要に応じた面接を経た答申に基づき理事長が可否を決定する。延長時も第5条各号の認定要件が再確認される建て付け。延長回数の上限は定められていない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_title_restriction', 'established', '第7条で法的責任を否認、保証誤認防止・使用範囲の定めなし', 'ベンチャー支援規程第7条（研究所の法的責任）は「国環研ベンチャーの認定及び称号の付与は、研究所に何ら法的責任を生じさせるものではない」と定めるのみ。品質保証・投資推奨・経営状態の保証と誤認させない旨の明示条項、称号の表示方法や使用範囲を限定する条項、使用停止を命じる条項は置かれていない。称号の使用は第6条第1項第6号で支援メニューの1つとされるだけで、停止規定は第9条第2項の取消後の禁止のみ。ロゴマークは別規程（ロゴマーク使用規程第5条第2項・第3項）で理事長の事前許可制であり、称号とは別扱い。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_cancellation', 'established', '取消事由4号、取消後の称号利用禁止、本人申出の解除も可', 'ベンチャー支援規程第9条第1項が取消事由を4号列挙する。第5条要件の不充足、研究所の事業活動の円滑な実施への支障、社会的信用を失墜する行為、研究所の不名誉となるおそれ等で、理事長が認定を取り消すことができる。第9条第2項は「取消しを受けた日以降、国環研ベンチャーとしての認定及び称号を使用していた事実を利用し、事業を行ってはならない」と営業利用を禁じる。第10条は認定を受けた側からの解除申出を認める。認定証の返付手続きや既存の表示物・広報物の削除義務は規定されていない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_report_change', 'established', '6月ごとの事業報告、増減資・解散・破産等は速やかに報告', 'ベンチャー支援規程第8条第1項「認定時にあらかじめ指定した日及びその後６月を経過するごとに、任意の形式により事業の状況について報告しなければならない」。年次ではなく半期ごとで、様式は任意。第8条第2項は「増資、減資、解散、破産、再生手続き、更生手続き等の事実があった場合には、速やかにその旨を理事長に報告しなければならない」と定め、資本構成の変動と解散・倒産を捕捉する。代表者の交代や所在地の変更を単独で届け出る義務、決算書等の提出義務は規定されていない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_support_request', 'established', '個別申請様式なし、審査委員会が支援内容を審議し個別契約', 'ベンチャー支援規程第3条第1項はベンチャー審査委員会の審議事項に「国環研ベンチャーへの支援内容」を含め、認定審査と一体で支援内容を決める。第4条第1項の申請書は「国立研究開発法人国立環境研究所ベンチャー認定申請書」1種で、事業内容と使用する知的財産等に関する書類を添付する。施設・登記・機器・広報・紹介ごとの個別申請様式や個別審査は置かれていない。第6条第2項が「支援措置の内容、条件等について契約を締結し、契約書を取り交わす」と定め、実際の支援内容は個別契約で確定する。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_facility_registration', 'established', '所内の事務室・研究室を無償貸与し、その住所で商業登記可', 'ベンチャー支援規程第6条第1項第1号「事務室又は研究室としての場所を研究所内に確保し、国立研究開発法人国立環境研究所固定資産等管理事務取扱細則（令２細則第１号）第２８条の定めるところにより、無償で貸与すること」。同項第2号「取扱細則第２８条又は第２９条の定めるところにより、前号により貸与した事務室又は研究室の住所を国環研ベンチャーの登記の住所とすることを認めること」。施設の無償貸与と商業登記が同一条で一体的に手当てされている。取扱細則本体は公開規程集に掲載がなく条文は未確認。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_vc_connection', 'established', '資金調達支援・専門家紹介どまり、VC等の接続先の明示なし', 'ベンチャー支援規程第6条第1項第5号が「会社設立支援、事業計画策定支援、資金調達支援、研究開発支援、販売販路開拓支援、専門家の紹介及び会社経営に関するセミナーについての情報の提供等を行うこと」を支援に挙げる。資金調達支援と専門家紹介は制度として明記されるが、ベンチャーキャピタル、金融機関、自治体、外部支援機関を接続先として名指しした条項はない。産学連携トップページと国環研ベンチャー紹介ページにも、VC・金融機関との連携や紹介の記載は見当たらない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_eir', 'not_started', '客員起業家・起業家メンターの制度なし（客員研究員のみ）', 'ベンチャー支援規程第6条第1項は支援を6号に限定列挙し、客員起業家（EIR）や起業家メンターの招聘は含まない。公開規程集の研究推進区分にある人材招聘規程は客員研究員規程・共同研究員規程・研究生受入規程・インターンシップ生受入規程で、客員研究員規程第2条は対象を「国内外の研究機関の研究員又は大学の教員等」で相当の研究実績を有する者に限り、委嘱期間も第4条で1事業年度を限度とする。起業家人材を招く枠組みではない。産学連携サイトにもEIRの記載なし。', 'official', 'https://www.nies.go.jp/about/disclosure/kitei/kt_kenkyuk.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_cxo_pool', 'not_started', '経営人材の紹介・マッチング制度なし（専門家紹介のみ）', 'ベンチャー支援規程第6条第1項の限定列挙に、CEO・CXO候補の紹介やマッチングは含まれない。第5号の「専門家の紹介」は会社設立・事業計画策定・資金調達・販路開拓の助言に付随する紹介で、経営人材プールの構築や派遣を定めた条項ではない。第5条第1項第2号は「希望者の創業者又は当該事業について責任を有する者」が事業に必要十分な知識を有することを認定要件とし、経営人材は申請者側で確保する前提に立つ。産学連携サイトにも人材紹介制度の記載はない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_ip_equity', 'not_started', '規程・運用なし。ただし国環研法第11条の2で法律上は取得可', 'ベンチャー支援規程第6条第1項第4号は知財活用の対価を「実施料の無償化又は支払いの一定期間の猶予若しくは免除等」と金銭で組み立て、株式・新株予約権を対価とする定めを置かない。知的財産取扱規程第31条から第35条の実施許諾・譲渡、第7条の補償も金銭前提。一方、国立研究開発法人国立環境研究所法第11条の2は科技イノベ活性化法第34条の5第1項・第2項による株式又は新株予約権の取得及び保有を認める。同法第34条の4第3項の無償化・低廉化措置が取得の要件で、支援規程第6条第1項第1号・第3号・第4号はまさにその措置に当たる。法律上の前提は満たすが内部規程が未整備。', 'official', 'https://laws.e-gov.go.jp/api/1/lawdata/411AC0000000216', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'pol_fund_investment', 'not_started', '出資規程・ファンドなし。ただし法律上は出資が業務の範囲', '公開規程集に出資・投資・ファンドに関する規程はなく、ベンチャー支援規程第6条の支援にも出資は含まれない。他方、国立研究開発法人国立環境研究所法第11条第1項第3号は業務の範囲として「科学技術・イノベーション創出の活性化に関する法律第三十四条の六第一項の規定による出資並びに人的及び技術的援助のうち政令で定めるものを行うこと」を掲げ、同法別表第三第二十六号に国立環境研究所が掲載されている。同条第1項は成果活用事業者、投資事業有限責任組合を含む資金供給等事業者、成果活用促進者への出資を認め、第2項で第2号・第3号への出資は主務大臣の認可を要する。', 'official', 'https://laws.e-gov.go.jp/api/1/lawdata/420AC0100000063', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_regulation_owner', 'established', '研究機関規程（国立研究開発法人の内部規程・令4規程第1号）', '国立環境研究所は国立研究開発法人であり（国立研究開発法人国立環境研究所法第3条の2）、大学・学校法人ではない。認定の根拠は「国立研究開発法人国立環境研究所ベンチャー支援規程」（令和4年11月1日制定・施行、令4規程第1号）1本で、法人の内部規程として制定されている。認定・審査・支援・報告・取消しを全13条の同一規程内で完結させ、他規程への委任は固定資産等管理事務取扱細則（施設貸与・登記）と兼業等規程（役職員の関与）に限られる。公開規程集には掲載がなく、産学連携サイト上でのみ公開されている。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_review_body', 'established', '国立研究開発法人国立環境研究所ベンチャー審査委員会', 'ベンチャー支援規程第3条第1項が「国環研ベンチャーの認定、認定の取消し、国環研ベンチャーへの支援内容及びその他の検討事項を審議するため、研究所に国立研究開発法人国立環境研究所ベンチャー審査委員会を置く」と定める。第4条で理事長が申請の審査を同委員会に諮問し、委員会が審査と必要に応じた面接を行って理事長に答申、理事長が認定の可否を決定する。委員会の運営等に必要な事項は第3条第2項で「別に定める」とされ、単独の規程は公開されていない。主管部署は第12条で連携推進部研究連携・支援室。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_equity_decider', 'not_started', '決裁ルールなし（内部規程に株式・新株予約権の定めがない）', 'ベンチャー支援規程・知的財産取扱規程のいずれにも株式・新株予約権の取得や処分に関する条項がなく、決裁者の定めもない。公開規程集にも出資・株式に関する規程、決裁規程、職務権限規程の掲載がない。参考として、国立環境研究所法第11条の2による株式・新株予約権の取得には主務大臣の認可要件が付されていないのに対し、同法第11条第1項第3号の出資は科技イノベ活性化法第34条の6第2項により第2号・第3号の相手方について主務大臣の認可を要する。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_amendment_decider', 'unknown', null, 'ベンチャー支援規程には制定改廃を定める条項がなく、附則も「この規程は、令和４年１１月１日から施行する」のみ。規程番号「令4規程第1号」から法人の内部規程として制定されたことは分かるが、改廃の決裁主体を明示した公開文書は確認できなかった。業務の適正を確保するための基本規程（平成27規程第1号）第1条は役員の職務執行について「国立環境研究所理事会規程及び国立研究開発法人国立環境研究所職務権限規程」に拠るとするが、この2規程はいずれも公開規程集に掲載がなく条文を確認できない。', 'official', 'https://www.nies.go.jp/about/disclosure/kitei/kt_tekiseikakuho.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_post_grad_limit', 'not_started', '規定なし（創業者の身分要件・退職後年数の要件を置かない）', 'ベンチャー支援規程第5条は認定要件を5号に限定列挙し、事業が研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用すること、創業者又は事業責任者が必要十分な知識を有すること等を求めるのみで、創業者が現職の役職員か退職者かを問わない。退職後何年以内という期限もない。第6条第3項は役職員が活動を準備する段階での支援を認め、第4項は活動時は兼業等規程による兼業とする。参考として知的財産取扱規程第42条は、退職後に完成させた知財も研究所の資金・施設・設備等を用いた場合は研究所が相応の持分を有すると定める。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_renewal_rule', 'established', '更新可（審査あり）。延長申請も審査委員会の審査を経る', 'ベンチャー支援規程第5条は有効期間を認定の日から5年とし「有効期間については、申請に基づく延長が可能なものとし、その有効期間はさらに５年とする」と定める。第4条第1項が「国環研ベンチャーの認定又は認定期間の延長を希望する者」を同一の申請手続に置くため、延長も認定と同じく理事長からベンチャー審査委員会への諮問、委員会の審査・面接、答申、理事長の決定という経路をたどる。届出のみで更新される仕組みではない。延長回数の上限は定められていない。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_naming', 'established', '独自名称。称号は「国環研ベンチャー」、大学発の語は不使用', 'ベンチャー支援規程第2条第1項が「国環研ベンチャーとは、研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用するベンチャー企業であって、本規程に基づき国環研ベンチャーと称号することが認められたものをいう」と定義する。正式名称は国立研究開発法人国立環境研究所ベンチャーで、略称が国環研ベンチャー。国立研究開発法人であり大学ではないため、大学発ベンチャー・大学発スタートアップの呼称は用いていない。称号の使用自体が第6条第1項第6号で支援メニューの1つに位置づけられている。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_support_period', 'established', '個別契約（第6条2項で支援の内容・条件を契約書で定める）', 'ベンチャー支援規程は称号の有効期間を第5条で5年（延長でさらに5年）と定める一方、支援期間を独立して定める条項を置かない。第6条第2項が「研究所は、国環研ベンチャーとの間で、前項各号に掲げる支援措置の内容、条件等について契約を締結し、契約書を取り交わすものとする」と定めるため、施設・設備の貸与期間や知財の実施許諾期間は個別契約で決まる。第6条第1項柱書は支援全体に「研究所の業務に支障のない範囲で」という制約を付している。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_support_contents', 'established', '事務室・研究室の無償貸与・貸与住所での商業登記・研究設備等の無償貸与・知財の独占的または一部独占的な利用許諾と実施料の無償化や猶予・免除・会社設立支援・事業計画策定支援・資金調達支援・研究開発支援・販売販路開拓支援・専門家の紹介・経営セミ…', 'ベンチャー支援規程第6条第1項が支援を6号に限定列挙する。第1号が事務室・研究室の無償貸与（固定資産等管理事務取扱細則第28条）、第2号が貸与した室の住所での登記、第3号が研究設備等の無償貸与、第4号が知的財産の独占的又は一部独占的な利用の許諾と実施料の無償化・猶予・免除等、第5号が会社設立支援・事業計画策定支援・資金調達支援・研究開発支援・販売販路開拓支援・専門家の紹介・会社経営に関するセミナーの情報提供等、第6号が称号の使用。第3項で役職員の起業準備段階にも第5号の措置と第1号・第3号の検討が及ぶ。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_bbc28fa08564', 'attr_source_docs', 'established', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf・https://www.nies.go.jp/sangaku/startup/・https://www…', '制度の中核はベンチャー支援規程PDF1本で、認定要件・審査・支援・報告・取消しまで完結する。国環研ベンチャー紹介ページは申請フロー（産学連携窓口への相談、連携推進部研究連携・支援室への申請書提出、審査委員会、理事長決定）と認定企業一覧を載せる。規程集は知的財産取扱規程・知的財産ポリシー・兼業等規程・利益相反マネジメント実施規程など周辺規程の入口だが、ベンチャー支援規程自体は掲載されていない。株式・出資の法的根拠は国立環境研究所法と科技イノベ活性化法で、この2法はe-Gov法令検索が正本。', 'official', 'https://www.nies.go.jp/sangaku/assets/img/startup/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_cert_update', 'unknown', null, '共創機構が公開する「ポリシー・規程・様式」一覧（約90件）と大阪大学規程集の五十音索引を全て確認したが、大学発ベンチャーの認定規程・称号規程は存在しない。「大学発ベンチャー起業に係るFAQ（令和8年4月1日版）」にも認定申請・認定期間・更新審査の記載がない。テクノアライアンス棟利用規程第8条の利用期間（大学発ベンチャー活動は原則1年以上5年以下）は施設利用の期間であり、認定期間ではない。', 'official', 'https://www.ccb.osaka-u.ac.jp/policy/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_title_restriction', 'established', '営利目的の大学名表示は担当理事許可・事実表示に限定', '「国立大学法人大阪大学における学外者による名義及び学章の使用に関する取扱規程」（令和6年9月18日施行）第5条は、営利目的の名義使用を別表の事実内容に基づく表示方法に限り担当理事の許可制とする。別表は「大阪大学との共同研究」といった包括的表示を認めず、実施許諾・共同研究等の事実表示に限定する。第9条は使用基準違反・虚偽記載・本学の名誉毀損のおそれ等で許可取消・使用中止を定める。品質保証や投資推奨の誤認防止を直接明記した条項、別表への大学発ベンチャー表示類型の記載は無い。', 'official', 'https://www.osaka-u.ac.jp/ja/guide/files/qzg291/@@download/file', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_cancellation', 'established', '施設利用許可と名義使用許可の取消規定あり', 'テクノアライアンス棟利用規程第7条は、規程違反時に管理運営責任者が管理運営委員会の議を経て利用許可の変更・取消し・利用中止ができると定め、第8条第5項で期間満了・中止時の原状回復と明渡しを義務づける。名義及び学章の使用に関する取扱規程第9条は、使用基準違反・虚偽記載・本学の名誉毀損のおそれ等で名義使用の許可取消・使用中止を定める。認定制度が公開規程に無いため、称号の返付・表示削除・営業利用停止を定めた条項は確認できない。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_report_change', 'established', '施設利用者は年1回報告・変更申請が必要', 'テクノアライアンス棟利用規程第10条は、研究代表者に利用状況を管理運営責任者へ年1回報告する義務を課す。第6条は利用計画に重要な変更を加えるとき管理運営責任者へ変更申請し、管理運営委員会の議を経て可否が決まると定める。第8条第3項は利用中止・期間短縮を6月前までに申し出るとする。認定制度に対応する代表者・所在地・資本構成の変更届や解散時報告の規定は公開規程に見当たらない。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_support_request', 'established', '支援ごとに個別申請・審査（認定は前提でない）', '認定を前提とせず支援ごとに個別の申請・審査を置く。テクノアライアンス棟利用規程第5条は、所定の利用申込書を管理運営責任者へ提出し、テクノアライアンス棟管理運営委員会の議を経て利用の可否を決定すると定める。株式等取扱規則第3条は、知財対価としての株式等取得に共創機構の審査を要し、共創担当理事が事前に経理担当理事へ審査内容を通知するとする。役員兼業は総長の許可、弁護士相談は産学法務支援室への相談による。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_facility_registration', 'established', 'テクノアライアンス棟に入居可・C棟で本店登記可', 'テクノアライアンス棟利用規程第3条第3号は「本学で得られた研究成果を基に設立されたベンチャー」の役職員と、設立を目指す研究プロジェクトの研究開発者を利用資格者とし、第4条第3号で大学発ベンチャーの活動を利用目的に認める。第8条は当該利用の期間を原則1年以上5年以下、第9条は経費を原則利用者負担とする。FAQ（令和8年4月1日版）2(6)は「学内ではテクノアライアンスＣ棟を登記場所とすることができます」と明記する。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_vc_connection', 'established', '連携VC41社・年5回の連携VC連絡会', '共創機構「ベンチャー創成・社会実装支援」ページは、大阪大学ベンチャーキャピタル株式会社（OUVC）を含む連携VCが41社であること、年5回連携VC連絡会を開催し起業者が研究シーズの事業化構想を紹介する場を設けていることを記載する。金融機関・自治体・外部支援機関への紹介導線は同ページでは確認できない。', 'official', 'https://www.ccb.osaka-u.ac.jp/service/venture_shien/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_eir', 'established', '共創機構が客員起業家（EIR）を公募', '共創機構のお知らせ（2023年8月8日）は「大阪大学共創機構では客員起業家（EIR）を募集しております」として、OUエコシステム構築の一環で大学研究シーズを活用した大学発ベンチャー創成支援活動に従事し、自らも大学研究シーズを活用した起業を志す者を公募すると告知している。募集要件・期間・身分は公募要領に委ねられ、規程としてのEIR制度は公開規程一覧では確認できない。', 'official', 'https://www.ccb.osaka-u.ac.jp/news/%E5%A4%A7%E9%98%AA%E5%A4%A7%E5%AD%A6%E5%85%B1%E5%89%B5%E6%A9%9F%E6%A7%8B%E3%81%A7%E3%81%AF%E5%AE%A2%E5%93%A1%E8%B5%B7%E6%A5%AD%E5%AE%B6%EF%BC%88eir%EF%BC%89%E3%82%92%E5%8B%9F%E9%9B%86%E3%81%97/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_cxo_pool', 'unknown', null, '共創機構トップページ、「ベンチャー創成・社会実装支援」、「How to 起業」（2023年8月24日版）、Innovators'' Clubの各ページを読んだが、経営人材（CEO/CXO候補）を紹介・マッチングする制度の記載は無い。「How to 起業」は経営体制の留意点として、教職員のCEO兼務は兼業申請（総長決裁）を要し利益相反マネジメント上も極めて困難とし、CEO候補者の確保を起業側の課題として示すにとどまる。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2023/08/HowTo%E8%B5%B7%E6%A5%AD_20230824.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_ip_equity', 'established', '知財対価として株式・新株予約権を取得する規則あり', '「大阪大学における知的財産権等の運用又は処分の対価として取得する株式等の取扱いに関する規則」（平成21年4月27日制定、令和6年4月1日改正）第2条は、当該企業が対価相当の現金を保有しないとき等に対価の軽減措置を講じて株式・新株予約権を取得できると定め、第3条で共創機構の審査を要するとする。第4条は発明規程第16条第1項に基づく発明者への補償金支払を定める。取得禁止事由は第2条第2項に列挙。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%A4%A7%E9%98%AA%E5%A4%A7%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E7%9F%A5%E7%9A%84%E8%B2%A1%E7%94%A3%E6%A8%A9%E7%AD%89%E3%81%AE%E9%81%8B%E7%94%A8%E5%8F%88%E3%81%AF%E5%87%A6%E5%88%86%E3%81%AE%E5%AF%BE%E4%BE%A1%E3%81%A8%E3%81%97%E3%81%A6%E5%8F%96%E5%BE%97%E3%81%99%E3%82%8B%E6%A0%AA%E5%BC%8F%E7%AD%89%E3%81%AE%E5%8F%96%E6%89%B1%E3%81%84%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E5%89%87%EF%BC%88R4.1%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'pol_fund_investment', 'established', 'OUVC（100%出資子会社）がOUVC1号・2号ファンドを運営', '共創機構「出資会社」ページは、大阪大学ベンチャーキャピタル株式会社（OUVC、2014年12月設立、100%出資子会社、文部科学大臣認可）が産業競争力強化法の特定研究成果活用支援事業者として、OUVC1号投資事業有限責任組合（2015年7月設立）とOUVC2号投資事業有限責任組合（2021年1月設立）を通じ投資と事業支援を行うと記載する。大阪大学フォーサイト株式会社（2022年8月設立、100%子会社）も研究成果活用事業として設立。', 'official', 'https://www.ccb.osaka-u.ac.jp/service/subsidiary/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_regulation_owner', 'established', '大学規程（国立大学法人大阪大学）', '認定規程は公開規程一覧に無いが、ベンチャー支援に関わる規程はいずれも国立大学法人大阪大学が制定する大学規程・規則である。テクノアライアンス棟利用規程、同管理運営規程、大阪大学共創機構規程は大阪大学規程集に収載され、株式等取扱規則と新株予約権等取得ガイドラインは共創機構が公開する。共創機構規程第3条第3号は本学発ベンチャーの起業支援を機構の業務と定める。', 'official', 'https://www.osaka-u.ac.jp/kitei/reiki_honbun/u035RG00000967.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_review_body', 'established', '共創機構／テクノアライアンス棟管理運営委員会', '認定委員会は存在しない。株式等取扱規則第3条は、知財対価としての株式等取得について共創機構の審査を経ると定め、共創担当理事が事前に経理担当理事へ審査内容を通知する。テクノアライアンス棟利用規程第5条と同管理運営規程第4条第3号は、利用の許可・利用計画の変更・利用許可の取消しをテクノアライアンス棟管理運営委員会が審議すると定める。共創機構規程第9条は機構の業務を審議する共創機構会議を置く。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.osaka-u.ac.jp/kitei/reiki_honbun/u035RG00000813.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_equity_decider', 'established', '総長（共創機構の審査結果に基づき決定）', '株式等取扱規則第2条は「総長は…次条に定める審査結果に基づいて、その全部又は一部の取得を決定することができる」と定め、第3条で共創機構の審査を経ることを要求する。第2条第2項は、発行会社の信用に問題があるとき、共益権を行使しないと経営に著しい影響を与えるとき、将来の売却可能性が低いとき等を取得禁止事由とする。売却と新株予約権の権利行使は、新株予約権等取得ガイドライン4により株式等管理細則に定めるとされる。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%A4%A7%E9%98%AA%E5%A4%A7%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E7%9F%A5%E7%9A%84%E8%B2%A1%E7%94%A3%E6%A8%A9%E7%AD%89%E3%81%AE%E9%81%8B%E7%94%A8%E5%8F%88%E3%81%AF%E5%87%A6%E5%88%86%E3%81%AE%E5%AF%BE%E4%BE%A1%E3%81%A8%E3%81%97%E3%81%A6%E5%8F%96%E5%BE%97%E3%81%99%E3%82%8B%E6%A0%AA%E5%BC%8F%E7%AD%89%E3%81%AE%E5%8F%96%E6%89%B1%E3%81%84%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E5%89%87%EF%BC%88R4.1%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_amendment_decider', 'unknown', null, 'テクノアライアンス棟利用規程第15条は「この規程を改正した場合は、本学から利用者に対して速やかに通知する」と定めるのみで、改廃の決裁主体を記載していない。株式等取扱規則、新株予約権等取得ガイドライン、大阪大学共創機構規程、同管理運営規程の本文にも制定改廃の決裁主体を定めた条項が無い。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_post_grad_limit', 'established', '関連性で判断（研究成果との関連のみ・年限なし）', 'テクノアライアンス棟利用規程第3条第3号は大学発ベンチャーを「本学で得られた研究成果を基に設立されたベンチャー」と定義し、その役職員と設立を目指す研究プロジェクトの研究開発者を利用資格者とする。研究成果との関連のみを要件とし、退職・卒業後の年限を定めていない。なお産学法務支援室の弁護士無料相談は、FAQ 3(1)により対象者を大阪大学の教職員（非常勤職員を含む）及び学生に限定している。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_renewal_rule', 'established', '更新可（審査あり）・施設利用期間のみ', '称号・認定の更新規定は公開規程に無い。テクノアライアンス棟利用規程第8条第1項は大学発ベンチャー活動を目的とした利用期間を原則1年以上5年以下とし、管理運営委員会が特に必要と認めたときは延長を認めることができると定める。第8条第2項は延長時に利用期間満了日の6月前までに所定の利用延長申請書を管理運営責任者へ提出させ、第4項で管理運営委員会の議を経て可否を決定するとする。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_naming', 'established', '大学発ベンチャー（称号付与制度はなし）', 'テクノアライアンス棟利用規程第3条第3号が「本学で得られた研究成果を基に設立されたベンチャー（以下「大学発ベンチャー」という。）」と定義し、共創機構は「大阪大学発ベンチャー」の表記でウェブページを設ける。新株予約権等取得ガイドラインの表題も「本学発ベンチャー企業支援」。称号を付与する規程は、共創機構の規程一覧にも大阪大学規程集の索引にも見当たらない。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2025/03/%E3%83%86%E3%82%AF%E3%83%8E%E3%82%A2%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%82%B9%E6%A3%9F%E5%88%A9%E7%94%A8%E8%A6%8F%E7%A8%8B%EF%BC%88R7.3.21%E6%94%B9%E6%AD%A3%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_support_period', 'established', '個別契約（支援内容は契約締結時に明確化）', '新株予約権等取得ガイドライン2(1)は「本学が、当該ベンチャー企業に対し、提供する支援内容については、当該ベンチャー企業との契約締結時に明確にする」と定め、支援の範囲を個別契約で決める建て付けを取る。称号期間という概念は無く、施設利用についてはテクノアライアンス棟利用規程第8条が原則1年以上5年以下と別に定める。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%9B%BD%E2%BD%B4%E2%BC%A4%E5%AD%A6%E6%B3%95%E2%BC%88%E2%BC%A4%E9%98%AA%E2%BC%A4%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E6%9C%AC%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E2%BD%80%E6%8F%B4%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E6%96%B0%E6%A0%AA%E4%BA%88%E7%B4%84%E6%A8%A9%E7%AD%89%E5%8F%96%E5%BE%97%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6%E3%81%AE%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%EF%BC%88R6.4%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_support_contents', 'established', '知財ライセンス・施設提供・技術指導・グラント・VC紹介・法務相談', '新株予約権等取得ガイドライン2(1)は必要な支援を「知的財産のライセンス、実験設備や事務用具が設置された施設やその他の設備の提供、さらには技術指導にとどまらない当該ベンチャー企業に対する全ての指導・助言等」とし、これらは原則有償と定める。共創機構「ベンチャー創成・社会実装支援」はシーズ育成グラント、社会実装支援グラント、連携VC41社、年5回の連携VC連絡会を挙げる。FAQ 3は産学法務支援室の弁護士無料相談を記載。', 'official', 'https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2024/04/%E5%9B%BD%E2%BD%B4%E2%BC%A4%E5%AD%A6%E6%B3%95%E2%BC%88%E2%BC%A4%E9%98%AA%E2%BC%A4%E5%AD%A6%E3%81%AB%E3%81%8A%E3%81%91%E3%82%8B%E6%9C%AC%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E4%BC%81%E6%A5%AD%E2%BD%80%E6%8F%B4%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E6%96%B0%E6%A0%AA%E4%BA%88%E7%B4%84%E6%A8%A9%E7%AD%89%E5%8F%96%E5%BE%97%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6%E3%81%AE%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%EF%BC%88R6.4%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_4dd74810eb71', 'attr_source_docs', 'established', 'https://www.ccb.osaka-u.ac.jp/policy/ ・ https://www.ccb.osaka-u.ac.jp/wpccb_handle/wp-content/uploads/2026/03/%E5%A4%A7…', '共創機構の「ポリシー・規程・様式」ページは知財・株式等・共同研究の規程を一覧化する制度の入口。FAQ（令和8年4月1日版）は兼業・利益相反・登記場所・学内設備利用の可否を問答形式で示す。新株予約権等取得ガイドラインは支援原則有償と株式取得の建て付けを定める中核文書。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ccb.osaka-u.ac.jp/policy/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_cert_update', 'established', '認定期間5年・更新可・新規と同じ手続と審査を準用', '認定規程第5条第2項が認定期間を認定した日から5年とし更新することができると定める。第3項は更新しようとする企業の代表者が別記様式第1号により学長へ申請し、その手続及び審査は第3条第2項（研究・イノベーション推進会議の議を経る）及び第4条（申請の条件）を準用すると定める。要件の再確認は第4条各号の準用として行われる。別記様式第1号の申請区分に新規・更新の選択欄がある。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_title_restriction', 'established', '品質保証目的の称号使用禁止・新たな情報公開は事前通知', '認定規程第6条第1項は、認定スタートアップが自社の製品、サービス等の内容及び品質を保証するために称号を使用してはならないと定める。第2項は称号を用いた新たな情報公開を行う場合の事前通知義務。第10条（免責）は、大学が製品・サービス等の内容及び品質並びに経営状況を保証するものではなく法的責任を負わないと明記。別記様式第2号の称号記にも同旨の注意書きが付されている。投資推奨に関する条項は置かれていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_cancellation', 'established', '学長が5事由で取消・称号記返還と称号使用禁止', '認定規程第8条第1項は、(1)定義に該当しなくなった場合、(2)社会的信用を失墜する行為を行った場合、(3)企業活動の実態がなくなった場合、(4)事業報告書等を提出しない場合、(5)その他称号を保持させることが適当でないと学長が認める場合の5事由で、研究・イノベーション推進会議の議を経て学長が認定を取り消せると定める。第2項で代表者へ通知、第3項で速やかに称号記を返還し通知日以降は称号を使用してはならない。第9条により取消しはホームページ掲載等で公表できる。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_report_change', 'established', '年次の事業報告書と収支決算書・解散等は速やかに報告', '認定規程第7条第1項は、年度毎に自社で定めた決算日から3月以内に事業報告書及び収支決算書を学長へ提出する義務を課す。第2項は、会社法の解散、破産手続、民事再生手続、会社更生手続、不正競争防止法に定める不正競争で同法第21条又は第22条の刑罰が確定した場合に、代表者又は清算人が速やかに学長へ報告する義務を定める。代表者・所在地・資本構成の変更届に関する条項は本規程に置かれていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_support_request', 'established', '支援ごとに関係規則等の手続・専用の申請様式なし', '認定規程第11条第1項は大学が支援を行うことができると定める裁量規定で、第2項は前項各号の支援を行うときは本学における関係規則等によるものとすると定める。施設使用や研究設備の利用は施設・共用に関する各規則の手続による。産学連携サイトの様式・契約ひな形ページに掲載された「奈良先端大発スタートアップ」関係の様式は認定申請書のみで、支援用の申請様式は公開されていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_facility_registration', 'established', '学内インキュベーション施設の使用と同施設での商業登記', '認定規程第11条第1項第1号は本学内にインキュベーション施設として確保した施設を使用させること、第2号は当該施設を認定スタートアップの所在地とする商業登記を認めること、第3号は商業登記をした場合に郵便物等の収受において便宜を与えることを定める。施設名は規程に記載が無く、使用条件は同条第2項により本学の関係規則等による。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_vc_connection', 'established', 'VC・金融機関と出会う場の創出支援・個社紹介の規定なし', '認定規程第11条第1項第5号の紹介は「他企業への紹介又は他企業との共同研究等の仲介」に限られ、VC・金融機関・自治体は含まれない。研究・イノベーション推進機構イノベーション推進部門の推進内容ページは、最先端科学の知見とイノベーション推進を担う官公庁・企業・金融機関・VC等がオンサイト・オンラインで出会う場の創出を支援すると記載。教育推進機構イノベーション教育部門は、関西15大学と産業界・金融界・官公庁41機関が参画するKSAC（京阪神スタートアップ アカデミア・コアリション）に参画している。', 'official', 'https://www.naist.jp/kensui/contents/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_eir', 'not_started', '制度なし・規程と支援メニューに客員起業家の定めなし', '認定規程第11条第1項は支援を8号で列挙するが、客員起業家（EIR）や起業家人材・起業家メンターの招聘は含まれない。規程集の目次全231件にEIR・客員起業家に関する規程は無い。イノベーション推進部門の推進内容ページ、及びイノベーション教育部門サイトの事業・活動内容ページにもEIR制度の記載は無く、掲載事業はGEIOT、KSAC連携プログラム、奈良先端アントレシリーズ等の教育プログラム。', 'official', 'https://dive.naist.jp/section', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_cxo_pool', 'not_started', '制度なし・経営人材の紹介やマッチングの定めなし', '認定規程第11条第1項の支援列挙に、経営人材（CEO/CXO候補）の紹介・マッチングは含まれない。規程集の目次全231件にも該当する規程は無い。教育推進機構サイトのイノベーション教育部門紹介には「創業前段階から経営人材と連携する」との記述があるが、人材プールや紹介の制度・手続としての記載は無く、同部門サイトの事業・活動内容も教育プログラムのみ。', 'official', 'https://www.naist.jp/iei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_ip_equity', 'not_started', '対価は実施料等の金銭・株式や新株予約権の定めなし', '実施許諾等取扱規程（平成16年規程第36号）第5条は実施許諾契約に含める許諾条件として「実施許諾の対価について、その額及び支払い方法等の支払い条件」を挙げるのみで、株式・新株予約権の取得を定める条項は無い。第9条は実施料等の収入が本学に帰属し、その一部を職務発明等取扱規程第18条により発明者等へ還元すると定める。規程集の目次全231件にも株式・新株予約権の取扱規程は無い。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/04080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'pol_fund_investment', 'not_started', '出資・ファンドの規程なし・資金支援の記載もなし', '規程集の目次全231件を確認したが、出資、株式、投資事業有限責任組合、ベンチャーキャピタル、ファンドに関する規程は存在しない。認定規程第11条第1項の支援列挙にも資金支援は含まれない。産学連携サイトの「奈良先端大発スタートアップ」ページにも、ギャップファンド・出資・投資に関する記載は無い。', 'official', 'https://reiki.naist.jp/kiyaku/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_regulation_owner', 'established', '大学規程（国立大学法人が定める令和6年規程第5号）', '正式名称は「国立大学法人奈良先端科学技術大学院大学における大学発スタートアップの認定等に関する規程」（令和6年3月27日、規程第5号）。学校法人ではなく国立大学法人の学内規程として制定されている。附則により令和6年4月1日施行、その後令和7年10月1日施行の改正を経た版が現行。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_review_body', 'established', '研究・イノベーション推進会議の議を経て学長が認定', '認定規程第3条第2項は、学長が研究・イノベーション推進機構規程（平成27年規程第7号）第4条の2に規定する研究・イノベーション推進会議の議を経て認定すると定める。同会議の委員は、研究・イノベーション推進機構長、各領域長、研究推進部門長、イノベーション推進部門長、事業推進部長、その他学長が必要と認める職員で、議長は機構長。認定に関する事務は事業推進部研究協力課（認定規程第12条）。認定委員会という名称の独立組織は置かれていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/01160.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_equity_decider', 'not_started', '規定なし・株式や新株予約権の取扱規程が存在しない', '規程集の目次全231件に、株式・新株予約権の取得や処分の決裁を定める規程は無い。実施許諾等取扱規程第4条は、実施許諾契約の締結権限が学長に属し、学長が研究推進部門長に契約書の作成・企業等との交渉その他の締結業務を行わせることができると定めるが、対価としての株式・新株予約権に関する定めは置かれていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/04080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_amendment_decider', 'established', '学長が制定・重要な学内規則は教育研究評議会が審議', '認定規程本体に改廃条項は置かれていない。基本規則（平成16年基本規則第1号）第22条第2項第3号は、学則その他の教育研究に係る重要な学内規則の制定又は改廃に関する事項を教育研究評議会の審議事項と定め、第21条第2項第3号は経営に係る重要な学内規則の制定又は改廃を経営協議会の審議事項と定める。認定規程は学長名の規程第5号として制定されている。規則等の制定改廃手続に特化した独立の規程は規程集に無い。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/01010.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_post_grad_limit', 'established', '3年以内（退職・修了・起業理由の退学から設立まで）', '認定規程第2条第3号は、本学の職員又は学生（本学を退職、修了又は退学（理由が起業によるものに限る）した者であって、退職等から設立までの期間が3年以内のものを含む）が設立者となるもの又はその設立に深く関与して設立されるもので、国立大学法人法第22条第1項第5号に規定する業務の遂行に寄与すると本学が認めたものを対象とする。第4号で学長が前3号に準じる資格を有すると認めたものも対象になる。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_renewal_rule', 'established', '更新可（審査あり）・新規と同じ様式と審議を準用', '認定規程第5条第2項で認定期間は認定日から5年とし更新することができると定める。第3項は更新しようとする企業の代表者が別記様式第1号により学長へ申請し、その手続及び審査は第3条第2項（研究・イノベーション推進会議の議を経る）及び第4条（申請の条件）を準用すると定める。届出のみで済ませる規定は無い。別記様式第1号の申請区分に新規・更新の選択欄がある。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_naming', 'established', '大学発スタートアップ（称号は奈良先端大発スタートアップ）', '規程名は「大学発スタートアップの認定等に関する規程」で、条文でも「大学発スタートアップ」を定義語として用いる。第5条第1項により学長が交付する称号記（別記様式第2号）で授与される称号は「奈良先端大発スタートアップ」。産学連携サイトでは「NAIST認定スタートアップ」の表記も併用されている。「ベンチャー」の語は規程・ページとも用いていない。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_support_period', 'established', '支援ごとに別に定める（関係規則等による）', '認定規程第11条第1項は認定スタートアップに対して支援を行うことができると定め、第2項は支援を行うときは本学における関係規則等によるものとすると定める。支援期間そのものを定める条項は置かれておらず、施設使用や研究設備利用の期間は各関係規則等による。称号側の認定期間は第5条第2項の5年。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_support_contents', 'established', '施設使用・商業登記・郵便物収受・設備利用・企業紹介・広報・ロゴ使用許可', '認定規程第11条第1項の列挙は、(1)本学内にインキュベーション施設として確保した施設の使用、(2)当該施設を所在地とする商業登記、(3)商業登記した場合の郵便物等の収受における便宜、(4)本学の研究設備等の利用許可、(5)他企業への紹介又は他企業との共同研究等の仲介、(6)本学主催イベント・広報誌・ホームページ等による広報、(7)認定スタートアップのロゴマークの使用許可、(8)その他学長が必要と認めること。いずれも本学の管理運営及び教育研究に支障のない範囲で行う。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e61783be8ca3', 'attr_source_docs', 'established', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf・https://www.naist.jp/sankan/content/ja/service/index.html・https://reiki.nai…', '1本目が認定制度の正本（令和6年3月27日規程第5号、令和7年10月1日施行の改正を含む現行版）で、定義・手続・称号・使用制限・報告・取消・支援・事務まで全13条と別記様式2件を収録。2本目が産学連携サイトの「奈良先端大発スタートアップ」ページで、認定企業一覧、支援内容の要約、窓口の研究協力課研究企画係、認定申請書へのリンクを掲載。3本目が規程集トップで、実施許諾等取扱規程・職員兼業規程・利益相反マネジメント規程・研究設備等の共用規程など関連規程を一覧できる。', 'official', 'https://reiki.naist.jp/kiyaku/pdf/03080.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_cert_update', 'established', '認定及び支援期間5年・6か月前申請で1回3年延長', '大学発ベンチャーに関する規程第4条第3項が認定及び支援期間を決定した日から5年を限度と定める。第6条第1項で期間終了日の6か月前までに学長へ延長を申請、第6条第2項で学長が認定委員会に付議し審議結果を踏まえて決定、第6条第3項で延長は1回を限度、第6条第4項で延長時の期間は3年を限度と規定。延長にも委員会審議が入るため、要件の再確認が更新手続に組み込まれている。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_title_restriction', 'established', '称号使用は認定期間内限定・取消後は使用禁止', '第7条第1項で学長が称号記(別紙様式第4号)により「宇都宮大学発ベンチャー」の称号を授与、第7条第2項で称号は第4条第3項および第6条第4項の認定及び支援期間内に限り使用できると規定。第11条第3項は取消通知日以降、称号と認定及び支援を受けていた事実の事業使用を禁止。第12条は認定及び支援によって生じた損失損害について大学はいかなる法的責任も負わないと定めるが、品質保証・投資推奨と誤認させない旨の明文条項は置いていない。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_cancellation', 'established', '取消事由7号・取消後は称号と認定事実の使用禁止', '第11条第1項が取消事由を7号列挙する。第2条第1号の定義に該当しなくなった場合、社会的信用を失墜する行為、事業活動の実態がない場合、活動存続が危惧される場合、代表者からの取消申出、事業報告等の未提出または法定報告があった場合、その他適当でないと認める場合。第11条第2項で認定・支援取消通知書により通知し、第3項で通知日以降の称号および認定・支援を受けていた事実の事業使用を禁止。称号記の返付を求める明文規定は無い。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_report_change', 'established', '決算日後3か月以内の事業報告・変更届・法定6事由報告', '第10条第1項で代表者は自社で定めた決算日から3か月以内に宇都宮大学発ベンチャー事業報告書により事業報告書と収支決算書を学長へ提出する義務を負う。第10条第2項は解散、破産手続、民事再生手続、会社更生手続、不正競争防止法第21条・第22条の罰則確定、その他法令違反処分の確定という6事由の報告を義務付ける。第9条は申請内容に変更が生じたときに学長へ速やかに書面で届け出ると定める。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_support_request', 'established', '認定と支援は一体申請・施設利用のみ別途センター長審査', '第4条第1項で「宇都宮大学発ベンチャー認定及び支援申請書」により学長へ申請し、第4条第2項で委員会付議の審議結果を踏まえ学長が可否を決定する。認定と支援は同一手続で、支援メニューごとの個別審査は規程上分かれていない。ただしイノベーション支援センター研究開発スペース利用要項第4条は利用申請書のセンター長への提出を、第5条はセンター長が可否を決定し利用許可書を交付することを定めており、施設利用のみ年度単位の別手続になる。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_facility_registration', 'established', '4施設を95%割引貸与・貸与施設での商業登記可', '第8条第1項第1号で別表第1の施設を使用料を割引した状態で貸与。別表第1はイノベーション支援センター本棟・北棟、ロボティクス・工農技術研究所インキュベーション室、オプティクス教育研究センターの4施設について、認定5年間は95%割引、延長3年間は1年目80%・2年目65%・3年目50%割引と定める。第8条第1項第3号で貸与施設を所在地とする商業登記を認め、退去時または支援終了時の早い日から1か月以内に登記変更を示す書面の提出を義務付ける。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_vc_connection', 'not_started', '支援内容9号にVC・金融機関紹介の号なし', '第8条第1項が支援内容を9号で限定列挙する。紹介・仲介にあたる号はイノベーション支援センター等による他企業への紹介又は仲介(第6号)と、学外ビジネスマッチングイベントの開催情報提供(第8号)にとどまり、ベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介の号は無い。イノベーション支援センターのイノベーション部門ページと地域創生推進機構サイトにも資金調達支援や金融機関紹介の記載は確認できなかった。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_eir', 'not_started', '支援内容9号に客員起業家・メンター制度なし', '第8条第1項の支援内容9号に客員起業家(EIR)、起業家メンター、起業家人材の招聘に相当する号は無い。イノベーション支援センター規程(令和3年規程第36号)第3条の業務は若手研究者の育成支援、知的財産の保護・活用、研究成果の社会実装、インキュベーション施設の維持・管理の4号で、EIRに相当する記載は無い。大学公式サイトの大学発ベンチャーページとイノベーション部門ページにも記載が無い。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_cxo_pool', 'not_started', '支援内容9号に経営人材紹介・マッチングなし', '第8条第1項第6号の紹介・仲介の対象は「他企業」であり、経営人材(CEO/CXO候補)の紹介やマッチングを定める号は9号のいずれにも無い。イノベーション支援センター規程第3条の業務4号にも人材紹介は含まれない。大学公式サイトの大学発ベンチャーページ、イノベーション支援センターのイノベーション部門ページ、地域創生推進機構サイトのいずれにも該当記載が無い。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_ip_equity', 'established', 'ライセンス対価の株式・新株予約権取得を要項で規定', '第8条第2項が知的財産権・研究成果の譲渡または実施権設定について優遇3号を定め、第3号が対価を株式又は新株予約権で受け取ることを認める。第8条第3項で取扱いを別に定めるとし、受け皿が「ライセンス等の対価として取得する株式等取扱要項」(令和2年3月24日制定、令和7年11月1日施行改正)。同要項第3条は対価の全額または一部を現金で支払うことが困難な場合を対象、第4条第2項は知的財産委員会の審議を経た役員会承認、第8条は原則として公開後速やかな売却を定める。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001388.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'pol_fund_investment', 'not_started', '出資・ファンド規程なし・株式は対価と寄附の2経路のみ', '規程集の目次を確認したが、ベンチャーキャピタル設立、認定VC、LP出資、指定ファンド、大学出資会社に関する規程は見当たらない。株式を取得する経路は「ライセンス等の対価として取得する株式等取扱要項」と「寄附により取得する株式取扱規程」(令和7年規程第64号)の2つのみで、いずれも既存企業からの受領であり大学からの出資ではない。大学発ベンチャー規程第8条第1項の支援内容9号にも資金支援の号は無い。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000010.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_regulation_owner', 'established', '大学規程（国立大学法人宇都宮大学の学内規程）', '認定制度の根拠は「国立大学法人宇都宮大学における大学発ベンチャーに関する規程」(令和7年規程第62号、令和7年11月1日施行、令和8年規程第66号で改正)。学校法人ではなく国立大学法人が定める学内規程で、規則等の制定等に関する規程(平成30年規程第100号)第2条第3号が「規程」を学長が定めるものと定義している。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001032.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_review_body', 'established', '宇都宮大学発ベンチャー認定委員会', '大学発ベンチャー規程第3条が宇都宮大学発ベンチャー認定委員会を設置し、第4条第2項で学長が申請を委員会へ付議して審議結果を踏まえ可否を決定する。宇都宮大学発ベンチャー認定委員会細則(令和4年12月21日制定、令和8年3月27日改正)第2条は認定及び支援、称号授与、認定に関し必要な事項を審議事項とする。第3条第1項の委員は学長指名の理事、地域創生推進機構長、イノベーション支援センター知財部門長、財務部長、社会共創・研究部長ほか。委員長は学長指名の理事、第6条は出席委員の過半数による議決。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001877.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_equity_decider', 'established', '役員会（知的財産委員会の審議を経る）', 'ライセンス等の対価として取得する株式等取扱要項第4条第2項で、株式等の取得は知的財産委員会による審議を経て役員会が承認して決定する。第6条第4項は新株予約権の権利行使等の変更・処分も同じ手続とする。第8条の売却および第10条のインサイダー取引該当確認は学長が担う。別経路の「寄附により取得する株式取扱規程」(令和7年規程第64号)は第6条第1項の受入決定、第10条第2項の売却、第11条の共益権行使をいずれも役員会の議を経て学長が決定と定める。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001388.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_amendment_decider', 'established', '学長（役員会・教育研究評議会の審議を経る）', '規則等の制定等に関する規程(平成30年規程第100号)第2条第3号が「規程」を学長が定めるものと定義し、第5条の別表で学則・規則・規程その他重要な規則等を役員会が審議、教育研究に係る重要な規則等を教育研究評議会が審議、経営に関する部分を経営協議会が審議すると定める。細則・内規・要項は学長が定める場合に各委員会等へ、部局長が定める場合に各教授会等へ附議する。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/110001032.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_post_grad_limit', 'established', '3年以内', '大学発ベンチャー規程第2条第1号ウが、教職員等・学生等であった者が退職、卒業又は修了の後、原則として3年以内に本学が保有する知的財産権又は研究成果等を基に設立した企業等を対象と定める。同号ア・イは在籍中の発明等や研究成果を基に設立した企業等および設立準備中の企業等、同号エは前号までに準じて設立した企業等で学長が特に認めるものを対象とする例外規定。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_renewal_rule', 'established', '更新可（審査あり）・1回3年で最長8年', '第4条第3項で認定及び支援期間は決定した日から5年を限度。第6条第1項で期間終了日の6か月前までに学長へ延長を申請、第6条第2項で学長が認定委員会に付議し審議結果に基づき決定、第6条第3項で延長は1回を限度、第6条第4項で延長時の期間は3年を限度と定める。届出のみの更新ではなく委員会審議を伴う審査型で、通算の上限は8年。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_naming', 'established', '大学発ベンチャー（称号は宇都宮大学発ベンチャー）', '第7条第1項で学長が称号記(別紙様式第4号)により「宇都宮大学発ベンチャー」の称号を授与すると規定。規程名も「国立大学法人宇都宮大学における大学発ベンチャーに関する規程」で、大学公式サイトの該当ページも「宇都宮大学発ベンチャー」と表記し、認定企業一覧を公開している。スタートアップの語は用いていない。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_support_period', 'established', '称号期間と同じ（認定及び支援期間として一体規定）', '第4条第3項が「認定及び支援期間は、決定した日から5年を限度とする」と定め、認定期間と支援期間を一体の期間として規定している。第7条第2項も称号の使用可能期間を第4条第3項および第6条第4項の認定及び支援期間内としており、称号期間と支援期間を分けていない。延長時も両者が同時に3年延びる。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_support_contents', 'established', '施設貸与・機器利用・商業登記・知財優遇・知財助言・企業紹介・広報・マッチング情報', '第8条第1項の9号。第1号 別表第1の施設を使用料割引で貸与、第2号 本学機器を学内者向け料金で使用、第3号 貸与施設を所在地とする商業登記を許可、第4号 知的財産権・研究成果の譲渡または実施権設定の優遇(第2項で独占的通常実施権の設定、対価の低額設定、株式・新株予約権による対価受領の3措置)、第5号 イノベーション支援センターでの知財戦略アドバイス、第6号 同センター等による他企業への紹介・仲介、第7号 大学主催イベント・広報誌・ホームページでの広報、第8号 学外ビジネスマッチングイベント開催情報の提供、第9号 その他学長が必要と認める事項。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5fc4daca90d2', 'attr_source_docs', 'established', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html・https://public2.legalcrud.com/utsunomiya_univ/act/1100…', '制度の中心は「国立大学法人宇都宮大学における大学発ベンチャーに関する規程」(令和7年規程第62号)で、認定要件から支援内容、報告、取消までを1本に収める。審査体制は宇都宮大学発ベンチャー認定委員会細則。対外的な制度説明と認定企業一覧は大学公式サイトの大学発ベンチャーページ。株式の取扱いは「ライセンス等の対価として取得する株式等取扱要項」(act/110001388)を併読する。', 'official', 'https://public2.legalcrud.com/utsunomiya_univ/act/119000011.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_cert_update', 'established', '支援は称号授与から5年限度、学長判断で1年単位延長', '認定等に関する規程第9条3項が「支援は，称号を授与した日から5年間を限度とし，学長が必要と認めた場合には，1年単位で延長することができる」と定める。認定及び称号そのものの有効期間や更新審査の条文は無く、称号は第7条の解除申出か第8条の取消まで存続する。要件の再確認は、第6条1項の毎年6月末日までの前年度事業報告書提出と、第8条1項各号（定義からの著しい逸脱、事業活動の実態の消滅、事業報告等から存続が危惧される場合など）に基づく取消審査で担保される。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_title_restriction', 'established', '品質・経営状況の非保証を明記、取消後は使用禁止', '認定等に関する規程第10条（免責）1項が、第3条2項の認定及び第5条の称号授与によって本学に何ら法的責任を生じさせるものではなく、山形大学発ベンチャーの製品・サービス等の内容及び品質並びに経営状況を保証するものではないと明記する。同条2項は取消により生じた損害の賠償義務も否定する。投資推奨の否定や称号の使用範囲を積極的に限定する条文は無いが、第8条4項が取消日以降に認定を受けていた事実を事業に使用することを禁じ、使用停止を担保している。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_cancellation', 'established', '取消5事由・称号記の返付・認定事実の事業使用禁止', '第7条は代表者が山形大学発ベンチャー認定解除及び称号返付申出書（別記様式3）で認定解除と称号返付を申し出る手続を定め、学長は決定を文書で通知する。第8条1項は取消事由5号（定義からの著しい逸脱、公序良俗違反・法令違反・社会的信用の失墜、事業活動の実態の消滅、事業報告等から存続が危惧される場合、その他称号保持が適当でない場合）を列挙し、研究戦略企画本部の議を経て学長が取り消す。同条4項が称号記の速やかな返付と、取消日以降に認定の事実を事業に使用することの禁止を定める。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_report_change', 'established', '毎年6月末に前年度事業報告書、解散・破産等は随時報告', '第6条1項が代表者に対し毎年6月末日までに適宜の様式で前年度の事業報告書を学長へ提出する義務を課す。同条2項は、会社法上の解散・合併・会社分割・株式交換・株式移転・事業譲渡、破産法の破産宣告、民事再生法の再生手続、会社更生法の更生手続、不正競争防止法違反による刑罰の確定のいずれかに該当したとき、代表者又は清算人が速やかに学長へ報告する義務を定める。代表者の交代、所在地の変更、資本構成の変更を届け出る条文は置かれていない。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_support_request', 'established', '支援申請書（様式4）を認定申請書と同時提出', '第9条2項が「申請者が前項の支援を希望する場合は，希望する支援を山形大学発ベンチャー認定申請書（別記様式1）と併せて支援申請書（別記様式4）を提出するものとする」と定める。支援の可否は第3条2項の認定審査と一体で研究戦略企画本部の議を経て学長が決定する建て付けで、認定後に施設・登記・機器・広報・紹介を個別に申請して個別審査を受ける独立の条文は無い。第12条は支援に必要な事項を別に定めるとするのみ。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_facility_registration', 'established', '本学施設の貸与と貸与施設での法人登記を規程で許可', '第9条1項1号が本学施設の貸与、2号が貸与した施設について当該山形大学発ベンチャーの所在地とする法人登記を認めることを支援として定め、施設利用と商業登記を同じ規程で一体化している。同項ただし書により支援内容に応じ一定の対価を求めうる。米沢キャンパスの工学部インキュベーション施設は工場スペースを備え、使用期間は5年を限度とし延長可と公開されているが、同ページには登記可否の記載は無い。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_vc_connection', 'unknown', null, '認定等に関する規程第9条1項の支援は施設貸与・法人登記・知財使用の優遇措置・ホームページ等での広報の4号と、5号「その他学長が必要と認めた支援」で構成され、VC・金融機関・自治体・外部支援機関への紹介は挙がっていない。アントレプレナーシップ開発センターは令和4年12月に信託銀行と民間企業1社との連携協定（3年間、更新可）を締結しているが、協力事項はアントレプレナーシップ教育、イノベーションエコシステムの推進、学生教育の支援、地方創生で、投資家紹介や資金調達支援の記載は無い。内閣府事業のプレスリリースは「産学官金医連携」と記すのみ。', 'official', 'https://www.yamagata-u.ac.jp/jp/information/press/20221208/01-21-2-2/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_eir', 'unknown', null, 'アントレプレナーシップ教育研究センターの公式サイト、オープンイノベーション推進本部の紹介ページ、内閣府「地域中核大学イノベーション創出環境強化事業」採択のプレスリリースのいずれにも、客員起業家（EIR）、起業家メンター、起業家人材の招聘制度の記載は無い。認定等に関する規程第9条1項の支援列挙にも人材の招聘・派遣は含まれない。公開情報だけでは制度の有無を判断できないため unknown とした。', 'official', 'https://yu-entrepreneur.yamagata-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_cxo_pool', 'unknown', null, '認定等に関する規程第9条1項の支援列挙に経営人材の紹介は含まれない。令和8年4月のプレスリリースでは、大学発ベンチャーORIDA株式会社が、大学単独では対応が難しい契約・意思決定・事業リスク対応を外部法人として補完し、センターが人材育成を担う役割分担が示されるが、CEO/CXO候補を紹介・マッチングする制度としての記載は無い。センターおよびオープンイノベーション推進本部の公式ページにも人材プールの記載は無い。', 'official', 'https://www.yamagata-u.ac.jp/jp/information/press/20260409/3/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_ip_equity', 'established', '知財の実施許諾等の対価を株式・新株予約権で取得可', '株式等取扱規程第2条4号アが「収益を伴う事業」に知的財産権の譲渡、専用実施権・仮専用実施権の設定、通常実施権の許諾、著作物等の使用許諾、出版権の設定を含める。第3条1項は、対価を支払うべき者が認定を受けた山形大学発ベンチャーであり、かつ現金で支払うことが困難な場合に限り株式等で取得できると定める。第5条が新株予約権の行使・変更・処分の審査、第6条が議決権の原則不行使、第7条が公開後速やかな売却を定める。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00000107.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'pol_fund_investment', 'unknown', null, '大学系ベンチャーキャピタル、認定特定研究成果活用支援事業者、指定ファンドへのLP出資、大学出資会社を持つという記載は、規程集の関連規程、オープンイノベーション推進本部の紹介ページ、アントレプレナーシップ教育研究センターの公式サイト、大学発ベンチャー一覧ページのいずれにも見当たらない。株式等取扱規程は事業の対価として株式等を受け取る制度であって出資ではない。ORIDA株式会社は認定を受けた大学発ベンチャーで、大学の出資会社という記載は無い。', 'official', 'https://yu-oi.yz.yamagata-u.ac.jp/headquarters/introduction/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_regulation_owner', 'established', '大学規程（国立大学法人山形大学の学内諸規則）', '認定制度の正本は「国立大学法人山形大学における大学発ベンチャーの認定等に関する規程」（令和4年9月28日制定、令和4年10月1日施行、令和5年5月10日施行の改正あり）。規程集の体系情報は全学規則／第4編 研究活動・国際交流／第2章 産学官地域連携・知的財産。学校法人の寄附行為に基づく規程ではなく、国立大学法人の学内諸規則として制定されている。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_review_body', 'established', '研究戦略企画本部の議を経て学長が決定', '第3条2項が「学長は，前項の申請があったときは，研究戦略企画本部の議を経て決定する」と定め、同条3項で審議に際し申請者への面接を認める。第8条1項の認定及び称号の取消しも研究戦略企画本部の議を経る。第11条は認定及び称号授与等に関する事務を研究情報部が、支援に関する事務を申請者に関係する部局が行うと定める。大学の研究紹介ページでは研究情報部研究推進課（産学連携担当）が問い合わせ窓口。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_equity_decider', 'established', '知的財産本部長が審査し学長の承認を得て取得', '株式等取扱規程第4条1項が、国立大学法人山形大学知的財産本部長が対象企業の財務状況その他取得の妥当性を判断するために必要な事項を審査し取得の可否を判断すると定め、同条2項で本部長が学長に報告し承認を得た上で取得すると定める。第5条は新株予約権の行使・変更・処分の審査も本部長が行うとする。第7条は公開株の取得後速やかな売却と未公開株の公開後速やかな売却を原則とし、第8条で財務関係業務担当理事をインサイダー取引管理責任者に充てる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00000107.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_amendment_decider', 'established', '学長。重要な規程は評議会等の審議と役員会の議決', '「国立大学法人山形大学における全学的事項に係る学内諸規則に関する規程」第3条が学内諸規則の制定を学長が行い、学長の認可を受けた場合は総務担当理事が専決すると定める。第5条は規則及び重要な規程・細則の制定改廃に、経営協議会又は教育研究評議会の審議と役員会の議決を要すると定める。第6条は題名・適用条項の変更、組織変更に伴う名称・職名の整備、字句の整備、形式的で軽微な改正について審議の省略を認める。認定等に関する規程自体には改廃条項は無い。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00000124.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_post_grad_limit', 'established', '1年以内（退職・卒業・修了後1年以内の設立）', '第2条3号が定義として「本学の教職員又は学生が，設立者であるもの又は設立に深く関与したもの（本学の教職員又は学生が，退職，卒業又は修了した後1年以内に設立したものを含む。）」を掲げる。ほかに1号の特許型、2号の研究成果・技術型、4号の学長が特に認めたものがあり、4号で個別救済は可能。第4条4号は教職員が設立する場合に本学採用後原則3年以上の経過と、兼業に関する規程・利益相反マネジメント規程その他関係規程の手続・許可が適正になされていることを申請条件とする。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_renewal_rule', 'established', '更新可（審査あり）。支援を1年単位で延長', '第9条3項が支援を称号授与日から5年間を限度とし、学長が必要と認めた場合に1年単位で延長できると定める。延長には学長の必要性判断が入るため届出のみの更新ではない。認定及び称号そのものの有効期間と更新手続の条文は無く、称号は第7条の解除申出又は第8条の取消まで存続する。工学部インキュベーション施設の使用期間も5年を限度とし延長可と公開されている。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_naming', 'established', '大学発ベンチャー（称号「山形大学発ベンチャー」）', '規程名が「大学発ベンチャーの認定等に関する規程」、第1条・第2条が制度対象を「大学発ベンチャー」と呼び、第5条が認定した法人に称号記（別記様式2）により「山形大学発ベンチャー」の称号を授与すると定める。スタートアップの語は規程本文で用いられていない。大学の研究紹介ページも「山形大学発ベンチャー」の表記で認定企業を一覧している。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_support_period', 'unknown', null, '［自動検証で否認: valueは支援ごとに別期間、noteの一律5年と矛盾］元の主張(established): 支援ごとに別に定める（称号は無期限、支援は5年）。第9条3項が支援の期間を称号授与日から5年限度・1年単位で延長可と定める一方、認定及び称号自体の有効期間を定める条文は無く、称号は第7条の解除申出又は第8条の取消まで存続する。したがって称号の存続期間と支援の提供期間は別建てで、期間の定めがあるのは支援側のみ。第9条1項の支援メニューごとに異なる期間を定める規定は無く、支援全体に対して一律に5年限度が適用される。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_support_contents', 'established', '施設貸与・貸与施設での法人登記・知財使用の優遇・大学HP広報・学長が認める支援', '第9条1項が、大学の管理運営及び教育研究に支障のない範囲で行う支援として、1号 本学施設の貸与、2号 貸与した施設について当該山形大学発ベンチャーの所在地とする法人登記を認めること、3号 本学が所有する特許・研究成果及び習得した技術の使用に関する優遇措置を許可すること、4号 ホームページ等において広報を行うこと、5号 その他学長が必要と認めた支援を列挙する。同項ただし書で支援内容に応じ一定の対価を求めうる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_634ea0a5f19c', 'attr_source_docs', 'established', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html・https://www.yamagata-u.ac.jp/reiki/reiki_…', '認定・称号・支援・報告・解除取消の全体は「大学発ベンチャーの認定等に関する規程」が正本。事業対価としての株式・新株予約権の取得は「株式等取扱規程」が正本。認定企業の一覧と申請窓口は大学サイトの研究ページ。関連して規程の改廃手続は「全学的事項に係る学内諸規則に関する規程」、申請条件は利益相反マネジメント規程と職員の兼業に関する規程の運用が根拠になる。', 'official', 'https://www.yamagata-u.ac.jp/reiki/reiki_int/reiki_honbun/w679RG00001902.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_cert_update', 'unknown', null, '研究推進・社会連携機構「起業・新規事業支援」ページの認定制度の節は、山梨大学発ベンチャーの定義3類型と支援項目6項目のみを掲げ、認定の有効期間・更新可否・更新審査・要件の再確認に一切触れていない。同ページは「学内手続等は学内専用ページでご確認ください」と案内しており、規程本文は外部から確認できない。令和8年6月19日の報道発表「山梨大学発ベンチャー4社を新たに認定」も通し番号と称号記授与のみで期間の記載がない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_title_restriction', 'unknown', null, '「起業・新規事業支援」ページの支援項目6)は大学主催イベント・広報誌・ホームページでの広報を認めるだけで、称号の使用範囲、品質保証・投資推奨・経営状態の保証と誤認させない旨、使用停止の条項は公開されていない。令和8年6月19日の報道発表も称号記の授与に触れるのみ。関係規程は学内専用ページにあり非公開。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_cancellation', 'unknown', null, '認定の取消事由、称号記の返付、表示の削除、営業利用の停止に関する記載は、「起業・新規事業支援」ページにも令和8年6月19日の報道発表「山梨大学発ベンチャー4社を新たに認定」にも見当たらない。規程本文は学内専用ページに置かれ公開されていない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_report_change', 'unknown', null, '年次報告、代表者・所在地・資本構成の変更届、解散時報告の定めは公開資料に見当たらない。「起業・新規事業支援」ページは山梨大学発ベンチャーの定義と支援項目6項目のみを掲げ、手続については「学内手続等は学内専用ページでご確認ください」とするにとどまる。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_support_request', 'established', '支援は貸与・許可制で学内手続あり（内容は学内専用）', '「起業・新規事業支援」ページの支援項目は1)「山梨大学内の施設を貸与すること」2)「商業登記を認めること」3)「研究設備等の利用を許可すること」と、いずれも大学側の許可行為として書かれ、同ページは支援項目の直後に「学内手続等は学内専用ページでご確認ください」と案内している。認定とは別に個別の学内手続が存在することは読み取れるが、申請様式・審査体制・決裁者は非公開で確認できない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_facility_registration', 'established', '学内施設を事務室・研究室として貸与、本店登記も許可', '「起業・新規事業支援」ページの支援項目1)「大学発ベンチャーの事務室又は研究室として山梨大学内の施設を貸与すること」、2)「貸与した施設について、大学発ベンチャーの所在地とする商業登記を認めること」、3)「山梨大学の所有する研究設備等の利用を許可すること」。施設の貸与と本店所在地としての商業登記が一体で用意されている。使用料・期間の定めは公開されていない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_vc_connection', 'established', 'IJIE参画によるVC8機関・地方銀行等との連携', '「起業・新規事業支援」ページに、山梨大学が甲信・北関東7大学のIJIE（Inland Japan Innovation Ecosystem）に参画し、地方自治体・地方銀行等との連携により地方型スタートアップ創出を推進すると明記。信州大学が公開するIJIE事業説明資料ver.2では、山梨大学はSU創出共同機関で、協力機関に山梨中央銀行ほか金融機関6、民間企業としてVC8機関・アクセラレーター4機関が並び、GAPファンドで「リスクマネーを投入する投資機関の呼び込み」を掲げる。山梨大学単独の紹介規程は非公開。', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/IJIE%E4%BA%8B%E6%A5%AD%E8%AA%AC%E6%98%8E%E8%B3%87%E6%96%99_ver.2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_eir', 'established', 'IJIEの起業支援人材配置とメンタリング', 'IJIE事業説明資料ver.2「スタートアップ創出支援体制・環境整備」に、起業支援人材の配置、外部専門家及び起業支援人材による支援体制の構築が挙げられ、スタートアップ創出プログラム（IJIE-GAPファンド）の支援内容にも「スタートアップ支援人材によるメンタリング」が明記されている。山梨大学は同事業のSU創出共同機関。大学側も令和6年度から専任のスタートアップ推進マネジャーを配置。山梨大学独自の客員起業家（EIR）規程は公開情報に無い。', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/IJIE%E4%BA%8B%E6%A5%AD%E8%AA%AC%E6%98%8E%E8%B3%87%E6%96%99_ver.2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_cxo_pool', 'established', 'IJIEの経営者候補人材の発掘・マッチング', 'IJIE事業説明資料ver.2「経営者候補人材供給機能の構築」に、自治体・金融機関・VC等と連携した経営者候補人材の発掘、経営候補人材と研究者とのマッチングおよびチーム組成プログラムの実施、大学研究者・大学院生等の経営者候補人材の育成が明記。IJIE-GAPファンドの支援内容にも「経営者候補人材とのマッチング」が入る。山梨大学はSU創出共同機関として参画。大学単独のCXO人材プール規程は非公開。', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/pdf/IJIE%E4%BA%8B%E6%A5%AD%E8%AA%AC%E6%98%8E%E8%B3%87%E6%96%99_ver.2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_ip_equity', 'unknown', null, '国立大学法人山梨大学知的財産ポリシー6.(1)は、職員等が兼業又は独立してベンチャー起業する場合、大学が承継・権利化した発明等について優先的に専用実施権の設定又は譲渡等を行うよう努めると定める。ただし対価は3.(4)②の「実施または処分により収益（収入）を得たとき」の発明者への実施補償金と、2.(3)①のロイヤリティー還流に触れるのみで、株式・新株予約権を対価として受け取れるかは書かれていない。', 'official', 'https://web.archive.org/web/2024id_/http://www.scrs.yamanashi.ac.jp/wp-content/uploads/2015/08/9cfb4b59318481d1b4cb56098791bdf9.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'pol_fund_investment', 'not_started', '大学VC・認定ファンドなし、支援6項目に出資なし', '「起業・新規事業支援」ページの支援項目6項目は限定列挙で、出資・投資を含まない。経済産業省「国立大学等によるVC等への出資」に掲載された認定特定研究成果活用支援事業者一覧（大阪大学ベンチャーキャピタル、京都大学イノベーションキャピタル、東北大学ベンチャーパートナーズ、東京大学協創プラットフォーム開発、ちばグロースアカデミア、Hirosaki共創1号、Toyama Co-Accel等）に山梨大学関係の法人・ファンドは無い。IJIE事業説明資料には「大学ファンド（事業期間中に設立予定）」の記載があるが設置主体は山梨大学と明示されていない。', 'official', 'https://www.meti.go.jp/policy/innovation_corp/syusshi.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_regulation_owner', 'established', '大学規程（国立大学法人山梨大学の学内制度）', '「起業・新規事業支援」ページに「大学との関係性を明確にするとともに、大学から様々な支援を受けられるよう、山梨大学発ベンチャー認定制度を整備しました」とあり、制度を定める主体は国立大学法人山梨大学。令和8年6月19日の報道発表も発出者が国立大学法人山梨大学で、中村和彦学長が称号記を授与する。学校法人ではなく国立大学法人の学内規程に位置づく。規程の正式名称は公開されていない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_review_body', 'established', '学長が認定、窓口は社会連携・知財戦略室', '令和8年6月19日の報道発表「山梨大学発ベンチャー4社を新たに認定」および大学ニュース「大学発ベンチャー企業の設立と認定に伴う称号記授与式を挙行」で、中村和彦学長が認定し称号記を授与する運用を確認。制度の窓口は研究推進・社会連携機構 社会連携・知財戦略室（スタートアップ推進マネジャーを配置）で、「起業・新規事業支援」ページの問い合わせ先に明記。認定委員会・審査会の設置有無と正式名称は公開されていない。', 'official', 'https://www.yamanashi.ac.jp/wp-content/uploads/2026/06/20260619.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_equity_decider', 'unknown', null, '株式・新株予約権の取得および処分に関する規程と決裁権者を示す記載は、「起業・新規事業支援」ページ、国立大学法人山梨大学知的財産ポリシー、令和8年6月19日の報道発表のいずれにも無い。関係規程は学内専用ページに置かれ公開されていない。', 'official', 'https://web.archive.org/web/2024id_/http://www.scrs.yamanashi.ac.jp/wp-content/uploads/2015/08/9cfb4b59318481d1b4cb56098791bdf9.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_amendment_decider', 'unknown', null, '認定制度の根拠規程の本文が公開されておらず、制定改廃を決める主体（役員会・教育研究評議会・学長など）を示す記載を公開資料に見つけられなかった。山梨大学は規程集をインターネット公開しておらず、「起業・新規事業支援」ページも学内手続は学内専用ページでの確認を求めている。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_post_grad_limit', 'established', '3年以内（設立まで他の職に就かないこと）', '「起業・新規事業支援」ページの山梨大学発ベンチャー定義の注記に「教職員が退職（学生等については卒業等）の後に起業した場合については、設立まで他の職に就かず、かつ、退職等から起業までの期間が３年以内のものに限る」と明記。在職・在学中の起業には期限の定めがない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_renewal_rule', 'unknown', null, '認定の更新可否、更新時の審査や届出に関する記載が公開資料に無い。「起業・新規事業支援」ページは定義と支援項目のみを掲げ、令和8年6月19日の報道発表も第9号から第12号の通し番号と称号記授与式の案内にとどまる。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_naming', 'established', '大学発ベンチャー（称号は山梨大学発ベンチャー）', '制度名は「山梨大学発ベンチャー認定制度」、称号は「山梨大学発ベンチャー」。令和8年6月19日の報道発表は認定企業を「山梨大学発ベンチャー第9号」から「第12号」と通し番号で表記し、称号記を授与する。機構サイトの一覧ページ名も「山梨大学発ベンチャー企業の紹介」。「スタートアップ」の語は創出プログラム（IJIE）側に使われ、称号には用いられていない。', 'official', 'https://www.yamanashi.ac.jp/wp-content/uploads/2026/06/20260619.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_support_period', 'unknown', null, '称号の期間も支援ごとの期間も公開資料に記載が無い。「起業・新規事業支援」ページは支援項目6項目を並べるのみで、期間、個別契約、支援の終期に触れていない。学内手続は学内専用ページに置かれ確認できない。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_support_contents', 'established', '施設貸与・商業登記・研究設備利用・経営相談・他企業紹介・広報掲載', '「起業・新規事業支援」ページの支援項目1)〜6)。1)大学発ベンチャーの事務室又は研究室として山梨大学内の施設を貸与、2)貸与した施設を大学発ベンチャーの所在地とする商業登記を認める、3)山梨大学の所有する研究設備等の利用を許可、4)教職員等が起業や起業後の経営等に関する相談業務に対応、5)教職員等による他企業への紹介又は仲介、6)大学が主催・参加するイベント、広報誌、ホームページ等での広報。6項目の限定列挙。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5617b63909d5', 'attr_source_docs', 'established', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/・https://www.yamanashi.ac.jp/w…', '制度本体は研究推進・社会連携機構「起業・新規事業支援」ページ（定義・支援項目6項目・IJIE参画）。ただし同サイトは現在外部からの取得が403で拒否されるため、Webアーカイブ版を一次確認先として挙げた。最新の認定状況と認定主体は大学の報道発表PDF（令和8年6月19日）、知財の扱いは国立大学法人山梨大学知的財産ポリシー（平成28年3月29日改正）で読む。', 'official', 'https://web.archive.org/web/20260208222200/https://www.scrs.yamanashi.ac.jp/business/675/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_cert_update', 'established', '称号3年・2年を限度に更新可（更新時も審査委員会審査）', '認定規程第6条第3項「称号の授与期間は，授与した日から3年とし，2年を限度として更新することができる」。第6条第4項で更新希望企業の代表者は岐阜大学発ベンチャー称号更新申請書（別紙様式第3号）により授与期間末日の3ヶ月前までに学長へ申請し、第5条第2項から第4項（審査委員会への付託・審査・学長決定）を準用する。要件の再確認は第9条第1項第1号（第3条の申請要件を満たさなくなったときは取消し）で担保されている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_title_restriction', 'established', '品質保証目的の称号使用禁止・不適当な広告は使用停止', '認定規程第7条第1項「認定企業は，当該企業の製品，サービス等の内容及び品質を保証するために称号を使用してはならない」。第7条第2項は広告又は宣伝に称号を用いる場合に学長が不適当と認めるときは使用を停止できると定める。第11条第1項「本学は，認定企業の製品，サービス等の内容及び品質を保証しない」、第11条第2項で認定又は取消しにより企業・第三者に損害が生じても賠償義務を負わないと明記。投資推奨や経営状態の保証を名指しした条項はない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_cancellation', 'established', '4事由で学長が取消し・称号記返付・認定事実の事業利用禁止', '認定規程第9条第1項の取消事由は、(1)第3条の申請の要件を満たさなくなったとき、(2)本学又は当該認定企業の社会的信用を失墜する行為を行ったとき、(3)称号の返付を申し出たとき、(4)前3号のほか称号を保持させることが適当でないと学長が認めるとき。第9条第2項「速やかに岐阜大学発ベンチャー称号記を返付し，取り消された日以後，大学発ベンチャーを認定された事実を当該企業の事業に使用してはならない」。施設側は産学連携オープンラボ使用内規第13条が使用許可の取消し・中止を定める。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_report_change', 'established', '毎年6月末までの活動内容報告書・変更届の定めなし', '認定規程第8条「認定企業は，毎年6月末日までに，別に定める活動内容報告書により，その前年度における活動内容を学長に報告しなければならない」。代表者・所在地・資本構成の変更届や解散時報告に関する条文は規程本文に置かれていない。第13条第2項は商業登記を認められた企業が本学から退去する際に登記を変更したことを示す書面の提出を求めるにとどまる。産学連携オープンラボ使用内規は第11条で活動成果報告、第12条で使用許可内容の変更申請を別途定める。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_support_request', 'established', '認定で一括付与、施設利用のみ別申請・運営会議審査', '認定規程第13条第1項は認定企業に対し大学が支援を行うことができると定めるだけで、支援メニューごとの個別申請条項は置いていない。一方、産学連携オープンラボ使用内規第6条は使用希望者に別紙様式1で管理責任者への申請と許可を義務づけ、第7条・第8条で岐阜大学学術研究・産学官連携推進本部運営会議が可否を審査すると定める。商業登記先として使う場合も第6条第2項で同じ申請・許可が必要で、施設・設備の変更は第18条で別申請となる。', 'official', 'https://ari.gifu-u.ac.jp/file/abc6da5c8456e4cf7a239d77c30c6eb7_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_facility_registration', 'established', 'オープンラボ入居と同所在地の商業登記を許可制で併用可', '認定規程第13条第1項第1号は岐阜大学学術研究・産学官連携推進本部オープン・スペース利用細則に基づく事務室・研究室の利用、第2号は「前号の施設等について，認定企業の所在地とする商業登記を認めること」。産学連携オープンラボ使用内規第6条第2項は商業登記先を希望するベンチャー企業に別紙様式1での申請と管理責任者の許可を求め、第10条で使用期間は1回の申請につき3年、第16条第2項で使用終了時に登記変更を示す書面の提出を義務づける。', 'official', 'https://ari.gifu-u.ac.jp/file/abc6da5c8456e4cf7a239d77c30c6eb7_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_vc_connection', 'established', '企業・自治体等関連機関への紹介・仲介（VCは明示なし）', '認定規程第13条第1項第6号「学術研究・産学官連携推進本部による企業・自治体等関連機関への紹介又は仲介を行うこと」。紹介・仲介は支援メニューとして条文に列挙されているが、ベンチャーキャピタルや金融機関を名指しした条項は見当たらない。東海国立大学機構スタートアップ統括室規程第2条の業務は戦略立案・事業計画・関係部局との調整等にとどまり、同統括室の支援策一覧ページ、岐阜大学の支援策ページ、岐阜大学起業ナビにもVC・金融機関紹介の名称付きメニューの掲載はなかった。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_eir', 'unknown', null, '認定規程、岐阜大学大学発ベンチャー審査委員会細則、産学連携オープンラボ使用内規、東海国立大学機構スタートアップ統括室規程のいずれにも客員起業家（EIR）・起業家メンター・起業家人材の招聘に関する条項はない。機構スタートアップ統括室の支援策一覧ページと岐阜大学向け支援ページ、岐阜大学起業ナビにも該当メニューの掲載がなかった。制度を置かないと明示した記述も確認できないため unknown とする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO・CXO候補）の紹介、人材プール、マッチングを定めた条項は認定規程・審査委員会細則・産学連携オープンラボ使用内規・東海国立大学機構スタートアップ統括室規程のいずれにもない。機構スタートアップ統括室の支援策一覧ページ、岐阜大学向け支援ページ、岐阜大学起業ナビの掲載メニューにも該当なし。支援メニューが限定列挙された認定規程第13条第1項にも人材紹介の号はないが、これは施設・広報系の列挙であり不存在の明示ではないため unknown とする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_ip_equity', 'established', '知財対価の現金支払を免除・軽減し株式/新株予約権を取得', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則第2条第1項は、知的財産権等を活用した事業の有用性が高く、現金支払の免除・軽減が成果活用事業者の経営加速に特に必要な場合に現金支払を免除又は軽減できると定める。第2条第2項「現金に代えて当該成果活用事業者の発行した株式又は新株予約権（発行価額が無償のものをいう。）を取得することができる」。第3条で議決権付株式は発行済株式総数の半数未満に制限。第7条で売却益等は知的財産等に係る収入配分細則により分配。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010858.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'pol_fund_investment', 'unknown', null, '［自動検証で否認: Tokai Innovation Institute社名は原文になし］元の主張(established): 機構出資子会社傘下VCによる東海研究開発1号ファンド。東海国立大学機構の公式お知らせ（2024年12月）によると、機構の出資子会社である株式会社Tokai Innovation Institute の傘下に株式会社Central Japan Innovation Capital を置き、同社が「東海研究開発1号投資事業有限責任組合」（Central Japan Innovative Research Fund I, LPS）を組成、想定規模50〜100億円でファーストクローズ33億円。投資対象は国内外のシード・アーリー期のディープテックスタートアップで大学発スタートアップが中心。岐阜大学発ベンチャーを対象と明示した記載や、岐阜大学単独の出資規程は規則集で確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_regulation_owner', 'established', '大学規程（岐阜大学規程第6号・学長制定）', '認定規程は「岐阜大学における大学発ベンチャーの認定等に関する規程」（平成31年規程第6号、令和6年5月27日最終改正）として東海国立大学機構規則集に岐阜大学単独の規程で掲載され、審査委員会細則は岐阜大学規則第21号。岐阜大学における規則に関する規程第5条は規程・細則を学長又は部局長が定めるものと分類する。ただし知的財産、株式等、利益相反、兼業、スタートアップ統括室は東海国立大学機構の機構規程・機構細則で運用されており、認定は大学規程、周辺制度は法人規程という二層構造になっている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_review_body', 'established', '岐阜大学発ベンチャー審査委員会（委員長は産学官連携推進本部長）', '認定規程第4条第1項で「岐阜大学発ベンチャー審査委員会」を設置し、細則第2条で大学発ベンチャーの認定又は不認定に関する事項等を審議。細則第3条第1項の委員は、学術研究・産学官連携推進本部長、同副本部長、同産学官連携推進部門長、同運営会議委員のうち1名、研究推進部長、その他委員会が必要と認める者。第5条第2項で委員長は本部長。第6条は委員の過半数出席で成立し出席委員の3分の2以上で議決。第7条で事務は研究推進部研究推進課。最終決定は規程第5条第4項により学長。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010597.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_equity_decider', 'unknown', null, '［自動検証で否認: 理事の決定は保有継続の例外、売却決定でない］元の主張(established): 取得は機構（知財統括室が受入報告）、売却は財務担当理事。知的財産権等の運用又は処分に伴う株式等の取扱細則第2条は主語を「機構」とし取得可否の決裁者を条文上明示しない。第6条第2項・第3項で学術研究・産学官連携統括本部知的財産統括室が株式等の受入れと新株予約権の行使可能時に経理責任者へ報告する。東海国立大学機構株式等管理事務取扱細則第4条は株式の売却を財務を担当する理事の決定により行い経理責任者が実行、第5条は議決権を原則不行使とし例外的行使の判断を同理事に、第6条は新株予約権を行使しない判断も同理事に置く。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_amendment_decider', 'established', '学長（全学規則は学長が制定改廃・審議機関の議を経る）', '認定規程と審査委員会細則には改廃条項がなく、規程第15条は「この規程に定めるもののほか，大学発ベンチャーの認定及び支援に関し必要な事項は，別に定める」とするのみ。岐阜大学における規則に関する規程第5条第3項は全学規則を学長が制定又は改廃すると定め、第5条第4項は部局規則を部局長（学長が必要と認めるときは学長）とする。第8条第1項は学則及び規程の制定改廃について教育研究評議会、運営会議、教授会その他必要な審議機関の議を経ると定める。認定規程は全学の岐阜大学規程第6号であるため学長が改廃主体。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010693.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_post_grad_limit', 'established', '1年以内（退職1年以内・卒業1年以内、在職6年/在学2年以上）', '岐阜大学 学術研究・産学官連携推進本部の大学発ベンチャーページは認定要件として、在職6年以上の役員・職員、退職1年以内で在職6年以上の元役員・職員、在学2年以上の学生、卒業1年以内で在学2年以上の元学生が設立者又は設立に深く関与した企業を挙げる。認定規程第2条第2号・第3号は「過去に役員，職員又は学生であった者を含む」と規定する。知的財産権活用型と研究成果活用型はこの年限とは別の類型で、年限の適用外。', 'official', 'https://ari.gifu-u.ac.jp/sangaku/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_renewal_rule', 'established', '更新可（審査あり）・2年を限度、3ヶ月前までに申請', '認定規程第6条第3項で称号の授与期間は3年、2年を限度として更新できる。第6条第4項で更新を希望する認定企業の代表者は岐阜大学発ベンチャー称号更新申請書（別紙様式第3号）により授与期間末日の3ヶ月前までに学長へ申請し、第5条第2項から第4項を準用して審査委員会の審査を経て学長が決定する。産学官連携推進本部の大学発ベンチャーページに更新申請書（Word）が掲出されている。更新後にさらに再更新できるかを定めた条文はない。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_naming', 'established', '大学発ベンチャー（称号は「岐阜大学発ベンチャー」）', '認定規程の題名は「岐阜大学における大学発ベンチャーの認定等に関する規程」で、第6条第1項は認定企業に「岐阜大学発ベンチャー」の称号を授与すると定め、第6条第2項で岐阜大学発ベンチャー称号記（別記様式第2号）を交付する。第13条第1項第4号は「岐阜大学発ベンチャーのロゴを使用する権利を与えること」。スタートアップの語は東海国立大学機構スタートアップ統括室規程など機構側で用いられており、岐阜大学の称号制度では大学発ベンチャーに統一されている。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_support_period', 'established', '支援ごとに別に定める（称号3年・オープンラボ1回3年）', '称号の授与期間は認定規程第6条第3項で3年（2年を限度に更新可）。産学連携オープンラボの使用期間は使用内規第10条で1回の申請につき3年とされ、第12条に基づく更新も1回の申請につき3年までの範囲と別に定められており、称号期間とは連動しない。共用設備の学内料金適用、ロゴ使用、紹介・広報など他の支援については期間を定めた条文がなく、認定企業である期間に対応する扱いとなる。', 'official', 'https://ari.gifu-u.ac.jp/file/abc6da5c8456e4cf7a239d77c30c6eb7_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_support_contents', 'established', 'オープン・スペース利用・商業登記・郵便物収受・ロゴ使用権・共用設備の学内料金・企業自治体等への紹介仲介・イベント広報誌での広報・支援イベント案内・学長が認める支援', '認定規程第13条第1項が支援を9号で限定列挙する。第1号はオープン・スペース利用細則に基づく事務室・研究室の利用、第2号はその施設等を所在地とする商業登記、第3号は郵便物等の収受の便宜、第4号は岐阜大学発ベンチャーのロゴ使用権、第5号は共用設備の学内料金での使用、第6号は学術研究・産学官連携推進本部による企業・自治体等関連機関への紹介又は仲介、第7号は本学主催の各種イベント・広報誌等での広報、第8号はベンチャー支援関係イベントの案内、第9号はその他学長が必要と認めた支援。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_84b7d5c12a65', 'attr_source_docs', 'established', 'https://public1.legalcrud.com/thers_ac/act/110010595.html・https://public1.legalcrud.com/thers_ac/act/110010597.html・htt…', '1本目は岐阜大学における大学発ベンチャーの認定等に関する規程（東海国立大学機構規則集、令和6年5月27日最終改正）で、対象類型・称号期間・取消し・年次報告・支援9項目の正本。2本目は岐阜大学大学発ベンチャー審査委員会細則で審査体制の正本。3本目は学術研究・産学官連携推進本部の大学発ベンチャーページで、申請書類・更新申請書・退職卒業後1年の年限・認定企業一覧を掲載。補完資料として知財対価の株式取扱は機構細則 act/110010858、施設と商業登記は産学連携オープンラボ使用内規。', 'official', 'https://public1.legalcrud.com/thers_ac/act/110010595.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_cert_update', 'unknown', null, '研究・イノベーション共創機構の規程・様式ページに「岡山大学発ベンチャー称号授与等規程」が掲載されているが、リンク先PDFは学内限定でHTTP 403。称号紹介ページ（岡大発ベンチャー）、制度創設ニュース、令和3年度授与式ニュースのいずれにも認定期間・更新可否・更新審査・要件再確認の記載がない。解説資料（制度概要）と解説資料（条文解説）も同じく学内限定403のため、有効期間の定めの有無自体を確認できない。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_title_restriction', 'unknown', null, '称号紹介ページには称号の使用範囲、使用上の注意、大学が品質・投資価値・経営状態を保証するものではない旨の記載がない。制度創設ニュースおよび令和3年度授与式ニュースにも同種の条項は見当たらない。根拠の称号授与等規程と条文解説資料が学内限定403のため、誤認防止条項や使用停止規定の有無は未確認。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_cancellation', 'established', '様式5「称号・称号記返還申出書」で返還手続きを整備', '規程・様式ページの「大学発ベンチャー支援関連」欄に【様式5】岡山大学発ベンチャー称号・称号記返還申出書が掲載され、称号記の返還手続きが制度として置かれていることを確認した。ただし様式本体と根拠の岡山大学発ベンチャー称号授与等規程（2024年3月改正）はいずれも学内限定でHTTP 403のため、取消事由、大学側からの取消発動、公表物からの表示削除、営業上の利用停止の定めは未確認。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_report_change', 'established', '様式1届出書・様式4活動内容報告書を整備', '同じ規程・様式ページに【様式1】大学発ベンチャー届出書、【様式4】岡山大学発ベンチャー活動内容報告書、事業継続性に係る補足説明資料（フォーマット）が掲載され、届出と活動報告の様式が整備されている。報告が年次かどうかの頻度、代表者・所在地・資本構成の変更届、解散時報告の定めは、様式本体と称号授与等規程が学内限定403のため未確認。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_support_request', 'established', '施設入居は申請書提出・審査で個別に可否決定', '共創イノベーションラボKIBINOVEの利用案内に「入居希望のラボが決まりましたら、下記書類を提出ください。審査の上、入居の可否を決定いたします」とあり、利用申請書兼資産貸付申込書の提出と審査が称号認定とは別建てで置かれている。規程・様式ページにも株式等による支払い申込書が称号授与申請書（様式2）とは別様式として掲載。機器共用・広報・人材紹介の個別申請様式は公開範囲では確認できず。', 'official', 'https://www.orsd.okayama-u.ac.jp/kigyo/kibinove/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_facility_registration', 'established', 'KIBINOVE入居可・貸与施設住所で商業登記可', '共創イノベーションラボKIBINOVEの利用案内が、利用パターンとして「自社が占有できるオフィスやラボを借りたい方」と「ベンチャー企業等で登記場所をKIBINOVEにしたい方」を並記し、登記用住所の利用を有償メニューとして独立させている。ドライラボ、ウェットラボ、レンタルオフィス、コワーキングスペースを月単位で貸与。称号紹介ページにも「本学貸与施設の住所による商業登記が可能」と明記。称号企業への優遇の有無はKIBINOVEページには記載なし。', 'official', 'https://www.orsd.okayama-u.ac.jp/kigyo/kibinove/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_vc_connection', 'established', 'リバネス協定で投資家・地域企業との接続を推進', '大学公式ニュース「株式会社リバネスと連携・協力に関する協定を締結」に、協定で「研究シーズの発掘、事業化人材の育成、地域企業や投資家との接続、国内外への展開支援」を進めると明記。産学官連携拠点KIBINOVEに提携ベンチャーキャピタルが拠点を構えたことが締結の契機と記載。起業相談窓口ページにも初回相談後「必要に応じて、適切なメンターや支援機関をご紹介」とある。金融機関・自治体への紹介を定めた規程や、称号企業に紐づく紹介制度は公開範囲では未確認。', 'official', 'https://www.okayama-u.ac.jp/tp/news/news_id15466.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_eir', 'unknown', null, 'ベンチャー支援サイトの起業支援ページ、起業相談窓口ページ、組織紹介ページ、研究・イノベーション共創機構の大学発ベンチャー企業支援ページのいずれにも、客員起業家（EIR）、起業家メンターの招聘、起業家人材の登用制度の記載がない。学内専用ページはアクセス制限で内容を確認できない。規程・様式ページの掲載規程一覧にも該当規程は無い。', 'official', 'https://venture.okayama-u.ac.jp/entrepreneurship-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_cxo_pool', 'unknown', null, 'リバネスとの連携協定ニュースに、今後推進する取組として「県内企業と連携したアントレプレナーシップ教育」「CXO人材育成」「博士人材等の活用による研究シーズを基盤としたスタートアップ創出」が挙げられているが、これは人材の育成であり、外部のCEO/CXO候補をプールして紹介・マッチングする制度としての記載ではない。起業支援ページと起業相談窓口ページにも経営人材紹介の記載はない。', 'official', 'https://www.okayama-u.ac.jp/tp/news/news_id15466.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_ip_equity', 'established', '株式等取扱規程と株式等による支払い申込書を整備', '規程・様式ページの「大学発ベンチャー支援関連」欄に、国立大学法人岡山大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程（2024年3月改正）と、株式等による支払い申込書（2021年5月改正）が掲載され、大学の事業対価を株式等で受け取る枠組みが整備されている。両方とも学内限定でHTTP 403のため、実施許諾料が対象事業に含まれるか、新株予約権の扱い、取得比率の上限は未確認。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'pol_fund_investment', 'unknown', null, '大学発ベンチャー企業支援ページに掲載された資金支援はJST地域プラットフォームPSIのGAPファンド説明会（ステップ1・ステップ2）と、学内公募の岡山大学発ベンチャー起業支援事業（事業化推進型・基盤形成型の予算配分）で、いずれも研究開発資金であり出資ではない。規程・様式ページの規程一覧にファンド組成・LP出資の規程は無く、経済産業省の国立大学等によるVC等への出資ページはHTTP 403で認定状況を確認できなかった。', 'official', 'https://www.orsd.okayama-u.ac.jp/kenkyusha/daigakuhatsu-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_regulation_owner', 'established', '大学規程（岡山大学発ベンチャー称号授与等規程）', '規程・様式ページに「岡山大学発ベンチャー称号授与等規程」（2024年3月改正）が掲載され、称号制度の根拠が国立大学法人岡山大学の学内規程であることを確認した。関連規程も「国立大学法人岡山大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程」で、いずれも大学規程。学校法人規程や外部団体規程との併用は見当たらない。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_review_body', 'established', 'スタートアップ・ベンチャー創出本部が窓口・学長授与', '令和3年度の称号授与式を伝える大学ニュースに、学長が授与企業の代表者に認定盾を授与したこと、実施主体が「イノベーションマネジメントコア ベンチャー支援フィールド」であることが記載。制度創設時ニュースでは申請窓口が研究推進機構産学連携・知的財産本部。現在の担当は研究・イノベーション共創機構のページで「岡山大学スタートアップ・ベンチャー創出本部」と確認した。審査委員会の正式名称と構成は称号授与等規程が学内限定403のため未確認。', 'official', 'https://www.okayama-u.ac.jp/tp/news/news_id10863.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_equity_decider', 'unknown', null, '株式等の取扱いに関する規程（2024年3月改正）と株式等による支払い申込書はいずれも学内限定でHTTP 403のため、株式・新株予約権の取得および処分の決裁者を確認できない。称号紹介ページ、大学発ベンチャー企業支援ページ、各ニュースにも決裁者の記載はない。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_amendment_decider', 'unknown', null, '称号授与等規程および株式等取扱規程の本文が学内限定403で読めず、附則の制定改廃条項を確認できない。両規程は大学公式規程データベース（諸規則集）の公開本文にも掲載されておらず、改廃決裁者を特定できる公開資料が見つからない。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_post_grad_limit', 'unknown', null, '称号紹介ページは対象を「本学教職員・学生が立ち上げたベンチャー企業」、制度創設ニュースと授与式ニュースは「本学の学生・教職員により、または研究成果を活用して起業したベンチャー企業」とするのみで、退職後・卒業後に何年以内の起業までを対象とするかの記載がない。称号授与等規程が学内限定403のため期限条項の有無を確認できない。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_renewal_rule', 'unknown', null, '称号紹介ページ、制度創設ニュース、授与式ニュースのいずれにも更新の可否・方法の記載がない。規程・様式ページに掲載された様式は届出書（様式1）、称号授与申請書（様式2）、活動内容報告書（様式4）、称号・称号記返還申出書（様式5）で、更新申請に相当する様式は公開一覧に現れない。規程本文が学内限定403のため更新条項の有無は未確認。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_naming', 'established', '大学発ベンチャー（称号名「岡山大学発ベンチャー」）', '称号紹介ページおよび規程名がいずれも「岡山大学発ベンチャー」で統一され、規程名も「岡山大学発ベンチャー称号授与等規程」。支援サイトの見出しは略称の「岡大発ベンチャー」。スタートアップという語は組織名（スタートアップ・ベンチャー創出本部）に使われるが、称号名としては用いられていない。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_support_period', 'established', '支援ごとに別に定める（施設は個別申請・月単位貸付）', 'KIBINOVEの利用案内は、ドライラボ・ウェットラボ・レンタルオフィス・コワーキングスペースを月単位貸しとし、利用申請書兼資産貸付申込書の提出と審査で入居可否を決めると記載。称号の付与手続きとは別建てで、支援ごとに期間が決まる構成。称号自体の有効期間は称号授与等規程が学内限定403のため未確認で、称号期間と施設利用期間の連動の有無は読み取れない。', 'official', 'https://www.orsd.okayama-u.ac.jp/kigyo/kibinove/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_support_contents', 'established', '広報PR・知財優遇・施設設備の優遇有償貸与・住所登記・起業相談', '称号紹介ページが称号付与企業のメリットとして「本学ホームページなどでの広報・PRや知的財産に関する優遇措置」「本学施設・研究設備等の優遇有償貸与・利用」「本学貸与施設の住所による商業登記が可能」の3点を明記。あわせて支援サイトに起業相談窓口、テックガレージ、ブートキャンプ、オープンラボ、専門家への相談が掲載され、共創機構側にPSI・GAPファンド説明会、V-Story、岡山大学発ベンチャー起業支援事業（事業化推進型・基盤形成型）がある。', 'official', 'https://venture.okayama-u.ac.jp/okadai-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_faf4fe8290f5', 'attr_source_docs', 'established', 'https://www.orsd.okayama-u.ac.jp/kitei/ ・ https://venture.okayama-u.ac.jp/okadai-venture/ ・ https://www.orsd.okayama-u.…', '1本目の規程・様式ページが称号授与等規程、株式等取扱規程、様式1・2・4・5、解説資料の存在と改正年を確認できる唯一の公開一覧（リンク先PDFは学内限定403）。2本目はスタートアップ・ベンチャー創出本部の称号紹介ページで支援メニューの正式表現の出典。3本目は研究・イノベーション共創機構の大学発ベンチャー企業支援ページで、担当組織名、PSI・GAPファンド、V-Story、起業支援事業の入口。', 'official', 'https://www.orsd.okayama-u.ac.jp/kitei/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_cert_update', 'established', '支援期間は最長2年、更新規定は非公開', '大学発ベンチャー支援申請書（様式1）の「２．支援期間（最長２年を限度）」が、称号・施設設備使用・知財優遇措置・登記住所を含む支援全体の期間を最長2年と定める。更新の可否、更新審査、要件の再確認を定めた条項は公開資料に見当たらない。規程本文「川崎医科大学発ベンチャー支援に関する規程」は産学連携知的財産管理室の「規程・様式」が学内限定のため閲覧できない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_title_restriction', 'unknown', null, '支援申請書（様式1）「４．付帯事項(2)」は、支援を受けたことにより生じた損失・損害について大学が責任を負わない旨の免責を置くのみ。称号が品質保証・投資推奨・経営状態の保証と誤認されることを防ぐ条項、称号の使用範囲、使用停止の定めは公開資料に無い。規程本文は学内限定ページにあり確認できない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_cancellation', 'unknown', null, '公開されている様式1（支援申請書）、様式2（支援決定申請書）、様式3（事業報告）に、取消事由、称号の返付、表示の削除、営業利用の停止を定めた記載は無い。様式2は支援決定・不支援の判定と不支援理由の欄のみを持つ。規程本文は産学連携知的財産管理室の「規程・様式」ページが学内限定のため確認できない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_report_change', 'established', '年度毎の事業報告書・収支決算書の提出', '産学連携知的財産管理室の大学発ベンチャーページが、起業後（年度毎）の提出書類として大学発ベンチャー事業報告（様式3）を掲げる。様式3は「川崎医科大学発ベンチャー支援に関する規程により」学長宛に事業報告書、収支決算書、その他を提出させる。代表者・所在地・資本構成の変更届、解散時報告の様式および条項は公開資料に無い。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_3.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_support_request', 'established', '支援希望項目ごとの申請と学長の可否決定', '大学発ベンチャー支援申請書（様式1）は、称号、本学施設・設備の使用、知的財産権とノウハウ使用の優遇措置、学内所在地での登記、その他の希望を項目別に希望有無で申請させ、付帯事項(1)で「審査の結果、希望に添えない場合もある」と定める。様式2（支援決定申請書）で学長が支援決定・不支援、支援決定の内容、不支援理由を通知する。認定と個別支援は同一の申請・決定で処理される。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_facility_registration', 'established', '施設使用と学内所在地での商業登記の併用可', '支援申請書（様式1）「１．支援希望内容」の(2)が本学施設・設備の使用、(4)が「本学施設・設備の使用期間中の限り、登記住所を本学所在地とする」を掲げ、両方を同時に申請できる。登記住所の利用は施設・設備の使用期間に連動し、支援期間の上限は最長2年。添付書類に履歴事項全部証明書が必須のため、設立登記前の申請はできない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_vc_connection', 'unknown', null, '産学連携知的財産管理室（さんち室）の紹介ページは、産・官・金・学の各方面と協働すると述べ金融業界を挙げるが、掲げる業務は学内発明の事務処理、共同研究等の事務、学外イベントへの出展、研究シーズの紹介にとどまる。VC、金融機関、自治体、外部支援機関へ大学発ベンチャーを紹介する導線を制度として定めた記載は、同ページにも大学発ベンチャーページにも無い。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/sanchi.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_eir', 'unknown', null, 'さんち室ページは体制を担当教員4名（兼務）、知財コーディネータ1名（専任）、事務職員3名（専任）と公開するが、客員起業家（EIR）、起業家メンター、起業家人材の招聘を定めた制度の記載は無い。大学発ベンチャーページ、産学官連携・知的財産ポリシー、支援申請書（様式1）の支援メニューにも該当する記載が見当たらない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/sanchi.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_cxo_pool', 'unknown', null, '支援申請書（様式1）の支援希望内容は称号、施設・設備の使用、知的財産権等の優遇措置、学内所在地での登記の4項目と「(5)その他の希望」で構成され、経営人材（CEO/CXO候補）の紹介・マッチングは挙がっていない。さんち室ページの業務内容にも人材紹介の記載は無い。「その他の希望」の余地があるため、制度として否定されているとまでは読めない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_ip_equity', 'unknown', null, '産学官連携・知的財産ポリシー（令和2年6月8日施行）は、実施料等の対価を得た場合に権利化・承継に係る経費を控除した後、適切に定めた割合で発明者等へ配分すると定めるのみで、株式・新株予約権による対価受領の可否に触れていない。支援申請書（様式1）(3)も「本学が所有する知的財産権、ノウハウ等の使用に関する優遇措置」と記すだけで、対価の形態を定めていない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/policy.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'pol_fund_investment', 'unknown', null, '学校法人川崎学園の情報公開ページは、寄附行為、組織図、役員・評議員一覧、耐震化率、令和7年度の事業報告書・計算関係書類・財産目録・監査報告を掲げるが、出資会社、ファンド、LP出資、関連会社に関する記載は無い。大学側の産学官連携・知的財産ポリシーおよび大学発ベンチャーページにも、出資やファンド組成を定めた規程は掲載されていない。', 'official', 'https://k.kawasaki-m.ac.jp/data/houjin/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_regulation_owner', 'established', '大学規程（川崎医科大学発ベンチャー支援に関する規程）', '規程名が「川崎医科大学発ベンチャー支援に関する規程」で、支援申請書（様式1）と事業報告（様式3）の宛先、支援決定申請書（様式2）の名義がいずれも川崎医科大学学長。同大学の利益相反マネジメント規程も川崎医科大学の制定で、規程集の整理番号Ⅴ－18を持つ。学校法人川崎学園の情報公開に対応規程は無い。称号は「川崎学園発ベンチャー」も選べるが、制度の主体は大学側。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_review_body', 'established', '学長が審査・決定、窓口は産学連携知的財産管理室', '支援決定申請書（様式2）が川崎医科大学学長名で支援の可否、支援決定の内容、不支援理由を通知し、支援申請書（様式1）付帯事項(1)も「審査の結果」と記す。申請先は産学連携知的財産管理室。認定委員会・審査会など専任の審査組織の名称は公開資料に無い。兼業は大学発ベンチャー企業起業にかかる兼業に関する規程第5条により学長へ申請し、利益相反は利益相反マネジメント規程第12条で利益相反委員会が審査する。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_equity_decider', 'unknown', null, '大学が株式・新株予約権を取得・処分する制度自体が公開資料に無く、決裁者の定めも見当たらない。利益相反マネジメント規程第3条第1号は「企業等から一定額以上の金銭もしくは株式等を取得する場合」を教職員個人の利益相反マネジメントの対象として挙げるにとどまり、大学による取得や処分の決裁を定めるものではない。', 'official', 'https://m.kawasaki-m.ac.jp/kenkyu/riekisouhan/document/kitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_amendment_decider', 'established', '学長（大学運営委員会・教授会の議を経て）', '川崎医科大学利益相反マネジメント規程（規程集Ⅴ－18、令和5年9月1日施行）第18条第2項が「この規程の改廃は、大学運営委員会、教授会の議を経て学長が定める」と定める。同大学における規程改廃の経路を示す条文。大学発ベンチャー支援に関する規程の本文は学内限定ページに置かれており、同一の改廃条項を持つかは公開資料で確認できない。', 'official', 'https://m.kawasaki-m.ac.jp/kenkyu/riekisouhan/document/kitei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_post_grad_limit', 'unknown', null, '大学発ベンチャー兼業許可申請書（様式1、兼業規程第5条関係）の⑩に「大学発ベンチャーの申請資格　規程第２条第（１・２・３・４）号」とあり、申請資格が4号に分かれることまでは分かる。各号の文言は公開されておらず、退職者・修了者を対象に含めるか、含める場合の年限があるかを確認できない。規程本文は学内限定。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_2.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_renewal_rule', 'unknown', null, '支援申請書（様式1）「２．支援期間（最長２年を限度）」で期間の上限は定まるが、期間満了後の更新の可否、更新時の審査、再申請の手続きを定めた記載は公開資料に無い。支援決定申請書（様式2）も初回の可否判定の様式にとどまる。規程本文は学内限定ページにあり確認できない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_naming', 'established', '大学発ベンチャー（大学発・学園発の2種から選択）', '支援申請書（様式1）「１．支援希望内容(1)」が、大学発ベンチャーの称号を「川崎医科大学発ベンチャー」又は「川崎学園発ベンチャー」と定め、申請者が希望の有無を選ぶ形式。産学連携知的財産管理室のページ、兼業許可申請書、事業報告のいずれも「大学発ベンチャー」表記で統一され、「スタートアップ」の語は用いられていない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_support_period', 'established', '称号期間と同じ（最長2年の支援期間に一本化）', '支援申請書（様式1）は、称号、本学施設・設備の使用、知的財産権等の使用の優遇措置、学内所在地での登記を「１．支援希望内容」として一括で申請させ、「２．支援期間（最長２年を限度）」を全体に対して1つだけ記入させる。称号にだけ別の期間を設ける規定や、支援メニューごとに期間を分ける記載は公開資料に無い。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_support_contents', 'established', '称号付与・施設設備の使用・知財優遇措置・学内住所での登記', '大学発ベンチャー支援申請書（様式1）「１．支援希望内容」が、(1)「川崎医科大学発ベンチャー」又は「川崎学園発ベンチャー」の称号、(2)本学施設・設備の使用、(3)本学が所有する知的財産権・ノウハウ等の使用に関する優遇措置、(4)本学施設・設備の使用期間中に限り登記住所を本学所在地とすること、(5)その他の希望、の5項目を列挙する。添付書類は履歴事項全部証明書、定款、会社概要、事業計画、利用する知的財産権・研究成果の概要ほか。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9e581f664d73', 'attr_source_docs', 'established', 'https://m.kawasaki-m.ac.jp/sanchi/venture.php・https://m.kawasaki-m.ac.jp/sanchi/document/venture_1.docx・https://m.kawas…', '大学発ベンチャーページが制度の入口で、申請様式（様式1・様式2）と年度毎の事業報告様式へのリンク、認定企業の掲載を持つ。支援申請書（様式1）が支援メニュー、支援期間、添付書類、付帯事項という制度の実体を示す唯一の公開文書。産学官連携・知的財産ポリシー（令和2年6月8日施行）が知財の帰属と対価配分を定める。規程本文を載せる「規程・様式」ページは学内限定で公開されていない。', 'official', 'https://m.kawasaki-m.ac.jp/sanchi/venture.php', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_cert_update', 'not_started', '期間・更新の定めなし（取消規定のみ）', '「ベンチャー企業に対する大学知的財産利用認定に関する要項」（2015年5月12日理事・副学長決裁、令和2年8月5日施行）の全8条と附則2本をPDF本文で通読した。第1条目的、第2条対象知財、第3条対象企業、第4条認定申請、第5条認定、第6条大学知的財産の利用、第7条認定の取消し等、第8条雑則で構成され、認定の有効期間、更新申請、更新審査、要件の再確認を定めた条項は存在しない。認定が終わる規定は第7条の取消しだけ。第8条は実施に必要な事項を別に定めるとするが、その細則は公開されていない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_title_restriction', 'not_started', '称号を付与せず、保証誤認防止の条項なし', '同要項の全8条に、認定企業へ称号を与える条項も、称号の使用範囲や使用停止を定めた条項もない。第1条は本認定の効果を「企業による本学知的財産の利用や、利用に当たっての優遇措置の適用を円滑に行うことができる」ことに限定し、大学が企業の品質、投資価値、経営状態を保証するものではないという誤認防止の注意条項も置いていない。大学名と学章の営利目的使用は別に広島大学学章使用細則が許可制と使用契約を定め、同細則第4条が本学の名誉を傷つけるおそれがあるときの許可取消を規定する。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_cancellation', 'established', '取消事由2号を規定、取消後の処理は定めなし', '要項第7条（認定の取消し等）は、発明審査会が(1)社会的信用を失墜する行為を行った場合、(2)その他本学と締結した契約等の取り決めに違反して本学に損害を与えた場合又は本学の名誉を傷つける恐れがある場合、に該当すると判定したとき、学長が本認定を取り消すものとすると定める。取消し後の称号返付、表示の削除、営業上の利用停止を求める条項はない。認定手続き側も第5条第2項が申請者への結果通知を定めるにとどまり、認定証の様式は要項に含まれない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_report_change', 'not_started', '年次報告・変更届の定めなし', '要項全8条に、認定企業の年次報告、代表者・所在地・資本構成の変更届、解散時の報告を求める条項はない。第6条第2項が利用許諾あるいは権利譲渡等の契約締結を義務づけるため、報告義務が個別契約側に置かれる余地はあるが、契約書ひな形は公開されていない。教職員側には広島大学利益相反管理に関する規則に基づく年1回の自己申告があり、起業マニュアルは対象例として「スタートアップ等から一定比率以上の株式等を取得している」場合を挙げるが、これは企業から大学への報告ではない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_support_request', 'established', '施設・機器・知財ごとに別途申請と許可', '認定は知財利用の有効性と妥当性を判断するもので、支援は別建ての申請と許可による。教育・研究施設の有効活用に関する規則第7条第1項が弾力的活用スペースの使用希望者に使用申請書での学長への申請と許可を求め、第6条が原則3年、第10条第1項が期間満了後の継続に新たな申請を要求する。インキュベーションオフィスは例年12月上旬の学内公募で翌年4月使用開始。共用機器は共用機器に関する規則第8条の利用者登録が要る。知財利用も要項第6条第2項で契約締結が別途必要。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000216.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_facility_registration', 'established', 'インキュベーションオフィス14室・原則3年、登記の定めなし', 'ベンチャービジネスの創出・育成支援ページが、東広島地区9室と広島地区（霞キャンパス総合研究棟）5室の計14室を、年1㎡当たり1万円（東広島）・2万円（広島）、入居期間は原則3年を超えない条件で提供すると記す。根拠は教育・研究施設の有効活用に関する規則で、第5条の産学連携使用スペースが本学の研究成果を活用した事業を行う者を対象とし、第8条が学外者に別途不動産の使用許可を求める。同規則を通読したが、当該スペースを本店所在地として商業登記できるかを述べた条文も、住所利用の記載もない。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_vc_connection', 'established', 'VCと支援投資組合の協定、外部支援機関も紹介', '2020年4月28日に株式会社広島ベンチャーキャピタルと「広島大学・広島県内大学発ベンチャー支援投資事業有限責任組合 設立・認定に関する協定」を締結し、研究シーズの事業化支援、大学発ベンチャーに対する投資、投資後の支援の3点で業務協力すると公表。窓口は産学連携推進部産学連携部門。大学発スタートアップ起業マニュアルP22は支援機関として、投資家・金融機関とのマッチングを支援するJ-Startup WEST、Healthcare Innovation Hub、MEDISO、INPIT知財支援窓口、広島市中小企業支援センターを掲載する。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/news/57802', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_eir', 'unknown', null, 'ベンチャービジネスの創出・育成支援ページの支援メニュー、大学発ベンチャーページ、大学発スタートアップ起業マニュアルのP21「広島大学の制度」とP22「支援機関」を読んだが、客員起業家、起業家メンター、起業家人材の招聘を制度として置いた記載はない。マニュアルが広島大学の制度として挙げるのは兼業手続きと利益相反管理の2つのみ。広島大学が主幹機関を務めるJST事業のPeace & Science Innovation Ecosystemは施策に「支援人材の拡充」を掲げるが、客員起業家制度の有無まで公開情報では確認できなかった。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_cxo_pool', 'unknown', null, '起業マニュアルは「経営経験があり、マネジメント力の高い人材をチームメンバーとして迎えることが難しい場合がある」を大学発スタートアップのデメリットとして挙げ、対処を事業計画書でのチーム構成の検討に委ねる。経営人材を紹介・マッチングする制度、人材データベース、CEO・CXO候補のプールに関する記載は、支援ページ、起業マニュアルのP21からP22、PSI関連の公開情報のいずれにもない。制度が無いと明記した文書も確認できていない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/252701/%E5%BA%83%E5%B3%B6%E5%A4%A7%E5%AD%A6%E2%80%97%E8%B5%B7%E6%A5%AD%E3%83%9E%E3%83%8B%E3%83%A5%E3%82%A2%E3%83%AB_0.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得する細則あり', '広島大学におけるライセンス等の対価として取得する株式等取扱細則（平成29年2月21日理事（社会産学連携担当）決裁、令和7年1月10日改正）第1条が大学発ベンチャー企業の育成を趣旨とし、第3条が相手方がベンチャー企業で対価の全額または一部の現金支払が困難な場合に株式・新株予約権で取得できると定める。第4条で発明審査会が審査、第5条で理事が取得の可否を決定し学長へ報告、第6条が新株予約権の行使、第7条が売却、第8条が経営参加権の原則不行使、第9条が換金後の報償金支払を規定する。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000832.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'pol_fund_investment', 'established', 'VCとの組合設立・認定協定。大学の出資規程なし', '制度としての関与は2020年4月28日に株式会社広島ベンチャーキャピタルと締結した「広島大学・広島県内大学発ベンチャー支援投資事業有限責任組合 設立・認定に関する協定」で、組合の設立と認定に大学が関与する枠組みを持つ。2026年3月27日公表のニュースは、株式会社ひろしまインキュベーション＆キャピタルが2026年1月7日にHIC第1号投資事業有限責任組合（出資約束金額11億9100万円、存続期間10年）を組成したと伝えるが、有限責任組合員に広島大学の記載はなく、大学の出資である旨も指定ファンドである旨も書かれていない。大学が自ら出資する規程は公開規程集に見当たらない。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/news/96554', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_regulation_owner', 'established', '大学規程（理事・副学長決裁の要項）', '認定の根拠は国立大学法人広島大学が単独で定める「ベンチャー企業に対する大学知的財産利用認定に関する要項」で、2015年5月12日に理事・副学長（社会産学連携・広報・情報担当）決裁により制定された学内文書。規則番号を持つ規則ではなく決裁による要項だが、学校法人規程でも外部機関との共同規程でもない。関連する技術移転細則、株式等取扱細則、共用機器に関する規則、教育・研究施設の有効活用に関する規則も、いずれも大学の公開規程集に収録された大学規程。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_review_body', 'established', '広島大学学術・社会連携室発明審査会', '要項第5条第1項「学長は、前条の申請があったときは、広島大学学術・社会連携室発明審査会（以下「発明審査会」という。）に諮り、企業が広島大学の知的財産を利用することの有効性及び妥当性を評価して、認定の可否を決定する」。第7条の取消しも発明審査会の判定に基づく。発明審査会は広島大学職務発明規則が置く常設の審査会で、認定専用の委員会ではなく、株式等取扱細則第4条の株式等取得審査も同じ審査会が担う。申請は第4条により理事（学術・社会連携担当）を経由して学長へ提出する。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_equity_decider', 'established', '理事（社会連携・基金・校友会担当）、審査は発明審査会', '株式等取扱細則第4条が広島大学学術・社会連携室発明審査会による審査と理事への報告を定め、第5条が理事（社会連携・基金・校友会担当）が審査結果に基づき株式等の取得の可否について決定し学長に報告すると規定する。第6条の新株予約権の行使、第7条の株式等の売却も同細則の手続きによる。細則自体は理事（社会産学連携担当）決裁で平成29年に制定されており、制定時の担当名と現行条文中の担当名が異なる。株式の寄附受入れは別に広島大学株式等による寄附金取扱規則が株式等受入審査会を置く。', 'official', 'https://public1.legalcrud.com/hiroshima_univ/act/110000832.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_amendment_decider', 'established', '理事・副学長（社会産学連携・広報・情報担当）決裁', '要項の冒頭に「(2015年5月12日 理事・副学長（社会産学連携・広報・情報担当）決裁)」とあり、学長裁定や規則番号を持つ規則ではなく、担当理事の決裁で制定・改廃される文書。附則は平成27年4月1日施行と令和2年8月5日施行（令和2年4月1日適用）の2本で、決裁者を変更する記載はない。第8条は実施に必要な事項を別に定めるとする。株式等取扱細則も理事（社会産学連携担当）決裁、技術移転細則は副学長（社会連携担当）決裁で、いずれも担当理事の決裁レベル。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_post_grad_limit', 'established', '規定なし（退職者は年限なく優遇対象）', '要項第3条が対象を「大学知的財産の利用を予定し、本学から利用許諾あるいは権利譲渡等を受けることを希望する企業」と定め、起業した個人の身分や退職・卒業からの経過年数を要件にしていない。技術移転細則第6条は「職員等が退職又は兼業によりベンチャー企業を設立し」た場合を優遇対象とし、退職者を含めるが年限を置いていない。要項全8条と技術移転細則のいずれにも、退職後・卒業後何年以内という期限規定はない。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_renewal_rule', 'established', '期限なし（要項に期間・更新の条項なし）', '要項に認定の有効期間を定めた条項がなく、更新申請、更新審査、届出による継続の規定もない。認定が終了するのは第7条の取消しに該当した場合だけで、取り消されない限り認定は継続する構造。第8条が実施に必要な事項を別に定めるとするため、学内細則で運用上の期限が置かれる余地は残るが、その細則は公開されていない。なお施設の使用許可は別制度で、教育・研究施設の有効活用に関する規則第10条第1項が期間満了後の継続に新たな申請と許可を求める。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_naming', 'established', '称号なし（公表では広島大学発ベンチャーと表記）', '要項は「広島大学知的財産利用認定」の可否を決めるもので、認定企業に称号を与える条項はなく、第1条の効果も知的財産の利用と優遇措置の適用に限られる。様式第1号の名称は「広島大学知的財産利用ベンチャー企業 認定申請書」。一方で大学の公表資料は「広島大学発ベンチャー」を用い、起業実績ページは令和8年4月1日現在で累計116社が設立されたと記載する。2024年12月時点の手引書の題名は「大学発スタートアップ起業マニュアル」で、本文はベンチャーとスタートアップを使い分けている。', 'official', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%AA%8D%E5%AE%9A%E8%A6%81%E9%A0%85%EF%BC%8820200401%E6%94%B9%E6%AD%A3%EF%BC%89HP%E7%94%A8.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_support_period', 'established', '支援ごとに別に定める（施設3年、実施料免除3年）', '認定自体に期間の定めがなく、支援ごとに期間が異なる。インキュベーションオフィスは教育・研究施設の有効活用に関する規則第6条と支援ページの記載により原則3年を超えない期間で、第10条第1項の再申請により継続できる。知的財産の実施料免除は技術移転細則第6条が当該ベンチャー企業の設立から3年を上限とする。共用機器の利用と、ライセンス対価としての株式・新株予約権の受入れには期間の定めがない。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_support_contents', 'established', '起業相談・入居施設・知財優遇・株式対価・共用機器・起業家教育', 'ベンチャービジネスの創出・育成支援ページと起業マニュアルP21からP22の記載による。起業相談窓口はスタートアップ推進部門、インキュベーションオフィスは計14室で年1㎡当たり1万円から2万円・原則3年、知的財産は権利化費用（直接経費）を目安とした有償譲渡・低率な実施料による独占的通常実施権・設立から3年を上限とする実施料免除、対価は株式や新株予約権でも受入れ可、共用機器は学外者料金で利用可、教育はMOT教育とアントレプレナーシップ養成およびひがしひろしま創業塾、ほかに起業マニュアルの配布と外部支援機関の紹介。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b23ba1a5f5b4', 'attr_source_docs', 'established', 'https://www.hiroshima-u.ac.jp/system/files/181970/%E5%A4%A7%E5%AD%A6%E7%99%BAVB%E7%9F%A5%E8%B2%A1%E5%88%A9%E7%94%A8%E8%…', '1本目が認定制度の一次資料である認定要項のPDF、2本目が支援メニューと料金を載せるベンチャービジネスの創出・育成支援ページ、3本目が手続きの流れと外部支援機関を載せる大学発スタートアップ起業マニュアルのPDF（2024年12月時点）。知財と株式の条文は公開規程集の技術移転細則（110000109）と株式等取扱細則（110000832）、施設は教育・研究施設の有効活用に関する規則（110000216）で読む。', 'official', 'https://www.hiroshima-u.ac.jp/iagcc/venture/kigyousupport', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_cert_update', 'established', '称号は原則永年・更新審査なし・支援は5年で延長可', '認定規則第5条第2項「「徳島大学発ベンチャー」の称号は，原則として永年使用することができる」。認定期間の区切り、更新申請、要件再確認を定めた条文は本則（第1条〜第11条）にも別記様式にも無い。称号の終了経路は第7条の解除申出（別記様式第3号）と第8条の取消しのみ。実質の継続要件は第6条第1項の年度毎の事業報告書等の提出で、不提出は第8条第1項第3号の取消事由になる。期間の再判断が働くのは第9条第2項の支援で、施設貸与・商業登記・研究設備利用は設立の日から5年を限度とし、学長が必要と認めた場合に延長できる。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_title_restriction', 'unknown', null, '［自動検証で否認: source_urlのガイドラインPDFに要項第6,7,9条の条番号記載なし］元の主張(established): 名義使用は学長許可制・品質保証の誤認表示を禁止。「国立大学法人徳島大学等における名義使用に関する要項」（令和2年7月21日学長裁定）第6条第1項は大学名義の営利使用を原則禁止し、同項第3号で「本学が認定した大学発ベンチャーの活動に係る宣伝広報」を学長許可の例外とする。第6条第2項で研究支援・産官学連携センターが内容を確認し、第7条で製造物責任を含む責任は使用者が負い、第9条で違反時に許可を取り消せる。「営利目的での大学の名義使用に関する承認ガイドライン」（令和2年10月8日、知財法務部門）は、大学が製造販売・宣伝内容の責任を負わないこと、製造物責任が及ぶと誤認される表示をしないこと、「徳島大学との共同開発」等の表現を避け「研究シーズを基に○○社が開発」とすること、「保証」「確実」等の語を使わないことを承認基準に置く。認定規則第8条第3項は取消し後の使用禁止を定める。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_cancellation', 'established', '取消4事由・称号記返付・認定事実の事業使用禁止', '認定規則第8条第1項が、センター会議の議を経て学長が認定と称号授与を取り消せる事由を4号列挙する。(1)事業活動が第2条の定義から著しく逸脱した場合、(2)社会的信用を失墜する行為を行った場合、(3)第6条第1項の事業報告書等を提出しない場合又は同条第2項の報告があった場合、(4)その他本学の不名誉となるおそれがある場合等で称号を保持させることが適当でないと認める場合。第2項で別記様式第5号により代表者へ通知。第3項「取消しを受けた者は，速やかに称号記を返付するものとし，当該取消しを受けた日以降，大学発ベンチャーとして認定を受けていた事実を事業に使用してはならない」。任意の解除は第7条で申出（別記様式第3号）→学長は認めるものとし別記様式第4号で通知。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_report_change', 'established', '年次事業報告書・異動事項届出書・解散等の即時報告', '認定規則第6条第1項で代表者は年度毎に自社の決算日から3か月以内に事業報告書と収支決算書を学長へ提出する義務を負う。第2項で会社法の解散、破産手続、民事再生手続、会社更生手続、不正競争防止法第21条の罰金刑確定に該当したときは代表者又は清算人が速やかに学長へ報告する。変更届は認定制度ページで「参考例:異動事項届出書」（tokudai-venture-idoujikou.docx）が配布され、代表者変更・所在地変更・事業年度変更・本店移転を対象とし、代表者変更時は履歴事項全部証明書の写し、定款変更時は定款の写しを添付する。事業報告様式（2024年9月1日改訂）は雇用者数、発行済株式総数、申請書記載事項の変更箇所の記載欄を持つ。', 'official', 'https://www.tokushima-u.ac.jp/ccr/active/venture/tokudai-venture-seido.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_support_request', 'unknown', null, '［自動検証で否認: ichiran.html40件確認、不動産貸付・名義使用許可申請書なし］元の主張(established): 支援ごとに個別申請（施設貸付・株式等申出・名義使用）。認定規則第9条第3項「第1項各号に規定する支援を行うときは，本学における関係規則等によるものとする」とし、認定と支援の手続を分けている。施設は研究支援・産官学連携センターの研究室ページで、教員は研究室利用申請書、大学発ベンチャーは不動産貸付申請書により申請し、地域共同インキュベーション研究室・ベンチャービジネス育成研究室の覚書を締結する。株式等による対価受領は認定ベンチャー対価規則第4条でセンターを受付窓口として申し出、第5条で知的財産専門委員会が審査する。広報での大学名義使用は名義使用要項第6条第2項により名義使用許可申請書を法人運営部総務課へ提出し学長の許可を得る。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_facility_registration', 'established', '施設貸与と所在地商業登記・設立後5年（延長可）', '認定規則第9条第1項第1号「事務室又は研究室として本学内の施設を貸与すること」、第2号「貸与した施設について，当該認定大学発ベンチャーの所在地とする商業登記を認めること」。商業登記は施設貸与を受けていることが前提で、第2項により設立の日から5年間を限度とし学長が必要と認めた場合に延長できる。対象施設は地域共同インキュベーション研究室とベンチャービジネス育成研究室で、センターの研究室ページに入居期間3年以内、利用代表者は徳島大学教員に限る旨が示され、規則・様式一覧に施設管理規則、利用の基本方針、利用申請書、両研究室の覚書、搬入機器の申し合わせ、使用心得、設置機器利用要項が揃っている。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_vc_connection', 'established', '産学連携キャピタルと連携協定・他企業紹介仲介を明記', '認定規則第9条第1項第4号「研究支援・産官学連携センター等による他企業への紹介又は仲介を行うこと」。VC接続は2020年5月21日に株式会社産学連携キャピタルと締結した「連携協力に関する協定書」が根拠で、連携事項は(1)研究シーズの社会実装化に関する支援、(2)徳島大学発ベンチャー企業の創業支援、(3)徳島大学発ベンチャー企業への支援。起業ハンドブックchapter2-04は、同社が運営する産学連携1号投資事業有限責任組合が徳島大学発ベンチャーへ株式投資しハンズオン経営支援を提供すること、徳島大学・阿波銀行・一般社団法人大学支援機構が主体となり地域経済活性化支援機構の特定専門家派遣を活用することを明記する。同章はNEDO、JST、中小機構、Otsucleも案内し、chapter2-01は大学産業院U-teraが投資が受けられるまで伴走支援すると記す。', 'official', 'https://www.tokushima-u.ac.jp/docs/20441.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_eir', 'not_started', '規定なし（起業支援メニューの列挙にEIRなし）', '認定規則第9条第1項は支援を5号（施設貸与、商業登記、研究設備利用、他企業紹介仲介、広報）で限定列挙し、起業家人材の招聘を含まない。起業ハンドブックchapter2「徳島大学の起業支援メニュー」もU-tera支援、認定制度、ビジネスコンテスト、助成金・外部資金の4項目のみで客員起業家の記載が無い。徳島大学大学産業院規則（令和5年度規則第15号）は全19条を通読したが、置く職員は大学産業院長、機構執行責任者、専任教員（特任教員を含む）、兼務教員、その他必要な職員で、外部起業家の招聘枠が無い。大学産業院の起業支援・産業人材育成部門ページとU-teraサイトにもEIRの記載が無い。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000830.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_cxo_pool', 'unknown', null, '制度としての人材プールやマッチング手続は公開文書に見当たらないが、支援が無いとも言い切れない。起業ハンドブックchapter1-01は「必ずしもご自身が経営者になる必要はありません。外部経営人材を活用し、自身はCTOとして技術支援を行うなど多くの道があります」とし、大学産業院に技術移転をサポートする人材と起業支援人材の双方が在籍して手伝う旨を記す。ただし候補者の登録名簿、紹介申請の様式、マッチングの手続を定めた規程・要項は、認定規則、大学産業院規則、センター規則・様式一覧、U-teraサイトのいずれにも無かった。chapter2の支援メニュー列挙にも経営人材紹介の項目が無い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_ip_equity', 'established', '実施権設定等の対価を株式・新株予約権で取得可', '「認定大学発ベンチャーから本学の収益を伴う事業の対価として取得する株式等取扱規則」（令和6年3月27日規則第90号、令和7年4月1日施行）第2条第2号アが「本学が所有する知的財産権の譲渡若しくは提供、実施権の設定又は実施権若しくは利用権の許諾」を対象事業に挙げ、イ学術指導、ウ研究成果有体物の提供、エ施設・設備等の資産貸与が続く。第2条第3号で株式等は株式、新株予約権、新株予約権付社債。第3条で事業の有望性、現金支払免除の必要性、反社会的勢力との無関係の3要件を課す。第5条で知的財産専門委員会が財務状況等を確認して審査、第6条で学長が可否を決定し契約書を締結。第7条は職務発明規則第13条の補償金を当該株式等の換金時に支払うと定める。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000834.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'pol_fund_investment', 'established', '出資取得規程あり・外部の産学連携1号ファンド', '「国立大学法人徳島大学株式等取扱規則」（令和6年3月27日規則第84号）第3条が株式等の取得経路を3号に限定し、第1号で国立大学法人法第22条に基づく出資による取得を認める。第4条で学長が、大学と発行者のあるべき関係性、役員派遣その他の経営関与、取得後の株主構成、本学の財務状況、取得金額を考慮して審査。第5条「出資による株式等の取得の決定は、経営協議会において審議し、役員会の議を経て、学長が行う」。第17条第2項で出資取得分は共益権を必要に応じて行使できる。一方で外部ファンドの産学連携1号投資事業有限責任組合は、大学支援機構と阿波銀行の出資で設立された株式会社産学連携キャピタルが運営しており、徳島大学自身の出資ではなく連携協力協定に基づく接続である。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000833.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_regulation_owner', 'established', '大学規程（国立大学法人徳島大学規則第21号）', '認定規則の題名は「国立大学法人徳島大学における大学発ベンチャーの認定に関する規則」で、平成28年10月19日規則第21号制定、令和3年7月29日規則第13号改正・令和3年8月1日施行。学校法人ではなく国立大学法人が定める学内規則で、附則の改正履歴も平成31年規則第89号、令和2年規則第80号、令和3年規則第86号、令和3年規則第13号とすべて同法人の規則番号で付番されている。株式等取扱規則（令和6年規則第84号）、認定ベンチャー対価規則（令和6年規則第90号）、大学産業院規則（令和5年規則第15号）、センター規則（平成27年規則第45号）も同じ体系にあり、規程主体は一貫して国立大学法人徳島大学。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_review_body', 'established', '徳島大学研究支援・産官学連携センター会議', '認定規則第3条第1項で申請者は大学発ベンチャー認定申請書（別記様式第1号）を学長に提出し、第2項「学長は，前項の申請があったときは，徳島大学研究支援・産官学連携センター会議（以下「センター会議」という。）の議を経て，認定を決定するものとする」。第4項でセンター長は審議に際しセンター会議の委員以外の者に意見を求め、又は申請者への面接を行うことができる。第8条第1項の取消しも同じセンター会議の議を経る。センター会議はセンター規則第11条で設置され、第12条で審議事項、第13条で委員構成を定める。株式等の審査は同規則第18条に基づく研究支援・産官学連携センター知的財産専門委員会が担う。認定事務は研究・産学連携部常三島研究・産学支援課（第10条）。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_equity_decider', 'established', '学長（知財専門委員会が審査・売却は役員会の議）', '株式等取扱規則（令和6年規則第84号）が経路別に決裁を分ける。第5条で出資による取得は経営協議会の審議と役員会の議を経て学長が決定。第11条第1項で認定大学発ベンチャーからの対価としての取得は第10条の審査を踏まえ学長が行い、下位の対価規則第5条で知的財産専門委員会が審査しセンター長が学長へ報告、第6条で学長が可否を決定して契約を締結する。第12条で管理責任者は会計規則第7条第2項の経理責任者。第13条で出資取得分と認定ベンチャー取得分は保有でき、株式公開等で公正な価格による売却が可能と認められた場合等に売却する。第16条第1項「株式等の管理及び売却に係る決定は、役員会の議を経て、学長が行う」。事務は経理部資産管理課（第19条）。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000833.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_amendment_decider', 'unknown', null, '認定規則は第11条の雑則で「この規則に定めるもののほか，大学発ベンチャーの認定に関し必要な事項は，別に定める」とするのみで、改廃の決裁主体を定めた条文が無い。株式等取扱規則（第20条雑則）、認定ベンチャー対価規則（第8条雑則）、大学産業院規則（第19条雑則）、研究支援・産官学連携センター規則も同様に改廃条項を置いていない。改廃手続の明文が確認できたのは上位の国立大学法人徳島大学規則第31条だけで、同条は「この規則の改廃は、教育研究評議会及び経営協議会で審議し、役員会の議を経て行う」と同規則自体を対象にしている。役員規則第2条の役員会審議事項にも規則の制定改廃が列挙されていないため、下位規則の改廃決裁者は公開情報から確定できなかった。', 'official', 'https://www.tokushima-u.ac.jp/legal/reiki_honbun/x383RG00000001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_post_grad_limit', 'established', '3年以内（第2条第4号該当時は1年以内）', '認定規則第2条第2号「本学を退職，卒業又は修了（以下「退職等」という。）した者で，退職等から設立までの期間が３年以内の者が所有する知的財産権を基に設立したもの」。認定制度ページの申請資格も「退職・卒業から企業設立までの期間は3年以内であること」と明示し、起業ハンドブックchapter2-02も同じ注記を置く。ただし別枠として第2条第4号は、職員等が設立者又は設立に深く関与するベンチャー企業について、退職等している場合は設立まで他の職に就かなかった場合又は設立までの期間が1年以内の場合を含むとしており、経路によって年限が異なる。学生が設立したものは第4条第5号で本学教職員からの推薦が必要。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_renewal_rule', 'established', '期限なし（原則永年使用・更新手続の定めなし）', '認定規則第5条第2項「「徳島大学発ベンチャー」の称号は，原則として永年使用することができる」。本則にも別記様式第1号から第5号にも、更新申請、期間満了、再審査、再申請の手続が置かれていない。別記様式は第1号が認定申請書、第2号が称号記、第3号が解除申請書、第4号が解除通知、第5号が取消通知で、更新用の様式が存在しない。認定制度ページの規則・様式欄も申請書、解除申請書、事業報告様式、異動事項届出書の参考例のみを掲げる。継続の可否が問われるのは第6条の年次報告を怠った場合等の第8条による取消しの局面に限られる。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_naming', 'established', '大学発ベンチャー（称号「徳島大学発ベンチャー」）', '規則名が「大学発ベンチャーの認定に関する規則」で、第2条が「大学発ベンチャー」を定義し、第5条第1項で学長が徳島大学発ベンチャー称号記（別記様式第2号）により「徳島大学発ベンチャー」の称号を授与する。認定された企業は第3条第2項以下で「認定大学発ベンチャー」と呼ばれ、株式等取扱規則第2条第3号、対価規則第2条第4号もこの語を引く。公開一覧のページ名も「徳島大学発ベンチャー企業一覧」。起業ハンドブックの本文はスタートアップという語を説明用に使うが、称号としての「大学発スタートアップ」の併記や独自名称は規則・様式・一覧のいずれにも無い。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_support_period', 'established', '支援ごとに別に定める（称号は永年・施設等は5年）', '認定規則は称号と支援で期間を分けている。第5条第2項で称号は原則永年使用できる一方、第9条第2項「前項第１号から第３号に定める支援については，設立の日から５年間を限度とする。ただし，学長が必要と認めた場合には，期間を延長することができる」として、施設貸与・商業登記・研究設備利用に期限を置く。起算点が認定日ではなく設立日である点に注意が必要で、設立から時間が経ってから認定を受けた場合は残期間が短くなる。第9条第1項第4号の他企業紹介仲介と第5号の広報には期間の定めが無い。実際の施設側はさらに短く、センターの研究室ページが入居期間3年以内としている。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_support_contents', 'established', '施設貸与・商業登記・研究設備利用・他企業紹介仲介・広報', '認定規則第9条第1項が「大学の管理運営及び教育研究に支障のない範囲において」行える支援を5号で限定列挙する。(1)事務室又は研究室として本学内の施設を貸与すること、(2)貸与した施設について当該認定大学発ベンチャーの所在地とする商業登記を認めること、(3)研究設備等の利用を許可すること、(4)研究支援・産官学連携センター等による他企業への紹介又は仲介を行うこと、(5)本学主催のイベント、本学の広報誌又はホームページにおいて広報を行うこと。これに加え認定ベンチャーだけの優遇として対価の株式等受領（対価規則）があり、認定外の共通メニューとして大学産業院U-teraの伴走支援、ビジネスコンテスト、助成金・外部資金案内が起業ハンドブックに載る。', 'official', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_3a28a90ae0d9', 'attr_source_docs', 'established', 'https://www.tokushima-u.ac.jp/fs/2/9/1/4/0/8/_/tokudai-venture-kisoku_210801.pdf・https://www.tokushima-u.ac.jp/legal/re…', '1本目が認定規則の本文と別記様式第1号から第5号までを含むPDFで、定義、認定手続、申請条件、称号、報告義務、解除、取消し、支援メニュー、期間、事務までを一冊で読める。2本目の国立大学法人徳島大学株式等取扱規則は、出資・寄附・認定大学発ベンチャーからの対価という3つの取得経路と、審査、決定、管理、売却、共益権不行使までを通した上位規程で、下位の対価規則（x383RG00000834.html）はここの第11条第2項を受けて作られている。3本目の起業ハンドブックは規程に載らないU-teraの3段階伴走支援、ビジネスコンテスト、GAPファンドや外部資金、VC接続を実務者向けにまとめている。運用の入口は認定制度ページ（tokudai-venture-seido.html）。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.tokushima-u.ac.jp/ccr/file/venture/TU-STARTUP-HANDBOOK.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_cert_update', 'not_started', '認定を行わないため認定期間・更新審査の定めなし', '慶應義塾大学関連スタートアップ制度のページは「本制度は支援対象企業等を定義することを目的としており、慶應義塾大学によるスタートアップの認定やその信用保証をするものではありません」と明記する。認定という行為自体が無いため、認定期間、更新の可否、更新審査、要件の再確認に関する規定は置かれていない。該当性は関連スタートアップの定義6要件のいずれかに当たるかで判断され、申請・更新の手続きは公開されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_title_restriction', 'established', '称号なし。認定・信用保証ではないと制度ページに明記', '慶應義塾大学関連スタートアップ制度のページが「本制度は支援対象企業等を定義することを目的としており、慶應義塾大学によるスタートアップの認定やその信用保証をするものではありません」と明記し、品質保証・信用保証と誤認させない旨を制度説明そのものに置いている。一方で称号の付与自体が無く、称号の使用範囲や使用停止を定める条項は存在しない。関連スタートアップの企業名リストも「公表しておりません」とし、大学名を冠した対外表示を大学が裏書きする構造を採らない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_cancellation', 'not_started', '認定・称号がなく取消事由や称号返付の定めなし', '認定・称号の付与が無いため、取消事由、称号の返付、表示の削除、営業利用の停止といった取消後処理の規定は制度ページに置かれていない。同ページは支援対象企業等を定義することが目的で、慶應義塾大学によるスタートアップの認定やその信用保証をするものではないと明記する。KSIP、CRIK信濃町入居、実施許諾契約といった個別支援ごとの解除条件は公開されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_report_change', 'not_started', '認定関係がなく年次報告・変更届の定めなし', '制度ページに申請・登録の手続きが無く、年次報告や代表者・所在地・資本構成の変更届、解散時報告に関する記載も置かれていない。同ページは支援対象企業等を定義することが目的で認定や信用保証はしないと明記し、企業名リストも公表しないとする。支援メニューを列挙するSupportページにも報告・届出の項目は無い。個別の契約や支援プログラムの中での報告義務は公開されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_support_request', 'established', 'KSIP・助成金・CRIKごとに個別申請と審査', '認定手続きは無い一方、支援ごとに独立した申請と審査がある。慶應スタートアップインキュベーションプログラム（KSIP）は通年応募でKSIPエントリーフォームから応募し、書類・対面審査を経て約10件／年を採択、常時5件程度を支援する。KSIP助成金は公募制で、応募主体を慶應義塾大学に在籍する教職員または学生とする。CRIK信濃町は入居希望をお問い合わせフォームで受け付ける。施設・資金・伴走支援がそれぞれ別の入口を持つ構成。', 'official', 'https://innov.keio.ac.jp/startup/support/ksip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_facility_registration', 'established', 'CRIK信濃町に入居し登記可（有料オプション）', '慶應義塾大学信濃町リサーチ＆インキュベーションセンター（CRIK信濃町、医学部／大学病院2号館9階）の会員プラン比較表に「登記」の行があり、オプション（有料）として提供される。プランは賃貸オフィス会員・専用デスク会員・ラウンジ会員の3種類で、施設は賃貸オフィス29室、デスクルーム26席、会議室3部屋等。利用条件は慶應義塾大学での研究・教育に由来するシーズ・技術やビジネスモデルを持つスタートアップなど4項目。ほかに慶應藤沢イノベーションビレッジがある。', 'official', 'https://crik.keio.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_vc_connection', 'established', '大学系VCの慶應イノベーション・イニシアティブと連携', 'Supportページの支援メニューに「ベンチャー・キャピタル」の項があり、株式会社慶應イノベーション・イニシアティブ（KII）による投資活動として案内される。KIIは株式会社慶應学術事業会が8割、野村ホールディングス株式会社が2割を出資して2015年12月17日に設立された会社で、KSIPではイノベーション推進本部とKII社が連携して伴走支援を行う。金融機関・自治体・外部支援機関への個別紹介を定めた制度は公開されていない。', 'official', 'https://innov.keio.ac.jp/startup/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_eir', 'unknown', null, '［自動検証で否認: 2025年CO2電極EIR公募の記載はtopics/205に無い］元の主張(established): 慶應版EIR（客員起業家）モデル。案件ごとに公募。2022年12月15日付の慶應義塾と株式会社ビズリーチの連携協定により「慶應版EIR（客員起業家）モデル」を構築し、研究成果を持つ研究者と起業をリードする経営プロ人材のマッチングを図るとTopics記事が示す。2025年3月5日にはイノベーション推進本部スタートアップ部門が、ダイヤモンド電極を利用したCO2の資源化に関わるプロジェクトの客員起業家（EIR）を公募し、併せてスタートアップ支援マネージャーも募集した。常設メニューではなく案件ごとの公募として運用されている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_cxo_pool', 'established', 'KSIPのビジネス人材プールとEIRの経営人材マッチング', 'KSIPの支援内容に「ビジネス人材プールからのチーム参画」が挙げられ、イノベーション推進本部とKII社が連携し、起業ツールキット提供、チーム目標設定・メンタリング、専門家相談やアイデア検証の機会とあわせて提供される。加えて慶應版EIRモデルが、ビズリーチとの連携協定に基づき経営プロ人材と研究者のマッチングを担う。CEO・CXO候補の登録名簿を公開する形式ではなく、プログラム内での紹介・参画として運用される。', 'official', 'https://innov.keio.ac.jp/startup/support/ksip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_ip_equity', 'established', '実施許諾・譲渡の対価として株式等での支払いを求める', '慶應義塾スタートアップ向け技術移転ガイドライン（2024年12月17日制定、2025年1月1日施行）3項(1)は「資金を成長等に投資する必要があるスタートアップからは、知的財産権の実施許諾および譲渡の対価として、一時金もしくはランニングロイヤリティ等の支払いの全部またはそれらの一部を代替することを目的として、株式等による支払いを求めるものとする」と定める。慶應義塾発明取扱規程第15条第1項は、株式・新株予約権等の売却収入を配分対象の実施料収入に含める。', 'official', 'https://drive.google.com/file/d/1AE1WRTQbHpZKFonRmhDn6UOh-juN7yGJ/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'pol_fund_investment', 'established', '慶應学術事業会が8割出資するKIIが3ファンドを運用', '株式会社慶應イノベーション・イニシアティブ（KII）は株式会社慶應学術事業会が8割、野村ホールディングス株式会社が2割を出資し2015年12月17日に設立された。1号ファンド、KII2号、KII3号インパクト投資事業の3本を運用し、LPには生命保険会社、産業革新投資機構、都市銀行等が参加する。あわせて慶應義塾発スタートアップ育成資金が寄付金制度として、スタートアップの創出・成長支援（ギャップファンド、シード投資を含む）に充てられる。義塾自身の出資規程は公開されていない。', 'official', 'https://www.keio-innovation.co.jp/about/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_regulation_owner', 'unknown', null, '［自動検証で否認: 受託研究等受入れ規程が大学名義との典拠が見当たらない］元の主張(established): ハイブリッド。学校法人規程が中心、一部が大学規程。認定規程そのものは存在しない。スタートアップ関連の主要文書のうち、慶應義塾発明取扱規程（平成17年2月22日制定、2024年12月17日改正）、慶應義塾対価収入の配分に関する細則、慶應義塾スタートアップ向け技術移転ガイドラインはいずれも学校法人「慶應義塾」名義で、改廃を塾長が決定する。一方、慶應義塾大学受託研究等受入れ規程は大学名義であり、法人規程と大学規程が併存する。主管はいずれも慶應義塾大学イノベーション推進本部。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_review_body', 'established', '認定審査なし。知財は知的資産実行会議が審議・決定', '認定制度が無いため認定委員会・審査会は置かれていない。知的財産の実施許諾・譲渡は慶應義塾発明取扱規程第11条の知的資産実行会議が審議・決定し、議長はイノベーション推進本部知的資産部門長が務め（同条2項）、委員は案件に応じて議長が指名する（同条3項）。重要案件は議長がイノベーション推進本部運営会議に報告し承認を受ける（同条6項）。KSIPの採否は運営部門による書類・対面審査で決まる。', 'official', 'https://drive.google.com/file/d/1WWi6Z5YsFJrz4DHcwMzjBNX_r_I4gsbg/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_equity_decider', 'established', '知的資産実行会議。重要案件は推進本部運営会議が承認', '慶應義塾発明取扱規程第11条第5項は、知的資産実行会議が「権利維持，譲渡および放棄に関する事項」および「第三者に対する特許権等の実施許諾，譲渡に関する事項」を審議し決定する権限を有すると定める。議長はイノベーション推進本部知的資産部門長（同条2項）、重要案件は議長が運営会議に報告し承認を受ける（同条6項）。株式等は実施許諾・譲渡の対価として取得するため（技術移転ガイドライン3項(1)）、取得可否は同会議の決定に係る。売却収入の配分は第15条と対価収入の配分に関する細則3項が定め、事務はイノベーション推進本部が行う。', 'official', 'https://drive.google.com/file/d/1WWi6Z5YsFJrz4DHcwMzjBNX_r_I4gsbg/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_amendment_decider', 'established', '塾長。イノベーション推進本部運営会議の審議を経る', '慶應義塾発明取扱規程第18条は「この規程の改廃は，イノベーション推進本部運営会議の審議を経て塾長が決定する」と定める。慶應義塾対価収入の配分に関する細則7項も同じ手続きを置く。慶應義塾スタートアップ向け技術移転ガイドライン5項は「このガイドラインの改廃は，イノベーション推進本部運営会議の発議に基づき，常任理事会の議を経て塾長が決定する」とし、ガイドラインについては常任理事会の議が加わる。', 'official', 'https://drive.google.com/file/d/1WWi6Z5YsFJrz4DHcwMzjBNX_r_I4gsbg/view?usp=sharing', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_post_grad_limit', 'established', '期限なし。在籍歴があれば年数を問わず対象', '関連スタートアップの定義のうち人材供給要件は「慶應義塾に在籍、または在籍した教職員・学生が創設メンバーや科学技術顧問」であり、退職・卒業からの年数制限は付されていない。技術移転、共同研究、資金調達、起業支援、その他慶應義塾との関連が認められるものという他の要件にも期限の記載は無く、関連性の有無だけで判断される。慶應義塾対価収入の配分に関する細則5項も、発明者等が退職または卒業した場合においても配分を行うと定める。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_renewal_rule', 'not_started', '規定なし。認定制度がなく更新の枠組みが無い', '認定制度が無いため更新の枠組み自体が置かれていない。制度ページは支援対象企業等を定義することが目的で、慶應義塾大学によるスタートアップの認定やその信用保証をするものではないと明記し、有効期間・更新審査・再申請に関する記載は無い。個別支援では、KSIPが通年応募で常時5件程度を支援、CRIK信濃町が会員制と、支援ごとに継続の扱いが分かれる。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_naming', 'established', '独自名称「慶應義塾大学関連スタートアップ」。称号付与なし', '制度の名称は「慶應義塾大学関連スタートアップ制度」で、対象を「慶應義塾大学関連スタートアップ」と呼ぶ。大学発ベンチャー、大学発スタートアップという称号を企業に付与する仕組みではなく、制度ページは慶應義塾大学によるスタートアップの認定やその信用保証をするものではないと明記する。企業名リストも公表しないとしており、称号としての対外使用を前提にしていない。支援サイトの名称は慶應スタートアップ。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_support_period', 'not_started', '規定なし。称号期間がなく支援ごとに扱いが分かれる', '称号・認定が無いため称号期間の概念自体が存在せず、支援期間を定める共通規定も公開されていない。KSIPは通年応募で約10件／年を採択し常時5件程度を支援するとだけ記載し、期間の明記が無い。CRIK信濃町は会員制で契約期間の記載が無い。知的財産の実施許諾契約は特許期間満了までを可能とする（慶應義塾スタートアップ向け技術移転ガイドライン3項(2)）。支援ごとに期間の扱いが分かれる。', 'official', 'https://innov.keio.ac.jp/startup/support/ksip/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_support_contents', 'established', 'KSIP・KSIP助成金・CRIK等施設・KII投資・EIR・COI管理', 'Supportページに列挙された支援メニューは、慶應義塾大学関連スタートアップ制度、インキュベーション施設、慶應義塾イノベサロン・ラボ、慶應義塾発スタートアップ育成資金、ベンチャー・キャピタル、利益相反マネジメント、KSIP助成金、慶應スタートアップインキュベーションプログラム（KSIP）、学内限定情報の9項目。これに加えTopics記事で慶應版EIR（客員起業家）モデルが案内される。', 'official', 'https://innov.keio.ac.jp/startup/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2e634684f6dc', 'attr_source_docs', 'established', 'https://innov.keio.ac.jp/startup/support/startup-system/・https://innov.keio.ac.jp/startup/support/・https://drive.google…', '1本目が慶應義塾大学関連スタートアップ制度のページで、関連スタートアップの定義6要件と、認定・信用保証をしない旨の明記を含む。2本目がSupportページで、支援メニュー9項目の全体像を示す。3本目が慶應義塾スタートアップ向け技術移転ガイドライン（2024年12月17日制定、2025年1月1日施行）で、株式等による対価支払い、特許期間満了までの独占実施許諾、主管と改廃手続きを定める。手続きの決裁構造は慶應義塾発明取扱規程を併読する。', 'official', 'https://innov.keio.ac.jp/startup/support/startup-system/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_cert_update', 'not_started', '認定制度なし・有効期間や更新審査の定めなし', '会員一覧ページ「『早稲田大学発ベンチャー』の呼称について」に「個別特定のベンチャー企業に対して、"早稲田大学発ベンチャー"およびこれに類する呼称を早稲田大学のもとで認定ないし付与することは行っておりません」と明記。認定制度自体が存在しないため、認定期間・更新可否・更新審査・要件再確認の定めも存在しない。代替枠組みのコミュニティ会員については、同ページおよびコミュニティ会員サービスページに期間・更新の記載がなく、確認できるのは会費が6か月分前払い制であることのみ。会員規約本文は公開されていない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_title_restriction', 'established', '認定・関与を否定する公表文（2011年）', '会員一覧ページの「『早稲田大学発ベンチャー』の呼称について」節に、呼称を大学のもとで認定ないし付与することは行っていない旨に加え、「早稲田大学及びアントレプレナーシップセンターは、当該企業の事業活動については、当該企業の責任のもとに行われ、早稲田大学及びアントレプレナーシップセンターは関与しておりません」と公表（2011年12月1日付）。称号を付与しないため、称号の使用範囲・使用停止に相当する条項は存在しない。品質保証や大学の関与と誤認されることの防止は、規程条項ではなくこの公表文で担保する形になっている。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_cancellation', 'established', '会員規約に基づく資格取消・取消企業を公表', '会員一覧ページに「※（社名）の会員取消について」という見出しで、「コミュニティ会員であった、（社名）について、早稲田大学アントレプレナーシップセンターは（日付）をもって、会員規約に基づき会員資格の取り消しを行いました」との公表が3社分（2020年・2021年・2025年）掲載されている。取消の根拠が会員規約であることは明示されるが、規約本文および取消事由の列挙は公開されていない。認定称号が存在しないため、称号返付・表示削除・営業利用停止に相当する取消後処理の規定は確認できない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_report_change', 'unknown', null, '現行のW-INC関連ページ（会員一覧、入会の流れ、コミュニティ会員サービス）に、年次報告、代表者・所在地・資本構成の変更届、解散時報告の定めは見当たらない。旧インキュベーション推進室時代の2016年1月の入居募集要領には「入居者には、毎月1回の事業活動報告を義務づけます」との記載があるが、現行の会員制度に引き継がれているかは確認できない。研究倫理オフィスの利益相反マネジメントページには年1回の定期自己申告が定められているが、これは兼業する教員側の義務であり、企業側の報告義務ではない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/news/2016/01/28/447', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_support_request', 'established', '個別審査あり（登記は入会後に別途審査・個室は入居契約）', 'コミュニティ会員サービスページに、法人登記は「一定の条件を満たした場合」に限られ「ご入会後に事業内容や活動実態等を確認させていただき、当センター所定の審査を経て、承認された場合に限りご利用いただけます」と明記。個室は「入居契約を交わした上で、施設内の個室を事業拠点として利用することができます」とされ、入会審査とは別の手続きが要る建て付け。入会の流れページの一次審査・二次審査・最終審査とは別枠。一方、研究機器利用・広報支援・外部紹介について独立した申請様式や審査の記載は確認できない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_facility_registration', 'established', '個室入居契約＋所定審査で法人登記可（19-3号館）', 'コミュニティ会員サービスページの提供サービス②に「法人登記ができます。早稲田大学アントレプレナーシップセンター（19-3号館）では、一定の条件を満たした場合、法人登記を行うことができます」と明記し、利用は入会後に事業内容・活動実態を確認する当センター所定の審査を経て承認された場合に限るとする。同ページの個室オプションは「入居契約を交わした上で、施設内の個室を事業拠点として利用することができます」と記載。起業用施設の利用と商業登記が同一施設で両立する。総合案内ページは同センターを19-3号館1階、開設2008年10月1日と記載。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_vc_connection', 'established', '提携VC2社・銀行・センター経由で紹介', 'サポーターページに、提携ベンチャーキャピタルとしてWERU InvestmentとBeyond Next Venturesを掲げ「本学の知的財産を活用したベンチャー企業への投資するファンドの組成、ハンズオン支援などを行う提携契約を締結」と記載。事業支援企業としてみずほ銀行（銀行取引に加え販路拡大・事業提携機会の提供）とSozo Ventures（経営人材の育成、Capital Formationの支援での連携）を掲載。紹介導線は「VCによる支援を希望する本学学生・教職員におかれましては、アントレプレナーシップセンターまでお尋ねください」と明記。自治体・公的支援機関への接続の記載は見当たらない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/supporter/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_eir', 'unknown', null, '研究者向け事業化支援ページには「事業化アドバイザー」が常駐し研究者に手厚いサポートを提供すると記載され、アドバイザー3名の経歴と支援内容が掲載されている。ただしこれはセンターが配置する専門人材の紹介であり、外部の起業家を客員起業家（EIR）として招聘する制度としての記載ではない。センター概要、サポーター、コミュニティ会員サービスの各ページにもEIR・客員起業家・起業家メンター制度の記載は見当たらない。制度の有無を公開情報で確定できないためunknownとする。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/for-researchers/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_cxo_pool', 'unknown', null, 'サポーターページはSozo Venturesとの連携について「ベンチャー企業の経営人材の育成、適切なCapital Formationの支援に関し、アントレプレナーシップセンターは今後同社と連携していくこと」と記すにとどまり、CEO/CXO候補を登録・紹介する人材プールの記述ではない。センターのニュースには京阪神スタートアップアカデミア・コアリション（KSAC）等が主催する、研究者とCXO候補人材のマッチングを目的としたプラットフォーム「ECP-KANSAI」のイベント告知が掲載されているが、主催は学外機関で【終了】表示。大学自身の経営人材紹介制度は確認できない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/supporter/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_ip_equity', 'unknown', null, '株式会社早稲田大学TLO設立ニュースによれば、同社は2024年4月11日設立で「早大100％出資の持株会社である早稲田大学グループホールディングス株式会社の傘下企業」であり、「知的財産化可能な技術シーズの発掘から、権利化や技術シーズに対するマーケティング、そしてライセンシングに至るまでを一貫して担当」する。ただし実施許諾の対価として株式や新株予約権を受け取る規程・運用の記載は同ニュースにも産官学連携ページにもない。大学発ベンチャーへの優先実施許諾や対価減免の記述も確認できない。', 'official', 'https://www.waseda.jp/inst/research/news/77947', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'pol_fund_investment', 'unknown', null, '［自動検証で否認: WUVの2022年4月/8月8日/ファンド名は記事に記載なし］元の主張(established): 大学出資VC2社経由の創業投資（WUV・WIC）。大学公式ニュースに「早稲田大学インパクト・キャピタル株式会社（WIC）」の設立が掲載され、運営会社を2025年10月21日に設立、ファンドは2026年に立ち上げることを目指すとし、株主構成として「学校法人早稲田大学 30％」と明記。投資対象はディープテックに人文・社会科学の知見を掛け合わせた領域。WICはディープテック分野の創業投資に注力する「早稲田大学ベンチャーズ株式会社（WUV）」に続くものと位置づけられる。WUVは2022年4月設立で、1号ファンド「WUV1号投資事業有限責任組合」を2022年8月8日に設立。WUVへの大学の出資比率は公式ページに記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_regulation_owner', 'not_started', '認定規程なし（会員規約は非公開）', '大学発ベンチャー認定規程は存在しない。会員一覧ページが呼称を大学のもとで認定・付与しないと公表しており、大学の情報公開ページに掲載される規則一覧（学校法人早稲田大学校規＝寄附行為、早稲田大学学則、大学院学則、学位規則、総長候補者選挙規則、および任期を定めた教員等の任期に関する規程等）にも、大学発ベンチャー認定に関する規程は含まれていない。実質的な枠組みのコミュニティ会員制度は資格取消の公表文で「会員規約に基づき」と記されるが規約本文が非公開のため、制定主体が大学か学校法人かを確定できない。', 'official', 'https://www.waseda.jp/top/about/work/regulations', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_review_body', 'established', '早稲田大学アントレプレナーシップセンター（入会審査を月1回）', '入会の流れページに、入会のご案内→書類審査（一次審査）→入会面談（二次審査）→入会申請→入会審査（最終審査）→結果通知→入会手続きの7段階が示され、最終審査はアントレプレナーシップセンターが月1回開催すると記載。センター概要ページによれば、同センターはリサーチイノベーションセンターのアントレプレナーシップセクションに属し、2021年1月に改名された組織。認定委員会に相当する組織は存在しない。旧制度では「インキュベーション推進室運営委員会」が入居更新の基準を持つ審議体だった。役員兼業の審査は別に「研究開発型ベンチャーの役員兼業に関する利益相反マネジメント委員会」が担う。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/membership-flow/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_equity_decider', 'unknown', null, '大学自身がベンチャーの株式・新株予約権を取得・処分する規程は、情報公開ページの規則一覧にも産官学連携ページにも見当たらない。学校法人早稲田大学が早稲田大学インパクト・キャピタル株式会社の株式を30％保有することは公式ニュースに記載されるが、その取得・処分を決裁する機関（理事会等）の記述は当該ニュースにない。学校法人早稲田大学校規（寄附行為）はBoxで公開されているがビューア形式で本文テキストを取得できず、議決機関の条文を確認できなかった。', 'official', 'https://www.waseda.jp/top/news/117770', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_amendment_decider', 'unknown', null, '大学の情報公開ページには学校法人早稲田大学校規（寄附行為）、早稲田大学学則、大学院学則、学位規則、総長候補者選挙規則などの主要な規則へのリンクしか掲載されておらず、規程の制定改廃手続を定めた条文はページ上に示されていない。校規本文はBoxのビューアで公開されているが本文テキストを取得できず、制定改廃の議決機関を確認できなかった。大学発ベンチャー認定規程が存在しないため、その改廃決裁者も定まらない。', 'official', 'https://www.waseda.jp/top/about/work/regulations', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_post_grad_limit', 'not_started', '規定なし（卒業・退職後の新規入会は不可）', '入会の流れページに「本学の在学生・専任教職員が対象です。卒業生、教職員を退職した方の入会はできません。」と明記されており、卒業・退職後に何年以内なら対象という猶予期間の考え方自体を採っていない。同ページには「ご卒業間近での入会につきましては、審査に一定の期間を要する都合上、特に2月および3月は審査期間の確保が困難であるため、入会をお受けしておりません」との記載もある。ただしコミュニティ会費の区分には卒業生・修了生の欄があり、在会中に卒業した場合の継続と読めるが、その扱いを明記した記述は確認できない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/membership-flow/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_renewal_rule', 'not_started', '規定なし（認定制度なし・会員規約は非公開）', '呼称の認定・付与を行わないため、認定の更新という概念が存在しない。代替のコミュニティ会員制度についても、会員一覧・入会の流れ・コミュニティ会員サービスの各ページに会員期間や更新審査の記載はなく、確認できるのは会費が6か月分前払い制であることのみで、会員規約本文は公開されていない。旧インキュベーション推進室時代の2016年入居募集要領には「入居期間は、原則として3年を限度」「インキュベーション推進室運営委員会の基準により更新（最大3年）を検討することもあります」とあったが、現行ページには引き継がれていない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_naming', 'not_started', '称号なし（呼称の認定・付与を行わない）', '会員一覧ページ「『早稲田大学発ベンチャー』の呼称について」に「早稲田大学では、早稲田大学に在籍する学生・教職員の手による起業およびベンチャー企業の支援を行っていますが、個別特定のベンチャー企業に対して、"早稲田大学発ベンチャー"およびこれに類する呼称を早稲田大学のもとで認定ないし付与することは行っておりません」と明記（2011年12月1日）。大学が付与する称号は存在せず、支援対象は「コミュニティ会員」（個室入居会員と一般会員の2区分）という会員資格で表される。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_support_period', 'established', '支援ごとに別に定める（会費6か月前払・個室は入居契約）', '称号を付与しないため称号期間という概念がなく、支援ごとに期間の建て付けが異なる。コミュニティ会員サービスページは「コミュニティ会費は6ヶ月分前払い制です」と記載し、個室利用は「入居契約を交わした上で」利用できるとして契約によるとする。早稲田PoCファンドプログラムは年度ごとの公募型。センター概要、総合案内、会員関連の各ページに、支援全体を通した一律の支援期間の定めは見当たらない。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_support_contents', 'established', 'ラウンジ・法人登記・個室入居・専門家相談・PoCファンド・起業家教育', 'コミュニティ会員サービスページが提供サービスとして「①Startup Loungeが利用できます。②法人登記ができます。③メールボックス（郵便受け）が活用できます。④無線LANが利用できます。⑤コンサルタントによる支援が受けられます。⑥MATLAB®が１年間無料で利用できます。」の6項目を列挙し、別に個室オプション（入居契約）を記載。センター概要ページは「起業家教育（グローバルエデュケーションセンターのビジネスクリエーションコース（BCC）科目、各種セミナー・プログラムの実施）」「早稲田PoCファンドプログラム」「起業活動支援」の3本柱を挙げる。研究者向けには事業化アドバイザーが常駐。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/comminuty-services/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7cd85e860bcd', 'attr_source_docs', 'established', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/・https://www.waseda.jp/inst/entrepreneur/winc/comminuty-servic…', '1本目の会員一覧ページは、呼称を認定・付与しない旨の公表（2011年12月1日）、会員規約に基づく資格取消の公表、個室入居会員と一般会員の一覧を載せており、認定・称号・取消の判断はここが起点になる。2本目のコミュニティ会員サービスページは、提供サービスの列挙、法人登記の可否と所定審査、個室の入居契約、会費の前払い区分を示す。3本目の研究倫理オフィス利益相反マネジメントページは、研究開発型ベンチャーの役員兼業に関する利益相反マネジメント規程（2021年4月1日施行）と、同名の委員会による審査・年1回の定期自己申告の運用を示す。', 'official', 'https://www.waseda.jp/inst/entrepreneur/winc/memberships/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_cert_update', 'not_started', '認定制度なし・施設利用は1〜3年で再審査', '東京大学アントレプレナープラザ支援企業選考規則（平成18年10月27日役員会議決・東大規則第39号）は支援企業の選考のみを定め、認定や称号の有効期間・更新審査の条項を置かない。有効期間があるのは施設利用契約で、アントレプレナープラザ募集要項2.(1)により審査委員会が1年・2年・3年のいずれかを決定する。契約の更新はできず、期間終了前の再申請と審査会承認で再契約する形をとる。要件の再確認は再申請時の審査によって行われる。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_title_restriction', 'established', '推薦は大学によるものでないと明示する義務', '「東京大学における研究成果に係る出所由来表示及び推薦に関するガイドライン」（平成17年12月20日総長裁定、令和2年11月1日実施）2.(1)は、本学が契約を締結していない又は契約の内容を超えた範囲で本学の名称・本学を想起させる呼称・マーク等の使用を第三者に認めることは法人として許容しがたいとする。2.(2)は、教職員等が第三者の製品やサービスを推薦する場合、推薦が自己の責任であり本学によるものでないことを明確にする義務と、顔写真等の使用への慎重な取扱いを定める。称号制度がないため称号の使用停止条項はない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400103789.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_cancellation', 'not_started', '取消制度なし・上場や事業統合で施設利用終了', '認定・称号の制度がないため、取消事由、称号返付、表示削除、営業利用停止の条項は支援企業選考規則にも募集要項にもない。アントレプレナープラザ募集要項2.(1)は、利用期間中に株式公開を行って上場企業になった場合、買収・合併・事業譲渡等により既存企業に事業が統合された場合には、原則として施設の利用を速やかに終了すると定める。表示面は出所由来表示ガイドラインが契約の範囲を超えた名称使用を認めない形で担う。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_report_change', 'established', '四半期ごとの事業報告・決算書提出・重要変更の報告', 'アントレプレナープラザ募集要項5.「事業化進捗状況の報告」は、支援企業に毎年度の決算書類提出と、原則3か月に1回の事業実施状況等の産学協創推進本部への報告を求める。加えて代表者や役員の変更、資金調達や資本構成の変化、事業状況の大きな変化があった際の報告を義務づけ、支援実績を把握するため支援期間終了後も事業に関して照会する場合があるとする。解散時の報告に関する規定は見当たらない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_support_request', 'established', '産学協創推進本部長への申請と審査委員会の審査', '東京大学アントレプレナープラザ支援企業選考規則第3条は、支援を希望する法人の代表者が事業計画等について本学所定の申請書類を産学協創推進本部長に提出しなければならないと定める。第4条は産学協創推進本部に置く東京大学アントレプレナープラザ審査委員会が事業に係る審査を行うとし、第5条はバイオサイエンス系実験を伴う場合にライフサイエンス委員会の実験審査を別途課す。起業相談／経営相談ページにも申請と審査を要する「大学発スタートアップ創出・事業化に向けた支援申請」の導線がある。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_facility_registration', 'established', '専有居室を1〜3年利用可・商業登記の可否は非公表', 'インキュベーション施設ページと募集要項により、本郷・駒場II・柏IIの6施設で居室の専有利用が可能で、期間は1年から3年、再契約可。ただしアントレプレナープラザの貸主は民間の㈱成信で、賃料等の条件は非公開の別紙2「建物賃貸に関するご案内」に委ねられ、要項本文には専有居室の転貸を原則禁止するとのみ記載がある。施設住所を本店所在地として商業登記できるかは、施設各ページ、募集要項のいずれにも記載がなく公開情報では確認できない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/activity/venture/incubation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_vc_connection', 'established', '東大IPC・UTECほか投資家の紹介とネットワーキング', 'アントレプレナープラザ募集要項1.の「支援の内容」は、東京大学協創プラットフォーム開発（株）や同社と連携する（株）東京大学エッジキャピタルパートナーズをはじめとする投資家の紹介、投資家・業界関係者・業務提携見込先等とのネットワーキング機会の提供を掲げる。起業相談／経営相談ページは、経営相談で内容に応じVC・弁護士・会計士などの専門家を手配するとし、関連支援機関ページがUTEC・UTokyo IPC・東大TLOを紹介する。自治体との接続は東京都との協定に基づくスタートアップ創出支援事業が該当。金融機関紹介の記載はない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_eir', 'established', '東大IPCが客員起業家（EIR）を認定し起業を無償支援', '本学100%出資で2016年設立の東京大学協創プラットフォーム開発（株）（東大IPC）が運営するスタートアップ創造プログラムは、客員起業家（EIR）を厳選認定し、研究者の紹介を含め技術シーズの商用化を目的とした起業を無償で支援すると明記する。募集要項・条件はフルタイムの仕事との両立可、起業準備の段階に応じたマイルストーンを設けて認定継続を判断、必要に応じ起業活動資金を支給とし、応募受付・面接・合否通知の選考フローを持つ。大学本体の学内規程ではなく、出資先会社の制度である。', 'official', 'https://startup-building-program.utokyo-ipc.co.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_cxo_pool', 'established', '東大IPC認定の経営者候補人材と研究者のマッチング', '東大IPCのスタートアップ創造プログラムは、研究者向け技術シーズ商用化支援で活用できるリソースとして「東大IPCが認定する経営者候補人材（客員起業家（EIR））とのマッチング機会」を挙げ、支援内容に経営チームの組成を含める。EIRの募集対象自体が経営者候補人材とされている。産学協創推進本部側は募集要項1.で法務・会計・税務・デザイン等の専門家紹介を掲げるが、CEO/CXO候補の人材プールを大学規程として持つ記載はない。', 'official', 'https://startup-building-program.utokyo-ipc.co.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_ip_equity', 'established', 'ライセンス及びベンチャー支援に伴う株式等取得取扱規則', '産学協創推進本部「規則・様式等一覧」の規則・細則欄に「東京大学におけるライセンス及びベンチャー支援に伴う株式等取得取扱規則」が掲載され、ライセンスやベンチャー支援に伴って株式等を取得する枠組みが存在することを確認した。リンク先は学内限定領域で外部からは403となり、条文と決裁者は未確認。東京大学規則集の公開目次には本規則が載らず、公開されている株式等取得規則は寄附によるものと技術研究組合に係るものの2件のみである。', 'official', 'https://www.ducr.u-tokyo.ac.jp/rules_and_forms/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'pol_fund_investment', 'unknown', null, '［自動検証で否認: 100%出資はTLOの記述。IPCに出資比率の記載なし］元の主張(established): 本学100%出資の東大IPCによるファンド出資・投資。関連支援機関ページは、東京大学協創プラットフォーム開発（株）（UTokyoIPC）を、産業競争力強化法における特定研究成果活用支援事業（国立大学法人によるベンチャーファンドへの出資促進業務）の実施のため2016年に設立された会社と説明し、東京大学・民間ベンチャーキャピタル・ファンドへの出資機関等との連携を掲げる。（株）東京大学エッジキャピタルパートナーズ（UTEC）はシード・アーリー段階のハンズオン型投資を行うファンド運営会社。学内側は「東京大学における出資を目的とした株式等取得取扱規則」（令和6年3月18日改正）が規則・様式等一覧に掲載されるが本文は学内限定。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_regulation_owner', 'established', '大学規程（役員会議決の東大規則）', '東京大学アントレプレナープラザ支援企業選考規則は平成18年10月27日役員会議決・東大規則第39号として制定され、東京大学規則集第4編第2章「研究・産学連携等」に収載されている。東京大学における寄附による株式等取得取扱規則も平成18年1月30日役員会議決・東大規則第55号。いずれも国立大学法人東京大学が自ら定める大学規程であり、学校法人規程や外部団体の規程ではない。なお、認定制度そのものを定める規程は存在しない。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_review_body', 'established', '東京大学アントレプレナープラザ審査委員会', '支援企業選考規則第4条は、申請の選考を行うため東京大学アントレプレナープラザ審査委員会を産学協創推進本部に置き、同委員会が事業に係る審査を行うと定める（委員会の詳細は別に定める）。第5条はバイオサイエンス系実験について東京大学アントレプレナープラザ・ライフサイエンス委員会を置き実験に係る審査を行うとし、第6条により産学協創推進本部長が審査結果を申請者と施設貸主へ通知する。募集要項4.(2)によれば審査委員長は産学協創推進本部長で、UTokyoIPCとUTECのメンバー等がオブザーバー参加する。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_equity_decider', 'established', '総長（寄附による株式等の受入決定）', '東京大学における寄附による株式等取得取扱規則（平成18年1月30日役員会議決・東大規則第55号）第3条はディベロップメントオフィスが受入審査を行うとし、第4条は株式寄附の受入決定を総長が行うと定める。第8条は一般企業の株式等について換金可能な時点で速やかに換金し、総長が換金額を受入担当部局長に通知するとし、第9条第2項はインサイダー取引防止責任者にCFOを充てる。ライセンス及びベンチャー支援に伴う取得と出資を目的とした取得の各規則は学内限定で、決裁者は未確認。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_pdf/h180130055.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_amendment_decider', 'established', '役員会（規則第8条で改廃を規定）', '東京大学アントレプレナープラザ支援企業選考規則第8条は「この規則の改廃は、役員会の議を経て行う」と明記する。同規則も東京大学における寄附による株式等取得取扱規則も、いずれも役員会議決として制定され、附則に施行日が列記されている。規則に定めのない選考の細目については、同規則第7条により産学協創推進本部長が別に定めるとされ、審査委員会とライフサイエンス委員会の構成も別に定める扱い。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_post_grad_limit', 'established', '関連性で判断（卒業間もない卒業生を対象に含む）', 'アントレプレナープラザ募集要項3.②は、本学の役員・教職員・学生（卒業間もない卒業生も含む）等が出資等によって設立に深く関与した設立後10年以内の未上場法人を対象とし、卒業後の年数で線引きしていない。2026年度スタートアップ創出支援事業の対象者②は「本学の在学生、または卒業生が、在学中の研究活動等を基に創業した、または創業予定のスタートアップ」とし、卒業後の年限を置かず在学中の研究活動との関連で判断する。支援企業選考規則第2条には卒業生に関する記載がない。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_renewal_rule', 'established', '更新不可・再申請（再審査で再契約、通算10年上限）', 'アントレプレナープラザ募集要項2.(1)は、利用期間を事業の状況や施設の利用目的等を勘案して審査委員会が1年・2年・3年のいずれかで決定し、契約の更新はできないが、契約期間終了前に再申請し再度審査会での承認を受ければ再契約できると定める。再契約の回数に制限はないが、産学協創推進本部が運営・管理するインキュベーション施設を通算10年以上利用することはできない。共用オフィスは1年で再契約1回、共用バイオ実験室は1年で原則2回まで再契約可。', 'official', 'https://www.ducr.u-tokyo.ac.jp/content/400104225.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_naming', 'established', '称号なし（規則では大学発ベンチャー企業と呼称）', '申請にもとづく称号授与の制度はない。呼称は文脈で分かれ、東京大学アントレプレナープラザ支援企業選考規則第1条は「本学と関係の深い大学発ベンチャー企業」と書き、産学協創推進本部サイトの区分名も「起業・大学発ベンチャー支援」である。一方、創出数の公表とスタートアップ創出支援事業のページは「東京大学関連スタートアップ」を用いる。いずれも支援対象の呼び方であって、企業に付与する称号ではない。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_support_period', 'unknown', null, '［自動検証で否認: 経費支援の記載が要項になし、施設期間のみ］元の主張(established): 支援ごとに別に定める（施設1〜3年、経費支援は年度）。称号制度がないため称号期間は存在せず、期間は支援ごとに個別に決まる。アントレプレナープラザ、南研究棟アントレプレナーラボ個室、駒場連携研究棟、柏IIアントレプレナーハブは1年から3年、共用オフィスと共用バイオ実験室は1年で、再契約の可否と回数も施設ごとに異なる。2026年度スタートアップ創出支援事業は実施期間を2027年3月31日までとし、上限に達し次第早期に締め切る場合があるとする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 経費支援は要項になし、他7項目は完全一致］元の主張(established): オフィス・実験室・共用設備・経営アドバイス・専門家紹介・投資家紹介・経費支援。アントレプレナープラザ募集要項1.の「支援の内容」は、オフィスや実験室スペースの提供、共用会議室やラウンジ等の施設内共用設備、事業化推進のための相談受付と経営アドバイス、法務・会計・税務・デザイン等の専門家紹介、UTokyoIPCやUTECをはじめとする投資家の紹介、投資家・業界関係者・業務提携見込先とのネットワーキング、支援先企業間のネットワーキング、本学教職員や学生との接点、各種公的支援制度の紹介を列挙する。ほかに共用研究設備・機器の有料利用、法務支援、経営相談、スタートアップ創出支援事業の経費支援がある。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ff01bb8086e3', 'attr_source_docs', 'established', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html・https://www.ducr.u-tokyo.ac.jp/content/40010422…', '制度の骨格はこの3本で読める。東京大学アントレプレナープラザ支援企業選考規則が申請先、審査体制、改廃主体を定める唯一の学内規則。アントレプレナープラザ募集要項（2025年6月、産学協創推進本部）が支援内容、対象、利用期間、再契約、報告義務を定める。産学協創推進本部の規則・様式等一覧が株式等取得やライセンス関係の各規則の所在を示すが、株式等取得のうち条文が公開されているのは寄附によるものだけである。', 'official', 'https://www.u-tokyo.ac.jp/gen01/reiki_int/reiki_honbun/u0740896001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_cert_update', 'not_started', '無期限・更新審査なし（失効と取消のみ規定）', '称号規則（令和6年10月4日規則第132号）を第1条から第10条・附則まで全文確認したが、認定期間・更新手続・要件の再確認を定める条文はない。期間に関わる規定は第6条第2項の「企業の買収、統廃合等により法人格の同一性が保たれない場合は、その効力を失う」と、第9条の学長による遡及取消のみ。第8条の事業報告書も「本学からの求めに応じ」であり、定期の更新審査ではない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_title_restriction', 'established', '免責条項あり（安全性・有効性を担保せず）', '称号規則第6条第3項「本学は、称号を授与した企業に対して、成果の安全性及び有効性等を担保するものではなく、また、一切の法的責任を負うものではない」。第2条で称号企業は「東京科学大学認定ベンチャー」及び「Science Tokyo Venture」の名称を利用できると定める。第9条第2項は取消後に「称号を授与されていた事実を事業に使用してはならない」と使用を止める。投資推奨や経営状態の保証に触れた条文はない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_cancellation', 'established', '遡及取消・称号記の返付・取消後の使用禁止', '称号規則第9条第1項で「社会的信用を失墜する行為を行ったとき」「称号を保持させることが適当でないと学長が認めるとき」に、学長が審査委員会の議を経て称号を遡って取り消す。第2項で取消企業は速やかに称号記を返付し、取消日以後は称号を授与されていた事実を事業に使用してはならない。第6条第2項は買収・統廃合で法人格の同一性が保たれない場合の失効を定める。ウェブ掲載の削除に関する明文はない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_report_change', 'established', '求めに応じ事業報告書を提出（変更届なし）', '称号規則第8条「称号企業は、本学からの求めに応じ、別に定める事業報告書により、本学に活動内容等を報告しなければならない」。イノベーションデザイン機構の申請資格・手続きページも「本学から事業報告書の提出を求められた場合」の様式として掲載し、2026年9月時点で「様式準備中」。定期の年次報告義務、代表者・所在地・資本構成の変更届、解散時報告を定める条文は規則にも申請案内にもない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_support_request', 'established', '施設は別途入居申請と専門委員会の審査', '認定とは別に施設ごとの個別申請と審査がある。Innovation Design Studio使用細則（令和6年細則第67号）第6条はオフィス・コワーキングの入居申請を施設長に提出させ、入居審査専門委員会の審査を経て可否を決定し、第8条は一時使用スペースの使用申請と施設長の許可を定める。TIPに係る共用実験室利用細則（令和6年細則第82号）第4条は利用申請書を医療イノベーション機構長に提出し運営委員会の議を経て許可。機器・広報・紹介の個別審査制度は確認できない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002099.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_facility_registration', 'established', 'TIPシェアラボは利用許可＋申請で登記可', 'TIPに係る共用実験室利用細則第12条（住所の登記）「利用責任者は、医療イノベ機構長への申請により当該スタートアップの所在地としてシェアラボを登記することができる」。同細則第3条で研究開発型スタートアップ（起業準備を含む）が利用対象、第9条で利用期間は原則3年以内、1年以内の延長を2回まで、最大5年。田町のInnovation Design Studio使用細則には登記の条文はなく、セットアップオフィスは第7条で定期建物賃貸借契約を締結する。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_vc_connection', 'established', '1st Round共催とGTIE主幹機関', '認定ベンチャー支援ページの「1st Round」は、東京大学協創プラットフォーム開発（東大IPC）が事務局を務めるプログラムを複数大学と共催するもので、ベンチャーキャピタルから外部調達する前のチームや設立3年以内のベンチャーに最大1,000万円を補助する。産学連携サイトのベンチャー創出活動ページは、大学・地方公共団体・VC・CVC・アクセラレーター・民間企業が結集するGTIEの主幹機関と記載。活動スペース支援ページは大田区・港区・横浜市・川崎市の自治体施設を情報提供する。', 'official', 'https://www.idp.ori.titech.ac.jp/venture/support/1stround/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_eir', 'established', '客員起業家（EIR）とのマッチング制度', 'イノベーションデザイン機構の「その他の起業支援」に「客員起業家（EIR）とのマッチング」を独立メニューとして掲載。ページ本文は「本学は、ビズリーチ社との協定に基づき、研究シーズを有する教員と共に起業するための経営者候補として、客員起業家（EIR）を募集し、学内教員の起業を支援しています」と説明し、転職サイト上でEIR等の人材を募集すると記す。過去の公募例も掲載。対応する要項は公開規程集には見当たらず、根拠は公式ページ。', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/other-support/recruitment-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_cxo_pool', 'established', '経営者候補を転職サイトで公募・マッチング', '同じ「客員起業家（EIR）とのマッチング」ページに「転職サイト『ビズリーチ』上で客員起業家（EIR）等の人材を募集し、起業にあたって課題となる『経営のプロ』の確保を支援いたします」と明記。教員のシーズと共に起業する経営者候補を外部から公募する形で、常設の人材プール名簿ではなく協定に基づく公募・マッチングとして運用されている。産学連携サイトも経営人材の確保支援を起業支援メニューに数える。', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/other-support/recruitment-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_ip_equity', 'established', 'ライセンス対価に株式・新株予約権を取得可', '「研究開発成果活用促進支援に伴う株式等の取得に関する規則」（令和6年10月1日規則第116号、令和8年6月16日改正）第2条第3号でライセンスを特許権等の譲渡・実施又は利用・使用の許諾（成果有体物の貸与及びノウハウの使用許諾を含む）と定義し、第5号でライセンスと施設使用を研究開発成果活用促進支援と定める。第3条で対象企業から対価として株式等を譲渡・付与する提案があった場合に取得の可否を決定。第2条第6号は株式等を株式及び新株予約権と定義。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'pol_fund_investment', 'established', '認定VC・LPS・指定事業者への出資事業あり', '「ベンチャー支援出資事業モニタリング委員会要項」（令和6年10月1日制定、令和8年4月1日適用の改正あり）第2条が、大学の研究成果等を活用したベンチャー企業支援のため大学が実施する出資事業のモニタリングを目的と定める。第3条は産業競争力強化法第19条第1項の認定特定研究成果活用支援事業者（株式会社及び投資事業有限責任組合）と、国立大学法人法第34条の2第1項の指定国立大学研究成果活用事業者を定義。第8条で出資先の業務運営・運用実績をモニタリングし、新たな出資先の選定も協議する。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001717.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_regulation_owner', 'established', '大学規程（東京科学大学規則第132号）', '称号規則は「東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則」（令和6年10月4日規則第132号）で、規程集の体系情報は「東京科学大学／[全学規則]／第8編 研究・産学連携」。国立大学法人の全学規則として制定され、附則第2項で旧・東京工業大学の同名規則（平成16年規則第140号）と旧・東京医科歯科大学の規則（平成24年規則第96号）を廃止した。学校法人規程やハイブリッドではない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_review_body', 'established', '東京科学大学認定ベンチャー称号授与審査委員会', '称号規則第4条第1項でイノベーションデザイン機構に「東京科学大学認定ベンチャー称号授与審査委員会」を置く。第2項の構成は機構長、副機構長、産学共創機構長、医療イノベーション機構長、その他機構長が指名する者で、第3項により委員長は機構長。第5条第3項で審査手順及び基準を審査委員会が定め、第4項で審議の内容・結果を研究・イノベーション本部規程（令和6年規程第144号）第7条のイノベーション合同会議の議を経て学長へ報告する。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_equity_decider', 'established', '理事長（株式等受入審査委員会の議を経て）', '株式等取得規則第3条「当該提案を受けた理事長は、次条に定める株式等受入審査委員会の議を経て、株式等の取得の可否を決定する」。第5条で委員会は株式等の取得可否と取得時の経済条件を、別に定める審査基準に基づき審議。第6条の構成はイノベーションを担当する理事（委員長）、産学共創・医療イノベーション・イノベーションデザインの各機構長、学外有識者若干人など。第10条は取得した株式等の評価・売却その他の取扱いを「別に定める」とし、処分の決裁者は公開規程では未特定。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_amendment_decider', 'unknown', null, '称号規則には改廃手続の条文がなく、第10条は「この規則に定めるもののほか、必要な事項は、学長が別に定める」との委任のみ。役員会規則（令和6年規則第7号）第3条の審議事項は、文部科学大臣の認可・承認事項、予算の執行及び決算、重要な組織の設置又は廃止、その他役員会が定める重要事項の4号で、規則の制定改廃を明示していない。規程集の第1編（組織及び運営）と第2編（総務）にも規則等の制定手続を定める規程は見当たらない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001705.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_post_grad_limit', 'established', '期限なし（申請時の経営参画を要件とする）', '称号規則第3条第5号ロは関連ベンチャーとして「設立した者又は設立に深く関与した者の全部若しくは一部が本学の学生であった者であって、かつ、称号の申請時において当該学生であった者が経営に参画するもの」と定め、卒業からの年数制限を置いていない。同号イも他大学等研究機関に所属した際に起業した本学職員を、申請時の経営参画を条件に対象とする。ハで「その他学長が特に認めるもの」も認める。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_renewal_rule', 'established', '期限なし（更新手続の定めなし）', '称号規則には有効期間と更新の条文がなく、称号が終わる規定は第6条第2項の失効（買収・統廃合により法人格の同一性が保たれない場合）と第9条の取消しだけ。再申請や届出による更新の手続も置かれていない。イノベーションデザイン機構の申請資格・手続きページも申請書・誓約書・必要書類による新規申請の案内のみで、更新に関する記載はない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_naming', 'established', '独自名称（東京科学大学認定ベンチャー）', '称号規則第2条「本学がベンチャー企業に授与する称号は、『東京科学大学認定ベンチャー』とする。称号の英語名称は、『Science Tokyo Venture』とし」。大学発ベンチャー／大学発スタートアップではなく、大学名に認定ベンチャーを付す独自名称。附則第3項により旧称号の東工大発ベンチャーと東京医科歯科大学発ベンチャーも引き続き利用でき、申請ページは旧称号企業が新称号を使う場合の番号を第T001〜T175号、第MD01〜MD15号と定める。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_support_period', 'established', '支援ごとに別に定める（規則第7条）', '称号規則第7条「本学は、称号企業に対し、本学の管理運営及び教育・研究に支障のない範囲において支援を実施することができるものとし、具体的な内容及び支援期間その他支援の実施に必要な事項は、別に定める」。称号自体に期間の定めがない一方、支援期間は支援ごとの定めに委ねられる。実例としてTIPに係る共用実験室利用細則第9条はシェアラボの利用期間を原則3年以内とし、延長2回で最大5年とする。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_support_contents', 'established', '活動スペース・1st Round・GAPファンド・EIRマッチング・起業相談室', '認定ベンチャーへの支援ページのメニューは1st Round、称号記授与式、ネットワーキングイベント、活動スペースの支援の4本。活動スペースはINDEST（田町）とTIP（湯島）、Science Tokyo横浜ベンチャープラザ、連携自治体の施設情報。起業を目指す方向けには資金支援（Science Tokyo GAP Fund Program 2026、社会変革チャレンジ賞、学生スタートアップ支援、GTIE GAPファンド）、Go Startup起業相談室、STARTech、客員起業家（EIR）とのマッチングを掲載。', 'official', 'https://www.idp.ori.titech.ac.jp/venture/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_251654a7c128', 'attr_source_docs', 'established', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html・https://www.idp.ori.titech.ac.jp/venture/app…', '1本目は称号授与規則（令和6年規則第132号）で、申請資格・審査体制・支援の委任・報告義務・取消しの正本。2本目はイノベーションデザイン機構の申請資格・手続きページで、申請書と必要書類、認定件数、事業報告書様式を案内する運用の入口。3本目は研究開発成果活用促進支援に伴う株式等の取得に関する規則（令和6年規則第116号）で、ライセンス対価としての株式・新株予約権の取得を定める。施設は細則第67号と細則第82号が正本。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_cert_update', 'unknown', null, '起業ハンドブック（2025年12月改版）7章「申請から認定までの大まかな流れ」は、審査委員会の審査を経て理事長が認定し、認定された場合に「支援基本契約書」（契約期間原則5年以内）を締結する、までを示すのみ。認定そのものの有効期間、更新の可否、更新審査、要件の再確認を定めた記載はない。「大学認定スタートアップになるには」も認定の効果を称号使用許可と施設・設備の貸与とするだけで期間に触れていない。認定規程本文は学外非公開。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_title_restriction', 'unknown', null, '「大学認定スタートアップになるには」は「東京理科大学発の称号使用許可、施設・設備の貸与など、ソフト・ハード両面からバックアップします」と書くのみで、称号の使用範囲、表示媒体、使用停止の条件を定めていない。起業ハンドブック13章の「学内認定スタートアップへの支援内容」も1番目に「東京理科大発スタートアップ企業」の称号授与を挙げるだけ。品質保証・投資推奨・経営状態の保証と誤認させない旨の条項は公開情報に見当たらない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_cancellation', 'unknown', null, '取消事由、称号の返付、表示の削除、営業利用の停止を定めた記載は、「大学認定スタートアップになるには」にも起業ハンドブック7章の認定フローにもない。施設側の「東京理科大学葛飾キャンパス産学連携スペース利用規則」は開館時間、鍵の受け渡し、薬品の取扱いなど13項目の利用条件を定めるが、利用許可の取消事由は含まない。認定規程本文が学外非公開のため、解除・取消の規律は確認できない。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2026/03/2.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E8%91%9B%E9%A3%BE%E3%82%AD%E3%83%A3%E3%83%B3%E3%83%91%E3%82%B9%E7%94%A3%E5%AD%A6%E9%80%A3%E6%90%BA%E3%82%B9%E3%83%9A%E3%83%BC%E3%82%B9%E5%88%A9%E7%94%A8%E8%A6%8F%E5%89%87_2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_report_change', 'unknown', null, '2026年度入居者募集要項4(3)②に「入居後、事業の進捗状況等を本学の求めに応じて報告してください」とあり、施設入居者には求めに応じた進捗報告義務がある。ただし年次報告の周期、代表者・所在地・資本構成の変更届、解散時報告を定めた記載は、募集要項にも起業ハンドブック7章にも「大学認定スタートアップになるには」にもない。認定側の報告義務は支援基本契約書に委ねられ、契約書は非公開。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2025/10/1.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%83%AB%E3%83%BC%E3%83%A0%E5%8F%8A%E3%81%B3%E7%94%A3%E5%AD%A6%E8%A9%A6%E4%BD%9C%E9%96%8B%E7%99%BA%E5%AE%A4%E5%85%A5%E5%B1%85%E8%80%85%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85_2026%EF%BC%884%E6%9C%8821%E6%97%A5%E8%BF%BD%E8%A8%98%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_support_request', 'established', '施設入居・助成金は認定と別に申請、入居審査委員会が選定', '2026年度入居者募集要項5は、指定様式の利用申請書・事業概要・事業計画書に会社案内、法人登記簿謄本、財務諸表、納税証明書を添えて書留で提出させ、「書類提出→審査（書面及び面接）→入居通知→入居契約→入居開始」の流れで「(2)審査：入居審査委員会にて選定します」と定める。PoC支援助成金は教職員ポータル（CENTIS）掲示、学生向けベンチャースタジオはCLASS掲示で個別に受け付ける。TUSIDEサポートページの「ワンストップ申請」は※準備中と表示。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2025/10/1.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%83%AB%E3%83%BC%E3%83%A0%E5%8F%8A%E3%81%B3%E7%94%A3%E5%AD%A6%E8%A9%A6%E4%BD%9C%E9%96%8B%E7%99%BA%E5%AE%A4%E5%85%A5%E5%B1%85%E8%80%85%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85_2026%EF%BC%884%E6%9C%8821%E6%97%A5%E8%BF%BD%E8%A8%98%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_facility_registration', 'established', '学内2室を有償貸与（原則3年以内）、登記可能拠点はqcpが提供', '2026年度入居者募集要項は葛飾キャンパス第1研究棟1階のインキュベーションルーム（33.24㎡・月額28,400円税抜）と産学試作開発室（99.72㎡・月額84,100円税抜）を対象とし、応募条件3(2)①に「葛飾区内に本社若しくは事業所を有する企業又は東京理科大学学内発スタートアップ企業等であること」、4(1)に利用期間「原則3年間以内」と規定。商業登記の可否は募集要項にも産学連携スペース利用規則にも記載がない。TUSIDEサポートページ「出会いたい」が「会社登記が可能な活動拠点の提供」をquantum cross pointで明示。', 'official', 'https://www.tus.ac.jp/ura/wp-content/uploads/2025/10/1.%E6%9D%B1%E4%BA%AC%E7%90%86%E7%A7%91%E5%A4%A7%E5%AD%A6%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%83%AB%E3%83%BC%E3%83%A0%E5%8F%8A%E3%81%B3%E7%94%A3%E5%AD%A6%E8%A9%A6%E4%BD%9C%E9%96%8B%E7%99%BA%E5%AE%A4%E5%85%A5%E5%B1%85%E8%80%85%E5%8B%9F%E9%9B%86%E8%A6%81%E9%A0%85_2026%EF%BC%884%E6%9C%8821%E6%97%A5%E8%BF%BD%E8%A8%98%E7%89%88%EF%BC%89.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_vc_connection', 'established', '金融機関・VC紹介、学外VC・監査法人・主幹事証券も紹介', 'TUSIDEサポートページ「相談したい」の「創業支援」に「提携金融機関の紹介、専門家の紹介（弁護士、公認会計士、税理士、司法書士、社会保険労務士）」、「外部ネットワーク構築支援」に「学外VC、監査法人、主幹事証券、特許事務所、共同研究企業等の紹介」と明記。起業ハンドブック13章の学内認定スタートアップ向け支援7項目にも「金融機関、VCの紹介」があり、9章は資金調達手段として東京理科大学IC(株)等のVC、日本政策金融公庫、自治体制度融資を挙げ、産学連携機構への相談を案内している。', 'official', 'https://www.tus.ac.jp/tuside/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_eir', 'not_started', '客員起業家（EIR）の招聘制度なし、メンタリングと助言のみ', 'TUSIDEサポートページは支援メニューを「相談したい」「学びたい／検証したい」「出会いたい」の3分類で列挙し、メンタリング（事業計画、資本政策の策定）、起業相談、セミナー、人材採用協力までを掲げるが、客員起業家（EIR）や起業家人材の招聘は含まれない。起業ハンドブック13章「産学連携機構による起業支援リスト」（教職員・学生向け13項目、学内認定スタートアップ向け7項目）もアドバイザーの指導と学生へのメンタリングまでで、EIRの記載はない。', 'official', 'https://www.tus.ac.jp/tuside/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_cxo_pool', 'established', '認定VCの役員派遣と副業・兼業のプロ人材紹介', 'TUSIDEサポートページ「相談したい」の「東京理科大学認定ベンチャーキャピタルからの資金調達と経営支援」に「経営支援（役員派遣）」、「出会いたい」の「人材採用協力」に「東京理科大学アカデミックパートナーズ（パートタイム、正社員の紹介）」「ビズリーチ・キャンパス（副業、兼業のプロフェッショナル人材紹介）」「東京理科大学学生のインターンシップ紹介」を明記。CEO/CXO候補に特化した人材プールや経営チーム組成の枠組みを定めた記載はなく、役員派遣は出資に伴う経営支援として位置づけられている。', 'official', 'https://www.tus.ac.jp/tuside/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_ip_equity', 'established', '実施料対価として新株予約権での契約を検討可能', '起業ハンドブック（2025年12月改版、Box共有リンクで公開）8章「知的財産権を活用する〜特許実施許諾契約（ライセンス）」に「本学の教職員が発明した特許の活用においては、権利者である本学との実施許諾の契約が必須」「実施料支払いには、一時金、ランニングロイヤリティ、など様々な手段があります。新株予約権（将来成功時支払い）での本学との契約も検討いたします」と明記。対価算定、持分上限、行使条件を定めた細則は非公開。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'pol_fund_investment', 'established', '大学出資会社TUSICが出資、認定ファンドで数千万〜数億円', 'TUSIDEサポートページに「東京理科大学認定ベンチャーキャピタルからの資金調達と経営支援」「数千万円〜数億円の成長投資」と明記。起業ハンドブック12章はTUSIDEを東京理科大学、東京理科大学インベストメント・マネジメント株式会社、東京理科大学イノベーション・キャピタル株式会社（TUSIC）の3法人で構成すると定義し、TUSICの役割を「スタートアップ出資」「投資先へのさまざまな経営支援、EXIT支援」と記す。TUSIDE実績ページは「東京理科大学認定ファンドのポートフォリオ」を掲載。ファンド名・規模と大学本体の出資決裁規程は非公開。', 'official', 'https://www.tus.ac.jp/tuside/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_regulation_owner', 'established', '学校法人規程（理事長が認定、公開ポリシーも学校法人名義）', '起業ハンドブック7章Step2に「「学内発スタートアップ企業等審査委員会」での審査を経て、その結果に基づき理事長が認定」と定められ、認定主体は大学の学長ではなく学校法人東京理科大学の理事長。産学連携機構が公開する関連規範も「学校法人東京理科大学知的財産ポリシー」「学校法人東京理科大学利益相反ポリシー」で学校法人名義。認定規程そのものの本文は学外に公開されておらず、規程の正式名称は確認できない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_review_body', 'established', '学内発スタートアップ企業等審査委員会（施設は入居審査委員会）', '起業ハンドブック7章「申請から認定までの大まかな流れ」Step2に「「学内発スタートアップ企業等審査委員会」での審査を経て、その結果に基づき理事長が認定」と明記。施設入居は別建てで、2026年度入居者募集要項5(2)が「審査：入居審査委員会にて選定します」と定め、書面及び面接（オンライン）で審査する。事務局は産学連携機構 起業支援・地域連携部門（研究推進部研究推進課産学連携推進室）。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_equity_decider', 'unknown', null, '起業ハンドブック8章は実施料の支払手段として「新株予約権（将来成功時支払い）での本学との契約も検討いたします」と記すが、取得・保有・処分を誰が決裁するかは書かれていない。9章の資金調達手段も出資者側として東京理科大学IC(株)等を挙げるにとどまる。株式・新株予約権の取扱規程は学外非公開で、TUSIDEサポートページにも産学連携機構の各ページにも決裁者の記載はない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_amendment_decider', 'unknown', null, '認定制度の規程本文が学外に公開されておらず、制定改廃を決める主体を示す記載は、「大学認定スタートアップになるには」、起業ハンドブック7章、TUSIDEサポートページのいずれにもない。公開されている関連規範は学校法人名義の知的財産ポリシーと利益相反ポリシーの2件だけで、いずれも改廃条項を含まない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_post_grad_limit', 'established', '規定なし（認定対象は現役の教育職員・学生に限定）', '「大学認定スタートアップになるには」は対象を「本学が2002年に開始した制度のもとに認定する現役教員または学生による研究成果や学びを梃としたスタートアップ」と定義し、現役に限定している。起業ハンドブック7章も「2022年度より、対象を学内発スタートアップ企業（教育職員）だけでなく、学内発学生スタートアップ企業（学部生または大学院生）に拡大しました」とするのみで、退職・卒業後の起業を何年以内まで対象にするかの期限規定は置いていない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_renewal_rule', 'unknown', null, '起業ハンドブック7章は認定後に「支援基本契約書」（契約期間原則5年以内）を締結するとだけ記し、認定の更新可否、更新方法、再申請の扱いを定めた記載はない。施設は別建てで、2026年度入居者募集要項4(1)が「原則3年間以内」「1年ごとに入居継続の中間審査をします。3年間の利用期間満了後も継続を希望する場合は、新規応募と同様に取り扱います」と定めるが、これは入居の更新ルールであり認定の更新ではない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_naming', 'established', '大学発スタートアップ（東京理科大学発スタートアップ企業）', '「大学認定スタートアップになるには」は称号を「東京理科大学発スタートアップ企業」または「東京理科大学発学生スタートアップ企業」と明記し、認定の効果に「東京理科大学発の称号使用許可」を挙げる。起業ハンドブック7章・13章も「東京理科大発スタートアップ企業」の称号授与と表記する。ベンチャーの語は実績側の「大学発ベンチャー社数」（経済産業省調査の集計値）に使われるだけで、称号としては用いていない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_support_period', 'established', '個別契約（支援基本契約書は原則5年以内、施設は原則3年以内）', '起業ハンドブック7章Step3に「認定された場合には、「支援基本契約書」（契約期間原則5年以内）を締結」と記載され、支援関係は認定ごとの契約で期間を定める。施設は別建てで、2026年度入居者募集要項4(1)が利用期間「原則3年間以内」、1年ごとの中間審査、入居契約は「10月1日〜翌年9月30日」の1年ごとと規定。称号そのものの有効期間を定めた記載はない。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_support_contents', 'established', '称号授与・施設貸与・資金調達支援・特許申請支援・専門家紹介・金融機関/VC紹介', '起業ハンドブック13章「産学連携機構による起業支援リスト」の「学内認定スタートアップへの支援内容」は、①「東京理科大発スタートアップ企業」の称号授与、②本学施設（インキュベーション施設）の貸与、③資金調達・経営・マーケティング等の支援、④特許等の申請支援、⑤アドバイザーの指導、⑥専門家（税理士、司法書士等）の紹介、⑦金融機関、VCの紹介の7項目。教職員・学生向けは13項目で、PoC支援助成金、学生向け起業推進支援助成金、ベンチャースタジオ、国プロ・STARTプログラム申請支援などを含む。', 'official', 'https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e437d589dc87', 'attr_source_docs', 'established', 'https://www.tus.ac.jp/ura/startup/tobecome/・https://tus.box.com/s/uxeh0xxzyxdm9bqmlhsgx1kaqzxv4ub1・https://www.tus.ac.j…', '認定の対象と効果は「大学認定スタートアップになるには」、認定フロー・審査委員会・支援基本契約・知財対価・支援メニューの全列挙は起業ハンドブック（2025年12月改版、Box共有リンクで公開）、施設・登記・出資・人材・VC接続はTUSIDEサポートページが最も詳しい。施設条件のみ別途「東京理科大学インキュベーションルーム及び産学試作開発室 2026年度入居者募集要項」。規程集は一般公開されていない。', 'official', 'https://www.tus.ac.jp/ura/startup/tobecome/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_cert_update', 'not_started', '有効期間・更新の定めなし（取消規定のみ）', '称号授与規則（令和6年10月4日規則第132号）を第1条から第10条および附則まで通して確認したが、称号の有効期間、更新申請、更新審査、要件の再確認を定めた条文はない。称号が失われるのは第6条第2項（買収・統廃合等で法人格の同一性が保たれない場合の失効）と第9条（学長による遡及取消し）だけで、期間満了という概念を置いていない。イノベーションデザイン機構の申請資格・手続きページにも有効期間と更新の記載はない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_title_restriction', 'established', '安全性・有効性の非担保条項あり・取消後は称号使用禁止', '第6条第3項「本学は、第1項の規定により称号を授与した企業に対して、成果の安全性及び有効性等を担保するものではなく、また、一切の法的責任を負うものではない」。第2条で称号企業は「東京科学大学認定ベンチャー」「Science Tokyo Venture」の名称を利用でき、第6条第1項で称号記が交付される。第9条第2項で取消後は称号記を返付し、称号を授与されていた事実を事業に使用してはならない。投資推奨や経営状態の保証を名指しで否定する条文までは置いていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_cancellation', 'established', '学長が審査委員会の議を経て遡って取消・称号記返付', '第9条第1項で、一 社会的信用を失墜する行為を行ったとき、二 前号のほか称号を保持させることが適当でないと学長が認めるとき、に学長が審査委員会の議を経て称号を遡って取り消す。第2項で取消しを受けた企業は速やかに称号記を返付し、取消日以後は称号を授与されていた事実を事業に使用してはならない。取消しとは別に第6条第2項で、買収・統廃合等により法人格の同一性が保たれない場合は称号が当然に効力を失う。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_report_change', 'established', '求めに応じた事業報告書の提出義務・変更届は規定なし', '第8条（報告義務）「称号企業は、本学からの求めに応じ、別に定める事業報告書により、本学に活動内容等を報告しなければならない」。年次など提出周期の指定はなく、大学からの求めが起点になる。イノベーションデザイン機構の申請資格・手続きページは事業報告書の様式を案内するが、様式は準備中と表示されている。代表者・所在地・資本構成の変更届、解散時の報告を定めた条文は規則にも手続ページにもない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_support_request', 'established', '支援は認定と別建て・施設利用と登記は申請許可制', '称号授与規則第7条は「本学は、称号企業に対し、本学の管理運営及び教育・研究に支障のない範囲において支援を実施することができるものとし、具体的な内容及び支援期間その他支援の実施に必要な事項は、別に定める」とし、称号授与と支援の申請を分けている。TIPに係る共用実験室利用細則第4条は、利用責任者が利用申請書を医療イノベ機構長へ利用開始の1月前までに提出し、機構長が運営委員会の議を経て許可すると定める。同細則第12条の登記も機構長への申請制。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002140.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_facility_registration', 'unknown', null, '［自動検証で否認: INDEST月3,000円は引用元・他資料とも記載なし］元の主張(established): INDEST月3,000円で登記可・TIPシェアラボも申請制。TIPに係る共用実験室利用細則（令和6年12月6日細則第82号）第12条「利用責任者は、医療イノベ機構長への申請により当該スタートアップの所在地としてシェアラボを登記することができる」。第3条で研究開発型のスタートアップ（起業準備を含む）等を利用対象とし、第9条で利用期間は原則3年以内、1年以内を限度に2回まで延長でき最大5年。田町のINDESTは入居者募集要項の賃貸借契約欄で、法人の登記住所として利用する場合に月額3,000円（税込）の登記手数料が発生すると明記している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: 日本政策金融公庫は引用元1st Roundページになし］元の主張(established): 1st Round共催・日本政策金融公庫の融資相談会。イノベーションデザイン機構の1st Roundページに、東京大学協創プラットフォーム開発（東大IPC）が事務局を務め複数大学と共催するプログラムとして掲載され、外部調達前のチームまたは設立3年以内のベンチャーに最大1,000万円の事業資金補助と東大IPCのハンズオン支援を提供すると記載。資金支援ページには「日本政策金融公庫×INDEST」の融資・資金計画個別相談会と、港区の創業・スタートアップ支援および補助金制度のオンライン説明会が掲載されている。紹介導線を制度として定めた規程は確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_eir', 'established', '客員起業家EIRをビズリーチ協定で募集・マッチング', 'イノベーションデザイン機構の「客員起業家（EIR）とのマッチング」ページに「本学は、ビズリーチ社との協定に基づき、研究シーズを有する教員と共に起業するための経営者候補として、客員起業家（EIR）を募集し、学内教員の起業を支援」と記載し、募集は転職サイト上で行うとする。認定ベンチャーページとその他の起業支援ページでも支援メニューとして「客員起業家（EIR）とのマッチング」を掲げる。任期、待遇、選考手続の記載はない。', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/other-support/recruitment-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_cxo_pool', 'established', '経営者候補の採用支援あり・EIR募集と同一枠組み', '同ページが「起業にあたって課題となる『経営のプロ』の確保を支援」と明記し、経営者候補としてEIRを募集する枠組みで経営人材を充てる形をとる。企業パートナー向けサイトの認定ベンチャー紹介ページも支援活動の一つに「人材採用支援」を挙げ、「経営のプロ」の採用支援と説明する。登録型の人材プール名簿、マッチングの選考基準、申請手続を定めた公開文書は確認できなかった。', 'official', 'https://www.idp.ori.titech.ac.jp/be-a-successful-entrepreneur/other-support/recruitment-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', '研究開発成果活用促進支援に伴う株式等の取得に関する規則（令和6年10月1日規則第116号）第2条第5号が「研究開発成果活用促進支援」を特許権等及びノウハウのライセンス、施設使用その他の支援業務と定義し、第2条第6号で「株式等」を株式及び新株予約権と定義する。第3条で、その対価として株式等の譲渡・付与の提案があった場合に理事長が取得の可否を決定する。発明規則（令和6年規則第114号）側には、ベンチャーへの優先的実施許諾や実施料減免の条項は確認できなかった。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'pol_fund_investment', 'unknown', null, '［自動検証で否認: 1億円・出資日・法令根拠が記事本文に記載なし］元の主張(established): 認定ファンド（みらい創造2号）へ1億円出資。旧東京工業大学が2023年12月25日、国立大学法人法第22条第1項に基づき、産業競争力強化法の特定研究成果活用支援事業計画の認定を受けたみらい創造二号投資事業有限責任組合（運営：株式会社みらい創造機構）へ1億円を出資した。財源は東京工業大学基金。統合後の東京科学大学は2025年1月にみらい創造インベストメンツと新連携協定を締結し、認定ファンド等を通じた資金・成長支援、GAPファンドの運営とキャピタリストによる伴走、ファンドからの投資とハンズオン支援を掲げる。大学名義の出資規程は規程集で確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_regulation_owner', 'established', '大学規程（学長決裁の規則、株式等は法人規則）', '認定規程の題名は「東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則」（令和6年10月4日規則第132号）で、申請の受理、審査委員会への付議、授与の決定、取消しをいずれも学長が行う大学側の規則。一方、株式等の取得に関する規則は「国立大学法人東京科学大学における…」と法人名を冠し理事長が決裁する法人規則で、認定の規程主体と分かれている。設置者は国立大学法人東京科学大学で、学校法人ではない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_review_body', 'established', '東京科学大学認定ベンチャー称号授与審査委員会', '第4条で審査委員会をイノベーションデザイン機構に置き、機構長、副機構長、産学共創機構長、医療イノベーション機構長、その他機構長が指名する者で組織し、委員長は機構長とする。第5条で、学長への申請を受けて学長が審査委員会に審査させ、審査委員会は研究・イノベーション本部規程（令和6年規程第144号）第7条のイノベーション合同会議の議を経て学長に報告し、第5項で学長が授与を決定する。申請の窓口事務はイノベーションデザイン機構。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_equity_decider', 'established', '理事長（株式等受入審査委員会の議を経て決定）', '研究開発成果活用促進支援に伴う株式等の取得に関する規則第3条で、理事長が株式等受入審査委員会の議を経て取得の可否を決定する。委員会は第4条で設置し、第6条第1項でイノベーションを担当する理事、産学共創機構等の各機構長、学外有識者若干人、その他委員長が指名する者で組織する。取得後の評価、保有、売却（処分）は第10条で「別に定める」とされ、本規則の中には決裁者が書かれていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00001733.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_amendment_decider', 'unknown', null, '称号授与規則には制定改廃の手続を定めた条文がない。第10条（雑則）が「この規則に定めるもののほか、必要な事項は、学長が別に定める」として細目を学長へ委任するにとどまる。株式等の取得に関する規則にも改廃条項はない。改廃の決裁ラインを定める規則等の制定手続規程は、今回の調査範囲では規程集上で特定できなかった。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_post_grad_limit', 'established', '期限なし（学生OB・他機関在籍時の起業も年数要件なし）', '第3条の関連ベンチャーが、イ 本学職員が他の研究機関に所属していたときに起業し申請時に経営に参画するもの、ロ 本学の学生であった者が設立し申請時に経営に参画するもの、ハ 学長が特に認めるもの、を対象とする。卒業後・退職後の経過年数を制限する条文はなく、要件は申請時に経営へ参画していることに置かれている。学生ベンチャーも、設立への関与と申請時の経営参画で判定する。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_renewal_rule', 'established', '期限なし（有効期間・更新の条項なし）', '称号授与規則には有効期間と更新の条項がなく、更新申請や更新審査の手続も定めていない。称号が失われるのは第6条第2項の法人格の同一性喪失と第9条の学長による取消しだけで、期間満了による失効はない。附則第3項・第4項は、旧東工大発ベンチャーおよび東京医科歯科大学発ベンチャーの称号を引き続き利用でき、新称号を利用したい場合は本学からの案内に従うとするだけで、再申請を求めていない。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_naming', 'established', '独自名称（東京科学大学認定ベンチャー）', '第2条で称号を「東京科学大学認定ベンチャー」、英語名称を「Science Tokyo Venture」と定め、称号企業はこの名称を利用できる。「大学発ベンチャー」「大学発スタートアップ」という一般名称は用いていない。附則第3項で旧東工大発ベンチャー、東京医科歯科大学発ベンチャーの称号も引き続き利用でき、機構が公開する一覧では旧東工大分に「T」、旧東京医科歯科大分に「MD」を称号番号の頭に付けて区別している。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_support_period', 'unknown', null, '［自動検証で否認: 3年側の根拠INDESTが確認資料になし］元の主張(established): 支援ごとに別に定める（称号は無期限、施設は最長3〜5年）。第7条が「具体的な内容及び支援期間その他支援の実施に必要な事項は、別に定める」とし、称号の保持期間と支援期間を切り離している。称号自体に期間の定めはない。実際の期間は各支援の文書で決まり、TIP共用実験室は利用細則第9条で原則3年以内、1年以内を限度に2回まで延長して最大5年。田町のINDESTは1年6か月更新で最大3年の定期建物賃貸借契約。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_support_contents', 'established', '活動スペース・共用実験室・GAPファンド・1st Round・EIR紹介', 'イノベーションデザイン機構のベンチャーページと企業パートナー向けページが掲げる支援は、称号記授与式、ネットワーキングイベントでの登壇、活動スペースの支援（INDEST、TIPシェアラボ）、1st Round、人材採用支援（「経営のプロ」の採用支援、客員起業家EIRとのマッチング）。資金支援ページはScience Tokyo GAP Fund Program 2026、第3回社会変革チャレンジ賞、学生スタートアップ支援、GTIE GAPファンドを案内する。起業前の段階には起業相談室Go Startup、学生向けSTARTech、Science Tokyo Venture Studioがある。', 'official', 'https://www.idp.ori.titech.ac.jp/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b8027b627d19', 'attr_source_docs', 'established', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html・https://www.somuka.titech.ac.jp/reiki_int/re…', '制度の中心は称号授与規則（令和6年規則第132号）で、申請資格の5区分、審査委員会、称号の効力と非担保条項、報告義務、取消しを定める。株式等の取得に関する規則（令和6年規則第116号）は、ライセンスや施設使用の対価として株式・新株予約権を取得する枠組みと理事長決裁を定める。運用と支援メニューはイノベーションデザイン機構のベンチャーページに集約される。施設面はTIPに係る共用実験室利用細則とINDEST入居者募集要項が根拠。', 'official', 'https://www.somuka.titech.ac.jp/reiki_int/reiki_honbun/x385RG00002097.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_cert_update', 'established', '支援期間5年以内・更新規定なし・再申請可', '東京都公立大学法人大学等発ベンチャー支援に関する規程（平成24年度法人規程第2号、令和8年4月1日施行）第5条第1項で支援期間は5年を超えない範囲でセンター長が必要と認める期間、第2項で再申請を妨げないと定める。更新申請・更新審査・期間延長・要件の再確認を定めた条文は置かれていない。期間中は第11条第1項で毎年度の事業報告書提出義務があり、第12条で定義からの著しい逸脱、企業活動の実態消滅、事業報告の拒否等があればセンター長が支援決定を取り消せる。施設の入居期間はインキュベーションルーム管理運営規程で別に定まる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_title_restriction', 'established', '免責条項のみ・誤認防止条項なし', '同規程第3条第1項第1号で4種の称号（東京都公立大学法人発／東京都立大学発／東京都立産業技術大学院大学発／東京都立産業技術高等専門学校発ベンチャー）から適当なものを選んで使用できる。同条第2項は「大学等発ベンチャーの称号を使用したことによって生じた損失及び損害について、法人は、いかなる法的責任も負わない」と定める免責条項。一方、品質保証・投資推奨・経営状態の保証と誤認させない旨の条項、称号の使用範囲の限定、使用停止を命じる規定は置かれていない。産学公連携センターのベンチャー支援ページにも注意書きはない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_cancellation', 'established', '取消事由6号を規定・取消後の処理は規定なし', '同規程第12条でセンター長が支援決定を取り消せる場合として、(1)第2条の定義から著しく逸脱した場合、(2)社会的信用を失墜する行為を行った場合、(3)企業活動の実態がなくなった場合、(4)本人から取消しの申出があった場合、(5)第11条第1項の事業報告を拒否した場合、(6)その他支援継続が適当でないとセンター長が認めた場合、の6号を列挙。取消し後に称号の使用をやめさせる、称号を返付させる、ウェブサイト等の表示を削除させる、営業上の利用を停止させるといった措置は規定されていない。第14条で必要事項はセンター長が別に定める。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_report_change', 'established', '毎年度の事業報告書と解散等の速報・変更届なし', '同規程第11条第1項で代表者は毎年度、活動状況について別に定める事業報告書を作成しセンター長に提出しなければならない。第2項で、会社法の解散、破産法の破産宣告、民事再生法の再生手続、会社更生法の更生手続、不正競争防止法第21条・第22条の罰則が裁判で確定した場合のいずれかに該当したときは速やかにセンター長へ報告する。代表者・所在地・商号・資本構成の変更届を求める条文はない。第10条（支援に附帯する手続）は、通知を受けた者が法人の関係規定等に従い必要な手続を執る旨を定めるにとどまる。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_support_request', 'established', '認定申請が支援申請を兼ねる・施設入居は別審査', '同規程第6条は、支援を受けようとする者がセンター長へ申請書、登記簿の写し、企業概要及び事業内容が分かる資料を提出すると定め、第8条でセンター長がベンチャー支援審査会の議を経て支援の可否を決定する。称号使用・登記住所・ライセンス対価の新株予約権化は第3条の支援内容として一括で決まり、支援ごとの個別申請は規定されていない。施設は日野キャンパス6号館インキュベーションルーム管理運営規程に基づく入居申込と審査が別に必要で、研究機器共用センターの機器も別途利用申込。広報・人材紹介の個別申請制度は公開情報にない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_facility_registration', 'unknown', null, '［自動検証で否認: 日野キャンパス6号館は誤り、実際は南大沢プロジェクト研究棟2F］元の主張(established): インキュベーションルーム10室・入居中は本店登記可。TMU Innovation Hub（令和5年10月開設、日野キャンパス6号館1階）のインキュベーションルーム詳細ページに、入居期間中に限り当該住所を法人の所在地として登記できると明記。大学等発ベンチャー支援規程第3条第1項第2号も同旨。室数は10室で、ウェットラボ7室（36〜73平米、うち2室はドラフトチャンバー付）とオフィス3室（13.5〜13.6平米）。入居料は月額40,500円〜219,000円、機器使用料月額21,000円、光熱水費別途、減額制度あり。入居期間は事業開始前が原則1年で1年更新2回まで、起業後は原則3年以内で2年以内の更新2回まで、いずれも審査あり。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_vc_connection', 'established', 'TAMA-LEAPで金融機関・自治体と連携・VC紹介は明記なし', '東京都立大学が事務局を務めるスタートアップ・エコシステムTAMA-LEAPのパートナー機関に、多摩信用金庫と東京きらぼしフィナンシャルグループの金融機関2社、日野市・八王子市の自治体2市、首都圏産業活性化協会・東京都中小企業振興公社・東京都立産業技術研究センターの産業支援機関3団体が並ぶ。支援例に資金調達支援、試作・設計、起業・経営相談、法務・知財相談、施設利用、専門家・メンターによる伴走支援を掲げる。ベンチャーキャピタルの参画や投資家への紹介手続は公開ページに記載がない。コアプレイヤー参加は無料で、参加申込書の提出と運営委員会の承認による。', 'official', 'https://research-miyacology.tmu.ac.jp/igac/tama-leap/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_eir', 'unknown', null, '産学公連携センターの大学等発ベンチャー支援ページ、総合研究推進機構のベンチャー支援ページ、TMU Innovation Hubページ、TAMA-LEAPページのいずれにも、客員起業家（EIR）の称号・任用・招聘に関する記載がない。大学等発ベンチャー支援規程にもEIRの条文はない。TAMA-LEAPは専門家・メンターによる伴走支援を掲げるが、メンターの任用制度や名簿は公開されていない。東京都立大学はGTIE（Greater Tokyo Innovation Ecosystem）にスタートアップ創出共同機関として参画しているが、東京都立大学自身のEIR制度としては公開情報で確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_cxo_pool', 'established', '副業CXO候補人材の公募（HiPro Direct活用）', '副業・フリーランス人材マッチングサービスHiPro Direct（パーソルキャリア）の特集記事（2024年9月6日掲載）で、東京都立大学が都立大発ベンチャー設立を目指す研究者に伴走するCXO候補人材を募集していることを確認。主体は産学公連携センターで、副学長兼産学公連携センター長が統括し、2023年開設のTMU Innovation Hubが起業・経営相談の窓口。関わり方は副業で週1日から、月10時間から応相談、報酬は月10万円程度。同記事はGAPファンド、アクセラレータ・メンタリング、会社登記費用の負担、インキュベーションルーム提供、本学住所での登記も支援メニューとして挙げる。大学規程上の制度ではなく外部サービスを使った取組。', 'official', 'https://hipro-job.jp/pro/service/direct/blog/issue-pr/tokyo-metropolitan-university/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_ip_equity', 'established', 'ライセンス対価を新株予約権化可・株式は規定なし', '大学等発ベンチャー支援規程第3条第1項第3号が支援内容として「法人が所有する知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること」を規定し、産学公連携センターのベンチャー支援ページにも同文を掲載。加えて東京都公立大学法人知的財産取扱規則第29条「大学発ベンチャーに対する優遇措置」で実施料の延払い及び減免等の優遇措置、第30条で専用実施権の設定が可能。第28条で譲渡・放棄・実施許諾は審査会の審議に基づきセンター長が決定。普通株式を対価として取得する規定、新株予約権の評価・行使・処分を定めた下位規程は公開されていない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'pol_fund_investment', 'not_started', '出資・ファンド組成なし（新株予約権取得のみ）', '大学等発ベンチャー支援規程第3条第1項が支援内容を、称号使用、インキュベーションルーム入居期間中の登記、ライセンス対価の新株予約権化、その他センター長が必要と認めることの4号で構成し、出資やファンドへの拠出は含まない。総合研究推進機構のベンチャー支援ページの支援メニューもTMU GAPファンド（学内公募の助成）、ベンチャー設立経費（登記費用）、TAMA-LEAP、インキュベーションルーム、外部の補助金・支援金等で、いずれも助成・施設提供であり出資ではない。産学公連携センター「規程・様式等」ページの掲載規程にも出資・ファンド関連規程はない。第4号の包括条項が残る点は留保。', 'official', 'https://www.tokyo-sangaku.jp/guideline/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_regulation_owner', 'established', '学校法人規程相当（東京都公立大学法人の法人規程）', '認定規程は東京都公立大学法人大学等発ベンチャー支援に関する規程（平成24年12月28日制定、平成24年度法人規程第2号、令和8年4月1日施行）で、大学単位ではなく設置法人が定める法人規程。東京都公立大学法人は地方独立行政法人であり学校法人ではないが、規程の主体は個別大学ではなく設置法人。同法人が運営する東京都立大学、東京都立産業技術大学院大学、東京都立産業技術高等専門学校の3校に共通で適用され、第2条の対象範囲も3校の教職員等・学生等を指す。事務は第13条により産学公連携センターが行う。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_review_body', 'established', 'ベンチャー支援審査会（産学公連携センター長が議長）', '同規程第7条でベンチャー支援審査会を置く。構成員はセンター長、東京都立大学総合研究推進機構長、センター長補佐、副センター長、機構長補佐、事務長、センター長が指名する各校の知的財産委員会委員各1名、知的財産マネージャー1名、URAまたは産学公連携コーディネーター1名、その他センター長が指名する者若干名で、議長はセンター長。第8条でセンター長が審査会の議を経て支援の可否を決定し、第9条で別に定める様式により申請者へ通知するとともに法人内の関係部署へ決定内容を報告する。事務は第13条により産学公連携センターが行う。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_equity_decider', 'established', '産学公連携センター長（ベンチャー支援審査会の議）', '新株予約権の取得は大学等発ベンチャー支援規程第3条第1項第3号の支援内容の一つであり、第8条によりセンター長がベンチャー支援審査会の議を経て可否を決定する。前提となる知的財産権の実施許諾も、東京都公立大学法人知的財産取扱規則第28条で審査会の審議に基づき産学公連携センター長が決定する。取得後の新株予約権の評価、権利行使、処分を誰が決裁するかを定めた規程は公開されていない。株式そのものの取得・保有・処分に関する規程も、産学公連携センターの規程一覧および法人例規集で確認できなかった。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_amendment_decider', 'established', '理事長（教学以外の法人規程）', '東京都公立大学法人の規則等の制定改廃に関する規則（平成17年4月1日、平成17年度法人規則第1号、令和2年4月1日施行）第2条で規則等を業務方法書・規則・規程・要綱・細則・基準の6種と定義し、規程は規則等に基づき法人の運営上必要な事務的な重要事項を定めるものとする。第4条で教学に関するもの以外の規程は理事長が定め、大学の教学規程は学長、高等専門学校の教学規程は校長が事務局長協議を経て定める。大学等発ベンチャー支援規程は教学規程ではない法人規程のため理事長が制定改廃する。同規程自体に改廃条項はなく、第14条で必要事項はセンター長が別に定める。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_post_grad_limit', 'established', '1年以内（退職・卒業・修了後、原則として）', '大学等発ベンチャー支援規程第2条第4号で、教職員等または学生等であった者が「退職、卒業又は修了の後、原則として1年以内に」設立者となるなど設立に深く関与して起業したものを大学等発ベンチャーに含める。「原則として」とあり審査会の判断で例外を認める余地は残るが、明示された年数は1年。なお同条の他の号（法人または教職員等・学生等が所有する知的財産権をもとに起業、法人の研究成果・習得技術に基づく起業）は在籍状況を条件にしていないため、知財や研究成果を根拠とする場合はこの1年の制限を受けない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_renewal_rule', 'established', '更新不可・再申請（支援期間は5年以内）', '同規程第5条第1項で支援期間は5年を超えない範囲でセンター長が必要と認める期間、第2項で「再申請を妨げるものではない」と定める。更新申請・更新審査・期間延長の手続は規定されておらず、期間終了後は第6条の申請手続（申請書、登記簿の写し、企業概要及び事業内容が分かる資料の提出）をあらためて行う建付け。再申請時も第8条によりベンチャー支援審査会の議を経てセンター長が可否を決定する。産学公連携センターの支援企業一覧には支援終了と注記された企業が並ぶ。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_naming', 'established', '大学発ベンチャー（東京都立大学発ベンチャー等4種）', '同規程第3条第1項第1号で、東京都公立大学法人発ベンチャー、東京都立大学発ベンチャー、東京都立産業技術大学院大学発ベンチャー、東京都立産業技術高等専門学校発ベンチャーのうち適当なものを選んで使用できる。規程名・制度名も「大学等発ベンチャー支援」で、スタートアップの語は称号に用いていない。令和2年4月1日施行の改正附則に新旧称号の使用選択に関する経過措置があり、旧称の首都大学東京発ベンチャーを使う企業が支援企業一覧に残る。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_support_period', 'established', '称号期間と同じ（支援期間5年以内に称号使用を含む）', '同規程は称号期間という概念を置かず、第3条第1項第1号の称号使用を、第5条の支援期間（5年を超えない範囲でセンター長が必要と認める期間）に含まれる支援内容の一つとして扱う。したがって支援期間の満了、または第12条による支援決定の取消しで称号使用の根拠も失われる。ただし施設は別建てで、日野キャンパス6号館インキュベーションルーム管理運営規程第6条により、起業後の入居期間は創業後10年目を超えない範囲で原則3年以内、審査を経て2年以内の更新を2回までとされ、支援期間とは一致しない。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_support_contents', 'established', '称号使用・登記住所・新株予約権化・GAPファンド・登記費用・施設・機器共用', '規程第3条第1項の支援内容は、称号の使用、インキュベーションルーム入居期間中に限る登記住所としての使用、知的財産権のライセンス等の対価の全部または一部の新株予約権化、その他センター長が必要と認めること。総合研究推進機構のベンチャー支援ページはこれに加えTMU GAPファンド（学内限定の公募）、ベンチャー設立経費（登記費用）、TAMA-LEAP、インキュベーションルーム、外部の補助金・支援金等（GTIE、大学発ベンチャー支援、海外特許申請費）を掲げる。研究機器共用センターの3Dプリンター等は学外者も学内料金で利用可。窓口は研究推進課起業推進係。', 'official', 'https://research-miyacology.tmu.ac.jp/igac/support-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_1abfa9e22bbc', 'attr_source_docs', 'established', 'ベンチャー支援規程・産学公連携センター・総合研究推進機構', '主要根拠は3本。(1)https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html が認定要件・支援内容・審査体制・事業報告・取消しの正本。(2)https://www.tokyo-sangaku.jp/support-venture/ が制度の公式説明と支援企業一覧、問合せ窓口。(3)https://research-miyacology.tmu.ac.jp/igac/support-venture/ がGAPファンド・設立経費・TAMA-LEAP等の実運用メニュー。施設条件は同機構のinnovation-hub/incubation-roomページを併読。', 'official', 'https://www1.g-reiki.net/tmu/reiki_honbun/u430RG00000310.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_cert_update', 'unknown', null, '認定制度そのものが公開情報で確認できず、認定期間・更新可否・更新審査・要件再確認の定めも見つからない。産官学連携担当サイトの構成は「ご案内」「技術・特許紹介」「企業・地域の方へ」「学内の方へ」「ME講座」「安全保障輸出管理」の6区分で、認定・称号のページを持たない。規程の集約先である学校法人東京電機大学規程集は学内者専用閲覧サイトのため、規程の存否を外部から確認できない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_title_restriction', 'unknown', null, '称号制度が確認できず、品質保証・投資推奨・経営状態保証と誤認させない条項や、称号の使用範囲・使用停止の規定も見つからない。「社会連携・社会貢献に関する基本方針」は建学の精神と、産・学・公・金の連携推進、研究インテグリティ確保を含む利益相反マネジメント体制の整備を述べるにとどまり、大学名・称号の使用条件に触れていない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/about/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_cancellation', 'unknown', null, '認定の取消事由、称号返付、表示削除、営業利用停止を定めた公開規程は見つからない。認定制度自体が公開されていないため、解除・取消後の処理も確認できない。産官学連携担当の企業向けメニューは技術相談・受託/共同研究、寄付金、知的財産ポリシー、コーディネーター紹介、FAQ、相談窓口、支援事業等、研究者情報、特許情報、会員登録の10項目で、認定の取消に関する記載はない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/corporation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_report_change', 'unknown', null, '年次報告、代表者・所在地・資本構成の変更届、解散時報告の義務を定めた公開資料は見つからない。認定制度が無いため、認定企業に課す報告義務という枠組み自体を確認できない。学内向けページの掲載項目は「発明から特許登録までの流れ」「各種書式等」「知的財産権について」「よくある質問」「相談窓口」「研究助成募集情報」で、ベンチャーの報告書式は含まれない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/campus/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_support_request', 'unknown', null, '［自動検証で否認: 令和6年度5件アクセラ選定の記述が根拠URLに無い］元の主張(established): 施設入居・研究費支援・アクセラ選定ごとに個別申請。支援は認定を起点にせず、支援ごとの個別申請と審査で運用されている。創業支援施設かけはしの入居は申込に対し「創業支援施設入居者選考委員会」が書類・面接の二段階で審査（既存調査で確認済みの募集要項2.(3)、9.、10.）。「足立成和信用金庫・東京電機大学 企業ニーズ向け研究費支援事業」は公募要領に基づく申請書類の提出と、研究コーディネーターまたは産学連携コーディネーターへの相談が必須。東京都事業では令和6年度に5件のアクセラレータープログラムを選定・支援。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_facility_registration', 'unknown', null, '［自動検証で否認: 本店登記が利用条件との記載がabout頁に無い］元の主張(established): 創業支援施設かけはし入居＋本店登記が利用条件。「東京電機大学が創業支援事業を展開するため、足立区と協業のもと、平成23年12月に開設」した創業支援施設かけはし（東京都足立区）。インキュベーションオフィスとシェアードオフィスを持ち、賃料の一部を足立区と大学が負担する有償利用。既存調査で確認済みの募集要項6.利用条件により、法人は本社として利用（営業所不可）、既登記の場合は入居後2か月以内に登記所在地を施設住所へ変更、創業予定者は原則2か月以内に法人登記を完了することが条件。施設利用と商業登記が一体で成立している。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_vc_connection', 'unknown', null, 'VC・金融機関・自治体・外部支援機関への紹介導線を制度として定めた公開記載は見つからない。かけはしの支援体制は中小企業診断士4名のインキュベーションマネージャーによる無料の経営相談・指導、年3回のセミナー、名刺交換会、勉強会、教員への技術相談と知的財産相談のコーディネートまでで、投資家紹介の記載はない。金融機関との連携は足立成和信用金庫との地域企業向け共同研究費支援事業にとどまる。2025アントレプレナー講座の「VCの役割を知る」は教育内容であり紹介制度ではない。', 'official', 'https://www.tdu-kakehashi.com/about/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_eir', 'unknown', null, '客員起業家（EIR）・起業家メンター・起業家人材の招聘制度は公開情報に見当たらない。東京都「大学発スタートアップ創出支援事業」（環境構築型、令和6年度採択、事業名「発明の社会実装拡大による社会貢献」）では、外部コーディネーターと「スタートアップ立ち上げ専門人材等による適正評価、提案、実現検証、事業化への伴走型支援」を本学教員へ提供すると記載されるが、大学が起業家人材を招聘・処遇する制度としての規定は示されていない。かけはしの常駐支援者は中小企業診断士。', 'official', 'https://www.dendai.ac.jp/news/20241128-02.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_cxo_pool', 'unknown', null, 'CEO/CXO候補の人材プールや経営人材マッチングの制度は公開情報に見当たらない。かけはしの支援は経営に係る相談・指導までで、人材紹介の記載はない。産官学連携担当の企業向けメニュー10項目（技術相談・受託/共同研究、寄付金、知的財産ポリシー、コーディネーター紹介、FAQ、相談窓口、支援事業等、研究者情報、特許情報、会員登録）にも経営人材の紹介は含まれない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/corporation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_ip_equity', 'unknown', null, '知的財産の実施許諾対価として株式・新株予約権を受け取る規程・運用は確認できない。既存調査で確認済みの「東京電機大学 知的財産ポリシー」の公開範囲は目的・基本的考え方・定義・対象者・推進体制の5項目にとどまり、株式対価の条項はない。産官学連携担当の企業向けメニューにも株式・新株予約権に関する記載はなく、詳細な知財規程は学内者専用の規程集にあると見られ外部確認不可。', 'official', 'https://www.dendai.ac.jp/crc/tlo/corporation/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'pol_fund_investment', 'unknown', null, '大学VC、認定VC、LP出資、指定ファンド、大学出資会社を通じた投資の公開情報は見つからない。「社会連携・社会貢献に関する基本方針」は産（企業）・学（他大学）・公（国、地域の公的機関）・金（金融機関）との連携推進を掲げるが、出資やファンド組成には触れていない。学校法人東京電機大学は私立の学校法人であり、産業競争力強化法に基づく国立大学法人等のVC出資スキームの枠組みとは別。', 'official', 'https://www.dendai.ac.jp/crc/tlo/about/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_regulation_owner', 'unknown', null, '認定規程が公開情報で確認できないため、制定主体を特定できない。参考として、規程の集約先は「学校法人東京電機大学規程集」で学内者専用閲覧サイト。産学連携の実務は東京電機大学 研究推進社会連携センター 産官学連携担当（文部科学省・経済産業省の承認を受けた技術移転機関）が担い、創業支援施設かけはしの主催・事務局は「学校法人東京電機大学 総務部 地域連携・事業担当」と「東京電機大学 創業支援施設『かけはし』事務局」で、大学側と学校法人側に担当が分かれている。', 'official', 'https://www.dendai.ac.jp/event/20251017-01.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_review_body', 'unknown', null, '認定の審査主体を定めた公開規程はない。参考として、創業支援施設かけはしの入居審査は「創業支援施設入居者選考委員会」が担い、各分野の専門家で構成する審査会が第一次（書類）・第二次（面接）の二段階で審査する（既存調査で確認済みの募集要項）。東京都事業では令和6年度に5件のアクセラレータープログラムを選定・支援した旨がDEMO DAY告知に記載されるが、選定を行った学内会議体の名称は公開されていない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/news/20260219-01.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_equity_decider', 'unknown', null, '株式・新株予約権の取得や処分を誰が決裁するかを示す公開規程はない。学内向けページの掲載項目は発明から特許登録までの流れ、各種書式等、知的財産権について、よくある質問、相談窓口、研究助成募集情報の6項目で、株式取得・利益相反・兼業・規程集へのリンクを持たない。学校法人東京電機大学規程集が学内者専用のため、理事会等の決裁構造を外部から確認できない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/campus/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_amendment_decider', 'unknown', null, '規程の制定改廃を決める主体を示す公開資料は見つからない。学校法人東京電機大学規程集が学内者専用閲覧サイトであり、理事会・評議員会・大学の会議体のいずれが改廃権限を持つかを外部から確認できない。産官学連携担当の学内向けページにも規程集や制定改廃手続へのリンクはない。', 'official', 'https://www.dendai.ac.jp/crc/tlo/campus/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_post_grad_limit', 'unknown', null, '認定制度が確認できないため、退職・卒業後の起業を何年以内まで対象とするかの規定も確認できない。東京都「大学発スタートアップ創出支援事業」の支援対象は「本学教員」と明記され、退職者・卒業生の扱いは示されていない。創業支援施設かけはしの募集対象は創業予定または創業後5年未満の法人・個人で、教職員・学生・卒業生といった身分要件を設けておらず、退職・卒業からの年限という考え方自体を持たない。', 'official', 'https://www.dendai.ac.jp/news/20241128-02.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_renewal_rule', 'unknown', null, '認定の更新可否・更新方法を定めた公開規程は見つからない。参考として、かけはしのインキュベーションオフィスは入居開始日から2年間、審査により認められた場合は1年ごとに最長5年間まで延長可能、シェアードオフィスは原則1年間（既存調査で確認済みの募集要項3.入居期間）。これは施設利用の延長審査であり、称号や認定の更新ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_naming', 'unknown', null, '「東京電機大学発ベンチャー」等の称号を用いた認定ページ・認定企業一覧は公開情報に存在しない。大学の公表文で用いられる「大学発スタートアップ」は東京都の事業名「大学発スタートアップ創出支援事業」の引用であり、自校の称号ではない。規程集が学内者専用のため、称号の有無そのものを外部から断定できない。', 'official', 'https://www.dendai.ac.jp/news/20241128-02.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_support_period', 'unknown', null, '称号期間という概念が公開情報に存在しないため、支援期間と分けているかを判定できない。支援ごとの期間は個別に設定されており、かけはしのインキュベーションオフィスは延長を含め最長5年、「足立成和信用金庫・東京電機大学 企業ニーズ向け研究費支援事業」は2025年4月1日から2026年3月31日までの1年度単位で最長3年間継続可能。', 'official', 'https://www.dendai.ac.jp/crc/tlo/corporation/supportproject.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_support_contents', 'unknown', null, '［自動検証で否認: アクセラ伴走・起業講座の記述がabout頁に無い］元の主張(established): 創業支援施設・経営相談・アクセラ伴走・技術相談・起業講座。かけはし側は、インキュベーションオフィスとシェアードオフィス、中小企業診断士4名のインキュベーションマネージャーによる無料の経営相談・指導（創業前から卒業後まで）、年3回の無料セミナー、名刺交換会、定期的な勉強会、学生向けアントレプレナークラブ、教員への技術相談と知的財産相談のコーディネート。大学側は、東京都事業に基づくスタートアップ立ち上げ専門人材の伴走型支援とアクセラレータープログラム、DEMO DAY、学生・若手研究者・技術者向けアントレプレナー講座（受講料無料、学外者も受講可）、地域企業との共同研究費支援。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_35b5c217ec7b', 'attr_source_docs', 'established', 'https://www.dendai.ac.jp/crc/tlo/ ・ https://www.tdu-kakehashi.com/ ・ https://www.dendai.ac.jp/crc/tlo/corporation/polic…', '1本目は研究推進社会連携センター 産官学連携担当（承認TLO）のトップで、企業向け・学内向けの全メニューの入口。2本目は東京電機大学と足立区が協業する創業支援施設かけはしの公式サイトで、施設・料金・募集要項・入居企業・支援体制を掲載し、起業支援の実体はここに集中している。3本目は東京電機大学 知的財産ポリシーで、既存の規程台帳に現行規程として登録済みの実在確認済みURL（本セッションでは未展開）。認定規程・称号規程は公開されておらず、学校法人東京電機大学規程集は学内者専用。', 'official', 'https://www.dendai.ac.jp/crc/tlo/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_cert_update', 'not_started', '認定制度がなく認定期間・更新審査の定めなし', '東北大学規程集で大学発ベンチャーの認定・称号付与に関する規程は確認できず、スタートアップ事業化センターの支援メニューにも認定は含まれない。したがって認定期間、更新の可否、更新審査、要件再確認を定めた条文は存在しない。期間と更新審査が定められているのは施設使用で、東北大学星陵スタートアップビレッジレンタルスペース使用内規第3条が原則1年を単位として使用させ、使用期間は最長5年、医学系研究科長が特に適当と認めるときは所定の審査を経て延長することがあると規定する。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_title_restriction', 'established', '称号制度なし、大学名称使用は許可制で誤認防止基準', '国立大学法人東北大学における大学名称等の使用に関する規程（令和3年規第37号、令和8年5月12日改正）第5条が使用の許可の基準6号を列挙する。第3号は本学の名誉が傷つけられ又は傷つけられるおそれがないこと、第4号は商品又は役務等の情報に関し誇大な又は事実と異なる表示により消費者及び社会に誤認を与えるおそれがないこと、第5号は本学と使用者とが明確に区分され本学が不当景品類及び不当表示防止法、製造物責任法その他関係法令による責任等を負うおそれがないこと。称号付与制度ではなく、研究成果を活用した商品・役務への大学名の使用を対象とする。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002785.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_cancellation', 'established', 'あり、名称使用許可の取消しと施設使用許可の取消し', '大学名称等の使用に関する規程第8条第1項が取消事由4号を列挙し、第2項で産学連携総括責任者は許可が取り消された場合に使用許諾契約を解除するものとすると規定、第3項で解除により損害が生じることがあっても本学はその責めを負わないとする。東北大学星陵スタートアップビレッジレンタルスペース使用内規第9条は、本学において使用する必要が生じたとき、または使用者が内規もしくは使用許可条件に違反したときの取消し・中止を定め、第12条は使用を終えたとき直ちに原状に回復し返還することを求める。認定制度が無いため称号の返付や表示削除の条文は存在しない。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002785.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_report_change', 'unknown', null, '［自動検証で否認: 規程は全10条、「第9条で完結」は誤り(実際は第10条雑則)］元の主張(not_started): 認定制度がなく年次報告・変更届の定めなし。大学名称等の使用に関する規程は第1条から第9条までで完結し、使用者の義務は第7条の規程および使用許諾契約の遵守のみで、年次報告や代表者・所在地・資本構成の変更届、解散時報告を課す条文は置かれていない。認定制度自体が無いため被認定企業の報告制度も存在しない。届出義務があるのは施設使用で、星陵スタートアップビレッジレンタルスペース使用内規第10条が使用期間の変更等について60日前までに医学系研究科長へ申し出て承認を受けなければならないと定める。株式等の取得に関する規程の報告義務は部局長から総長への学内報告である。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_support_request', 'established', 'あり、施設・名称使用・機器・資金が各別に申請審査', '認定と切り離した個別申請・審査が支援ごとに置かれている。星陵スタートアップビレッジレンタルスペース使用内規第4条は所定の期日までに別記様式第1号により申請書を医学系研究科長に提出させ、第5条で星陵スタートアップビレッジ運営委員会の審査を経て研究科長が条件を付して許可し、学外の利用者は総長との契約を要する。大学名称等の使用に関する規程第3条は産学連携総括責任者への申請、第4条は同責任者とコンプライアンス総括責任者の協議による許可の決定を定める。青葉山ガレージは学外からの利用希望をフォームでの連絡としている。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_facility_registration', 'established', 'あり、青葉山ガレージで本社登記可・施設は有償貸与', 'スタートアップ事業化センターの青葉山ガレージのページは、学内の方が広く利用できるスペースとして2021年12月にオープンし、原則平日9-17時は自由に入退室でき、東北大関連ベンチャーの方は本社登記を行いオフィスとしての利用も可能と記載する。スタートアップ事業化センター作成資料の東北大学スタートアップガレージ（TUSG）活動拠点図でも青葉山ガレージの機能として法人登記が挙げられている。川内・星陵にも常設ガレージがあり、星陵スタートアップビレッジのレンタルスペースは内規に基づく有償貸与。登記に関する内規の本文は公開されていない。', 'official', 'https://startup.tohoku.ac.jp/aobayama_garage/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_vc_connection', 'established', 'あり、THVP・地域金融機関・自治体・東証と連携', 'スタートアップ事業化センター作成資料「東北大学のスタートアップ支援について」（2025年3月14日）は、東北大学スタートアップガレージの活動として大学シーズと企業とのマッチング支援およびVC・金融機関と連携し資金調達を支援すると明記する。同資料は、東北大学・七十七銀行・宮城県・仙台市・東京証券取引所／日本取引所グループが2022年度から開講するIPO経営人材育成プログラムTOHOKU、産官学金で構成し共同機関22校が参加するMASP、東北大学・仙台市・宮城県・NTTグループ等が2023年6月に連携協定を締結したSENDAI STARTUP CAMPUS構想を掲載する。', 'official', 'https://impact-consortium.fsa.go.jp/wp-content/uploads/2025/06/wg03_fw02_ref03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_eir', 'established', 'あり、東北大学版EIR制度とTHVPのEIR採用', '東北大学「スタートアップ・ユニバーシティ宣言」（2020年10月29日）が国内大学初のベンチャー創出支援パッケージの柱として東北大学版EIR（Entrepreneur in Residence）制度の創設を掲げ、本学でアントレプレナーシップの育成やベンチャー支援業務に携わりながら、いわば住み込みで本学研究成果を活用した起業を目指してもらうと説明する。100％出資VCの東北大学ベンチャーパートナーズは2024年2月に同社として初のEIR3名を採用し、最大1年間の業務期間でキャピタリスト伴走のもと研究シーズのソーシングと事業創出のサポートを担わせている。EIRの学内規程本文は非公開。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.tohoku.ac.jp/japanese/2020/10/press20201029-02-start.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_cxo_pool', 'established', 'あり、THVPがCxO・EIR等経営候補をマッチング', '東北大学ベンチャーパートナーズの運営ファンドページが、支援内容としてCxO人材、EIR等の経営候補人材のマッチングによる支援と、アドバイザー・大企業とのネットワークを挙げる。同社ニュースは、採用のミスマッチを防ぐため半年から1年程度は副業としてスタートアップや起業を目指す研究者に伴走したうえで入社・創業を判断する仕組みを導入したと説明する。大学側は「スタートアップ・ユニバーシティ宣言」で同窓会組織と連携し支援者・経営者候補を確保する東北大学スタートアップ・アルムナイと、卒業生による東北大学スタートアップアドバイザー制度を掲げる。大学規程としての人材プール規程は確認できない。', 'official', 'https://thvp.co.jp/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_ip_equity', 'established', '可、継続実施料を新株予約権へ置換可（総長決定）', '産学連携機構「本学発スタートアップへの技術移転の基本的考え方」は、対価を一時金と継続実施料（ランニングロイヤリティ）の二階建てとし、継続実施料はスタートアップの事業計画等に応じて新株予約権に置換可能、マイルストーン設定と新株予約権のハイブリッド等も柔軟に対応可能と明記する。譲渡（専用実施権を含む）と独占的通常実施権で継続実施料部分の価格・料率が変わるとも説明する。受け皿は国立大学法人東北大学における株式等の取得に関する規程で、第2条が本学が実施する事業の対価として研究成果の事業化を目的とした企業等から株式等を取得する場合を掲げ、第10条第1項で当該取得は総長が行うと定める。', 'official', 'https://www.rpip.tohoku.ac.jp/jp/property/gijutsuiten_to_su.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'pol_fund_investment', 'established', 'あり、100％出資のTHVPが3本のファンドを運用', 'スタートアップ事業化センター作成資料は、東北大学ベンチャーパートナーズを2015年2月設立の東北大学100％出資ベンチャーキャピタルと記載し、第1号ファンド2015年8月組成、第2号ファンド2020年10月組成と示す。同社運営ファンドページは第3号ファンドを2026年6月5日設立、無限責任組合員を同社、有限責任組合員に国立大学法人東北大学ほかと記載し、投資対象を東北大学および東北圏域周辺地域の国立大学の研究成果を活用したスタートアップ、投資段階をシード・アーリー中心とする。大学自身の出資は株式等の取得に関する規程第2条・第4条による。', 'official', 'https://thvp.co.jp/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_regulation_owner', 'established', '大学規程、国立大学法人東北大学が単独で制定', '設置形態は国立大学法人であり、学校法人規程やハイブリッドの余地はない。認定規程そのものは存在しないが、関連する株式等の取得に関する規程、大学名称等の使用に関する規程、星陵スタートアップビレッジレンタルスペース使用内規はいずれも国立大学法人東北大学の学内規則として制定されている。国立大学法人東北大学における学内規則の区分及び制定等の手続に関する規程（平成30年規第167号）第3条第1項は、規程は法令等又は管理運営若しくは教育研究上の必要性に基づき本学の重要事項及び基本的事項について定め、役員会の議を経て総長が定めると規定する。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002636.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_review_body', 'not_started', '認定の審査主体なし、支援ごとに委員会・責任者が審査', '認定制度が無いため認定委員会や審査会は存在しない。実際に機能している審査主体は支援ごとに分かれる。星陵スタートアップビレッジレンタルスペースは星陵スタートアップビレッジ運営委員会が使用目的等を審査し医学系研究科長が許可する（同内規第5条）。大学名称等の使用は産学連携総括責任者及びコンプライアンス総括責任者が協議の上で許可を決定する（同規程第4条）。株式等の取得は経営協議会の議に付し役員会の議を経て総長が決定し、株式等の取得に関する諮問会議が総長の諮問に応じて協議し助言・提言する（同規程第4条・第11条）。支援の受付窓口はスタートアップ事業化センター。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002657.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_equity_decider', 'established', '総長、経営協議会の議に付し役員会の議を経て決定', '国立大学法人東北大学における株式等の取得に関する規程（平成31年規第43号、令和6年最終改正）第4条は、出資による株式等の取得の決定は経営協議会の議に付し、役員会の議を経て、総長が行うと規定する。第6条第1項も寄附による出資可能相手方の株式等について同じ手続を定める。第7条第2項・第3項は寄附による出資可能相手方以外の株式等について部局長が取得を決定し速やかに総長に報告するとし、第10条第1項は事業の対価による取得を総長が行うと定める。第11条に株式等の取得に関する諮問会議。第13条は換金することが可能となったときは速やかに売却するとするが、処分の決裁者は明記されていない。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002657.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_amendment_decider', 'established', '総長、役員会の議を経て制定（学内規則手続規程）', '国立大学法人東北大学における学内規則の区分及び制定等の手続に関する規程（平成30年11月26日規第167号、令和3年4月1日施行）第3条第1項が、規程は役員会の議を経て総長が定めると規定し、組織運営規程や重要な教育研究上の規程については教育研究評議会・経営協議会等の審議を経ることを各号で定める。第2項は内容が軽微又は形式的である規程について役員会、教育研究評議会及び経営協議会の審議を省略できるとする。個別の株式等の取得に関する規程と大学名称等の使用に関する規程には改廃条項が置かれておらず、改廃への準用を明示する条文は本規程でも確認できなかった。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002636.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_post_grad_limit', 'not_started', '規定なし、卒業生を年数要件なく支援対象', '認定制度が無いため、退職後・卒業後の年数要件は設けられていない。東北大学星陵スタートアップビレッジレンタルスペース使用内規第2条は対象を本学の教員等および本学の教員等が関係するスタートアップ企業等と定めるのみで、退職や卒業からの経過年数を条件としていない。既存の確認済み評価（attr_eligible_scope）でも、スタートアップ事業化センターのコンセプトページが教員・学生・卒業生を幅広くサポートすると記載するにとどまり、年数要件の記載は無い。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_renewal_rule', 'not_started', '規定なし、施設使用のみ審査を経た延長可', '認定制度が無いため認定の更新ルールは存在しない。期間と更新の定めがあるのは施設使用で、東北大学星陵スタートアップビレッジレンタルスペース使用内規第3条が原則として1年を単位として使用させ、使用の期間は最長で5年間とし、医学系研究科長が特に適当と認めるときは所定の審査を経て延長することがあると規定する。第10条は使用期間の変更等について60日前までに医学系研究科長に申し出て承認を受けなければならないとする。大学名称等の使用に関する規程には使用期間・更新の条文が置かれていない。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_naming', 'not_started', '称号なし、公式表記は大学発スタートアップが主', '認定・称号付与の制度が無いため、大学が付与する呼称は存在しない。公式ページでの呼び分けは混在しており、スタートアップ事業化センターのトップページは大学発スタートアップおよび東北大学発スタートアップ、産学連携機構の技術移転ページは本学発スタートアップ、スタートアップ事業化センター作成資料は東北大学発スタートアップと東北大学発ベンチャーの双方を使う。青葉山ガレージのページは登記利用の対象を東北大関連ベンチャーと表記する。［検証エージェントは出典を開けず未照合］', 'official', 'https://startup.tohoku.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_support_period', 'established', '支援ごとに別に定める、称号期間の概念なし', '称号が無いため称号期間は存在せず、支援ごとに期間が定められている。星陵スタートアップビレッジレンタルスペースは原則1年単位・最長5年で審査を経た延長可（同内規第3条）。東北大学ベンチャーパートナーズのEIRは最大1年間の業務期間。ギャップファンドのビジネスインキュベーションプログラムはPhase別に支援内容を設定する。青葉山ガレージは利用期間・更新の記載が無い。大学名称等の使用に関する規程は使用期間の条文を置かず、第6条の使用許諾契約に委ねる形になっている。', 'official', 'https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00003005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_support_contents', 'established', '起業教育・ギャップファンド・ガレージ伴走・本社登記／施設貸与・共用機器・知財移転・THVP投資・EIR／CxOマッチング', 'スタートアップ事業化センター作成資料「東北大学のスタートアップ支援について」（2025年3月14日）が、アントレプレナーシップ育成プログラム、ギャップファンドプログラム（ビジネスインキュベーションプログラムとみちのくギャップファンド）、東北大学スタートアップガレージによる常設コミュニティスペース提供・起業塾とピッチイベント・大学シーズと企業のマッチング・VCと金融機関と連携した資金調達支援・メンターによる起業相談、東北大学ベンチャーパートナーズによる投資を柱として示す。これに青葉山ガレージでの法人登記、星陵のレンタルスペース貸与、研究基盤利用ポータル経由の共用機器利用、知財の技術移転が加わる。', 'official', 'https://impact-consortium.fsa.go.jp/wp-content/uploads/2025/06/wg03_fw02_ref03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_9ed928e1e75c', 'attr_source_docs', 'established', 'https://startup.tohoku.ac.jp/ssp/・https://www1.g-reiki.net/tohoku.ac/reiki_honbun/u101RG00002785.html・https://www1.g-re…', '1本目はスタートアップ事業化センターのスタートアップ支援プログラムページで、支援メニューと問い合わせ導線の入口。2本目は国立大学法人東北大学における大学名称等の使用に関する規程で、認定・称号制度が無い東北大学において大学名の使用可否、誤認防止の許可基準、取消しと契約解除を定める唯一の規律。3本目は国立大学法人東北大学における株式等の取得に関する規程で、出資および事業の対価としての株式・新株予約権の取得手続と決裁を定める。あわせて産学連携機構の技術移転ページと、スタートアップ事業化センター作成資料が基礎資料になる。［検証エージェントは出典を開けず未照合］', 'official', 'https://startup.tohoku.ac.jp/ssp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_cert_update', 'established', '有効期間5年、延長申請で更に5年。延長も委員会審査', 'ベンチャー支援規程第5条本文「その有効期間は認定の日から5年間とする。ただし、延長申請を妨げないものとし、その有効期間はさらに5年間とする」。第4条第1項は「認定又は認定期間の延長を希望する者」が様式1を理事長へ提出すると定め、様式1に「新規・延長」の選択欄がある。延長も第4条第2〜4項の諮問・審査・面接・答申・理事長決定を経る。第9条第1号が第5条の要件を満たさなくなった場合を取消事由とし、期間中も要件が確認される。認定期間は様式2甲の認定書に記載。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_title_restriction', 'established', '認定に法的責任は生じない旨を明記、取消後は称号利用禁止', '第7条（機構の法的責任）「森林総研発ベンチャーの認定付与は、機構に何ら法的責任を生じさせるものではない」。第9条第2項は取消しを受けた者が取消日以降「認定を受けていた事実を利用し、事業を行ってはならない」と定め、様式4の認定取消通知書にも同旨を再掲する。一方、品質保証・投資推奨・経営状態の保証と誤認させない旨の明文や、称号を表示できる範囲（広報物・商品表示等）を定めた条項はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_cancellation', 'established', '取消事由4号、取消後は認定実績を使った事業を禁止', '第9条第1項が取消事由を4号列挙。一号=第5条の要件を満たさなくなった場合、二号=企業活動が機構の事業活動の円滑な実施に支障を来たすと判断した場合、三号=社会的信用を失墜する行為、四号=機構の不名誉となるおそれ等。第2項で取消日以降の認定実績を利用した事業を禁止し、様式4に取消理由欄を置く。第10条・様式5で認定を受けた側から解除を申し出られる。認定書の返付や表示物の削除を求める条項はない。様式2甲別紙3は同じ事由で支援の中止・変更を行うと定める。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_report_change', 'established', '毎事業年度後の実施状況報告、増減資・解散等は随時報告', '第8条第1項「毎事業年度終了後、速やかに様式３により事業の実施状況について報告しなければならない」。様式3は実施状況の確認資料と、決算書・税務申告書・財務諸表等の財務資料の添付を求める。第2項は増資、減資、解散、破産、再生手続、更生手続等の事実があった場合の速やかな報告を義務づける。様式2甲別紙2(3)は支援内容の変更が必要になった場合の速やかな申出を条件とする。代表者や所在地の変更届を定めた条項・様式はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_support_request', 'established', '認定申請書に希望支援を記載、理事長が支援内容を個別決定', '様式1の記載事項「５．会社が希望する支援の内容」で認定申請と一体に支援を申請する。第4条第4項は理事長が委員会の答申を基に「認定及び支援内容の可否」を決定し様式2で通知すると定める。様式2甲の別紙「支援内容通知書」は第6条第1項の一〜四号ごとに場所・内容・期間を個別記載し、支援に関する要望があった場合のみ作成、一括不承認の記載例も置かれる。認定とは別建ての支援申請様式や審査手続はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_facility_registration', 'established', '所内の事務室・研究室を貸与、商業登記の可否は不記載', '第6条第1項第1号「事務室又は研究室として森林総合研究所等内に場所を確保し、貸与すること」。第2項で不動産等管理規程（13森林総研第84号）に基づく契約を締結し、理事長が適当と認めるときは貸付料の減免等の措置をとることができる。貸与の場所・内容・期間は様式2甲別紙の支援内容通知書に個別記載される。本店所在地としての商業登記の可否は同規程にも産学官民連携・知的財産ページにも記載がなく、インキュベーション施設の名称や入居要項も公開されていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_vc_connection', 'not_started', 'VC・金融機関への紹介制度なし', '第6条第1項の支援は一号=場所の貸与、二号=研究設備等の利用許可、三号=知的財産権（森林総研成果活用ロゴマークを含む）の実施権の許諾又は設定、四号=その他理事長が必要と認める支援で、金融機関やベンチャーキャピタルへの紹介は含まれない。産学官民連携・知的財産ページの掲載メニューも実用化カタログ、展示会参加、外部ネットワーク連携、共同研究・受託研究、NDA、MTA、実施許諾契約、ベンチャー支援の8項目で、資金調達先や自治体への接続導線は掲載されていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_eir', 'not_started', '客員起業家・起業家メンターの制度なし', 'ベンチャー支援規程第6条第1項の支援類型に外部人材の招聘は含まれない。第6条第5項は機構の役職員が森林総研発ベンチャーの活動を行う場合を兼業取扱規程（17森林総研第1542号）に基づく兼業と定めるのみで、外部の起業家を機構側へ迎える枠組みではない。知的財産権実施規程第9条の技術指導・役職員派遣も費用を実施者が負担する技術支援である。産学官民連携・知的財産ページにも客員起業家や起業家メンターの記載はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_cxo_pool', 'not_started', '経営人材の紹介・マッチング制度なし', '第6条第1項各号の支援は場所の貸与、研究設備等の利用許可、知的財産権の実施許諾又は設定、理事長が必要と認めるその他の支援で、経営人材の紹介やマッチングは含まれない。様式1の添付書類は会社定款、事業計画書、会社経歴書、決算報告書（直近2カ年分）、代表者の履歴書で、経営体制の補強を前提とした手続はない。産学官民連携・知的財産ページの支援メニューにもCEO・CXO候補の紹介制度の記載はない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_ip_equity', 'established', '機構法第15条の2により減免支援時の株式・新株予約権取得可', '国立研究開発法人森林研究・整備機構法第15条の2（株式等の取得及び保有）「機構は、科学技術・イノベーション創出の活性化に関する法律第34条の5第1項及び第2項の規定による株式又は新株予約権の取得及び保有を行うことができる」。同法第34条の5第1項は、第34条の4第2項の支援（知的財産権の移転・設定・許諾、施設又は設備の貸付け等）につき第3項の無償化・時価より低い対価の措置をとる場合に株式等を取得できると定める。ベンチャー支援規程第6条第2〜4項の減免措置はこれに対応するが、同規程と様式に株式の定めはなく、知的財産権実施規程第7条第2項は実施料を銀行振込とする。', 'official', 'https://laws.e-gov.go.jp/api/1/lawdata/411AC0000000198', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'pol_fund_investment', 'not_started', '出資は機構法上の業務、政令の指定と内部規程はなし', '機構法第13条第1項第5号は「科学技術・イノベーション創出の活性化に関する法律第34条の6第1項の規定による出資並びに人的及び技術的援助のうち政令で定めるもの」を業務とし、同法別表第三の十八に機構が掲げられている。第34条の6第1項は成果活用事業者、資金供給等事業を行う者（投資事業有限責任組合を含む）、技術移転等を促進する者への出資を認め、第2項で二号・三号への出資に主務大臣の認可、第3項で財務大臣協議を求める。ただし機構法施行令（平成27年政令第43号）の現行全15条に出資の指定規定はなく、ファンド組成・出資規程・出資実績も公開されていない。', 'official', 'https://laws.e-gov.go.jp/api/1/lawdata/411AC0000000198', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_regulation_owner', 'established', '研究機関規程。機構が定める内部規程（6森林機構1078号）', '規程名は「国立研究開発法人森林研究・整備機構の研究開発分野におけるベンチャー支援規程」、令和7年3月11日6森林機構1078号、附則により令和7年4月1日施行。制定主体は国立研究開発法人森林研究・整備機構で、大学規程でも学校法人規程でもない。第1条の適用対象は機構の森林総合研究所、森林総合研究所林木育種センター、森林総合研究所森林バイオ研究センター。申請・認定・取消しの名宛人と発出者はいずれも機構理事長。主管部署は企画部研究管理科（第12条）。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_review_body', 'established', 'ベンチャー認定委員会。委員長は企画・総務・森林保険担当理事', '第3条第1項で森林総合研究所等にベンチャー認定委員会を置き、認定、認定の取消し、その他の検討事項を審議する。第2項で委員長は理事（企画・総務・森林保険担当）とし、委員会は必要に応じ委員長が招集する。第3項の委員は理事（研究担当、育種事業・森林バイオ担当、法令遵守担当）、総括審議役、企画部長、研究リスク管理監、研究企画科長、研究管理科長、社会実装推進・知財戦略室長、総務部長、総務調整監、担当研究ディレクター、担当研究コーディネーター等。第4項で外部有識者等の出席を求めることができる。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_equity_decider', 'unknown', null, '機構法第15条の2は機構が株式又は新株予約権を取得し保有できると定めるが、取得・処分の決裁者や手続を定めた規程は公開されていない。ベンチャー支援規程では第4条第4項で理事長が委員会の答申を基に認定と支援内容の可否を決定し、第6条第2〜4項で貸付料・実施料の減免等の措置を理事長が判断すると定めるにとどまる。第3条第1項のベンチャー認定委員会の審議事項は認定、認定の取消し、その他の検討事項で、株式取得の審議は明示されていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_amendment_decider', 'unknown', null, 'ベンチャー支援規程に制定改廃の手続や決裁者を定めた条項はない。第13条（その他）は「この規程に定めるもののほか、この規程の実施において必要な事項は、別に定める」とするのみで、附則は施行日（令和7年4月1日）だけを定める。規程番号6森林機構1078号は機構が発する内部規程の番号体系で、申請・通知・取消しの発出者はいずれも理事長だが、規程自体の改廃権者は本文に明記されていない。機構の規程管理に関する上位規程も公開されていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_post_grad_limit', 'not_started', '規定なし。第5条は法人要件のみで個人の年限を定めず', '第5条の認定要件は6号の限定列挙で、一号=科技イノベ活性化法第34条の4第1項の成果活用事業者であること、二号=研究成果の社会実装の実現が見込まれること、三号=森林総合研究所等の業務に支障を与えないこと、四号=公序良俗に反しないこと、五号=設立した日から概ね10年を経過していないこと、六号=その他不適当でないこと。いずれも法人の属性で、創業者が役職員か退職者かの区分や退職後の年限はない。役職員の関与は第6条第5項で兼業取扱規程による兼業として扱う。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_renewal_rule', 'established', '更新可（審査あり）。延長申請で有効期間を更に5年', '第5条本文ただし書「延長申請を妨げないものとし、その有効期間はさらに5年間とする」。第4条第1項は「認定又は認定期間の延長を希望する者」が様式1の申請書に事業内容・使用する知的財産などに関する書類を添えて理事長へ提出すると定め、様式1に「（ 新規 ・ 延長 ）」の選択欄がある。延長も第4条第2〜4項に従い理事長が委員会へ諮問し、委員会が審査と必要に応じた面接を行い答申、理事長が可否を決定する。届出のみで更新される仕組みではない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_naming', 'established', '独自名称。認定書の称号は「森林総研発ベンチャー企業」', '第2条は森林総合研究所等の所有する知的財産権を活用する成果活用事業者であって本規程に基づき認定されたものを「森林総研発ベンチャー」と定義する。規程上の正式表記は「森林総合研究所等発ベンチャー」で、様式1が「（略称：森林総研発ベンチャー）」と記す。様式2甲の認定書は「貴社を『森林総研発ベンチャー企業』として認定します」と記載し、様式2乙の結果通知書、様式4の認定取消通知書も同じ称号を用いる。大学発ベンチャー、大学発スタートアップの語は使われていない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_support_period', 'established', '支援ごとに別に定める。支援内容通知書に各支援の期間を記載', '認定の有効期間は第5条で認定の日から5年、延長でさらに5年。これに対し様式2甲の別紙「支援内容通知書」は、第6条第1項の一号（場所の貸与）、二号（研究設備等の利用許可）、三号（知的財産権の実施許諾又は設定）、四号（その他）ごとに「場所・内容・期間」を個別記載する構成で、支援の期間は認定期間とは別に決定される。第6条第2〜4項により各支援は不動産等管理規程、物品管理規程、知的財産権実施規程に基づく個別契約を締結し、契約でも期間が定まる。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_support_contents', 'established', '事務室・研究室の貸与・研究設備等の利用許可・知財の実施許諾・使用料減免', '第6条第1項の各号。一号=事務室又は研究室として森林総合研究所等内に場所を確保し貸与、二号=研究設備等の利用を許可、三号=森林総合研究所等が所有する知的財産権（森林総研成果活用ロゴマークを含む）の実施権の許諾又は設定、四号=その他理事長が科学技術・イノベーション創出の活性化のために必要と認める支援。第2〜4項で不動産等管理規程、物品管理規程、知的財産権実施規程に基づく契約を締結し、理事長が適当と認めるときは貸付料・実施料の減免や一定期間の優先的な実施が可能。産学官民連携ページも「各種支援のほか許諾・使用料の減免」と記載。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f47662863af3', 'attr_source_docs', 'established', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf・https://www.ffpri.go.jp/sangakukan/documents/ip_kitei.pdf・http…', '1本目がベンチャー認定制度の正本（令和7年3月11日6森林機構1078号、全13条と様式1〜5）。2本目はベンチャー支援規程第6条第4項が実施許諾の根拠に指定する知的財産権実施規程（13森林総研第72号、令和6年3月22日最終改正）。3本目は産学官民連携・知的財産の入口ページで、支援メニューと申込窓口（企画部研究管理科社会実装推進・知財戦略室）を掲載する。株式取得と出資の授権は機構法第15条の2・第13条第1項第5号にあり、機構サイトには掲載がない。', 'official', 'https://www.ffpri.go.jp/sangakukan/documents/venture.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_cert_update', 'unknown', null, 'AISolスタートアップ認定の有効期間・更新審査・要件再確認を定めた公開文書を確認できなかった。根拠だった産総研ベンチャー支援規程（令02規程第8号）は令06規程第31号で廃止され、研究施設等の利用及び貸付に関する規程の附則（令06規程第50号）第2条第3項が廃止と経過措置を明記、施行は2025年4月1日。規程類一覧ページにもベンチャー支援規程は掲載されていない。施設の一時利用は1年以内で再申込だが、これは認定の更新ではない。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_title_restriction', 'unknown', null, '称号の使用範囲、品質保証・投資推奨・経営状態保証と誤認させない旨の条項、使用停止の定めを公開情報で確認できなかった。AISolのスタートアップ支援ページとAISolスタートアップ紹介ページは、認定の観点（社会課題解決への貢献、技術的競争優位性、市場性、産総研とのシナジー）を書くにとどまる。旧称号のマークの根拠だったベンチャー支援規程は廃止済み。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_cancellation', 'unknown', null, '認定の取消事由、称号返付、表示削除、営業利用停止を定めた公開文書は確認できなかった。近い規定は施設側と出資側にあり、研究施設等の利用及び貸付に関する規程第4条が一時利用の受入取消・中止と賃貸借契約の解除を、成果活用等支援法人出資業務規程第10条第4項が経営に重大な障害が生じた場合等の出資継続可否の判断と株式等の処分を定める。いずれも称号の取消ではない。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_report_change', 'established', '出資先・実施権者に定期報告、認定企業の変更届は規定なし', '認定企業に年次報告や代表者・所在地・資本構成の変更届を課す公開規定は確認できなかった。定期報告の規定があるのは出資と知財の側で、成果活用等支援法人出資業務規程第10条第1項が経営状況と成果活用促進事業の実施状況の定期的把握を、同条第2項が出資先へ財務情報等の定期的又は臨時の報告を求めることができると定める。知的財産権の実施許諾及び譲渡に関する規程第2条第5項第1号は実施権者に実施状況の定期報告を約させる。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/seikakatsuyou_shusshi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_support_request', 'established', '施設利用・出資・プログラムごとに個別申請と審査', '認定とは別に支援ごとの申請と審査がある。研究施設等の利用及び貸付に関する規程第3条第2項は施設管理者の内諾を得て申込書を提出させ、同条第1項の要件審査を経て第3項・第4項で利用契約または賃貸借契約を締結する。成果活用事業者出資業務規程第6条が出資の受入手続、第7条が審査と出資先の決定を定める。AISolアクセラレーションプログラムは一次選考・ブラッシュアップ・二次選考・最終選考の段階審査。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_facility_registration', 'established', '研究施設等の貸付・一時利用あり、商業登記の規定なし', '研究施設等の利用及び貸付に関する規程（令05規程第49号）第3条第1項第4号ヘが、経済産業省関係産業競争力強化法施行規則第14条の25の研究施設等を新たな事業活動を行う者が利用する場合を貸付の要件に挙げる。業務方法書第20条の2と第43条は産業競争力強化法第21条の18の業務として施設貸付を位置づける。同規程を全文確認したが、本店所在地の商業登記に関する条文はない。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_vc_connection', 'established', '国内外VC紹介とマッチング、協調出資、1stRound参画', 'AISolのスタートアップ支援ページが資金関連サービスとして国内外のベンチャーキャピタル紹介とマッチング機会の提供、産総研グループ等との協調出資による資本力強化支援を掲げる。2025年10月6日のお知らせで産総研とAISolが創業成長支援プログラム1stRoundに参画。1stRound公式ページは最終審査にコーポレートパートナーと外部VCが加わる選考と、専属ファンドによる投資検討を記載。自治体・金融機関への紹介の記載はない。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_eir', 'unknown', null, '客員起業家（EIR）、起業家メンター、起業家人材の招聘制度を公開情報で確認できなかった。AISolのスタートアップ支援ページとAISolスタートアップ紹介ページの支援メニューは技術・マーケティング・知財・グローバル展開・資金関連の5サービスで、人材面は人材育成と各種セミナー・アドバイザー紹介の記載にとどまる。参画先の1stRound公式ページにも客員起業家の記載はない。', 'official', 'https://www.aist-solutions.co.jp/service/service_menu/page000043.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_cxo_pool', 'established', '1stRound経由で経営人材のチーム組成支援', '産総研・AISol独自の経営人材プールや紹介制度は確認できなかった。AISolの支援メニューは人材育成と各種セミナー・アドバイザー紹介にとどまる。一方、産総研とAISolが2025年10月に参画した1stRoundの公式ページは、提供リソースとして経営人材をはじめとしたチーム組成の支援と、人材サービス会社と連携した副業・兼業のマッチングを掲げており、採択企業はこの枠組みを利用できる。', 'official', 'https://www.1stround.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_ip_equity', 'established', '知財の現物出資で株式・新株予約権を取得可、許諾対価の株式化は規定なし', '知的財産権の実施許諾及び譲渡に関する規程（13規程第15号）を全文確認したが、実施許諾の対価を株式・新株予約権とする条文はなく、第2条第2項は有償・無償の別を定めるにとどまる。株式化の経路は現物出資で、成果活用事業者出資業務規程第2条第3号・第4号が知的財産権を金銭以外の財産、株式等を株式・新株予約権・持分と定義し、第4条で現物出資、第13条で発明者補償の読み替え、第15条で知財規程の一部適用除外を定める。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/syuxtushi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'pol_fund_investment', 'established', '出資規程2本、直接出資と支援法人出資、LP出資は規定なし', '出資規程は2本。成果活用事業者出資業務規程（令01規程第15号）第5条が活性化法第34条の6第1項第1号の成果活用事業者への直接出資を定め、第4条第2項で議決権を原則3分の1未満に制限。成果活用等支援法人出資業務規程（令04規程第23号）第6条第2項が経済産業大臣の認可を受けた成果活用等支援法人への出資を定め、AISolがこれに当たる。両規程を全文確認したが、投資事業有限責任組合へのLP出資やファンド組成の条文はない。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/seikakatsuyou_shusshi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_regulation_owner', 'established', '研究機関規程（産総研規程）、認定はAISol運用', '産総研は国立研究開発法人で、出資・研究施設利用・知的財産の各規程はいずれも産総研の規程（○規程第○号）として規程類一覧ページで公開されている。一方、称号の根拠だったベンチャー支援規程は2025年4月1日に廃止され、規程類一覧にも掲載がない。現在の認定は全額出資子会社である株式会社AIST Solutionsが行うため、認定そのものを定めた産総研規程は存在しない。', 'official', 'https://www.aist.go.jp/aist_j/information/outline/comp-legal/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_review_body', 'established', '成果活用事業者出資委員会／成果活用等支援法人出資委員会', '業務方法書第20条第2項第1号が、出資規程に外部有識者からなる委員会の設置と審議に関する事項を定めることを義務づける。これを受け成果活用事業者出資業務規程第3条が成果活用事業者出資委員会を、成果活用等支援法人出資業務規程第3条・第4条が成果活用等支援法人出資委員会を置く。後者は外部有識者中心で役職員からの委員は1名以内、任期2年、事務は経営企画本部企画部AIST Solutions室が行う。認定と支援の窓口はAISolプロデュース事業本部スタートアップ部。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/seikakatsuyou_shusshi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_equity_decider', 'established', '理事長が決定（支援法人出資）、事業者出資は委員会審議後に研究所決定', '成果活用等支援法人出資業務規程第6条第1項は、出資及び出資内容を第3条に基づく委員会の審議の結果を踏まえ理事長が決定すると定め、第12条第2項で株式等の処分に委員会を活用できるとする。成果活用事業者出資業務規程は第7条で研究所が審査を行い出資先を決定、第12条第2項で処分の内容について審査を行い決定と定め、第3条の成果活用事業者出資委員会が重要事項を審議する。第9条の2の一号出資管理者は研究戦略本部長が指定する。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/seikakatsuyou_shusshi.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_amendment_decider', 'established', '研究所が整備・公表（業務方法書第44条）、業務方法書は経産大臣認可', '業務方法書（13業務方法書第1号）第44条が、研究所は業務に関する規程を定めるとともに業務の適正な実施に必要な規程を整備し、それらを公表するものとすると定める。業務方法書自体は附則により経済産業大臣の認可のあった日から施行。各出資規程は第1条で業務方法書第20条第2項に基づくと明記する。今回開いた規程本文には制定改廃を理事長が行う旨の条文はなく、表記は制定年月日と規程番号のみ。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/houhou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_post_grad_limit', 'established', '規定なし（転出先特例・出資要件とも年数制限なし）', '知的財産権の実施許諾及び譲渡に関する規程第4条と第6条は、知財の創造に創作的に寄与した役職員等が転出する場合に、その転出先へ独占的・一部独占的実施許諾または譲渡を行える特例を置くが、退職・転出後の年数制限はない。成果活用事業者出資業務規程第5条の出資対象要件にも年数や設立年数の制限はない。旧ベンチャー支援規程にあった設立5年以内の要件は、同規程の廃止で根拠を失った。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/chizai.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_renewal_rule', 'unknown', null, 'AISolスタートアップ認定の更新可否や更新手続を定めた公開文書を確認できなかった。関連する期間規定は施設側にあり、研究施設等の利用及び貸付に関する規程第3条第2項は一時利用の期間を1年以内とし、1年を超える利用を希望するときは申込書を再度提出させる。これは施設利用の再申込であって認定の更新ではない。旧ベンチャー支援規程は廃止済み。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_naming', 'established', '独自名称（AISolスタートアップ）、旧称号は廃止', 'AISolが認定する呼称は「AISolスタートアップ」で、支援ページは支援中7社とIPO済み1社を認定年月付きで掲載している。大学発ベンチャー・大学発スタートアップの語は用いていない。旧称号「産総研技術移転ベンチャー」は根拠のベンチャー支援規程が2025年4月1日に廃止され、産総研側の実績ページと一覧ページも現在404を返す。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_support_period', 'established', '支援ごとに別に定める（施設一時利用は1年以内、許諾は契約で設定）', '支援ごとに期間が決まる構造。研究施設等の利用及び貸付に関する規程第3条第2項は一時利用を1年以内とし、貸付は同条第4項の賃貸借契約で期間を定める。知的財産権の実施許諾及び譲渡に関する規程第2条第3項は実施許諾の期間を定めるものとする。1stRoundは6か月のハンズオンを提供。認定自体の期間規定は公開情報で確認できず、称号期間と支援期間を結びつける記載もない。', 'official', 'https://www.aist.go.jp/Portals/0/resource_images/aist_j/outline/comp-legal/pdf/shisetsuriyoukashitsuke.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_support_contents', 'established', '技術・マーケティング・知財・グローバル展開・資金関連・研究施設装置利用・出資', 'AISolのスタートアップ支援ページとAISolスタートアップ紹介ページが、技術サービス（小ロット試作・共同研究・産総研の先端装置活用・研究施設／装置利用支援）、マーケティングサービス、知財サービス、グローバル展開サービス（米国拠点経由）、資金関連サービス（国内外VC紹介・協調出資）の5つを列挙する。加えてAISolアクセラレーションプログラムと、1stRound参画による非株式型の資金支援およびハンズオン支援がある。', 'official', 'https://www.aist-solutions.co.jp/aisol_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dd388f7debe3', 'attr_source_docs', 'established', 'https://www.aist-solutions.co.jp/aisol_startup/・https://www.aist.go.jp/aist_j/information/outline/comp-legal/index.html…', '1本目はAISolのスタートアップ支援ページで、認定の観点・支援メニュー5種・認定企業一覧を掲載。2本目は産総研の規程類一覧ページで、出資2規程、知的財産権の実施許諾及び譲渡に関する規程、研究施設等の利用及び貸付に関する規程、兼業等規程、利益相反マネジメント実施規程へのPDFリンクを持ち、ベンチャー支援規程が掲載されていないことも確認できる。3本目は成果活用事業者出資業務規程の現行PDF。', 'official', 'https://www.aist.go.jp/aist_j/information/outline/comp-legal/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_cert_update', 'established', '有効期間3年経過年度の8月末日・更新申請と再審査あり', '認定規程第6条第1項で有効期間は認定の日から起算して3年を経過する日の属する年度の8月末日まで。第2項で満了の3月前までに更新申請を義務づけ、第3項で第3条第2項（イノベーションデザイン部会議の議を経た学長の認定）を更新に準用するため、更新時も認定手続と同じ審議を通る。第4条の申請条件も準用によって再度かかる。令和8年7月28日改正の附則により、施行時に称号を授与済みの認定ベンチャーの有効期間は令和11年8月31日まで。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_title_restriction', 'established', '品質保証目的の称号使用禁止・大学は品質と経営を不保証', '認定規程第7条「認定ベンチャーは，自社の製品，サービス等の内容及び品質を保証するために，神戸大学発ベンチャーの称号を使用してはならない」。第8条で本学は認定ベンチャーの製品、サービス等の内容及び品質並びに経営状況を保証するものではなく責任を負わない旨を明記。第5条で学長が別記様式2により称号を授与し、第11条第1項第5号でロゴマークの使用許可を支援として列挙。第10条第4項で取消日以降の称号使用を禁止。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_cancellation', 'unknown', null, '［自動検証で否認: 意見聴取は「できる」の裁量規定で義務でない］元の主張(established): 取消5事由・意見聴取のうえ称号記返還と使用停止。認定規程第10条第1項の取消事由は、事業活動が第2条各号の定義から著しく逸脱した場合、社会的信用を失墜する行為を行った場合、企業活動の実態がなくなった場合、事業報告を提出しない場合、その他認定が相当でないと認める場合。学長はイノベーションデザイン部会議の議を経て取り消し、取消前に意見を聴く。取消通知後は称号記を返還し、第4項で取消しを受けた日以降は称号を事業に使用できない。ホームページ等からの表示削除を個別に定めた条文はない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_report_change', 'established', '毎年8月末の事業報告と解散等の速報・変更届は定めなし', '認定規程第9条第1項で認定ベンチャーの代表者は毎年8月末日までに前年度の事業内容及び決算状況を反映した事業報告を別記様式3により学長へ提出。第2項で解散、破産、民事再生、会社更生、不正競争に係る各号のいずれかの適用を受けたときは代表者又は清算人が速やかに学長へ報告。商号、代表者、所在地、資本構成の変更届を義務づける条文は同規程に置かれていない。事業報告の未提出は第10条第1項の取消事由。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_support_request', 'established', '施設入居は別途申請と委員会選考・GAPファンドは公募', '認定規程第11条は支援を列挙するのみで支援ごとの申請手続を定めず、第2項で「前項各号に掲げる支援を行うときは，本学における関係規則等によるものとする」と各規則へ委ねる。産官学連携本部棟入居者募集要領（令和8年度入居用）は申請書の提出期限と、本学が設置する委員会による選考を定め、選考基準は研究完結の見込み、知的財産権の保有状況、資金獲得の見込み、商業的な成功の見込み、経営者の経営能力・信頼性。GAPファンド（うりぼーファンド）も公募と選考委員会による採択。', 'official', 'http://www.innov.kobe-u.ac.jp/document/epd-applicationguide2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_facility_registration', 'established', '本部棟に月3,500円/㎡で入居可・貸与施設への商業登記可', '認定規程第11条第1項第1号で事務室又は研究室としての学内施設の貸与に優遇措置、第2号で「貸与した施設について，当該認定ベンチャーの所在地とする商業登記を認めること」。産官学連携本部棟入居者募集要領（令和8年度入居用）は申請対象に本学の教員、学生が行った研究成果を基に起業した企業又は起業しようとする者を含め、神戸大学発ベンチャーの月額平米単価を3,500円（税込、光熱水料込、別途オフィス賦課金200円）と設定。入居期間は原則1年度で委員会の議により年度毎更新、転貸は禁止。', 'official', 'http://www.innov.kobe-u.ac.jp/document/epd-applicationguide2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_vc_connection', 'established', '関連会社の大学VCとKSACへ接続・規程の紹介先は他企業のみ', '認定規程第11条第1項第3号の紹介は「他企業への紹介又は他企業との共同研究等の仲介」に限られ、ベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介は規程に明文がない。一方、学術・社会共創機構社会共創部門のスタートアップ支援ページは関連会社の株式会社神戸大学キャピタル（KUC）を支援メニューとして掲げ、京阪神スタートアップアカデミア・コアリション（KSAC）にも参画。KUC1号（神戸大学ファンド）の出資者は金融機関6社。', 'official', 'http://www.innov.kobe-u.ac.jp/entrepreneur/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_eir', 'unknown', null, '［自動検証で否認: EIR公募・締結日・対象研究科が同URLに無い］元の主張(established): ビズリーチ連携で客員起業家を公募・学内規程は未確認。神戸大学産官学連携本部、株式会社神戸大学イノベーション、株式会社ビズリーチが2023年11月30日に大学発スタートアップ創出を目的とする連携協定を締結（大学公式お知らせ2023年12月5日）。転職サイト上での人材募集により人材登用の仕組みを構築するもので、第1弾は理学研究科と農学研究科の研究シーズを事業化する経営者候補としての客員起業家（EIR）公募。ビズリーチ発表（2024年3月18日）は副業・兼業限定で応募276名から初採用と報告。客員起業家の委嘱を定めた学内規程は公開範囲では確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_cxo_pool', 'unknown', null, '［自動検証で否認: 経営者候補(EIR)公募の記述が同URLに無い］元の主張(established): ビズリーチ連携での経営者候補公募・常設の人材プールなし。上記3者連携協定の内容は、転職サイト上で人材を募集することによる神戸大学発スタートアップの人材登用の仕組みの構築で、経営者候補（EIR）の公募がその第1弾。案件ごとの公募方式であり、CEO・CXO候補をあらかじめ登録しておく人材プールや常設のマッチング窓口を定めた規程・公式ページは確認できなかった。学術・社会共創機構社会共創部門起業推進部が相談窓口。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_ip_equity', 'established', '実施許諾等の対価としての株式等取得を規則で明文化', '国立大学法人神戸大学株式等取扱規則第1条が「寄附及び知的財産のライセンス，施設・設備の提供，技術指導等の支援の対価等として取得する株式等」を対象と定義し、第11条で知的財産権の実施許諾等の対価として株式等を取得した場合の取扱いを定める。対象は株式、新株予約権、新株予約権付社債。知的財産取扱規程第21条は大学発ベンチャーへのライセンスについて実施料の延べ払い、減免等の優遇措置を定めるが、同規程には株式等での対価受領を直接定めた条文はない。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000839.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'pol_fund_investment', 'established', '関連会社KUCが大学ファンドを運営・大学自身の出資なし', '株式会社神戸大学キャピタル（KUC）が神戸大学の関連会社として大学ファンドを運営。大学公式お知らせ（2023年3月7日）はKUC1号投資事業有限責任組合（神戸大学ファンド）を2023年1月31日に20億円で設立した国立大学初の100％民間資本の大学ファンドと説明し、大学自身は出資せず金融機関6社が出資者。KUCサイトは2026年3月31日発表のKUC2号（総額60億円規模を目指す）を掲載。投資対象は神戸大学および神戸・関西地域の研究成果を活用するベンチャーと、卒業生が経営陣に参画するベンチャー。産業競争力強化法の認定特定研究成果活用支援事業者としての記載は確認できなかった。', 'official', 'https://www.kobe-u.ac.jp/ja/announcement/2023_03_07_01/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_regulation_owner', 'established', '大学規程・国立大学法人神戸大学が制定', '題名が「国立大学法人神戸大学における大学発ベンチャーの認定に関する規程」で、神戸大学規則集に収録される国立大学法人本体の規程。令和3年7月27日制定（同年8月1日施行）、令和8年7月28日最終改正。第3条第2項で学長が認定を決定し、第12条で事務は学術研究・社会共創推進部社会共創課が処理する。学校法人の規程ではない。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_review_body', 'established', '学術・社会共創機構イノベーションデザイン部会議', '認定規程第3条第2項で、学長は「神戸大学学術・社会共創機構社会共創部門及び共創事業部門イノベーションデザイン部会議」の議を経て認定を決定。同会議の議は更新（第6条第3項の準用）と取消（第10条第1項）にもかかる。事務は第12条により学術研究・社会共創推進部社会共創課。施設入居の可否は別に本学が設置する選考委員会が審査し、株式等の受入れは株式等受入審査会が審査する。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_equity_decider', 'established', '役員会の議を経て学長・受入審査会と評価会が事前審査', '国立大学法人神戸大学株式等取扱規則第10条第1項「株式等の受入れ，管理及び売却に係る決定は，役員会の議を経て，学長が行う」。第4条第2項の株式等受入審査会は学長が指名する理事、受入事務を所掌する事務局担当部署の部長及び課長等で組織。第7条第2項の株式等評価会は財務担当役、財務担当役が指名する財務部の課長等で組織し、外部専門家の意見を参考に評価額を決定。第8条第1項で共益権は原則として行使しない。第13条で事務は財務部財務戦略課。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000839.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_amendment_decider', 'unknown', null, '認定規程、株式等取扱規則、知的財産取扱規程のいずれにも「この規程の改廃は…」に当たる改廃手続条項が置かれておらず、附則にも改正を決裁した機関名の記載がない。知的財産取扱規程第31条は必要事項を機構長に委任する規定にとどまる。規則等の制定改廃手続を定めた規則も神戸大学規則集の検索範囲では確認できなかったため、改廃決裁者は特定できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_post_grad_limit', 'established', '規定なし・年限を置かず研究成果と関与で判断', '認定規程第2条は、第1号で本学が承継した特許に基づく起業又は本学で創出された研究成果もしくは習得した技術等に基づく起業、第2号で本学の教職員、学生等が設立者となり又は設立に深く関与して起業したもの、第3号で本学の支援により起業したもの又は学長が認めたものと定義し、卒業後・退職後の年数による限定を置いていない。神戸大学キャピタルの投資対象には卒業生が経営陣として参画するベンチャーも含まれる。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_renewal_rule', 'established', '更新可（審査あり）・満了3月前までに更新申請', '認定規程第6条第2項で、有効期間終了後も引き続き認定を受けようとする認定ベンチャーは満了する日の3月前までに更新の申請を行わなければならない。第3項で第3条第2項（イノベーションデザイン部会議の議を経た学長の認定）を更新に準用するため、届出のみでは足りず認定時と同じ審議を経る。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_naming', 'established', '大学発ベンチャー・称号は「神戸大学発ベンチャー」', '認定規程第1条で大学発ベンチャーを「神戸大学発ベンチャー」として認定すると定め、第5条で学長が別記様式2により称号を授与。規程の題名も「大学発ベンチャーの認定に関する規程」で、公式ページの一覧名も「神戸大学発ベンチャー一覧」。スタートアップの語は支援施策名（スタートアップ支援ページ、起業推進部）に使われるが、称号自体は大学発ベンチャーで統一されている。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_support_period', 'established', '支援ごとに別に定める・称号3年、施設は年度更新', '認定規程第11条第2項「前項各号に掲げる支援を行うときは，本学における関係規則等によるものとする」により、支援の期間は各支援の規則・要領へ委ねられる。称号の有効期間は第6条第1項で認定日から3年を経過する日の属する年度の8月末日まで。産官学連携本部棟の入居期間は原則1年度で委員会の議により年度毎更新。GAPファンド（うりぼーファンド）の助成期間は2026年4月から2027年3月末。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_support_contents', 'established', '施設貸与優遇・商業登記・他企業紹介・広報・ロゴ使用許可', '認定規程第11条第1項各号。第1号 事務室又は研究室として本学内の施設の貸与において優遇措置、第2号 貸与した施設を所在地とする商業登記を認めること、第3号 他企業への紹介又は他企業との共同研究等の仲介、第4号 本学主催のイベント・広報誌・ホームページ等による広報、第5号 本学のロゴマークの使用許可、第6号 その他学術・社会共創機構長が必要と認める支援。規程外の施策としてGAPファンド（うりぼーファンド）、起業部、関連会社の神戸大学キャピタルによる投資がある。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_77be07932123', 'attr_source_docs', 'established', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html・https://www.office.kobe-u.ac.jp/plan-rules/act/110000839.…', '第一は認定規程（神戸大学規則集 110000881）で、定義、認定手続、有効期間、称号の使用制限、報告義務、取消、支援内容までを一本で定める。第二は株式等取扱規則（同 110000839）で、株式等の受入れ・管理・売却の決裁と審査体制を定める。第三は学術・社会共創機構社会共創部門のスタートアップ支援ページで、認定ベンチャー一覧、GAPファンド、起業部、神戸大学キャピタルへの導線をまとめている。補助資料として知的財産取扱規程（110000225）、産官学連携本部棟入居者募集要領、うりぼーファンド応募要領。', 'official', 'https://www.office.kobe-u.ac.jp/plan-rules/act/110000881.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_cert_update', 'unknown', null, '「大学発ベンチャー」公式ページ、RIMIXの起業支援ページと立命館スタートアップマップ、GIC公式サイトを開いたが、認定・称号制度とその有効期間・更新審査・要件再確認の記載はない。参考として教職員の兼業承認の期間は学校法人立命館教職員兼業規程第7条で申請年度内とされ更新を妨げないが、これは個人の兼業承認であり企業に対する認定の更新ではない。', 'official', 'https://www.ritsumei.ac.jp/research/activities/activity/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_title_restriction', 'unknown', null, '認定・称号制度が確認できないため、称号の使用範囲や使用停止、品質保証・投資推奨・経営状態の保証と誤認させない旨の条項も不見当。大学名・校章・ロゴの使用条件を定めた文書も、確認した公式ページ（研究・産学官連携の大学発ベンチャー、RIMIX起業支援、GIC）には見当たらない。', 'official', 'https://www.ritsumei.ac.jp/research/activities/activity/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_cancellation', 'unknown', null, '称号の取消事由、称号返付、表示削除、営業利用停止を定めた文書は不見当。関連するのは立命館大学利益相反規程（2004年3月24日 規程第593号）第13条の勧告・命令で、利益相反委員会の改善指導に従わない場合や虚偽の申請・報告が発覚した場合を対象とするが、これは教職員の兼業等に対するもので企業の称号取消ではない。', 'official', 'https://www.ritsumei.ac.jp/research/member/file/007/090/090-p02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_report_change', 'unknown', null, '認定に伴う年次報告、代表者・所在地・資本構成の変更届、解散時報告を定めた文書は不見当。立命館大学利益相反規程第12条は報酬・知的財産権に係る収入・株式配当等の金銭的情報を年1回開示する義務を教職員に課すが、これは個人の開示であって企業側の報告義務ではない。', 'official', 'https://www.ritsumei.ac.jp/research/member/file/007/090/090-p02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_support_request', 'established', '認定によらず支援ごとの個別申込', '産学官連携の申請方法ページに、受託研究・共同研究、奨学寄附金、技術指導、委託分析、委託加工が個別制度として並び、技術指導・委託分析・委託加工はリサーチオフィスへの書式提出が必要と案内される。RIMIX側もサポーターズクラブや各プログラムに個別に申し込む構成。認定を条件に支援を一括で受ける仕組みは不見当で、施設利用や登記の申請書式と審査の有無は公開ページに記載がない。', 'official', 'https://www.ritsumei.ac.jp/research/collaboration2/application/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_facility_registration', 'established', 'GICのStartup Loungeが登記可能', 'グラスルーツ・イノベーションセンター（GIC）公式サイトの施設紹介で、2階Startup Loungeを「入居者が交流できる登記可能なラウンジ」、2階GIC Labを「シード期～アーリー期のスタートアップ向けのインキュベーション施設」と記載。プレオープン記事も個室ウェットラボ・共用分析機器のラボ・登記可能なラウンジという構成を記す。入居の申請手続、審査、利用料金は公開ページに記載がない。', 'official', 'https://gic.ritsumei.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_vc_connection', 'established', '地元銀行網への参画とVCマッチング支援', '学校法人立命館が内閣府へ提出した令和5年度地域中核大学イノベーション創出環境強化事業 構想調書に、地元銀行・信用金庫との連携による「しがぎん」ニュービジネス支援ネットワーク「野の花応援団」への参画とVCマッチング支援、滋賀県・草津市等の自治体との協定締結、Venture Café Tokyoと連携した地域イノベーション促進イベントが記載。事業化時にVC等からの投資マッチングを実施しファンドとの相乗効果を狙うとも明記。常設の紹介制度としての要項は不見当。', 'official', 'https://www8.cao.go.jp/cstp/daigaku/chosyo/chiiki_r5_ritsumeikan.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_eir', 'unknown', null, '内閣府提出の構想調書の全文、RIMIXの起業支援ページ、GIC公式サイトとニュース一覧を確認したが、客員起業家（EIR）・起業家メンター・起業家人材の招聘制度の記載はない。構想調書には京阪神アカデミア・コアリション加盟のもとで客員教員による研究シーズの事業化支援を実施したとあるが、これは教員の招聘であり客員起業家制度ではない。', 'official', 'https://www8.cao.go.jp/cstp/daigaku/chosyo/chiiki_r5_ritsumeikan.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_cxo_pool', 'unknown', null, '外部のCEO・CXO候補を紹介するプールの記載は不見当。構想調書は起業人材・経営人材・支援人材の「育成」と投資ファンドの組成を掲げ、学生ベンチャーコンテストも経営人材の育成と位置づける。RIMIXサポーターズクラブは卒業生有志による起業・経営相談と起業シーズプロジェクトへの人的リソース支援を掲げるが、経営人材のマッチング制度としては明示されていない。', 'official', 'https://r-rimix.com/startup/supporters/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_ip_equity', 'unknown', null, '立命館大学発明規程（1992年3月27日 規程第253号）の全条を確認したが、第13条の補償金は特許権の譲渡または実施許諾により学校法人立命館が収入を得た場合に費用を差し引いた残額を配分する金銭型で、株式・新株予約権を対価として取得する条文はない。立命館大学知的財産ポリシーのPDFは画像のみでテキストが取得できず、ライセンス対価の方針は未確認。', 'official', 'https://www.ritsumei.ac.jp/file.jsp?id=407726&f=.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'pol_fund_investment', 'established', '学園100%出資の立命館ソーシャルインパクトファンド', 'RIMIXのFUNDページに、学校法人立命館の100％出資で2020年4月に設置され、運用期間10年、運営をプラスソーシャルインベストメント株式会社が担う立命館ソーシャルインパクトファンドが示される。投資対象は社会課題をビジネスで解決しようとする（もしくは起業予定の）立命館学園の教職員・学生・卒業生で法人格は不問、投資方法は株式・新株予約権・社債等。内閣府提出の構想調書には外部投資家を入れ投資対象を学外へ広げる2号ファンドの組成検討も記載。', 'official', 'https://r-rimix.com/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_regulation_owner', 'unknown', null, '［自動検証で否認: 引用URLは利益相反規程のみ、兼業規程は未確認］元の主張(established): ハイブリッド。法人規程と大学規程が併存。認定規程は不見当。確認できた起業関連規程は、兼業が学校法人立命館教職員兼業規程（2020年9月9日 規程第1192号）で法人規程、発明が立命館大学発明規程（規程第253号）、利益相反が立命館大学利益相反規程（規程第593号）で大学規程。法人規程と大学規程が併存し、承認の実務は立命館大学利益相反委員会が担う構成になっている。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_review_body', 'unknown', null, '認定制度が不見当のため認定委員会・審査会は確認できない。起業に関わる審査主体として、立命館大学利益相反規程第3条により常任理事会のもとに立命館大学利益相反委員会が設置され、兼業申請手続とその承認、金銭的情報開示、利益相反の相談・助言を所掌する。産学官連携の窓口は学校法人立命館 産学連携推進本部とリサーチオフィス。', 'official', 'https://www.ritsumei.ac.jp/research/member/file/007/090/090-p02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_equity_decider', 'unknown', null, '大学が直接株式・新株予約権を取得・処分する規程は不見当。株式等の取得は学校法人立命館が100％出資する立命館ソーシャルインパクトファンドを通じて行われ、運営はプラスソーシャルインベストメント株式会社だが、投資の決定者、申請・審査の流れはFUNDページに記載がない。', 'official', 'https://r-rimix.com/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_amendment_decider', 'established', '常任理事会。発明規程は大学協議会が決定', '立命館大学発明規程第20条は「本規程の改廃は、常任理事会の議を経て大学協議会で行う」と定める。立命館大学利益相反規程第17条は「本規程の改廃は、利益相反委員会の議を経て、常任理事会で行う」。学校法人立命館教職員兼業規程第11条も常任理事会による改廃を定める。認定規程は不見当のため、起業に関わる現行規程での定めを記す。', 'official', 'https://www.ritsumei.ac.jp/file.jsp?id=407726&f=.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_post_grad_limit', 'unknown', null, '退職・卒業後の年限を定めた文書は不見当。RIMIXの起業支援ページは支援対象に立命館学園の在校生・卒業生・教職員を挙げ、立命館ソーシャルインパクトファンドの投資対象も教職員・学生・卒業生とするが、卒業や退職から何年以内という条件も、研究成果との関連性で判断する旨も示されていない。', 'official', 'https://r-rimix.com/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_renewal_rule', 'unknown', null, '認定制度が不見当のため更新の可否と方法も確認できない。参考として教職員の兼業承認は学校法人立命館教職員兼業規程第7条で申請年度内とされ、同条第2項が承認の更新を妨げないと定めるが（既存調査で全文確認済み）、企業に対する称号の更新ではない。今回のセッションでは同規程PDFを開いていないためURLは付さない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_naming', 'unknown', null, '称号を付与する制度が不見当のため、称号としての呼び方は確認できない。呼称の実態としては、大学公式の研究・産学官連携サイトが「大学発ベンチャー」の見出しを用い、GIC公式サイトとRIMIXは「大学発スタートアップの創出」を用いるなど、両方が使われている。', 'official', 'https://www.ritsumei.ac.jp/research/activities/activity/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_support_period', 'unknown', null, '称号制度が不見当のため、称号期間と支援期間を分ける定めも確認できない。個別の支援では、立命館ソーシャルインパクトファンドの運用期間が10年、構想調書のプロジェクト推進人材の大学雇用枠が最大5年と期間が異なり、支援全体に共通する期間規定は公開ページに見当たらない。', 'official', 'https://r-rimix.com/fund/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_support_contents', 'unknown', null, '［自動検証で否認: GIC/FUND等は本文でなく共通ナビのみ］元の主張(established): 起業相談・登記可能施設・共用機器・資金支援・ファンド投資。RIMIXの起業支援ページに、相談窓口、RIMIXサポーターズクラブ、freee起業ダンドリコーディネーター、GIC、OIC CONNÉCT、研究シーズ型ベンチャーの創出、FUNDが並ぶ。GICはコワーキングスペース、GIC Fab、共用のCommunal Lab、GIC Lab、登記可能なStartup Lounge。構想調書のグラスルーツ・イノベーションプログラムは入居料・人件費・知財取得経費等の資金支援と、実証実験・ビジネスモデル作成・起業方法・市場調査・資金調達・知財出願登録・試作外注の各支援を挙げる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_33f367188cf9', 'attr_source_docs', 'established', 'RIMIX起業支援・GIC公式・内閣府構想調書', '主要URLは https://r-rimix.com/startup/ ・ https://gic.ritsumei.ac.jp/ ・ https://www8.cao.go.jp/cstp/daigaku/chosyo/chiiki_r5_ritsumeikan.pdf の3本。1本目が支援メニューの入口、2本目が施設と登記、3本目が資金支援・VCマッチング・ファンド組成の根拠。規程本文は立命館大学発明規程と立命館大学利益相反規程のPDFで確認できる。', 'official', 'https://r-rimix.com/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_cert_update', 'not_started', '有効期間・更新審査の定めなし。取消しまで継続', '国立大学法人筑波大学における大学発ベンチャーの支援に関する規程（令和3年法人規程第35号）第1条から第10条まで、および大学発ベンチャーの支援に関する要項（令和3年6月24日国際産学連携本部長決定、令和5年12月26日改正）第1項から第8項までのPDF全文を取得して通読したが、認定の有効期間、更新、再認定、要件の再確認に関する条文は存在しない。称号は第8条の取消事由に該当するまで継続する構成。第7条第2項が法人から求めがあった場合の事業報告書・収支決算書の提出を課すにとどまり、期日を定めた定期の要件審査は置かれていない。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_title_restriction', 'established', 'ロゴ用途限定と品質非保証を明記、大学は損害免責', '支援規程第3条第4項が「法人は、大学発ベンチャーが『筑波大学発ベンチャー』と称したこと及び第2項の支援を受けたことによって生じた損失若しくは損害又は企業活動によって生じた損失若しくは損害について、いかなる責任も負わないものとする」と免責を定める。要項第7項はロゴ申請を称号授与企業に限り、申請した用途のみ使用可とする。認定ロゴのページは「認定ロゴは、筑波大学発ベンチャーの製品、商品、サービスの品質を証明するものではありません」と明記し、製品・商品・サービスおよびその広報・広告宣伝・販売促進の目的での使用を禁じる。投資推奨や経営状態の保証を否認する文言と、称号自体の使用停止規定はない。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/spin_offs/v-logo/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_cancellation', 'established', '取消事由4号と申出解除を規定、取消後処理の定めなし', '支援規程第8条（支援の決定の取消し）第1項が、(1)第4条に規定する要件を満たさなくなった場合、(2)法人の社会的信用を失墜させる行為を行った場合、(3)企業活動の実態がなくなった場合、(4)その他支援を継続することが適当でないと本部長が認めた場合に、本部長が支援の決定を取り消すことができると定める。第2項は、支援を受けている大学発ベンチャーから支援の解除に係る申出があった場合には取り消すものとする。規程と要項の全文を通読したが、取消後の称号記の返付、ウェブサイト掲載の削除、称号・ロゴの営業利用停止に関する条文は存在しない。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_report_change', 'established', '変更報告と解散等の報告を義務化、年次報告は求めに応じ', '支援規程第7条（報告等の義務）第1項が、第5条の申請の際に届け出た事項等について変更等があった場合に本部長へ報告する義務を課す。代表者、所在地、資本構成はいずれもこの届出事項の変更に含まれる。第2項は法人から求めがあった場合に事業報告書、収支決算書等を提出する義務を定めるもので、期日を定めた定期の年次報告ではない。第3項は代表者等または清算人に対し、会社法の解散、破産手続開始の決定、民事再生手続開始の決定、会社更生手続開始の決定、不正競争防止法第21条・第22条の罰則確定の5類型に該当した場合の速やかな報告を義務づける。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_support_request', 'established', '支援ごとに様式第1〜3号と公募応募で個別申請', '要項第4項が称号授与の申請様式を別記様式第1号と定める。第5項は支援内容(1)の公募事業について、当該事業で定められた応募書類の提出を求め、提出できるのは応募要件等を満たす大学発ベンチャーに限るとする。第6項は登記の住所とする支援について別記様式第2号による申請を求め、申請できるのは称号授与企業と、称号授与の申請を行っている企業又は者（同時申請を含む）に限る。第7項はロゴ使用について別記様式第3号による申請を求め、称号授与企業に限り申請した用途のみ使用できるとする。認定の可否とは別に、支援ごとに申請と審査が置かれている。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-youkou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_facility_registration', 'established', 'ILC棟等の貸与とその住所での登記承認、様式第2号で申請', '要項第3項(1)が本部の実施する公募事業における研究費の支援及び研究室等の研究場所の貸与を、(2)が前号により貸与した研究室等（スペースチャージを支払って使用している研究室等）又は使用を許可した研究室等の住所を大学発ベンチャーの登記の住所とすることを認めることを支援内容とする。申請は第6項により別記様式第2号。2026年度事業化促進プロジェクト募集要項は、産学リエゾン共同研究棟（ILC棟）と共同研究棟A内の部屋を貸与対象とし、起業済ベンチャー成長コースは施設部施設マネジメント課と賃貸契約を締結すると定める。施設利用と商業登記が一つの制度で接続している。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-youkou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_vc_connection', 'established', 'つばさplusのDemo Dayで金融機関等とマッチング', '筑波大学ベンチャー起業支援事業「つばさplus」の事業概要ページが、プログラムの最終段階として「Demo Day 活動の総仕上げ。プレゼン会にて、事業化促進機関（ベンチャーキャピタルなど金融機関）とマッチング。」と明記する。要項第3項(3)も経営、財務、人材、販路、知財等の相談に係る対応を支援内容とする。一方、支援規程と要項には、ベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介を制度として定めた条文はない。紹介導線は規程ではなく本部の事業プログラムの設計として置かれている。', 'official', 'https://tsubasa.sanrenhonbu.tsukuba.ac.jp/outline/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_eir', 'established', '客員起業家（EIR）を公募しシーズとマッチング', '国際産学連携本部が「【募集】EIR（客員起業家）の募集について（2026年度）」を公表し、スタートアップを目指す研究シーズの支援およびエコシステム構築のため、将来の経営者となりうる人材（EIR／客員起業家）の参画とチーム体制の構築を進めるとしている。募集は事業化シーズごとに行われ、条件合意事項の雛形が用意されている。2026年度事業化促進プロジェクト募集要項B.1(3)は、本学が提供する起業支援プログラムの一つとして⑤「経営チーム支援（EIR）」を列挙し、ベンチャー創業準備コースの応募要件に組み込む。規程・要項ではなく本部の事業として運営されている。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/eir_bosyuu2026-1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_cxo_pool', 'established', '経営者候補を外部人材紹介サービス経由で公募・選考', '「筑波大学発ベンチャー創業に向けた経営者候補人材マッチング支援事業（2026年度）」の学内公募ページが、技術シーズを基にベンチャー創業を計画している本学の教員に対し、将来起業した際の経営者候補となる客員起業家（EIR）とのマッチングを行うと定める。方式は、プロジェクト代表者の事業化シーズを外部の人材紹介サービスを介して公開し、その事業化シーズを基にした大学発ベンチャーを数年以内に起業することを視野に入れたEIRの探索及び採用を行うもので、大学が独自の人材プールを保有する形ではない。教員公募とEIR公募を時期を分けて実施する。JSTスタートアップ・エコシステム共創プログラムの採択事業。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/2026eir2/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得可、現金困難時限定', '国立大学法人筑波大学が大学発ベンチャーからライセンス等、研究経費等又は財産貸付の対価として取得する株式等の取扱いに関する規程（平成30年1月25日法人規程第8号、令和3年法人規程第34号改正）のPDF全文を確認。第2条(5)が株式等を株式及び新株予約権と定義し、(2)がライセンス等を知的財産権の譲渡及び提供並びに実施権の設定、実施許諾及び利用許諾とする。第3条は対価の全部又は一部を現金で支払うことが困難な場合に限り株式等を取得できるとする。第6条はライセンス等の対価として取得した株式等を売却し収入を得た場合の発明者等への補償金に知的財産規則第6条を準用する。対象は第2条(6)により支援決定済みの大学発ベンチャー。', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2018hkt08.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'pol_fund_investment', 'not_started', '認定VC・ファンドなし、支援内容の限定列挙に出資なし', '経済産業省「国立大学等によるVC等への出資」の認定状況一覧を確認したが、認定特定研究成果活用支援事業者および認定ファンドに筑波大学関係の法人・組合の記載はない。掲載は大阪大学・京都大学・東北大学・東京大学の各VCとファンド、TUAT1号、ビジョンインキュベイト、みらい創造二号、ちばグロースアカデミア、Hirosaki共創1号、イノベーション京都2026、Toyama Co-Accel。要項第3項は支援内容を5項目に限定列挙しており出資・投資は含まれず、規則集第1章にも出資に関する規程はない。ただし支援規程第2条(4)が「法人から出資があるもの」を出資ベンチャーの区分として定義しており、出資の可能性自体は排除されていない。', 'official', 'https://www.meti.go.jp/policy/innovation_corp/syusshi.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_regulation_owner', 'established', '大学規程。国立大学法人筑波大学の法人規程第35号', '国立大学法人筑波大学における大学発ベンチャーの支援に関する規程は、令和3年6月24日法人規程第35号として制定された国立大学法人の法人規程。第1条は国際産学連携本部規程（平成26年法人規程第46号）第21条の規定に基づくとし、第2条以下で法人を国立大学法人筑波大学と定義する。学校法人規程ではなく、国立大学法人が定める大学規程にあたる。下位の実施細則である大学発ベンチャーの支援に関する要項は、規程第10条に基づく国際産学連携本部長決定であり、規程と要項の2層構成をとる。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_review_body', 'established', '国際産学連携本部長。合議体なし、事務は産学連携企画課', '支援規程第6条第1項が「本部長は、前条の申請があったときは、第4条に規定する要件を踏まえ、支援の可否を決定するものとする」と定め、第2項で文書により通知する。第2条も国際産学連携本部の本部長が認めたものと規定。規程・要項の全文を通読したが、認定委員会その他の合議体は置かれていない。国際産学連携本部規程第7条の国際産学連携本部運営委員会は、基本的な方針及び本部の運営に関して重要な事項について学内の意見を聴くための組織であり、個別のベンチャー認定を審査する機関ではない。事務は支援規程第9条により産学連携部産学連携企画課が行う。本部長は本部規程第4条により産学連携を担当する副学長又は大学執行役員をもって充てる。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_equity_decider', 'established', '学長。国際産学連携本部が審査し本部長が学長へ報告', '平成30年法人規程第8号第4条第1項が「学長は、大学発ベンチャーから株式等による支払の申込みを受けた場合には、国際産学連携本部に当該株式等の取得に係る審査を付託するものとする」と定める。第2項で本部が大学発ベンチャーの財務状況その他株式等の取得の妥当性を判断するために必要な事項を踏まえて審査し、第3項で本部長が審査の結果を学長に報告する。第5条第1項が「学長は、前条第3項の規定により報告を受けた場合には、株式等の取得の可否を決定する」とし、第2項で契約書を取り交わして取得する。取得後の処分（売却）を誰が決裁するかを定めた条文はない。', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2018hkt08.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_amendment_decider', 'established', '学長。運営会議と役員会の議を経る。要項は本部長決定', '国立大学法人筑波大学の組織及び運営の基本に関する規則（平成16年法人規則第1号）第12条第1項(2)が、役員会の審議事項として「法人規則及び法人規程の制定又は改廃に関する事項」を掲げる。同規則第32条第4項は「学長は、法人規則、法人規程若しくは法人細則を定め、又は改廃しようとするときは、運営会議の議を経るものとする」と定める。ベンチャー支援規程は法人規程第35号であり、この経路で改廃される。下位の大学発ベンチャーの支援に関する要項は規程第10条に基づく国際産学連携本部長決定で、実際に令和4年2月22日と令和5年12月26日に本部長決定で改正されている。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.tsukuba.ac.jp/images/pdf/2004hks01.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_post_grad_limit', 'established', '期限なし。職員等ベンチャーに経過年数の制限なし', '支援規程第2条(6)は「法人の職員若しくは職員であった者又は筑波大学の卒業生若しくは修了生が起業したもの」と定めるのみで、退職・卒業からの経過年数の上限を置いていない。要項第2項(6)の職員等ベンチャーも同じ文言。年数要件が付くのは別の区分で、(2)共同研究ベンチャーが設立後5年以内に筑波大学と共同研究等を行ったもの、(3)技術移転ベンチャーが設立後5年以内に法人から技術移転等を受けたものと定める。いずれも企業の設立からの年数であり、退職・卒業からの年数ではない。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_renewal_rule', 'established', '規定なし。更新・再認定の条文が存在しない', '支援規程第1条から第10条まで、要項第1項から第8項までの全文を通読したが、認定の更新、再認定、有効期間の満了に関する条文は存在しない。称号は第8条の取消しがあるまで継続する構成で、更新の届出も更新審査も置かれていない。なお、研究場所の貸与については2026年度事業化促進プロジェクト募集要項が、貸与期間の終了後に1回に限る継続申請と、貸与期間中の実績評価を含む審査を定めるが、これは称号の更新ではなく施設貸与の継続手続であり、通算貸与期間は最大6年とされている。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_naming', 'established', '大学発ベンチャー。称号は「筑波大学発ベンチャー」', '支援規程第3条第1項「法人は、第6条第1項の規定により支援を決定した大学発ベンチャーに対し、『筑波大学発ベンチャー』の称号を授与する」。規程・要項とも用語は一貫して「大学発ベンチャー」であり、認定制度の条文に「スタートアップ」の語は使われていない。要項第8項は称号記を授与し、本部のウェブサイトにおいて当該大学発ベンチャーの企業名等を公表すると定める。付与されるロゴの名称も「筑波大学発ベンチャー認定ロゴ」で、公表一覧のページ名は「筑波大学発ベンチャーリスト」。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_support_period', 'established', '支援ごとに別に定める。研究場所は1〜3年、通算最大6年', '支援規程と要項には称号の期間を定めた条文がなく、期間は支援メニューごとに定まる構成。要項第3項(1)の公募事業について、2026年度事業化促進プロジェクト募集要項は研究場所の貸与期間を、産学共同研究コースと起業済ベンチャー成長コースで3年以内、ベンチャー創業準備コースで2年以内とし、継続申請は1回に限り、採択された場合の通算貸与期間は最大6年とする。経営者候補人材マッチング支援事業の支援期間は2026年12月1日から2027年8月31日までで、最大1年間の延長が可能とされている。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2026/06/proproject1705.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_support_contents', 'established', '研究費と研究場所貸与・学内住所登記・経営相談・講習会案内・ロゴ使用権', '要項第3項が支援規程第3条第2項の支援内容を5つに限定列挙する。(1)本部が実施する公募事業における研究費の支援及び研究室等の研究場所の貸与、(2)前号により貸与した研究室等又は使用を許可した研究室等の住所を大学発ベンチャーの登記の住所とすることを認めること、(3)経営、財務、人材、販路、知財等の相談に係る対応、(4)本部等が実施する大学発ベンチャーへの支援に関係する講習会、起業家向け教育講座等の案内、(5)「筑波大学発ベンチャー」認定ロゴを使用する権利の付与。第3条第1項の称号授与と称号記の授与はこれとは別に置かれる。', 'official', 'https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp-content/uploads/2024/01/venture-youkou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c4c7f7501f8', 'attr_source_docs', 'established', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf・https://www.sanrenhonbu.tsukuba.ac.jp/wp/wp…', '1本目が認定制度の根拠となる法人規程（令和3年法人規程第35号）、2本目が支援内容・申請様式・公表を定める実施細則の要項（国際産学連携本部長決定）、3本目がライセンス等の対価として株式・新株予約権を取得する場合の手続規程（平成30年法人規程第8号）。いずれもPDF全文を取得して通読した。補助資料として、国際産学連携本部の筑波大学発ベンチャーのページ、認定ロゴのページ、筑波大学発ベンチャーリスト、事業化促進プロジェクト募集要項、つばさplus事業概要、EIR募集ページがある。', 'official', 'https://www.tsukuba.ac.jp/about/disclosure-ho-kisoku/s-05/pdf/2021hkt35.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_cert_update', 'established', '認定期間5年、更新規定はなく再申請可', '認定規程第5条第2項「『群馬大学発ベンチャー』の称号は、5年間使用することができる。ただし、再申請することを妨げないものとする」。同条第3項は「前項に規定する認定期間中は、商標、商号、広告及び宣伝に使用することができる」とし、5年を認定期間と呼ぶ。更新審査・更新申請・要件再確認を定めた条文は置かれておらず、期間満了後は第3条の認定手続（機構会議の議を経て役員会が認定）を再度踏む再申請となる。期間中の要件維持は第7条の事業報告書等の毎年度提出と第9条の取消事由で担保する構造。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_title_restriction', 'established', '品質保証目的の使用禁止、大学は品質を保証せず', '認定規程第6条（使用の制限）「認定大学発ベンチャーは、自社の製品、サービス等の内容及び品質を保証するために『群馬大学発ベンチャー』の称号を使用してはならない」。第12条（法的責任）で称号使用は本学に何ら法的責任を生じさせないと定め、第13条（免責）第1項で製品・サービス等の内容及び品質を保証しない、第2項で称号の使用又は取消しにより認定ベンチャー又は第三者に損害が生じても賠償義務を負わないとする。使用可能範囲は第5条第3項の商標・商号・広告・宣伝で、投資推奨や資金調達での表示を名指しで制限する条項は置かれていない。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_cancellation', 'established', '取消4事由、称号記返付と認定事実の使用禁止', '認定規程第9条第1項で学長は研究・産学連携推進機構会議の議を経て認定及び称号授与を取り消すことができ、事由は(1)第2条の定義から著しく逸脱、(2)社会的信用を失墜する行為、(3)第7条第1項の事業報告書等の不提出又は同条第2項の報告があった場合、(4)本学の不名誉・不利益のおそれ等で名称保持が適当でないと認める場合の4号。第2項で代表者へ通知。第3項で「速やかに称号記を返付するものとし、当該取消しを受けた日以降、大学発ベンチャーとして認定を受けていた事実を事業に使用してはならない」。第8条は代表者からの解除申請書による解除・称号返付の申出で、学長はこれを認めるものとする。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_report_change', 'established', '事業報告書等を毎年提出、解散・合併等は報告義務', '認定規程第7条第1項で代表者は年度毎に適宜の様式により、自社で定めた決算日から3か月以内に事業報告書及び収支決算書を学長に提出しなければならない。第2項で会社法の解散、破産手続、民事再生手続、会社更生手続、不正競争防止法第21条の罰金刑確定のいずれかの適用を受けたときは、代表者又は清算人が速やかに学長へ報告。第3項で合併又は事業譲渡をするときは速やかに報告し事前の許可を得る。代表者・所在地・資本構成の変更届を定めた条文はない。施設貸与を受けた場合は第10条第2号により退去時に登記場所変更を示す書面の提出が必要。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_support_request', 'established', '施設利用は機構長へ別途申請、機構会議が承認', '認定規程第10条は「学長は…次の各号に掲げる支援を行うことができる」とするだけで、支援ごとの申請手続を規定していない。実際の受け皿である群馬大学研究・産学連携推進機構施設利用要項（平成29年2月1日制定、令和6年6月1日改正）第5で「施設を利用しようとする者は、本学教職員名による利用申請書を機構長に提出する」、第6で機構長は機構会議の議を経て承認の可否を決定し申請者に通知する、と認定とは別の個別申請・審査を置く。第7で申請内容の変更は速やかに届出、第8で機構長は毎年及び必要に応じ利用報告を求める。第9は虚偽記載・無断転貸等での利用中止。申請名義が本学教職員である点が実務上の制約。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_20/sec_2020/202710.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_facility_registration', 'established', '施設を有償貸与、その施設での商業登記を許可', '認定規程第10条第1号「本学が保有する施設及び設備等を有償で貸与すること」、第2号「貸与した施設について、当該認定大学発ベンチャーの所在地とする商業登記を認めること。この場合において、退去時に登記場所を変更したことを示す書面を本学に提出しなければならない」。登記できるのは大学から貸与を受けた施設に限られる。施設側の制度は機構施設利用要項で、第3の第13号が「本学の研究成果を基にした実用化研究及びベンチャー事業」を利用目的に、第4の第3号が「本学の研究成果の活用を目指す者」を利用資格に挙げ、同号目的の利用期間は5年以内（機構長が特に認めれば延長可）。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_vc_connection', 'established', '連携金融機関・自治体の起業相談窓口へ取次ぎ', '認定規程第10条第5号「本学職員等による相談業務への対応並びに他企業への紹介及び仲介を行うこと」。ベンチャー支援サイトの支援内容3本のうち1本が「起業相談窓口への連絡（金融機関や自治体）」で、本文は「群馬大学と連携している金融機関や自治体の起業相談の担当者にお繋ぎいたします」。同サイトのPARTNER欄に八十二銀行、山梨中央銀行、足利銀行、群馬銀行、東和銀行、埼玉りそな銀行、日本政策金融公庫、三菱UFJ銀行等の金融機関と長野県・群馬県・埼玉県・栃木県ほかの自治体を掲げるが、これはIJIEの参画機関一覧で、ベンチャーキャピタルは含まれていない。VCへの紹介導線を定めた学内規程・記載は確認できなかった。', 'official', 'https://startup.opric.gunma-u.ac.jp/content/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_eir', 'not_started', '規程・支援メニューにEIR制度なし', '群馬大学規則集の全リンク889件の規程名を機械的に走査し、「客員」「起業」「メンター」「インキュベ」を含む規程は0件だった。認定規程第10条・第11条の支援措置の列挙にも客員起業家・起業家メンター・起業家人材の招聘は含まれない。ベンチャー支援サイトの「支援内容」ページは支援メニューを産学連携・知的財産活用センターへの相談、大学が発行する広報媒体への掲載、起業相談窓口への連絡（金融機関や自治体）の3本に限定列挙しており、EIRに相当する項目はない。なお第10条第6号に「その他、学長が必要と認めること」の包括条項があるため、個別対応の余地までは否定されていない。', 'official', 'https://www.gunma-u.ac.jp/kisoku/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_cxo_pool', 'not_started', '経営人材の紹介制度なし、IJIEでの連携のみ', '認定規程第10条第5号の紹介・仲介は「他企業への紹介及び仲介」であり、経営人材の紹介ではない。規則集889件に経営人材プール・CXOマッチングを定めた規程はなく、ベンチャー支援サイトの支援内容3本にも含まれない。トップページのIJIE-GAPファンドプログラムの説明に「参画大学の研究者や学生が、事業化推進機関、経営者候補人材等と連携して実施する研究開発・実証試験等を支援する」とあるが、これは外部助成の実施体制要件であって、大学がCEO/CXO候補を保有・紹介する制度ではない。IJIE-GAPファンドプログラム2026募集要項も同様に連携を要件として記す。', 'official', 'https://startup.opric.gunma-u.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_ip_equity', 'established', '実施許諾等の対価を株式・新株予約権で受領可', '認定規程第11条第3号「譲渡、提供、設定及び許諾に関する契約において、その対価を、当該認定ベンチャーの株式又は新株予約権で受け取ること」。手続は大学発ベンチャー企業等から対価として取得する株式等取扱規程（令和6年8月1日制定）が定め、第1条で認定大学発ベンチャーからのライセンス供与等の対価に限定、第3条で(1)対価相当の現金を保有していない、(2)現金払により資金繰りに窮する、(3)現金払が経営に重要な影響を及ぼす、(4)その他審議を経て学長が認めた、のいずれかで株式等収納が可能。第11条で発明者への補償金は株式等を換金し収入を得た後に支払う。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061350.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'pol_fund_investment', 'not_started', '出資・ファンド規程なし、対価取得のみ', '群馬大学規則集の全リンク889件の規程名を走査し「出資」「ファンド」「投資」を含む規程は0件。保有する株式等の規程は2本のみで、いずれも出資ではない。株式等管理要領（令和3年2月3日制定）第1は固定資産管理規程第28条に基づく管理規定、株式等取扱規程第1条は認定大学発ベンチャーからライセンス供与等の対価として取得する株式等に限定する。経済産業省「国立大学等によるVC等への出資」の認定特定研究成果活用支援事業者一覧（大阪大学VC、京都大学イノベーションキャピタル、東北大学ベンチャーパートナーズ、東京大学協創プラットフォーム開発等）にも群馬大学および群馬大学系の法人・ファンドは含まれていない。', 'official', 'https://www.meti.go.jp/policy/innovation_corp/syusshi.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_regulation_owner', 'established', '大学規程（国立大学法人群馬大学の学内規程）', '正式名称は「国立大学法人群馬大学における大学発ベンチャーの認定及び支援に関する規程」で、群馬大学規則集の第6章（研究）に061340として収録された国立大学法人の学内規程。令和6年8月1日制定・施行。対の規程である「国立大学法人群馬大学大学発ベンチャー企業等から対価として取得する株式等取扱規程」（061350）も同章・同日施行。第17条で「この規程の改廃は、役員会の議を経て、学長が行う」と定め、学校法人や外部機関の規程ではないことが明確。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_review_body', 'established', '研究・産学連携推進機構会議の議を経て役員会', '認定規程第3条第1項で申請者は大学発ベンチャー認定申請書に必要書類を添えて学長に提出。第2項「学長は、前項の申請があったときは、研究・産学連携推進機構会議の議を経て、役員会にて認定を行い、その結果を文書により申請者に通知するものとする」。第3項で学長は審議に際し外部有識者に意見を求め、又は申請者への面接を行うことができる。取消しも第9条第1項で同じ機構会議の議を経る。事務は第15条により研究推進部産学連携推進課が処理する。株式等の取得については別途、株式等取扱規程第4条の審査委員会（委員長は研究・産学連携推進機構長）が審査する。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_equity_decider', 'established', '取得は学長、審査委員会が審査、売却は役員会の議', '株式等取扱規程第4条で審査委員会が取得の可否を審査する。委員は研究・産学連携推進機構長（委員長）、高度研究推進・支援部門長、産学連携・知的財産部門長・同副部門長、産学連携・知的財産活用センター長、財務部長、研究推進部長ほか。第4項で財務状況・事業計画等を踏まえ審査し、必要に応じ外部専門家の意見を活用できる。第5項で委員の3分の2以上の出席がなければ議決できない。第6項で委員長が学長へ報告し、第5条で学長が取得の可否を決定して契約を締結する。売却は第9条第1項で株式等管理要領第3により役員会の議を経て学長が決定。第10条でインサイダー取引防止責任者（学長が指名する理事又は副学長）を置く。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061350.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_amendment_decider', 'established', '役員会の議を経て学長', '認定規程第17条（規程の改廃）「この規程の改廃は、役員会の議を経て、学長が行う」。対の株式等取扱規程も第14条で同じく「役員会の議を経て、学長が行う」と定める。株式等管理要領には改廃条項が置かれていない。施設側の群馬大学研究・産学連携推進機構施設利用要項は第17で「この要項の改廃は、機構会議の議を経て、機構長が行う」とし、機構長決裁である点が学長決裁の認定規程と異なる。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_post_grad_limit', 'established', '3年以内', '認定規程第2条第3号「本学の教職員、学生等が発起人又は設立時に取締役相当となるなどして設立したもの（教職員、学生等が退職、卒業等の後に設立した場合については、退職、卒業等から設立までの期間が3年以内のものに限る。）」。3年の期限は第3号にのみ付され、第1号（教職員又は学生が所有する知的財産権に基づいて設立）、第2号（本学で達成された研究成果又は習得した技術を基に設立）、第4号（その他学長が特に必要と認めたもの）には期限の定めがない。第4条第5号で本学教職員であった者については在職中の所要の手続・許可が適正になされていることを申請条件とする。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_renewal_rule', 'established', '更新不可・再申請（5年後に再申請可）', '認定規程第5条第2項「『群馬大学発ベンチャー』の称号は、5年間使用することができる。ただし、再申請することを妨げないものとする」。更新申請、更新審査、期間延長を定めた条文はなく、継続には第3条の認定手続（申請書提出、研究・産学連携推進機構会議の議、役員会での認定）を改めて経る再申請による。附則第2項は施行前から活動している企業についても申請と承認を要し「承認日を遡及することはできない」と定めるため、認定の空白期間は遡って埋められない。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_naming', 'established', '大学発ベンチャー（称号「群馬大学発ベンチャー」）', '規程名は「国立大学法人群馬大学における大学発ベンチャーの認定及び支援に関する規程」で、第2条が「大学発ベンチャー」を定義。第5条第1項で学長は認定した大学発ベンチャーに称号記を交付し「群馬大学発ベンチャー」の称号を授与する。認定を受けたものは規程上「認定大学発ベンチャー」と呼ぶ。ベンチャー支援サイトの見出し・一覧ページは略称の「群大発ベンチャー」を用いるが、規程上の正式な称号は「群馬大学発ベンチャー」。スタートアップの語は規程本文には現れず、IJIE関連の記述で「大学発スタートアップ」「スタートアップ創出プログラム」として使われる。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_support_period', 'established', '支援ごとに別に定める（施設利用は5年以内）', '認定規程第5条第2項の称号使用期間は5年だが、第10条の各支援には期間の定めがなく、支援側の制度がそれぞれ期間を持つ。機構施設利用要項第5の3項は、第3の第13号（本学の研究成果を基にした実用化研究及びベンチャー事業）目的の利用期間を5年以内とし、ただし機構長が特に認めた場合は延長できるとする。第12号目的の利用は1年以内。共用機器は「研究設備・機器の共用化推進に関する規程」に基づく予約制で、期間ではなく利用単位で課金される。知的財産の優遇措置（第11条）は個別のライセンス契約の期間による。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_20/sec_2020/202710.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_support_contents', 'established', '施設有償貸与・商業登記・広報掲載・知財優遇・株式等対価・相談仲介・金融機関紹介', '認定規程第10条第1項が支援を6号で列挙する。(1)本学が保有する施設及び設備等を有償で貸与、(2)貸与した施設を所在地とする商業登記を認める、(3)本学の広報誌またはwebサイト等における広報、(4)知的財産権又は研究成果等の譲渡・提供・実施権の設定・実施許諾及び利用許諾に関する優遇措置、(5)本学職員等による相談業務への対応並びに他企業への紹介及び仲介、(6)その他、学長が必要と認めること。第11条が(4)の内容を独占的通常実施権の設定、対価の低額設定、対価を株式又は新株予約権で受け取ることの3号に限定。ベンチャー支援サイトの支援内容は産学連携・知的財産活用センターへの相談、広報媒体への掲載、金融機関や自治体の起業相談窓口への取次ぎの3本。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_75953cdd2d43', 'attr_source_docs', 'established', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf・https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061350.pdf・https:/…', '1本目が認定制度の正本である「国立大学法人群馬大学における大学発ベンチャーの認定及び支援に関する規程」（令和6年8月1日制定・施行、全17条＋附則2項）。2本目が同日施行の対「国立大学法人群馬大学大学発ベンチャー企業等から対価として取得する株式等取扱規程」（全14条）。3本目が研究・産学連携推進機構が運営するベンチャー支援サイトで、支援メニュー、認定企業一覧、IJIE-GAPファンドプログラムの公募情報を掲載。補助的には群馬大学研究・産学連携推進機構施設利用要項（chap_20/sec_2020/202710.pdf）と株式等管理要領（chap_03/033015.pdf）、規則集トップ（https://www.gunma-u.ac.jp/kisoku/）を併読する。', 'official', 'https://www.gunma-u.ac.jp/kisoku/pdf/chap_06/061340.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_cert_update', 'not_started', '規定なし（存続中有効・年次報告で継続確認）', '認定規程（令和2年規程第4号、令和2年1月9日施行）を全文確認。第5条第2項は称号を「原則として企業が存続する間使用することができる」と定め、認定期間・更新の可否・更新審査・要件の再確認に関する条項は全11条のいずれにも置かれていない。継続確認は更新審査ではなく、第6条第1項の年度毎の事業報告書及び収支決算書の提出（自社で定めた決算日から3か月以内、理事長宛）と、第8条の取消事由審査が担う。第8条第1項第3号は事業報告書等の未提出自体を取消事由とする。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_title_restriction', 'established', '存続中使用可・取消後は使用禁止・大学は免責', '認定規程第5条第1項で理事長が称号記（別記様式第2号）により「自治医科大学発ベンチャー」の称号を授与し、第2項で原則として企業が存続する間使用できると定める。第8条第3項は取消しを受けた者に称号記の速やかな返付を課し、取消日以降に大学発ベンチャーとして認定を受けていた事実を事業に使用することを禁じる。認定申請書（別記様式第1号）には、称号使用により当方若しくは第三者に損害又は不測の事態が生じた場合は当方で処理し大学及び関係者へ損害賠償請求を一切行わない旨の誓約がある。品質保証・投資推奨・経営状態の保証と誤認させない旨の条項は、規程・申請書のいずれにも置かれていない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_cancellation', 'established', '取消4事由・称号記返付・認定事実の使用禁止', '認定規程第8条第1項で理事長が推進委員会の議を経て認定及び称号授与を取り消せる事由を4号列挙。(1)事業活動が第2条の定義から著しく逸脱した場合、(2)社会的信用を失墜する行為を行った場合、(3)事業報告書等を提出しない場合又は第6条第2項の報告があった場合、(4)その他本学の不名誉となるおそれがあり称号保持が適当でないと認める場合。第2項で別記様式第4号により代表者へ通知。第3項は称号記の速やかな返付と、取消日以降に認定を受けていた事実を事業に使用することを禁じる。第7条は代表者からの認定解除・称号返付の申出（別記様式第3号）を認め、理事長はこれを認めるものとする。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_report_change', 'established', '年次事業報告書と解散等の報告義務あり', '認定規程第6条第1項で代表者は年度毎に適宜の様式により、自社で定めた決算日から3か月以内に事業報告書及び収支決算書を理事長へ提出しなければならない。第2項で会社法の解散、破産法の破産宣告、民事再生法の再生手続、会社更生法の更生手続、不正競争防止法違反により同法第21条の罰金刑が確定した場合は、代表者又は清算人が速やかに理事長へ報告する義務を負う。未提出は第8条第1項第3号の取消事由。代表者・所在地・資本構成の変更届に関する規定は全11条のいずれにも無い（これらは認定申請書の記載事項ではあるが、変更時の届出義務は定められていない）。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_support_request', 'established', 'あり（事務室は要望書と称号記を提出し二段審査）', '認定規程第9条第2項は「前項に規定する支援を行うときは、本学における関係規程等によるものとする」とし、認定とは別の手続を置く。「大学発ベンチャーへの事務室等の貸与について」2(2)によれば、事務室貸与を要望する者は貸与要望書（様式の定めなし）に別記様式第2号の称号記（称号授与手続中は認定申請書）を添付して研究支援課へ提出し、産学連携推進委員会の承認を得たうえで大学管理スペース検討部会長へ提出して貸与の可否を検討願う。承認時は要望者へ通知。研究室・研究設備の利用は同3(2)・4により共同研究契約の締結と研究実施場所の指定が条件。紹介仲介・広報に個別申請の定めは無い。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_facility_registration', 'established', '可（合同研究棟事務室・年78万円・3年更新可）', '認定規程第9条第1項第1号で事務室又は研究室として学内施設を貸与でき、第2号で「貸与した施設について、当該大学発ベンチャーの所在地とする商業登記を認めること」と明記。商業登記は施設貸与を受けることが前提。「大学発ベンチャーへの事務室等の貸与について」2(1)により、貸与場所は合同研究棟の個室事務室（1室26.49㎡）で不足時は学内空きスペースの利用を検討、料金は年間780,000円（30,000円/㎡×26㎡、平成22年10月20日学長決裁の学外オープンラボ料金を適用）、期間は3年間とし更新を認める。認定解除・称号返付の申出を理事長が認めた場合は貸与を中止する。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_vc_connection', 'established', 'IJIE経由でVC・地銀と接続（学内規程なし）', '学内規程には導線が無い。認定規程第9条第1項の支援は5号の限定列挙で、第4号は「オープンイノベーションセンター等による他企業への紹介又は仲介」にとどまり、VC・金融機関・自治体・外部支援機関への紹介は含まれない。一方、本学はJST大学発新産業創出基金事業のプラットフォームIJIE（Inland Japan Innovation Ecosystem）にSU創出共同機関として参画し、責任者は副学長。IJIE参画87機関には足利銀行・群馬銀行・八十二銀行・日本政策金融公庫等の金融機関と多数のVCが協力機関として名を連ね、事業化推進機関候補一覧にもVCが公開列挙されている。', 'official', 'https://ijie.jp/about/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_eir', 'unknown', null, '産学官連携トップページの規程等一覧（産学連携推進委員会設置規程・産学官連携ポリシー・秘密情報取扱規程）と、大学発ベンチャーページの規程等一覧（認定規程・株式等取扱規程・事務室等の貸与について）および認定申請書を確認したが、客員起業家・起業家メンター・起業家人材の招聘に該当する規程・ページは見つからなかった。参画するIJIEのトップページ、IJIEについて、スタートアップ創出プログラム、事業化推進機関候補の各ページにもEIRの記載は無い。制度が無いと明示した文書も確認できないため unknown とする。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_cxo_pool', 'established', 'IJIE経由で経営人材紹介（学内制度なし）', '学内には該当制度が無い。認定規程第9条第1項の支援5号に経営人材の紹介は含まれない。一方、参画するIJIEのIJIE-GAPファンドプログラムは「参画大学の研究者や学生が、事業化推進機関、経営者候補人材等と連携して実施する研究開発・実証試験等を支援する」と定義され、ステップ2では研究代表者に事業化推進機関が付く。公開されている事業化推進機関候補一覧には、経営チームの組成と経営人材の育成を掲げるBeyond Next Ventures、CxO人材探索を行うケイエスピー、CXO候補等150人超が登録する人材コミュニティを運営するSpireteが含まれる。', 'official', 'https://ijie.jp/institution/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で受領可', '「自治医科大学発ベンチャーから取得する株式等取扱規程」（令和5年規程第30号、令和5年4月1日施行、改正令和6年規程第29号）第3条「本学は、大学発ベンチャーから研究成果に係るライセンス供与等の対価の全部又は一部を、現金に代えて、株式等により取得することができる」。第2条で株式等＝株式及び新株予約権、ライセンス供与等＝知的財産権の譲渡及び提供又は実施権の設定・実施許諾・利用許諾、対象知財＝発明等取扱規程第2条第4号の権利及び成果有体物取扱規程第2条第1号の成果有体物と定義。第8条で経営に参加する権利は原則として行使しない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_04.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'pol_fund_investment', 'not_started', '規定なし（ライセンス対価の株式取得のみ）', '株式等取扱規程を全文確認。第1条の趣旨は「ライセンス供与等の対価として株式等を取得する場合の取扱い」に限定され、第3条も対価の全部又は一部を「現金に代えて」株式等により取得すると定める。現金出資、大学VCの設立、認定VC、LP出資、指定ファンド、大学出資会社に関する条項は全9条に無い。産学官連携トップページの規程等一覧（産学連携推進委員会設置規程・産学官連携ポリシー・秘密情報取扱規程）と大学発ベンチャーページの規程等一覧にも出資・ファンド関係の規程は掲載されていない。学校法人であり国立大学法人法の出資制度の対象外。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_04.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_regulation_owner', 'established', '学校法人規程（令和2年規程第4号・理事長認定）', '認定規程の題名は「学校法人自治医科大学における大学発ベンチャーの認定に関する規程」（令和2年規程第4号、令和2年1月9日施行）で、第1条は「学校法人自治医科大学（以下「本学」という。）における大学発ベンチャーの円滑かつ適正な支援を図るため」と定め、法人を主体とする。認定申請書の宛先も学校法人自治医科大学理事長で、認定・称号授与・取消しの決裁者はいずれも理事長（第3条・第5条・第8条）。ただし株式等取扱規程では決裁者が学長であり、認定は法人、株式等は大学という決裁の分かれ方をしている。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_review_body', 'established', '自治医科大学産学連携推進委員会（決定は理事長）', '認定規程第3条第2項で理事長は自治医科大学産学連携推進委員会の議を経て認定を決定し、第8条の取消しも同委員会の議を経る。同委員会は自治医科大学産学連携推進委員会設置規程（平成31年規程第28号、改正令和2年規程第3号・令和5年規程第29号・令和6年規程第29号）に基づき、第2条第8号で大学発ベンチャーに関すること、第9号で株式及び新株予約権の取得、第10号でその売却・権利行使・処分を審議事項とする。構成は副学長（委員長）、学長委嘱の医学部基礎系2名以上・臨床系2名以上・看護学部1名以上、総務部長、大学事務部長ほか。庶務は研究推進課、認定事務は研究支援課。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/index_kitei_01.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_equity_decider', 'established', '学長（産学連携推進委員会の審査を経て決定）', '株式等取扱規程第4条で、株式等による支払の申出があった場合に産学連携推進委員会へ取得の審査を付託し、委員会は財務状況・将来性その他の妥当性を踏まえて審査、委員長が学長へ報告する。第5条で学長が取得の可否を決定。第6条で新株予約権の権利行使・売却・変更・処分は委員会が審査し学長の承認を得たうえで対応し、取得後の管理は大学事務部研究推進課が行う。第7条で株式等の売却は委員会の審議を経て学長が決定する。委員会設置規程第9条は下部組織として株式等取得検討部会を置き、VC・株式等、法律、財務会計の識見者やオープンイノベーションセンタークリエイティブマネージャー等で構成する。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_04.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_amendment_decider', 'unknown', null, '認定規程（全11条＋附則）、株式等取扱規程（全9条＋附則）、産学連携推進委員会設置規程（全12条＋附則）のいずれにも、規程の制定改廃を決める主体を定めた条項が無い。株式等取扱規程第9条は「この規程に定めるもののほか、必要な事項については、理事長が別に定める」、委員会設置規程第12条は同様の事項を委員長が別に定めるとするが、いずれも改廃条項ではない。学校法人自治医科大学寄附行為（昭和47年2月5日制定、令和4年11月2日改正）も第39条で寄附行為自体の変更手続を定めるのみで、諸規程の制定改廃の明文が無く、第13条第2項が理事会は法人の業務を議決すると定めるにとどまる。', 'official', 'https://www.jichi.ac.jp/assets/pdf/gaiyo/kisoku/kifukoui.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_post_grad_limit', 'established', '3年以内（退職・卒業・修了から設立まで）', '認定規程第2条第2号「本学を退職、卒業又は修了（以下「退職等」という。）した者で、退職等から設立までの期間が3年以内の者が所有する知的財産権を基に設立したもの」。起算点は退職等の日、終期は会社の設立で、その間が3年以内であることを要する。なお第1号（本学又は教職員・学生が発明者である知的財産権を基に設立）と第3号（本学で達成された研究成果又は習得した技術等を基に設立し業務の遂行に寄与するもの）には年数要件が無い。認定申請書の代表者区分も職員（教職員であった者を含む）・学生（学生であった者を含む）・第三者から選択する。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_renewal_rule', 'established', '期限なし（企業存続中は称号使用可）', '認定規程第5条第2項「「自治医科大学発ベンチャー」の称号は、原則として企業が存続する間使用することができる」。認定の有効期間、更新の可否、更新時の審査・届出に関する条項は全11条に無い。認定が終わるのは、第7条により代表者からの認定解除・称号返付の申出を理事長が認めたとき、又は第8条により理事長が推進委員会の議を経て取り消したときに限られる。継続確認は第6条第1項の年度毎の事業報告書及び収支決算書の提出で行い、未提出は第8条第1項第3号の取消事由となる。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_naming', 'established', '大学発ベンチャー（称号は自治医科大学発ベンチャー）', '規程名は「学校法人自治医科大学における大学発ベンチャーの認定に関する規程」で、第5条により授与する称号は「自治医科大学発ベンチャー」。産学官連携サイトのページ名も「大学発ベンチャー」で、本文は「自治医科大学発ベンチャーとして認定を行っています」と記す。スタートアップの語は規程・申請書・当該ページのいずれにも使われていない。ただし本学が参画するIJIEはスタートアップ創出プラットフォームであり、外部プログラム側では大学発スタートアップの語が使われる。', 'official', 'https://www.jichi.ac.jp/kenkyushien/cooperation/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_support_period', 'established', '支援ごとに別に定める（事務室貸与は3年・更新可）', '称号の使用は認定規程第5条第2項により原則として企業が存続する間で、期限の定めがない。一方、支援の期間は支援ごとに別途定める建て付けで、同第9条第2項は「前項に規定する支援を行うときは、本学における関係規程等によるものとする」とする。「大学発ベンチャーへの事務室等の貸与について」2(1)③は事務室の貸与期間を3年間とし更新を認めるが、認定解除・称号返付の申出を理事長が認めた場合は貸与を中止する。研究室・研究設備の利用は同3(2)・4により共同研究契約の期間と研究実施場所の指定に従う。称号期間と支援期間は一致しない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_03.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_support_contents', 'established', '事務室貸与・商業登記・研究設備利用・他企業紹介仲介・広報', '認定規程第9条第1項が5号を限定列挙。(1)事務室又は研究室として本学内の施設を貸与すること、(2)貸与した施設について当該大学発ベンチャーの所在地とする商業登記を認めること、(3)研究設備等の利用を許可すること、(4)オープンイノベーションセンター等による他企業への紹介又は仲介を行うこと、(5)本学主催のイベント、広報誌又はホームページにおいて広報を行うこと。柱書で「本学の管理運営及び教育研究に支障のない範囲において」と制約する。大学発ベンチャーページ本文も学内施設の貸与・研究設備の利用・他企業への紹介仲介・広報を掲げる。資金支援・人材紹介・VC接続は列挙されていない。', 'official', 'https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation/venture/index_kitei_02.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_46957a06d459', 'attr_source_docs', 'established', 'https://www.jichi.ac.jp/kenkyushien/cooperation/venture.html・https://www.jichi.ac.jp/assets/pdf/kenkyushien/cooperation…', '1本目は産学官連携サイトの大学発ベンチャーページで、支援内容の概要、認定企業10社の実名・関係講座・事業内容、規程等3本と認定申請書へのリンク、窓口（研究推進課・知的財産管理係）を載せる制度の入口。2本目は認定規程本体（令和2年規程第4号）で、定義・認定手続・申請条件・称号・報告義務・解除取消・支援事業5号を定める。3本目は産学連携推進委員会設置規程（平成31年規程第28号）で、審議事項・構成・議決・株式等取得検討部会を定める。株式等の取扱いは同ページのindex_kitei_04.pdf、施設貸与の細目はindex_kitei_03.pdfが正本。', 'official', 'https://www.jichi.ac.jp/kenkyushien/cooperation/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_cert_update', 'established', '5年間・更新手続なし、再申請可', '称号授与内規（平成18年4月20日制定、令和4年3月28日改正・令和4年4月1日施行）第6条第2項「称号の有効期間は、授与した日から5年間とする。ただし、再申請を妨げない。」全9条を通読したが、期間満了時の更新申請・更新審査・要件再確認を定めた条文は置かれていない。期間満了後は第4条の様式1による申請と第5条の推進委員会審議をあらためて経る。株式等取扱規程第2条第4号が対象を「称号が有効期間中である企業」に限定するため、有効期間の維持が他の支援の前提になる。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_title_restriction', 'established', '称号授与による法的責任を負わない旨を明記、使用範囲の規定なし', '称号授与内規第6条第3項「大学は、前2項の称号を授与したことにより、法的責任を負うものではない」。称号が品質保証・投資推奨・経営状態の保証ではないことを免責の形で明示する条項がある。一方、称号の表示媒体・広告利用の範囲、使用停止命令、誤認表示の是正を定めた条文は全9条のいずれにも置かれていない。使用の終了は第8条の取消しと称号記の返付によって処理される構造。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_cancellation', 'established', '推進委員会審議を経て学長が取消し、称号記を返付', '称号授与内規第8条「学長は、称号を授与された者が社会的信用を失墜する行為を行った場合その他その称号を保持するのに適当でない場合には、推進委員会の審議を経て、称号の授与を取り消し、称号記を返付させる」。取消事由は社会的信用の失墜と保持不適当の包括条項の2つ。称号記の返付は定めるが、表示物の削除や営業利用の停止を求める条文はない。登記住所使用は別建てで、住所使用要項第8条が全学財務・施設委員会の審議を経た許可取消し、第9条が速やかな住所変更と住所使用終了届を定める。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_report_change', 'established', '登記住所許可法人に年次事業報告義務、称号側は規定なし', '住所使用要項（令和5年2月16日要項第1号）第7条「毎年度、決算日から3カ月以内に事業内容及び収支決算を学長に報告」、第9条で許可取消時の住所変更と住所使用終了届による届出を義務づける。学生起業支援基金（村上基金）貸与要項第9条も年1回の業務状況報告を課す。一方、称号授与内規には年次報告、代表者・所在地・資本構成の変更届、解散時報告を定めた条文がなく、第7条は大学職員が申請資格該当者を学長へ申し出る情報提供の規定にとどまる。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001355.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_support_request', 'established', '株式等・登記住所・施設使用ごとに別申請・別審査', '称号は支援を伴わず、支援ごとに独立した申請と審査を置く構造。株式等取扱規程第4条で代表者が学長へ申請し推進委員会が審査会を設置して可否と数量を審査、第6条で学長が承認・不承認を決定。住所使用要項第4条で登記申請予定日の1か月前までの申請、第5条で全学財務・施設委員会の審議を経て学長が許可。固定資産使用許可取扱要項第5条で長期使用は2か月前までの申請、日立地区は工学部長、阿見地区は農学部長、その他は学長が決裁。村上基金は選考委員会の審査を経て学長が決定。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001356.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_facility_registration', 'established', '施設使用が登記住所使用の前提条件、3キャンパスで登記可', '住所使用要項第3条は、教職員又は学生が設立・経営に深く関与し、かつ本学施設を使用する法人であることを申請資格とし、知的所有権の活用または研究成果・技術の活用に該当することを求める。第6条で水戸・日立・阿見の3キャンパス住所を登記可能住所に指定。施設側は固定資産使用許可取扱要項第3条第8号ウが「本学の研究成果を活用した事業（当該事業に係る創業の準備を含む。）を行う中小企業又は個人」を使用許可の範囲に含め、第6条で1事業年度ごとの許可、研究成果活用事業は5年を限度に更新できる。施設利用と商業登記が連結した制度。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001355.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_vc_connection', 'established', 'NEDO覚書でカタライザー派遣、VC・金融機関紹介は制度なし', '大学公式ニュース「茨城大学とNEDOが起業家支援・産学連携に関する覚書を締結」（2026年3月4日）に、研究者と企業のマッチング支援、セミナー・情報提供、起業支援経験者「NEDOカタライザー」の派遣による相談対応、支援人材育成事業への参加、イベント連携の5項目が示される。外部支援機関への接続はこの覚書が根拠。ベンチャーキャピタル・金融機関・自治体への紹介導線を定めた規程や公式ページの記載は確認できなかった。首都圏連携としてCIC Tokyoサテライトオフィスとサイエンスアイデアソンが挙げられている。', 'official', 'https://www.ibaraki.ac.jp/news/n/2026/03/04014570.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_eir', 'not_started', '制度なし、支援メニューに客員起業家の記載なし', '研究・産学官連携機構「企業・地域の方へ」の支援メニューは、技術相談・共同研究・受託研究・受託研究員制度・学術指導・寄附金・秘密保持契約・研究者情報総覧・公開特許・教員への兼業依頼・研究設備機器の利用と依頼分析・大学発ベンチャー・ポリシー規程集の限定列挙で、客員起業家（EIR）・起業家メンター・起業家人材の招聘の項目はない。「大学発ベンチャー」ページも称号の説明と根拠2規程へのリンクのみ。iRICのポリシー・規程集ページの産学官連携関係規程にもEIRの規程はない。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_cxo_pool', 'not_started', '制度なし、経営人材紹介・マッチングの記載なし', '研究・産学官連携機構「企業・地域の方へ」の支援メニュー13項目に、CEO/CXO候補などの経営人材の紹介・マッチングは含まれない。「大学発ベンチャー」ページにも記載がない。大学ニュース（2026年3月4日）が示すNEDO覚書の協力5項目も、研究者と企業のマッチング、セミナー、NEDOカタライザーによる相談対応、支援人材育成、イベント連携であり、認定ベンチャーへ経営人材を紹介する制度ではない。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_ip_equity', 'established', '知財の譲渡・実施許諾の対価に株式・新株予約権を取得可', '株式等取扱規程（令和5年2月22日規程第5号、令和8年6月25日改正・令和8年7月1日施行）第2条第3号で「株式等」を株式及び新株予約権と定義し、同条第6号の「収益を伴う事業」に「知的財産権の譲渡、実施許諾及び使用許諾」を明記。第3条で事業の有望性が高く現金支払の免除が企業成長に資することを取得基準とし、公序良俗違反・反社会的勢力関係・運営支障を取得禁止事由とする。第7条で学長が契約を締結して取得。知的財産ポリシー第6の2は、本学帰属の発明等を創出した教職員等が設立するベンチャーへ優先的に実施許諾又は譲渡を行うと定める。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001356.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'pol_fund_investment', 'not_started', '制度なし、株式等は事業対価取得のみで出資規程なし', 'iRICのポリシー・規程集ページが掲げる産学官連携・知的財産関係の規程は、知的財産ポリシー、利益相反ポリシー、利益相反マネジメント規程、職務発明規程、学生及び研究員等発明要項、研究ライセンス及びリサーチツール特許ライセンスポリシー、称号授与内規、株式等取扱規程で、大学VC・認定VC・投資事業有限責任組合へのLP出資・大学出資会社を定めた規程はない。株式等取扱規程第1条も「収益を伴う事業の対価として株式等を取得する場合」に適用範囲を限定しており、金銭出資やファンド組成の根拠にはならない。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_regulation_owner', 'established', '大学規程（国立大学法人茨城大学の内規・規程）', '称号授与内規は「国立大学法人茨城大学の研究成果等を活用したベンチャー企業への称号の授与に関する内規」、株式等取扱規程は「国立大学法人茨城大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程」で、いずれも国立大学法人茨城大学自身が制定主体。規則等の制定改廃に関する規則（平成27年3月26日規則第30号）第3条は、規則等の種類を学則・規則・規程・細則・要項の5種と定める。学校法人や別法人の規程を借りる形はとっていない。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000853.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_review_body', 'unknown', null, '［自動検証で否認: 細則第5条は委員任期規定、審査会規定ではない］元の主張(established): 茨城大学研究・産学官連携推進委員会（全学委員会）。茨城大学研究・産学官連携推進委員会細則（平成29年12月19日細則第33号）第1条で全学委員会の設置に関する規程第2条第2項に基づく委員会と位置づけ、第3条の審議事項は学術研究推進、研究環境整備、産学官連携推進など。第4条の構成は学術担当理事、各学野の研究担当副学野長等、研究・産学官連携機構長・副機構長、全学共同利用施設の長ほか。第6条で委員長は学術担当理事、第7条で3分の2以上の出席と出席委員の過半数で議決、第11条で庶務は研究推進部。ベンチャー認定専用の委員会ではなく全学委員会が兼ねる。株式等の審査は第5条に基づき本委員会が設置する審査会が行う。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_equity_decider', 'established', '学長（推進委員会が設置する審査会の審査を経て決定）', '株式等取扱規程第4条で代表者が申請書により学長へ申請し、学長が研究・産学官連携推進委員会に付議、同委員会が審査会を設置して取得の可否と数量を審査し結果を学長へ報告。第5条の審査会は研究・産学官連携機構長、研究推進部長、財務部長ほか学長の指名する者で構成し、外部専門家の意見を聴取できる。第6条で学長が承認・不承認を決定して通知、第7条で学長が契約を締結して取得。第8条は取得後の管理を株式等管理規程に基づく管理責任者に委ね、売却など処分の決裁は同管理規程側に置かれる（当該管理規程の本文は今回確認できず）。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110001356.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_amendment_decider', 'established', '学長（規程は役員会審議、細則・要項は学長決裁）', '規則等の制定改廃に関する規則第9条で「規程」は役員会の審議を経て学長が定める（必要に応じ教育研究評議会又は経営協議会へ諮問）、第10条で「細則」、第11条で「要項」は学長が決裁により定める（部局に関する事項は部局の長）、第8条で「規則」は教育研究評議会・経営協議会・役員会の審議を経て学長が定める。株式等取扱規程は規程のため役員会審議、住所使用要項と固定資産使用許可取扱要項は学長決裁。称号授与内規は第3条の5種類に含まれない旧形式で、直近改正は令和4年3月28日規則第5号として行われている。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000853.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_post_grad_limit', 'established', '1年以内（学生のみ、教職員の退職後は規定なし）', '称号授与内規第3条第3号は、大学の学生が設立又は設立に深く関与した場合を対象とし、学生の身分を失ったときから起業まで他の職に就かなかった者、および身分を失ったときから1年以内に起業した者を含めると定める。教職員の退職後何年以内という期限規定は置かれておらず、第1号（大学職員又は学生が所有する知的所有権の活用）と第2号（大学で達成された研究成果又は習得した技術等の活用）は在職・在籍の要件ではなく成果の由来で判定する構造。第4号に学長が認めた場合の受け皿がある。住所使用要項第3条も学生・教職員の身分喪失後1年以内を資格に含める。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_renewal_rule', 'established', '更新不可・再申請（5年満了後に改めて申請）', '称号授与内規第6条第2項は有効期間を授与日から5年間とし、ただし書で再申請を妨げないとする。更新申請の様式、更新審査、要件の再確認、期間伸長を定めた条文は全9条のいずれにも存在しない。再申請は第4条の様式1による学長への申請と第5条の推進委員会審議という新規申請と同じ経路をたどる。第8条により期間中でも社会的信用の失墜等があれば推進委員会の審議を経て学長が取り消し、称号記を返付させる。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_naming', 'established', '大学発ベンチャー（称号は「茨城大学発ベンチャー」）', '称号授与内規第2条で称号を「茨城大学発ベンチャー」と定め、第6条第1項で様式2の称号記を授与する。規程上の呼称は「ベンチャー企業」に統一されており、「スタートアップ」を称号として併記する規定はない。大学ニュースや研究・産学官連携機構のページでは「茨大発ベンチャー」「大学発スタートアップ」という語も使われるが、いずれも広報上の表現で、授与される称号自体は内規第2条の一本。', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_support_period', 'established', '支援ごとに別に定める（株式等のみ称号期間に連動）', '固定資産使用許可取扱要項第6条第1項は許可期間を1事業年度内とし、第2項で特別の事由があれば1年ごとに更新でき、研究成果活用事業（創業準備を含む）は5年を限度とする。住所使用要項は許可期間の年限を定めず、第7条の年次報告と第8条の取消しで継続を管理。村上基金貸与要項第4条は貸与の実施を3年以内とする。称号期間と連動するのは株式等取扱規程第2条第4号で、対象を称号が有効期間中の企業に限定する部分のみ。［検証エージェントは出典を開けず未照合］', 'official', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000133.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_support_contents', 'established', '技術相談・共同研究・受託研究・受託研究員制度・学術指導・寄附金・秘密保持契約・研究者情報総覧・公開特許・教員への兼業依頼・研究設備機器の共用利用と依頼分析・大学発ベンチャー称号', '研究・産学官連携機構「企業・地域の方へ」に列挙された支援メニューをそのまま採録（末尾のポリシー・規程集はメニューではなくリンク集のため除外）。規程側で追加される認定ベンチャー向けの実質支援は、固定資産使用許可取扱要項第3条第8号ウの創業準備を含む施設使用、住所使用要項第6条の3キャンパスでの本店登記、株式等取扱規程による現金対価の株式等への振替、知的財産ポリシー第6の2の優先的な実施許諾・譲渡、村上基金による学生向け無利子貸与。伴走支援・アクセラレーションのメニューはない。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_cbd79e6a149d', 'attr_source_docs', 'established', 'https://houki.admb.ibaraki.ac.jp/lc25/act/110000162.html・https://houki.admb.ibaraki.ac.jp/lc25/act/110001356.html・https…', '1本目が称号授与内規（認定要件・有効期間・取消し）、2本目が株式等取扱規程（対価としての株式・新株予約権の取得手続と決裁）、3本目が研究・産学官連携機構のポリシー・規程集ページで、知的財産ポリシー、利益相反ポリシー、利益相反マネジメント規程、職務発明規程、学生及び研究員等発明要項、研究ライセンス及びリサーチツール特許ライセンスポリシー、称号授与内規、株式等取扱規程への公式リンクを一覧できる。施設・登記の要項は規程集の要項欄（110001355、110000133）にある。', 'official', 'https://www.iric.ibaraki.ac.jp/for-companies/policy.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_cert_update', 'established', '有効期間3年、更新可、更新も新規と同一手続', '長崎大学における長崎大学発ベンチャーの称号授与に関する規程（令和4年3月28日規程第34号、令和8年3月31日規程第33号改正・令和8年4月1日施行）第4条第1項「称号の有効期間は、称号授与の日から3年間とする」「更新することができる」。同条第2項が更新手続に第3条を準用するため、更新時も学長への申請と長崎大学研究開発推進機構運営委員会の議を経る。要件の再確認は第8条第1項第1号（第2条各号の企業に該当しなくなったとき取消可）により有効期間中も継続して働く。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_title_restriction', 'established', '品質保証目的の使用禁止と学長による使用停止', '称号授与規程第7条第1項「当該企業の製品、サービス等の内容又は品質を保証するために称号を使用してはならない」、第2項「学長は、称号の使用が前項の規定に違反すると認めるときは、当該使用を停止させることができる」。第10条第1項は本学が成果の安全性、有効性等を担保するものではない旨、第2項は授与・取消等により損害が生じても本学は責を負わない旨を規定。投資推奨と誤認させない条項、経営状態の保証を否定する条項、使用範囲（媒体・表示方法）の具体的限定は規程本文にない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_cancellation', 'established', '取消事由4号、称号記返還・取消後の事業利用禁止', '称号授与規程第8条第1項が取消事由を4号列挙（第2条各号の企業に該当しなくなったとき、第6条第2項の報告があったとき、社会的信用を失墜する行為を行ったと認めるとき、その他称号の保持が適当でないと認めるとき）。第2項は「速やかに称号記を学長に返還」し「当該取消しを受けた日以後、称号を保持していた事実を当該企業の事業等に利用してはならない」と規定。第9条は学長が授与および取消しを学内外に公表するものとすると定める。既存表示物の削除期限や猶予期間の定めはない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_report_change', 'established', '変更・解散等の報告義務、事業報告は学長の求めに応じ提出', '称号授与規程第3条第3項が申請内容に変更が生じた場合の速やかな学長への報告を義務づける（代表者・所在地・資本構成を個別に列挙する条文はなく、申請内容の変更として包含）。第6条第1項は「学長の求めに応じて、事業報告書、収支決算書又はこれらに類する書類」の提出を求める形で、定期の年次報告義務ではない。第6条第2項は会社法の解散、破産手続、民事再生手続、会社更生手続、不正競争防止法第21条・第22条の罰則確定、その他法令違反による処分確定の6号について速やかな報告を義務づける。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_support_request', 'established', '称号と支援は分離、支援事項は規程外の別定めに委任', '称号授与規程第5条第1項は「本学の管理運営及び教育研究に支障のない範囲において、支援を行うことができる」と任意規定にとどめ、第2項が「支援に関し必要な事項は、別に定める」と委任する。したがって称号授与だけでは支援が発生せず、施設・機器・広報等は個別の申請と許可を要する構造。ただし委任先の支援要項は、長崎大学規則集（内容現在 令和8年8月1日）第5編「研究及び知的財産」の目次にも、研究開発推進機構の称号授与ページにも掲載がなく、申請様式・審査基準は公開情報で確認できない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_facility_registration', 'established', '機構施設の有償利用と起業向けブース、登記の定めなし', '大学公式ニュース「長崎大学にオープンイノベーション拠点『CROSS Nagasaki』が誕生」（2025年3月19日開所、文教キャンパス、内閣府 令和5年度地域中核大学イノベーション創出環境強化事業、総事業費約1億7800万円）が、1階のフリースペースと2階の産学官連携推進室・知的財産室・FFGアントレプレナーシップセンター入居、および大学発ベンチャー・スタートアップ向けの個別ブース設置を記載。同記事に入居条件と商業登記の可否の記載はない。称号授与規程にも本店所在地としての登記を認める条文はない。研究室・実験室の有償利用は研究開発推進機構研究室等利用規程による。', 'official', 'https://www.nagasaki-u.ac.jp/ja/news/news4590.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_vc_connection', 'unknown', null, '称号授与規程第5条は支援内容を「別に定める」に委任するのみで紹介導線を定めない。長崎大学研究開発推進機構規則（平成30年規則第31号）第3条・第8条はアントレプレナーシップセンターの業務をアントレプレナーシップ教育、アントレプレナー人材の育成に係る支援、ベンチャー支援、その他の4号とするにとどまり、ベンチャーキャピタル・金融機関・自治体への紹介に関する条文はない。大学公式の産学官連携協定一覧には金融機関4件（十八銀行、長崎銀行、ふくおかフィナンシャルグループ、日本政策金融公庫長崎支店）等の包括協定があるが、スタートアップ支援を目的とする協定の掲載はない。センター独自サイトはHTTP 401で閲覧できない。', 'official', 'https://www.nagasaki-u.ac.jp/ja/gakusai/sangaku/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_eir', 'unknown', null, '長崎大学研究開発推進機構規則（平成30年規則第31号）を確認したが、客員起業家（EIR）、起業家メンター、起業家人材の招聘を定めた条文はない。第14条に客員コーディネーターの制度はあるが、産学官連携のコーディネーターであり起業家の招聘制度ではない。長崎大学規則集第5編「研究及び知的財産」の目次にもEIR関連規程は存在しない。運用の有無を確認できる長崎大学研究開発推進機構FFGアントレプレナーシップセンターのサイト（www.nfec.nagasaki-u.ac.jp）はドメイン全体がHTTP 401 Unauthorizedで閲覧できず、Wayback Machineにも保存がない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000815.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_cxo_pool', 'unknown', null, '長崎大学研究開発推進機構規則第8条第2項が定めるアントレプレナーシップセンターの業務は、学生等へのアントレプレナーシップ教育、アントレプレナー人材の育成に係る支援、ベンチャー支援、その他目的達成に必要な事項の4号で、経営人材（CEO/CXO候補）の紹介・マッチングを定めた条文はない。同規則第8条第1項が置くベンチャー支援室と人材育成室にも人材プールの規定はない。長崎大学規則集第5編の目次にも該当規程はない。センターのサイトがHTTP 401で閲覧できないため、規程外の運用の有無は確認できていない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000815.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得可', '長崎大学における大学発ベンチャー企業への支援の対価として取得する株式等取扱規程（令和6年3月5日規程第6号）第3条が、本学の研究成果等に係るライセンス供与等の対価の全部又は一部を株式等により取得できると規定。第2条は株式等を株式及び新株予約権と定義。第6条は新株予約権の行使が可能となったときの速やかな行使と、行使前の有償譲渡を認める。第11条は職務発明規程に基づく補償金を、株式等を換金し収入を得た後に支払うと定める。なお長崎大学知的財産権の実施許諾及び譲渡に関する規程（平成16年規程第74号、平成30年7月1日施行）側には株式対価の条文はなく、第2条が非独占・独占・一部独占の許諾と有償又は無償の許諾を定めるのみ。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000955.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'pol_fund_investment', 'not_started', '大学からの出資・ファンド組成の規程なし', '長崎大学規則集（内容現在 令和8年8月1日）第5編「研究及び知的財産」の目次51件を通読したが、大学ベンチャーキャピタル、認定特定研究成果活用支援事業者、LP出資、指定ファンド、大学出資会社に関する規程は1件も存在しない。同編に置かれる資金関連規程は寄附金取扱規程、西遊基金規則、グローバルヘルス基金規程など受入側のみ。株式等取扱規程（令和6年規程第6号）も「支援の対価として取得する株式等」の取扱いに限られ、大学からの金銭出資を定めていない。GAPファンドはJST大学発新産業創出基金の採択プログラムPARKS経由で、長崎大学単独の基金規程ではない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_taikei/r_taikei_05.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_regulation_owner', 'established', '大学規程（国立大学法人長崎大学の規程第34号）', '称号制度の根拠は「長崎大学における長崎大学発ベンチャーの称号授与に関する規程」（令和4年3月28日規程第34号、令和4年4月1日施行。令和8年3月31日規程第33号改正、令和8年4月1日施行）。国立大学法人長崎大学の学内規程として長崎大学規則集第5編「研究及び知的財産」に収載されている。学校法人の寄附行為に基づく規程ではなく、大学単独の規程。関連する株式等取扱規程（令和6年規程第6号）、株式等取扱委員会規程（同）も同じ規則集の同編に置かれる。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_review_body', 'established', '長崎大学研究開発推進機構運営委員会', '称号授与規程第3条第2項「学長は…長崎大学研究開発推進機構運営委員会の議を経て、称号の授与の決定を行う」。運営委員会は長崎大学研究開発推進機構規則（平成30年規則第31号）第15条から第20条に組織と運営が定められ、委員は機構長、副機構長、機構長特別補佐、専任教員、首席リサーチ・アドミニストレーター等で構成し、機構の活動方針、管理運営、研究費支援、産学官連携事業等を審議する。称号授与専用の認定委員会は置かれていない。事務は称号授与規程第11条により研究推進部研究推進課が処理する。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_equity_decider', 'established', '学長決定（株式等取扱委員会と役員会の議を経る）', '株式等取扱規程（令和6年3月5日規程第6号）第5条「株式等の取得は、長崎大学株式等取扱委員会の議に付し、役員会の議を経て、学長が決定する」。委員会の組織は別途「長崎大学株式等取扱委員会規程」（令和6年規程、規則集第5編に収載）が定める。第7条が財務担当理事を株式等の管理責任者とし、第8条が経営参加権の原則不行使、第9条が原則として有価証券処分信託等による売却を規定するため、処分も同じ決裁系統の下にある。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000955.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_amendment_decider', 'unknown', null, '称号授与規程には改廃条項がなく、第12条の補則が「この規程に定めるもののほか、必要な事項は、別に定める」と記すのみ。長崎大学役員会規則第2条の審議事項5号（中期目標についての意見、文部科学大臣の認可・承認事項、予算の作成執行決算、重要な組織の設置廃止、その他役員会が定める重要事項）に規則等の制定改廃は含まれない。長崎大学教育研究評議会規則第2条第3号は「学則（経営に関する部分を除く。）その他の教育研究に係る重要な規則の制定又は改廃に関する事項」を審議事項とするが、規程レベルの改廃決裁者を明示する条文は国立大学法人長崎大学基本規則にも見当たらない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_post_grad_limit', 'established', '期限なし（在職・在学していた者を含む）', '称号授与規程第2条第3号が対象を「本学の教職員、学生等（在職又は在学していたものを含む。）が本学において習得した技術、知識等を活用して設立した企業」と定め、退職・卒業からの経過年数による制限を置いていない。第1号（本学又は教職員・学生が所有する知的財産権の活用）、第2号（本学で達成された研究成果の活用）にも年限の定めはなく、第4号は学長が特に必要と認めた企業を包括的に対象とする。ただし教職員による起業の場合は、同条ただし書により兼業規程その他の本学関係規則等に定める所要の手続と承認を要する。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_renewal_rule', 'established', '更新可（審査あり）、3年ごとに新規と同一手続', '称号授与規程第4条第1項が有効期間を称号授与の日から3年間とし更新可能と定め、第2項が「更新の手続については、第3条の規定を準用する」と規定。準用される第3条は、様式による学長への申請（第1項）、長崎大学研究開発推進機構運営委員会の議を経た学長の決定（第2項）、称号記の交付による授与（第4項）を定めるため、更新は届出ではなく新規と同じ審査を経る。申請様式（別記様式第1号）にも「新規／更新」の区分があり、更新申請ではこれまでの活動状況の説明を求める。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_naming', 'established', '大学発ベンチャー（「長崎大学発ベンチャー」）', '規程の正式名称が「長崎大学における長崎大学発ベンチャーの称号授与に関する規程」で、第1条が「長崎大学発ベンチャーの称号」と規定。研究開発推進機構の公式ページも「長崎大学発ベンチャー称号授与制度」と表記し、令和4年4月1日運用開始と記載。「大学発スタートアップ」の語は規程本文にも同ページにも現れず、併記もしていない。制度上の呼称は「認定」ではなく「称号授与」で、第3条第4項により称号記の交付をもって授与する。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_support_period', 'established', '支援ごとに別に定める（規程第5条第2項の委任）', '称号授与規程は第4条で称号の有効期間を3年と定める一方、第5条第1項の支援については期間を定めず、第2項で「支援に関し必要な事項は、別に定める」と委任している。したがって称号期間と支援期間は規程上分離されており、支援の期間は個別の定めに委ねられる。実際、研究開発推進機構研究室等利用規程は利用期間を当該事業年度内とし機構長が認めれば3年を限度に更新可と定めるなど、制度ごとに独自の期間を持つ。称号期間3年と連動させる条文は称号授与規程にない。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_support_contents', 'unknown', null, '称号授与規程第5条第1項は「本学の管理運営及び教育研究に支障のない範囲において、支援を行うことができる」と述べるのみで支援メニューを列挙せず、第2項が「別に定める」に委任する。研究開発推進機構の称号授与ページ（page_id=12487）も制度概要、資格要件、申請手続、規程と申請書様式の掲示にとどまり、施設利用・機器・広報・紹介等のメニュー、認定企業一覧、支援期間の記載がない。機構トップページの企業向け案内も産学官連携推進室、知的財産室、設備共同利用部門、アントレプレナーシップセンター、学術研究支援室の紹介にとどまる。センター独自サイトはHTTP 401で閲覧できない。', 'official', 'https://www.ciugc.nagasaki-u.ac.jp/?page_id=12487', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_515e2fa03507', 'attr_source_docs', 'established', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html・https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x…', '1本目は長崎大学における長崎大学発ベンチャーの称号授与に関する規程（令和4年規程第34号、令和8年4月1日改正施行）で、資格・手続・有効期間・支援・報告・使用制限・取消・公表・免責を一通り定める中心規程。2本目は大学発ベンチャー企業への支援の対価として取得する株式等取扱規程（令和6年規程第6号）で、ライセンス対価の株式等取得と決裁系統を定める。3本目は研究開発推進機構の称号授与ページで、運用開始時期と申請書様式の入手先を示す。いずれも長崎大学の公式サイトおよび長崎大学規則集で本文を確認した。', 'official', 'https://www1.g-reiki.net/nagasaki-u/reiki_honbun/x893RG00000914.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_cert_update', 'not_started', '有効期間・更新審査の規定なし、無期限保持', '称号授与規則（平成23年4月13日規則第2号、令和3年1月25日規則第39号改正）全12条を確認。認定期間、更新申請、更新審査、要件の再確認を定めた条項がない。称号の終了は第9条の返付申し出と第10条の学長による取消しだけで、期間満了という概念を置いていない。第8条は事業報告書及び財務諸表の提出を求めるが、更新の審査手続ではない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_title_restriction', 'established', '法的責任の否認条項あり、取消後は使用禁止', '称号授与規則第7条「称号の授与は、本学に法的責任を生じさせるものではない」。第10条第2項で取消後は「静岡大学発ベンチャーの称号の授与を受けていた事実を事業に使用してはならない」と定める。一方、品質保証・投資推奨・経営状態の保証と誤認させない旨を直接定めた条項や、称号の表示方法・使用範囲を限定する条項は同規則にない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_cancellation', 'established', '学長が取消し、称号記の返付と表示使用の禁止', '称号授与規則第10条第1項の取消事由は3つ。第2条の定義から著しく逸脱した場合、社会的信用を失墜する行為を行った場合、その他本学の不名誉となるおそれがあり保持させることが適当でないと学長が認める場合。第2項で速やかに称号記を返付し、取消日以後は称号授与を受けていた事実を事業に使用できない。第9条は代表者が機構長経由で学長へ返付を申し出る手続で、学長は申し出を認めるものとする。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_report_change', 'established', '事業報告書と財務諸表の提出義務、変更届の定めなし', '称号授与規則第8条「静岡大学発ベンチャーの代表者は、事業報告書及び財務諸表を機構長を経由して学長に提出しなければならない」。ただし本学が行う業務状況に関する説明の聴取に応じる場合は提出を要しない。提出頻度は条文に明記されていない。代表者・所在地・資本構成の変更届、解散時の報告に関する規定は同規則にない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_support_request', 'established', '施設入居は毎年度申請と入居審査、株式等は審査会', '称号とは別の申請・審査が2系統ある。インキュベーション施設は年度ごとの入居者募集で募集要項と施設利用申請書を提出し、利用期間1年、毎年度の入居審査結果により最長3年の継続利用（令和8年度入居者募集）。機構管理施設利用規則第4条は本学の役員又は教職員を代表者として利用申請書を機構長に提出し承認を受けると定める。株式等の取得は株式等取得に関する規則第3条のベンチャー企業株式等審査会が個別に審査する。', 'official', 'https://www.oisc.shizuoka.ac.jp/news/incubation2026/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_facility_registration', 'established', 'インキュベーション施設利用のみ、商業登記の定めなし', '浜松キャンパスの機構内にインキュベーションルームを設置。実験室タイプ40平米が9室、オフィスタイプ21平米が5室。使用料は無料で水道光熱費・通信費のみ実費負担、利用期間1年、入居審査により最長3年。入居資格は研究シーズを活用して自ら起業を検討する学内の教職員・学生、および地域の中小企業と共同で新事業を検討する教職員・学生。施設住所を本店所在地として商業登記できるかは、令和8年度入居者募集、機構のベンチャー支援ページ、機構管理施設利用規則のいずれにも記載がない。', 'official', 'https://www.oisc.shizuoka.ac.jp/inside/venture-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_vc_connection', 'established', '地域金融機関・政府系融資・自治体補助金へ接続', '機構の大学発ベンチャー支援ページに、コーディネータが支援機関や地域金融機関と連携して起業計画の立案をサポート、県・市等の補助金活用や政府系金融機関等の制度融資の活用等をサポート、ビジネスマッチングフェアへの出展とBtoBマッチング支援と記載。ベンチャーキャピタルの紹介・接続は同ページにもスタートアップ・エコシステム形成支援ページにも記載がない。', 'official', 'https://www.oisc.shizuoka.ac.jp/inside/venture-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_eir', 'not_started', '客員起業家・起業家メンター招聘制度なし', '機構の大学発ベンチャー支援ページの支援メニューはビジネスモデル立案の相談対応、インキュベーション施設、起業計画支援、資金計画支援、販路開拓の5項目で、スタートアップ・エコシステム形成支援ページは学生向け起業家人材育成プログラム、中高生向けプログラム、しずはま起業部、Tongaliイベント、コワーキングスペースを列挙する。いずれにも客員起業家（EIR）や起業家メンターの招聘はない。規則集の産学連携支援課分野24件の規程一覧にも該当規程がない。', 'official', 'https://www.oisc.shizuoka.ac.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_cxo_pool', 'established', 'Tongali採択者にCxO候補マッチング、学内独自プールなし', '静岡大学は名古屋大学を中心とする東海地区プラットフォームTongaliのGAPファンドプログラム（令和8年度ステップ1）の対象16機関に含まれる。同プログラムの支援内容に経営者候補人材（CxO）とのマッチング機会とメンタリングプール活用支援が明記されている。対象は採択された研究代表者に限られ、静岡大学単独の経営人材プール・紹介制度は機構の支援ページと規則集の規程一覧に記載がない。', 'official', 'https://tongali.net/x/gapfund2026-step1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_ip_equity', 'established', '知財ライセンスの対価として株式・新株予約権を取得可', '国立大学法人静岡大学における大学発ベンチャー企業支援を目的とした株式等取得に関する規則（令和元年11月27日規則第22号）第1条で対象を称号授与企業に限定し、第2条で株式等取得の対価を知的財産権のライセンス、大学施設・設備の使用許可、技術相談業務・技術顧問業務・経営指導その他コンサルティング業務と定める。第3条・第4条で審査会が妥当と判断し学長の承認を得て取得する。職務発明規則には株式・新株予約権の規定はなく金銭のライセンス補償金のみで、株式対価の経路はこの規則が担う。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000670.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_fund_investment', 'not_started', '出資・ファンド組成の規程なし、株式等取得のみ', '規則集の産学連携支援課分野に収録された24件の規程一覧に、出資、ファンド組成、投資事業有限責任組合、ベンチャーキャピタルに関する規程がない。大学発ベンチャー関連は株式等取得に関する規則のみで、同規則第2条の対価も知財ライセンス・施設設備の使用許可・コンサルティング業務に限られ、現金出資の枠組みを置いていない。機構のベンチャー支援ページとスタートアップ支援ページにもファンドへの出資・投資の記載がない。なお経済産業省の認定VC一覧ページは応答が拒否され開けていない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/aggregate/field/result/field20.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_regulation_owner', 'established', '大学規程（静岡大学規則第2号として制定）', '称号授与規則は「静岡大学における静岡大学発ベンチャーの称号授与に関する規則」（平成23年4月13日規則第2号、令和3年1月25日規則第39号改正）として静岡大学規則集の第2編第22章（イノベーション社会連携推進機構）に収録された学内規則。株式等取得に関する規則は「国立大学法人静岡大学における大学発ベンチャー企業支援を目的とした株式等取得に関する規則」で法人名義。学校法人規程や外部団体の規程ではない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_review_body', 'established', '審査委員会（機構産学連携推進部門、委員長は機構長）', '称号授与規則第4条。審査委員会はイノベーション社会連携推進機構の産学連携推進部門に置き、委員は(1)機構長(2)機構産学連携推進部門長(3)機構社会連携機構会議の委員のうち機構長が指名した者若干人(4)その他機構長が指名する者若干人で組織し、委員長は機構長をもって充てる。第5条で申請は機構長を経由して学長へ行い、学長が審査委員会に審査を付議し、その結果を踏まえ授与を決定する。第11条で事務は学術情報部産学連携支援課が処理する。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_equity_decider', 'established', 'ベンチャー企業株式等審査会の判断と学長の承認', '株式等取得に関する規則第3条・第4条。審査会が株式等の取得を妥当と判断した場合、学長の承認を得た上で取得する。第3条第2項の審査会構成は学長が指名する理事（議長）、イノベーション社会連携推進機構長、学長が指名する副学長、財務施設部長、学術情報部長、株式等やベンチャー経営に高い識見を有する外部委員等。第8条第2項で売却も審査会の審査と学長の承認を要する。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000670.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_amendment_decider', 'unknown', null, '称号授与規則に改廃条項がなく、第12条は「この規則に定めるもののほか…必要な事項は別に定める」とするのみ。国立大学法人静岡大学役員会規則第3条の審議事項は中期目標への意見、文部科学大臣の認可承認事項、予算決算、重要な組織の設置廃止、その他役員会が定める重要事項の5号で、規則の制定改廃を明示していない。株式等取得に関する規則第10条は補則として必要事項を審査会の議を経て学長が定めるとする。制定改廃手続を定める規程は産学連携支援課分野の規程一覧に収録されていない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000004.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_post_grad_limit', 'established', '5年以内（退職・卒業等から会社設立まで）', '称号授与規則第2条第1号。教職員・学生が設立又は設立に深く関与して起業した企業を対象とし、教職員の退職又は学生の卒業等から会社設立までが5年以内であれば同様に扱う。第2号以下では本学又は本学教員が所有する知的財産・研究成果・ノウハウを基に起業した企業、本学から技術移転を受けた企業、共同研究を基に新事業を興した企業、大学独自の資金・人材供給システムを活用した企業も対象とする。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_renewal_rule', 'established', '期限なし（更新規定なし、返付と取消のみ）', '称号授与規則には有効期間も更新手続もない。第9条で代表者が機構長経由で学長へ返付を申し出ることができ、学長は申し出を認めるものとする。第10条で学長が取消しを行う。更新申請、再申請、要件の定期再確認に相当する条項は全12条のいずれにもない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_naming', 'established', '大学発ベンチャー（称号は「静岡大学発ベンチャー」）', '称号授与規則第6条で、学長は称号記により「静岡大学発ベンチャー」の称号を授与する。規則名、機構の学内向け支援ページ、企業紹介ページのいずれも「静岡大学発ベンチャー」で統一され、「大学発スタートアップ」との併記はない。別制度として「静岡大学認定商品」の称号授与に関する規程が規則集にあるが、これは商品を対象とする別の称号。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_support_period', 'established', '支援ごとに別に定める（称号は無期限）', '称号は有効期間の定めがなく返付・取消まで継続する。インキュベーション施設は利用期間1年で毎年度の入居審査により最長3年（令和8年度入居者募集）。機構管理施設利用規則第5条は「施設を利用することができる期間は、機構長が適当と認めた期間とする」と定める。Tongali GAPファンドは公募年度単位。称号の期間と支援の期間を一致させる規定は置かれていない。', 'official', 'https://www.oisc.shizuoka.ac.jp/news/incubation2026/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_support_contents', 'established', '施設無料貸与・起業計画相談・補助金/融資支援・販路開拓・起業家育成', '機構の大学発ベンチャー支援ページはビジネスモデル立案に関する相談対応、インキュベーション施設（実験室タイプ9室・オフィスタイプ5室、使用料無料）、コーディネータが支援機関・地域金融機関と連携する起業計画支援、県・市等の補助金や政府系金融機関等の制度融資の活用サポート、ビジネスマッチングフェア出展とBtoBマッチングを列挙する。スタートアップ・エコシステム形成支援ページは大学生向け起業家人材育成プログラム、中高生向けプログラム、しずはま起業部、Tongaliイベント、コワーキングスペースを掲げる。', 'official', 'https://www.oisc.shizuoka.ac.jp/inside/venture-support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'attr_source_docs', 'established', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html・https://reiki.adb.shizuoka.ac.jp/act/110000670.html・https://www.ois…', '1本目は称号授与規則で、対象範囲・審査委員会・授与手続・事業報告・返付・取消しまでを収録。2本目は大学発ベンチャー企業支援を目的とした株式等取得に関する規則で、対価の種類、審査会の構成、学長承認、売却手続を収録。3本目は機構の大学発ベンチャー支援ページで、施設、支援メニュー、費用負担の現行運用を確認できる。規程の全体像は規則集の産学連携支援課分野の一覧で追える。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000279.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_96888e99eb1a', 'pol_ip_license', 'established', '発明者へ優先的独占許諾、機構が技術移転を実施', '静岡大学職務発明規則（平成16年3月17日規則第387号、令和2年3月18日規則第224号改正）第8条で、機構が機関帰属とした知的財産権の実施、譲渡等の技術移転を行う。第16条第1項は、発明者等が知的財産権を教職員の研究成果等を基に起業する又は起業したベンチャーに活用する場合、発明者等に対し優先的に独占的な通常実施権又は専用実施権を与えると定める。同規則に株式・新株予約権の規定はなく現金のライセンス補償金のみで、株式等を対価とする経路は株式等取得に関する規則第2条が定める。実施料の減免規定は同規則に見当たらない。', 'official', 'https://reiki.adb.shizuoka.ac.jp/act/110000024.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_cert_update', 'established', '有効期間3年、以後2年ごと更新、更新時も研究企画会議の審査', '称号授与規程第5条第2項「称号の有効期間は，授与した日から3年間とし，以後，2年ごとに更新することができる」。第3項で更新しようとする法人は学長に申請しなければならず、当該申請及び選考は第3条（称号申請書により研究担当理事を経て学長に申請）及び第4条（学長が研究企画会議の議を経て可否を決定）を準用するため、更新時も新規と同じ審査を経る。第8条第1項第7号は第2条の要件に該当しなくなった場合を取消事由とし、要件の再確認が取消手続を通じて働く。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_title_restriction', 'established', '品質を保証しない免責条項、取消後は称号の使用禁止', '称号授与規程第9条（免責）第1項「本学は，認定ベンチャーの製品，サービス等の内容及び品質を保証しない」。第2項は称号の授与又は授与の取消しにより認定ベンチャー又は第三者に損害が生じても本学は賠償義務を負わないと定める。第8条第2項は、取消しを受けた法人は速やかに称号記を返付し、取消しを受けた日以後、称号を授与されていた事実を事業に使用してはならないと定める。投資推奨や経営状態の保証を個別に否定する条項は置かれていない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_cancellation', 'established', '取消事由11号、称号記返付と称号使用の禁止', '称号授与規程第8条第1項は、学長が研究企画会議の議を経て取り消せる事由として、解散・合併・会社分割・株式交換・株式移転・事業譲渡（第1号）、破産宣告（第2号）、民事再生手続（第3号）、会社更生手続（第4号）、不正競争防止法の刑罰確定（第5号）、公序良俗違反・法令違反・社会的信用の失墜（第6号）、第2条の要件不該当（第7号）、支援の取消しの申出（第8号）、事業活動の実態の消滅（第9号）、事業報告等から存続が危惧される場合（第10号）、その他支援が適当でない場合（第11号）の11号を列挙。第2項で称号記の返付と、取消日以後の称号の事業利用の禁止を定める。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_report_change', 'established', '毎年度の事業報告書・財務諸表提出、変更届の定めなし', '称号授与規程第7条第1項「認定ベンチャーは，毎年度，事業報告書及び財務諸表を当該年度分が確定し次第，速やかに学長に提出しなければならない」。第2項で、本学から知的財産権を譲渡され実施許諾を受けていない認定ベンチャーは毎年度その活用状況を報告する。代表者・所在地・資本構成の変更届と解散時の報告義務を定める条文は無く、解散・合併・事業譲渡等は第8条第1項第1号の取消事由として扱われる。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_support_request', 'established', '称号申請時と年次報告時に希望支援を学長へ申出', '認定ベンチャー支援にかかる取扱要領第3条「認定ベンチャーは，規程第3条に規定する申請時及び規程第7条に規定する事業報告等の提出時に，前条各号のうちから本学に希望する支援を学長へ申し出ることができる」。支援ごとに独立した審査会は置かれず、要領第2条柱書が「本学の教育・研究及び管理運営に支障のない範囲で」支援を行えると定める。施設はVBLの使用申請、共用機器は設備共同利用推進総合システムの予約という別系統の手続による。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_facility_registration', 'established', 'VBL入居可、VBL工房の有償使用者はVBL住所で登記可', 'VBLベンチャー企業等使用取扱要領第2条で研究室等の個室又はVBL工房の使用を申請し、第4条で使用期間は原則3年以内・最大5年以内。VBLのQ&A（2023年2月20日付）は、VBL工房を月2,000円で使用して得られる権利を問う設問に「ＶＢＬの住所で登記可能になります」と回答し、事務室前のメールボックスで郵便物を大学で受け取れるとする。同Q&Aは個室使用料の起算を企業の「登記」から3年間と説明する。無償の学生サークル使用では登記できず、教員の推薦を要する。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl2/vbl/update/QandA-240206.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_head_office_registration', 'established', 'VBL工房の有償使用でVBL住所での登記が可能', '従前は根拠不明としていたが、VBLのQ&A（2023年2月20日付）に明記を確認。VBL工房を月2,000円で使用した場合に得られる権利を問う設問に対し「ＶＢＬの住所で登記可能になります」と回答し、あわせて事務室前のメールボックスで郵便物を大学で受け取れるとする。同Q&Aは個室の使用料単価を企業の「登記」から3年間が1平方メートル当たり月300円、4年目以降が月1,000円と説明し、登記を起算点として扱う。無償の学生サークル使用では登記できない。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/about/vbl2/vbl/update/QandA-240206.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_vc_connection', 'established', 'VC・ファンドレイジングページで公的機関と政策金融を紹介', '機構の「VC／ファンドレイジング」ページがJSTのSCORE・START・SUCCESS、NEDOの研究開発型スタートアップ支援事業、AMEDのViCLE、中小機構ファンド出資、日本政策金融公庫の創業支援を紹介し、学内支援制度は「準備中」と表示する。「事業化支援」ページは石川県産業創出支援機構、中小機構、NEDOを外部支援機関として挙げ、ワンストップ窓口への問い合わせを案内する。制度上の根拠は認定ベンチャー支援にかかる取扱要領第2条第6号「本学が協定を締結する機関への斡旋・紹介」。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/venture/vc.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_eir', 'not_started', '客員起業家の招聘制度なし', '認定ベンチャー支援にかかる取扱要領第2条は支援を第1号から第9号まで具体的に列挙し第10号を学長が必要と認める支援とするが、客員起業家や起業家メンターの招聘は含まれない。機構の大学発ベンチャー・事業化支援ページ、VC／ファンドレイジングページ、事業化支援ページ、TeSHのプログラムページとハブページにも招聘制度の記載が無い。起業支援の助言役はVBLコーディネーターに関する取扱要領第2条が定める学内のコーディネーターであり、外部起業家を招く制度ではない。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_cxo_pool', 'unknown', null, '認定ベンチャー支援にかかる取扱要領第2条の支援メニューに経営人材の紹介・マッチングは無く、同条第7号は「本学が協定を締結する機関とタイアップした経営指導・支援」にとどまる。機構の事業化支援ページはビジネスモデル相談と財務・経営相談をいずれも「準備中」と表示する。検索結果にTeSH関連の経営人材（CxO）マッチングイベントの告知が外部の転職情報サイトで出たが、金沢大学とTeSHの公式ページでは人材プールや紹介制度の有無を確認できなかった。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/venture/biz.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_ip_equity', 'established', '知財の実施許諾等の対価として株式・新株予約権を取得可', '株式等取扱規程（令和4年1月21日規程第3677号）第2条第3号アが「収益を伴う事業」に知的財産権の譲渡・提供・実施権の設定・許諾を含め、同条第4号が株式等を株式及び新株予約権と定義する。第3条で当該事業の対価として株式等を取得でき、第4条で研究企画会議が審査、第5条で学長が可否を決定する。第7条で経営参加権は原則として行使せず、例外的かつ緊急避難的な場合に限り行使する。第8条で発明者への補償金は株式等を換金し収入を得た後に支払う。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000873.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'pol_fund_investment', 'established', '大学100%出資VCビジョンインキュベイトと認定ファンド', '本学ニュースによれば、金沢大学は2023年8月29日に100%出資のベンチャーキャピタル株式会社ビジョンインキュベイトを設立した。産業競争力強化法に基づく特定研究成果活用支援事業計画について文部科学大臣及び経済産業大臣の認定を受け、特定成果活用支援事業者への出資について文部科学大臣の認可を得ている。VI-1号ファンドを2023年9月に組成する予定とし、本学が出資するとともに北陸地域を中心に投資事業有限責任組合員（LP）を募集する。国立大学等の自己財源100%出資でのVC設立と認定ファンドへの出資は国内初とする。', 'official', 'https://www.kanazawa-u.ac.jp/en/news/128859', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_regulation_owner', 'established', '大学規程（国立大学法人金沢大学の規程第3511号）', '認定制度の根拠は国立大学法人金沢大学認定ベンチャー称号授与規程（令和3年3月19日規程第3511号）で、金沢大学規程集の第1編全学規程（全学共通）第5章研究に収録され、分野は社会共創推進部社会共創企画課。支援の細則は同規程第6条第2項に基づく国立大学法人金沢大学認定ベンチャー支援にかかる取扱要領（令和3年4月1日、研究・社会共創担当理事裁定）。設置形態は国立大学法人であり、学校法人の寄附行為に基づく規程ではない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_review_body', 'established', '研究企画会議（基幹会議の一つ、研究担当理事の諮問）', '称号授与規程第4条で学長は研究企画会議の議を経て授与の可否を決定し、第8条第1項の取消しも同会議の議を経る。研究企画会議は国立大学法人金沢大学規則第21条に基づく基幹会議の一つで、国立大学法人金沢大学基幹会議規程第2条が基幹会議は所掌する理事の諮問に応じ必要な事項を審議すると定め、第7条が研究企画会議の審議事項を定める。申請の経路は称号授与規程第3条により研究担当理事を経て学長へ。事務は社会共創推進部社会共創企画課（第10条）。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_equity_decider', 'established', '取得は学長（研究企画会議の議）、売却は財務担当理事', '株式等取扱規程第4条で研究企画会議が取得の可否を審査し、第5条で学長が決定して当該企業と契約を取り交わす。処分は株式等管理規程（令和4年1月26日規程第3678号）が定め、第2条で財務担当理事を管理責任者とし、第3条で管理責任者が株式を定期的に評価して効果的かつ公正な判断により売却し、必要な場合は外部専門家の意見を活用する。第4条で売却は原則として有価証券処分信託による。第5条で新株予約権の行使・変更・処分も管理責任者が判断する。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000872.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_amendment_decider', 'established', '学長（諸規程の制定は学長名義で決裁）', '称号授与規程には改廃条項が置かれていない。国立大学法人金沢大学文書処理規程（平成16年4月1日規程第398号）第7条が文書の名義者を別表で定め、別表は「学則等の諸規程の制定及び告示，通知等のうち重要なもの」の名義者を国立大学法人金沢大学長又は金沢大学長とし、第8条で起案文書は名義者の決裁を得て施行すると定める。国立大学法人金沢大学規則第17条・第19条は教育研究評議会と経営協議会の審議事項を重要な規則の制定改廃としており、規程レベルの制定改廃は明示していない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_post_grad_limit', 'established', '期限なし（在職・在学していた者を含むと規定）', '称号授与規程第2条第1項第1号が対象を「本学の役職員又は学生(在職又は在学していた者を含む。以下本号において同じ。)が，本学において習得した技術，知識等を活用して設立した法人」と定め、退職後・卒業後の年数の上限を置いていない。要件は第2号の知的財産権の実施許諾又は譲渡された知財の活用、第3号の会社法により設立された法人と併せた3号すべての該当で、第2項により学長が特に必要と認めた法人も申請できる。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_renewal_rule', 'established', '更新可（審査あり）、3年後に以後2年ごと', '称号授与規程第5条第2項で有効期間は授与した日から3年間、以後2年ごとに更新することができる。第3項で更新しようとする法人は学長に申請しなければならず、当該申請及び選考には第3条（金沢大学認定ベンチャー称号申請書により研究担当理事を経て学長に申請）及び第4条（学長が研究企画会議の議を経て可否を決定し申請者に通知）を準用する。届出のみで自動更新される仕組みではない。更新回数の上限は規定されていない。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_naming', 'unknown', null, '［自動検証で否認: 起業準備中の文言は第1条でなく第2条の規定］元の主張(established): 独自名称「金沢大学認定ベンチャー」。称号授与規程第1条が「本学が『金沢大学認定ベンチャー』の称号を授与する」と定め、第5条第1項で「金沢大学認定ベンチャー」称号記により授与する。称号名に「大学発ベンチャー」「大学発スタートアップ」の語は用いない。第1条は対象に「スタートアップとして起業準備中の者を含む」と記す。機構側の該当ページ名は「ベンチャー認定制度」、支援全体のページ名は「大学発ベンチャー・事業化支援」。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_support_period', 'established', '称号期間と同じ（個別支援は年限を別に設定）', '称号授与規程第6条第1項は支援の対象を「前条により称号を授与された法人」とし、第8条の取消しにより認定ベンチャーの地位を失うため、支援は称号の有効期間に連動する。支援期間を独立に定める条文は称号授与規程にも支援取扱要領にも無い。個別の支援には別の年限があり、要領第2条第4号の知的財産権の独占実施は「一定の年限を区切って」許可し、VBLの使用はベンチャー企業等使用取扱要領第4条で原則3年以内・最大5年以内とする。', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_support_contents', 'established', 'ロゴ使用・情報発信・知財独占実施・展示会・斡旋紹介・経営指導・補助金・表彰推薦', '認定ベンチャー支援にかかる取扱要領第2条が10号を列挙。(1)「金沢大学認定ベンチャー」のロゴマーク等の無償使用許諾、(2)本学ホームページでの認定事実の公開、(3)本学広報誌等での情報発信、(4)一定の年限を区切って当該知的財産権の独占実施の許可、(5)本学が関係する各種展示会での出展・紹介、(6)本学が協定を締結する機関への斡旋・紹介、(7)本学が協定を締結する機関とタイアップした経営指導・支援、(8)起業時の各種補助金に関する情報提供、(9)起業時の各種表彰事業への積極的推薦、(10)その他、学長が必要と認める支援。柱書は教育・研究及び管理運営に支障のない範囲とする。', 'official', 'https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d28e96c9a63e', 'attr_source_docs', 'established', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html・https://o-fsi.w3.kanazawa-u.ac.jp/update/venture_youryou.pdf・h…', '1本目は認定制度の正本である称号授与規程の全文（金沢大学規程集、第1編全学規程 第5章研究）。2本目は支援の細則である認定ベンチャー支援にかかる取扱要領の全文PDF。3本目は先端科学・社会共創推進機構のベンチャー認定制度ページで、認定要件と支援内容の要約、認定企業一覧、規程・要領・申請書類のリンクを掲載する。株式・新株予約権は規程集の株式等取扱規程と株式等管理規程、施設はVBLの取扱要領とQ&Aが別に定める。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.kanazawa-u.ac.jp/kiteishu/act/110000794.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_cert_update', 'established', '支援期間5年以内等を規定、更新条項なし', '支援規則（平成30年3月22日規則第81号、令和8年8月3日規則第181号まで7回改正）第3条第2項。大学発ベンチャーへの支援期間は5年を超えない範囲で学長が必要と認める期間、熊本大学認定ベンチャー及び熊本大学認定法人は実施権許諾契約の期間。ただし書で大学発ベンチャーの称号使用は支援期間終了後も継続できる。更新、再申請、期間満了時の再審査を定めた条文は全12条のいずれにも置かれていない。要件の継続確認は第7条第1項の毎年度の事業報告書・収支決算書（翌年6月末日まで）の提出と、第8条第1項第1号の定義に該当しなくなった場合の取消でまかなう構造。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_title_restriction', 'established', '取消後の称号・支援事実の使用禁止、誤認防止条項なし', '支援規則第3条第1項各号アが「熊本大学発ベンチャー」「熊本大学認定ベンチャー」「熊本大学認定法人」の称号の授与及び使用を支援内容とし、第3条第2項ただし書で大学発ベンチャーの称号は支援期間終了後も使用させることができる。第8条第3項は、支援決定取消の通知日以降、授与した称号及び支援を受けていた事実を事業に使用してはならないと定める。第9条は支援によって生じた損失・損害に本学がいかなる法的責任も負わないとする。品質保証・投資推奨・経営状態の保証と誤認させない旨の条項、称号の表示方法を定めた条項は、規則にも大学発ベンチャー支援制度ページにも置かれていない。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_cancellation', 'established', '取消7事由と取消通知書、通知日以降の称号使用禁止', '支援規則第8条第1項が取消事由を7号列挙する。第2条第1号から第3号までの定義に該当しなくなる場合、公序良俗違反・法令違反・社会的信用を失墜する行為、事業活動の実態がなくなった場合、事業報告等から存続が危惧される場合、代表者からの取消申出、事業報告等の未提出又は第7条第2項の報告があった場合、その他学長が適当でないと認めた場合。第2項で支援決定取消通知書（別記様式第4号）により通知し、第3項で通知日以降、称号及び支援を受けていた事実を事業に使用できない。称号記の返付や表示物の回収を求める条項は置かれていない。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_report_change', 'established', '年次事業報告を翌年6月末まで、変更は書面で届出', '支援規則第6条は、支援決定後に申請内容に変更が生じたときは速やかに学長へ書面で届け出るものとし、代表者・所在地・資本構成など変更事項を限定していない。第7条第1項は毎年度の事業報告書及び収支決算書を当該年度の翌年6月末日までに学長へ提出する義務を課す。第7条第2項は、会社法上の解散、破産法上の破産宣告、民事再生手続、会社更生手続、不正競争防止法第21条・第22条の罰則の確定、その他法令違反による処分の確定に該当したときの速やかな報告を義務づける。事業報告等の未提出と同項の報告は、第8条第1項第6号の取消事由となる。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_support_request', 'established', '認定申請が支援申請を兼ね、施設利用は別途申請・契約', '支援規則第5条第1項で、支援を受けようとする企業等の代表者が大学発ベンチャー等支援申請書（別記様式第1号）又は認定法人支援申請書（別記様式第2号）により学長へ申請し、第2項で熊本大学研究開発戦略本部知的財産審査委員会の議を経て可否を決定する。認定と支援の申請は一体で、支援メニューごとの申請様式は置かれていない。施設・設備の利用は第10条第1項により固定資産管理規則等の基準に従い、大学発ベンチャー支援制度ページも「利用には条件があり、申請・契約等が必要」と記載する。株式等の取得は株式等取扱規則第4条・第5条で別に審査し決定する。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_facility_registration', 'established', '4施設を賃貸契約で貸与、貸与地で登記・移転登記可', '支援規則第3条第1項第1号イで、大学発ベンチャーは地域共同ラボラトリー、インキュベーションラボラトリー、ベンチャービジネスラボラトリー又は産業イノベーションラボラトリーを事業の範囲内で使用でき、同号ウで当該施設の住所を登記に使用できる。第2号イ・ウで熊本大学認定ベンチャーは本学の施設及び設備を使用し、移転登記に当該住所を使用できる。第3号イの熊本大学認定法人は施設・設備の使用のみで登記の記載がない。第10条第1項で貸付と住所使用は固定資産管理規則（平成27年3月31日制定）等の基準による。公式ページは「大学との賃貸契約が必要」と明記する。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_vc_connection', 'established', 'ベンチャーコンソーシアムで支援、PARKS参画と地銀連携', '大学発ベンチャー支援制度ページと支援概略図は、熊本大学発ベンチャー企業及び熊本大学認定ベンチャー企業への支援として「ベンチャーコンソーシアムで支援」を掲げる。支援規則第3条第1項第2号オ・第3号ウは研究開発戦略本部が所管するイベント、ウェブサイト等による事業内容の紹介までを定め、投資家や金融機関への紹介を定めた条文はない。2024年10月22日付の本学報道発表は、九州・沖縄のスタートアップ創出プラットフォームPARKSのGAPファンドプログラムに本学教員6名・学生1名が採択されたこと、包括連携協定を締結する熊本銀行が主催し本学と肥後銀行が共催する採択者記念ピッチを開催することを記載する。', 'official', 'https://venture.kuma-u.jp/program/academic_startups/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_eir', 'unknown', null, '熊本大学研究開発戦略本部規則（令和7年3月27日規則第42号、令和8年5月28日規則第171号まで改正）第7条が本部に置く職員を本部長、副本部長、部門長、専任教員、特任教員、技術職員、研究支援職員、研究コーディネーター、知的財産推進員と列挙し、客員起業家やEIRの職名はない。第12条の地域連携ユニバーシティ・アドミニストレーターは行政機関等と連携して活動する高度専門人材で、起業家招聘制度ではない。熊本大学規則集の現行規則一覧735件には客員教授等選考規則、客員研究員取扱要項、外国人客員研究員規則があるが起業家招聘の規程はなく、ベンチャー推進部門の各ページにも記載を確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_cxo_pool', 'unknown', null, '支援規則第3条第1項の支援内容は、称号、施設・設備の使用、貸与地での登記、知的財産権又は研究成果等の実施権許諾の優遇措置、イベント・ウェブサイトでの紹介で構成され、経営人材の紹介・派遣・マッチングを定めた号はない。ただし熊本大学認定ベンチャーの第2号カ、熊本大学認定法人の第3号エに「その他学長が必要と認める支援」があるため限定列挙とは断定できない。熊本大学研究開発戦略本部規則第3条の業務にも経営人材マッチングの記載はなく、大学発ベンチャー支援制度ページ、部門概要ページにもCEO・CXO候補の紹介制度は掲載されていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_ip_equity', 'established', '知財の実施許諾を含む支援の対価を株式・新株予約権で取得可', '株式等取扱規則（平成28年3月24日規則第49号、令和7年3月27日規則第133号まで改正）第2条第1号が「支援」を、本学の有する知的財産権の移転、設定又は許諾、技術的な指導又は助言、その保有する施設又は設備の貸付けその他研究開発の成果の普及及び活用の促進に必要な支援と定義し、実施許諾が対価の対象に含まれる。第2条第3号で株式等は株式及び新株予約権。第3条で、ベンチャー企業から株式等による支払いの申し出を受け、事業の創出・成長発展の支援になり、かつ資力等を勘案して支援を無償とし又は対価を時価より低く定める必要がある場合に、対価の全部又は一部を株式等で取得できる。第10条で発明者補償金は株式等を換金し収入を得た時点で支払う。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110000930.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'pol_fund_investment', 'unknown', null, '熊本大学規則集の現行規則一覧735件を走査したが、名称に出資・ファンド・投資・キャピタル・会社を含む規程は0件で、大学ベンチャーキャピタルの設立、認定ベンチャーキャピタルへの出資、LP出資、指定ファンド、大学出資会社経由の投資を定めた公開規程は確認できなかった。株式等取扱規則は、支援の対価としてベンチャー企業側の申し出により株式等を受け取る取得を定めるもので、本学からの出資を認める規定は置いていない。同規則第2条第4号ロはベンチャーキャピタル等のファンドから出資を受け又は受けようとする企業であることを対象要件とし、出資者を外部ファンドに置く前提をとる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_regulation_owner', 'established', '大学規程（国立大学法人熊本大学の規則）', '認定制度の根拠は国立大学法人熊本大学大学発ベンチャー等の支援に関する規則（平成30年3月22日規則第81号）で、国立大学法人熊本大学が定める法人規則として熊本大学規則集の第2編大学・第5章学術研究の振興に編さんされ、分野表示は産学連携推進課。学校法人の寄附行為に基づく規程ではない。関連する株式等取扱規則、利益相反管理に関する規則、営利企業役員等兼業及び勤務時間内非役員兼業規則、職務発明等規則、民間機関等との共同研究規則も同じ法人規則の体系に属し、支援規則がこれらを条文で参照する構造をとる。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_review_body', 'established', '熊本大学研究開発戦略本部知的財産審査委員会', '支援規則第5条第2項で、学長は申請があったときは熊本大学研究開発戦略本部知的財産審査委員会の議を経て支援の可否を決定する。同委員会は熊本大学研究開発戦略本部規則第19条に基づき本部に置かれ、熊本大学研究開発戦略本部知的財産審査委員会細則（令和7年3月28日細則第19号）第3条第4号が審議事項に「大学発ベンチャー企業の認定に関すること」を明記する。事務は研究・社会連携部産学連携推進課（支援規則第11条）。旧規定にあった熊本創生推進機構知的財産審査委員会は、令和7年4月1日の研究開発戦略本部設置に伴い承継された。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_equity_decider', 'established', '学長が決定、審査は知的財産審査委員会、売却は担当理事', '株式等取扱規則第4条第1項で株式等の取得の審査は熊本大学研究開発戦略本部知的財産審査委員会が行い、第2項で財務状況・事業計画その他取得の妥当性を判断するために必要な事項を踏まえて審査し必要に応じ外部専門家の意見を聴取、第3項で委員長が審査結果を学長に報告する。第5条第1項で学長が審査結果に基づき取得の可否を決定し、第2項で契約書を取り交わす。第6条で新株予約権の行使及び株式等の売却に関する業務の責任者を置き、総務・財務・施設担当の理事をもって充てる。第9条で取得した株式等に基づく経営参加権は原則として行使しない。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110000930.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_amendment_decider', 'established', '学長が規則として制定改廃、規程内に改廃条項なし', '支援規則は全12条に改廃手続を定める条文を置かず、第12条の雑則で「この規則に定めるもののほか、必要な事項は別に定める」とするにとどまる。同規則は国立大学法人熊本大学の規則として公布され、令和元年5月23日規則第280号から令和8年8月3日規則第181号まで7回改正されている。国立大学法人熊本大学法人基本規則第26条第5項第3号は経営に係る重要な規則の制定又は改廃を経営協議会の審議事項とし、第27条第5項第3号は教育研究に係る重要な規則の制定又は改廃を教育研究評議会の審議事項とする。第25条第2項は学長が役員会の議を経る事項を列挙する。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110000001.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_post_grad_limit', 'established', '3年以内（原則、退職・卒業・修了後）', '支援規則第2条第1号ウ。教職員等及び学生等であった者が、退職、卒業又は修了の後、原則として3年以内に本学が保有する知的財産権又は研究成果等を基に設立した、又は設立に深く関与して起業した企業等を大学発ベンチャーに含める。「原則として」と定めており厳格な失権期限ではない。同号エは学生等が在学中に起業した企業等で学長が特に認めるもの、令和8年改正で加わった同号オは、その他教育研究に係る分野において本学と深い関連があると学長が特に認める企業等を対象とし、3年の枠外でも学長の個別認定で対象になりうる。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_renewal_rule', 'established', '規定なし（更新条項を置かず、称号は期間後も使用可）', '支援規則第3条第2項は支援期間を定めるが、更新、再申請、期間満了時の再審査を定めた条文は全12条に置かれていない。同項ただし書で大学発ベンチャーの称号の使用は支援期間の終了後も引き続き使用させることができるとし、期間満了で称号が失効しない構造をとる。期間中の適格性は第7条第1項の年次の事業報告書・収支決算書と、第8条第1項第1号の定義に該当しなくなった場合の取消で担保する。熊本大学認定ベンチャー及び熊本大学認定法人の支援期間は実施権許諾契約の期間であり、契約の更新に連動する。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_naming', 'established', '大学発ベンチャー（認定ベンチャー・認定法人を併設）', '支援規則第2条が大学発ベンチャー、熊本大学認定ベンチャー、熊本大学認定法人の3区分を定義し、第3条第1項各号アで「熊本大学発ベンチャー」「熊本大学認定ベンチャー」「熊本大学認定法人」の称号を授与し使用させる。公式ページと支援概略図は「熊本大学発ベンチャー企業」「熊本大学認定ベンチャー企業」と企業を付した表記を用いる。スタートアップの語はベンチャー推進部門サイトの見出し「大学発スタートアップ」や研究開発戦略本部規則第3条第7号に現れるが、称号としては用いていない。熊本大学認定ベンチャー企業のみマークの使用が支援内容に含まれる。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_support_period', 'established', '支援ごとに別に定める、大学発5年以内・認定は契約期間', '支援規則第3条第2項。大学発ベンチャーへの支援期間は5年を超えない範囲で学長が必要と認める期間、熊本大学認定ベンチャー及び熊本大学認定法人への支援期間は本学が有する知的財産権又は研究成果等の実施権の許諾に関する契約期間とし、区分ごとに定め方が異なる。ただし書で大学発ベンチャーの称号の使用は支援期間の終了後も引き続き使用させることができるとし、称号の使用期間と支援期間を切り離している。施設・設備の使用は第10条第1項により固定資産管理規則等の基準に基づく賃貸契約で別に期間を定める。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_support_contents', 'established', '称号使用・施設貸与・貸与地登記・知財優遇・イベント紹介・コンソーシアム支援', '支援規則第3条第1項と大学発ベンチャー支援制度ページの支援内容表による。大学発ベンチャーは称号使用、地域共同ラボラトリー・インキュベーションラボラトリー・ベンチャービジネスラボラトリー・産業イノベーションラボラトリーの貸与、貸与地での登記。熊本大学認定ベンチャーは称号及びマークの使用、本学の施設・設備の貸与、貸与地での移転登記、知的財産権又は研究成果等の実施権許諾の優遇措置、大学所管イベント等での紹介、その他学長が必要と認める支援。熊本大学認定法人は称号使用、施設・設備の貸与、イベント等での紹介。支援概略図は認定2区分に「ベンチャーコンソーシアムで支援」を掲げる。', 'official', 'https://venture.kuma-u.jp/program/academic_startups/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbbf36b7e6aa', 'attr_source_docs', 'established', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html・https://venture.kuma-u.jp/program/academic_startups/・http…', '1本目は熊本大学規則集にある大学発ベンチャー等の支援に関する規則の現行版で、令和8年8月3日規則第181号までの7回の改正を反映する。ベンチャー推進部門サイトが配布するPDFは平成30年制定時の原文であり、対象範囲を広げた第2条第1号オ、産業イノベーションラボラトリーの追加、審査委員会名と事務担当課の変更が未反映のため、条文の確認は規則集を使う。2本目は支援区分・支援条件・支援内容・支援期間・申請窓口をまとめた公式ページ。3本目は支援の対価として株式・新株予約権を取得する規則。規則集は既存URLからexternal.jimu.kumamoto-u.ac.jpへ転送され、HTTPSの証明書が失効しているため取得時に検証を外す必要がある。', 'official', 'http://kokai.jimu.kumamoto-u.ac.jp/~kisoku/act/110001031.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_cert_update', 'established', '最長3年、更新2回まで、継続時は申請書類を再提出', 'ご案内PDF「支援期間（登録期間）」欄に「1度での支援期間は最長3年間です。継続して支援を希望される場合には、改めて申請書類をご提出ください。（なお、更新回数は2回までとなります。）」とあり、通算は最長9年。再提出する書類は初回と同じ4点（登録申請書、法人概要、誓約書、履歴事項全部証明書）で、履歴事項全部証明書は申請日前3か月以内発行のものを求められるため、更新のたびに法人の現況と誓約事項が確認し直される構造になっている。更新審査の基準、可否の判断手続、要件の再確認方法を定めた文書は公開されていない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_title_restriction', 'unknown', null, '称号の使用範囲、使用停止、品質保証や投資推奨と誤認させない旨の条項は公開文書に見当たらない。ご案内PDFの恩典欄は称号付与とロゴ使用を挙げるのみ。申請書に添付する誓約書（別紙2）は第3項④で風説の流布や偽計・威力による大学の信用毀損と業務妨害の禁止、第4項で違法ビジネス活動・宗教活動その他大学の名誉と信頼を毀損する一切の活動の禁止を定めるが、いずれも大学側の信用保護であり、登録が企業の品質や投資適格を保証しない旨の注意書きではない。根拠規程本文は非公開。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_form.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_cancellation', 'established', '誓約書違反・虚偽申告で登録解除、返付規定なし', '申請書に添付する誓約書（別紙2）第5項「上記各項のいずれかを満たさないと認められることが判明した場合又はこの表明・確約が虚偽の申告であることが判明した場合には、登録が解除されても異議申し立てを行いません。これにより損害が生じた場合でも、一切を当社及び私の責任といたします」。解除事由は反社会的勢力への該当や関係、暴力的要求等の行為、違法ビジネス活動・宗教活動その他大学の名誉と信頼を毀損する活動、および虚偽申告。称号の返付、大学HP掲載の削除、ロゴの営業利用停止など解除後の処理を定めた条項は公開文書にない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_form.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_report_change', 'unknown', null, '登録制度のご案内PDFと登録申請書に、年次報告、代表者・所在地・資本構成の変更届、解散時報告の定めはない。登録期間中の状況報告を求める記載もない。施設側は別建てで、SITインキュベーションスクエア シェアオフィス利用規約第2条5項が「利用の期間途中において、本条1項で管理責任者に提供した情報に変更が生じたときは、管理責任者に申し出て許可を得てください」と定めるが、これは施設利用者の義務であり登録ベンチャーの報告義務ではない。登録制度の根拠規程本文は非公開のため、報告義務の有無を確認できない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_support_request', 'unknown', null, '［自動検証で否認: 機器の学外利用手続はどの文書にも記載なし］元の主張(established): 恩典は申請書で選択、施設・機器は別途申請と審査。登録申請書に「希望の恩典にチェックしてください」欄があり、登録ベンチャー称号、ロゴ使用、大学HPへの掲載、経営相談・支援、情報提供の5つから個別に選ぶ。施設と機器はこれとは別の手続で、シェアオフィス利用規約第2条が所定の手続による利用申請と管理責任者の利用可否判断・通知を、第6条14項が本施設住所での商業登記の事前許可を求める。共通機器・ものづくりセンターの学外利用は、申請書提出、書類審査（必要に応じヒアリング）、SIT総合研究所長名の承諾書という別の流れになる。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_facility_registration', 'established', 'シェアオフィス月額有償、事前許可で商業登記可', 'SITインキュベーションスクエア シェアオフィス利用規約（令和4年12月23日版、令和6年3月28日改定、学校法人芝浦工業大学名義）。第2条2項で原則前月20日までの申込、申込期間は1か月以上・当該年度末までとし、管理責任者が利用可否を判断して通知した時点で利用契約が成立。第6条14項で本施設住所を用いた商業登記等を所定の手続による事前許可制で認め、別表2備考(ウ)で登記日翌月分から郵便BOX利用と合わせた追加の月額利用料を課す。所在地は豊洲キャンパス本部棟10階。第5条により規約違反や利用料延滞では事前通知なく登録抹消と退去命令が可能。', 'official', 'https://www.shibaura-it.ac.jp/assets/SharedOffice_Rules.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_vc_connection', 'unknown', null, 'VC、金融機関、自治体、外部支援機関へ登録ベンチャーを紹介する制度は公開情報で確認できない。登録の恩典5項目に紹介は含まれず、近いのは「経営相談・支援、情報提供」という包括的な記載のみ。BOiCEページは企業・地域自治体・金融機関・大学の強みを結集する拠点という設置目的を述べるが、紹介の手続や連携先は示されていない。2026年度事業計画はBOiCEでインキュベーションマネージャーとコーディネーター（URA）による伴走型支援を実施すると記載。学生向けSIT GRIT² Programに資金調達の個別相談があるが、対象は本学学生とSBMC Junior参加者に限られる。', 'official', 'https://www.shibaura-it.ac.jp/about/educational_foundation/plan/2026.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_eir', 'unknown', null, '客員起業家（EIR）、起業家メンター、起業家人材の招聘制度は公開情報で確認できない。大学公式サイトマップに収録された全6,432件のURLに該当ページはなく、BOiCEページ、産学官連携の各ページ、SIT GRIT² Program資料にも記載がない。2026年度事業計画は「起業支援人材の拡充などを通じ、オープンイノベーション創出に向けた体制強化を継続」と述べるが、名前が挙がる人材はインキュベーションマネージャーとコーディネーター（URA）で、外部起業家を一定期間招く制度としては書かれていない。卒業生起業家によるセミナーは実施している。', 'official', 'https://www.shibaura-it.ac.jp/about/educational_foundation/plan/2026.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO/CXO候補）を紹介・マッチングする制度は公開情報で確認できない。登録の恩典5項目に人材紹介はなく、BOiCEページ、SIT GRIT² Program資料にも記載がない。複合領域産学官民連携推進本部のサービス紹介ページは、コーディネータ/URAが窓口となって「技術相談、委託・共同研究」「技術移転」「起業支援」の3つを提供すると説明し、起業支援の中身は個別相談、講座、イベントとして記述されている。大学公式サイトマップの全URLにも人材プールに関するページはない。', 'official', 'https://www.shibaura-it.ac.jp/research/industry/service.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_ip_equity', 'unknown', null, '知財の実施許諾対価として株式や新株予約権を受け取る規程・運用は公開情報で確認できない。2026年4月開始の登録制度の恩典5項目に実施許諾自体が含まれない。2023年4月開始の旧認定制度の大学公式ニュースには大学保有特許の実施権付与の記載があるが、対価の定めには触れていない。知的財産ポリシーは大学公式の「各種ポリシー」ページにも産学官連携の各ページにも掲載がなく、本文を確認できない。2026年度事業計画は知財の権利化・活用を担う専門人材の配置と知財戦略の高度化を掲げるが、株式対価には触れていない。', 'official', 'https://www.shibaura-it.ac.jp/about/educational_foundation/plan/2026.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'pol_fund_investment', 'unknown', null, '大学VC、認定VC、LP出資、指定ファンド、大学出資会社を通じた投資の制度は公開情報で確認できない。ご案内PDF2ページ目の類型定義⑥「大学からの出資がある等その他、大学と深い関連のあるベンチャー」は対象企業を分類するための一般的な定義であり、大学が出資する制度の根拠ではない。2026年度事業計画にも出資やファンド組成の記載はなく、資金面はGTIE（主幹3機関は東京大学、東京科学大学、早稲田大学）のGAPファンド公募で本学の研究テーマが支援を獲得したという外部資金の記述にとどまる。', 'official', 'https://www.shibaura-it.ac.jp/about/educational_foundation/plan/2026.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_regulation_owner', 'established', '大学規程、施設の規約のみ学校法人名義', '登録制度の公開文書はすべて大学名義。ご案内PDFの制度名は「芝浦工業大学発ベンチャー登録制度」、登録申請書と誓約書の宛先は「芝浦工業大学 複合領域産学官民連携推進本部長 殿」で、誓約書の相手方も芝浦工業大学。産学官民連携ポリシーも「芝浦工業大学産学官民連携ポリシー」（平成21年6月26日制定、令和6年4月1日改定）で大学名義。一方、施設側のシェアオフィス利用規約は冒頭で「学校法人芝浦工業大学（以下『本学』という。）が管理・運営する」と定義し法人名義。登録制度の根拠規程そのものは公開されていない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_form.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_review_body', 'established', '複合領域産学官民連携推進本部長宛、委員会名は非公開', '芝浦工業大学ベンチャー登録申請書の宛名が「芝浦工業大学 複合領域産学官民連携推進本部長 殿」。同本部は2009年4月1日発足の産学官民連携の拠点組織で、産学官民連携ポリシーにも設置が明記されている。申請の受付窓口はご案内PDFの問い合わせ欄に記載の研究推進部オープンイノベーション推進課で、申請書類はメール添付で送付する。認定委員会や審査会などの会議体名、議決手続、審査基準を定めた文書は公開情報では確認できない。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_form.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_equity_decider', 'unknown', null, '大学が株式や新株予約権を取得・処分する制度自体が公開情報で確認できないため、決裁者も確認できない。登録制度のご案内PDF、登録申請書、産学官民連携ポリシー、利益相反マネジメントページ、2025年度および2026年度事業計画のいずれにも株式・新株予約権の取得や処分に関する記載はない。大学公式サイトマップの全URLにも該当する規程やポリシーのページは存在しない。', 'official', 'https://www.shibaura-it.ac.jp/about/educational_foundation/plan/2026.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_amendment_decider', 'unknown', null, '登録制度の根拠規程が公開されていないため、制定改廃を決める主体は確認できない。関連文書のうち改廃の定めがあるのはシェアオフィス利用規約第11条で、「本学は、利用者の承諾なく、必要に応じて、本規約及び諸規約を改定することができる」とし、この「本学」は同規約冒頭で学校法人芝浦工業大学と定義されている。制定・改定時は管理責任者が適当と認める方法で利用者へ通知する。産学官民連携ポリシーは制定日と改定日を記すのみで、決裁主体の記載はない。', 'official', 'https://www.shibaura-it.ac.jp/assets/SharedOffice_Rules.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_post_grad_limit', 'established', '5年以内（教職員）、学生は卒業生まで期限なし', 'ご案内PDF「対象企業」欄。①本学に在籍している教職員又は本学退職後5年以内の教職員、②本学に在籍している学生又は本学卒業生、のいずれかが籍を有する大学発ベンチャー企業が対象。教職員は退職後5年以内という年限があるが、卒業生には年限の記載がない。なお同PDF2ページ目の類型定義では②共同研究ベンチャーと③技術移転ベンチャーに「設立5年以内」の要件があるが、これは会社設立からの年数であり、退職・卒業からの年限とは別の要件。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_renewal_rule', 'unknown', null, '［自動検証で否認: 審査基準非公開なのに審査ありと断定］元の主張(established): 更新可（審査あり）、2回まで、申請書類を再提出。ご案内PDF「支援期間（登録期間）」欄に「1度での支援期間は最長3年間です。継続して支援を希望される場合には、改めて申請書類をご提出ください。（なお、更新回数は2回までとなります。）」。届出ではなく初回と同じ4点の申請書類を出し直す方式で、履歴事項全部証明書は申請日前3か月以内発行のものが必要になり、誓約書も改めて差し入れる。宛先も初回と同じ複合領域産学官民連携推進本部長。更新時の審査基準や可否の判断手続を定めた文書は公開されていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_naming', 'established', '独自名称「芝浦工業大学登録ベンチャー」', 'ご案内PDFの支援内容(恩典)欄に「『芝浦工業大学登録ベンチャー』の称号付与」と明記され、登録申請書の恩典選択欄も「登録ベンチャー称号」。制度名は「芝浦工業大学発ベンチャー登録制度」、対象企業の定義語は「大学発ベンチャー企業」で、制度概要文では「スタートアップ企業(大学発ベンチャー)」と併記されるが、企業に与えられる称号自体は登録ベンチャーという独自の名称になっている。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_support_period', 'established', '称号期間と同じ、支援期間＝登録期間で最長3年', 'ご案内PDFは項目名を「支援期間（登録期間）」とし、支援期間と登録期間を同一のものとして最長3年間・更新2回までを定める。恩典ごとに別の期間を定める記載はない。ただし施設は別契約で、シェアオフィス利用規約第2条2項が申込期間を1か月以上・当該年度末までとし、第4条で有効期限は利用許可通知に記載の終了日までと定める。共通機器の学外利用も年間利用登録料による年度単位の登録になっている。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_support_contents', 'established', '称号付与・ロゴ使用・大学HP広報誌掲載・経営相談支援・情報提供', 'ご案内PDF「支援内容(恩典)」欄の記載を分解した。「芝浦工業大学登録ベンチャー」の称号付与、芝浦工業大学登録ベンチャーのロゴ使用、大学公式ホームページや広報誌等への掲載、経営相談・支援と情報提供の4行。登録申請書の「希望の恩典にチェックしてください」欄では、登録ベンチャー称号、ロゴ使用、大学HPへの掲載、経営相談・支援、情報提供の5つを個別に選ぶ形式。HP掲載を選ぶ場合は法人概要（別紙1）に法人名、代表者、法人番号、掲載用住所、事業概要を記入し、代表者と法人番号も併せて掲載される。', 'official', 'https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_918b6fd6a473', 'attr_source_docs', 'established', 'https://www.shibaura-it.ac.jp/research/industry/boice.html・https://www.shibaura-it.ac.jp/assets/venture_inf_ver2.pdf・ht…', 'BOiCEページが制度の入口で、案内資料と登録申請書の最新版はここから配布される。ご案内PDFに対象企業、恩典、支援期間、申請書類、大学発ベンチャー6類型の定義がある。申請書DOCXには宛先、恩典の選択欄、法人概要（別紙1）、誓約書（別紙2）が含まれ、登録解除の根拠になる条項は誓約書第5項にある。施設利用と商業登記を読むにはシェアオフィス利用規約PDF、機器利用は共通機器・ものづくりセンター外部利用ページ、体制と方針は産学官民連携ポリシーPDFと年度事業計画ページを併せて開く。', 'official', 'https://www.shibaura-it.ac.jp/research/industry/boice.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_cert_update', 'not_started', '有効期間・更新審査の定めなし、年次事業報告で継続確認', '大阪公立大学発ベンチャー企業取扱規程（令和6年10月29日規程第223号）全14条を通読したが、認定の有効期間、更新可否、更新審査、要件の再確認を定める条文はない。第9条第1項で代表者が毎年9月末までに様式第5号の事業報告を提出し、第11条の取消基準（企業活動の実態消失、社会的信用の失墜、事業報告の拒否、第9条第2項の解散・破産等の報告）と第10条の称号返還申請で認定の維持・終了を管理する設計。附則第2項で旧両大学発ベンチャーを認定済みとみなす経過措置も、更新審査を課していない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_title_restriction', 'established', '品質保証目的の称号使用禁止、大学は経営状況を保証せず', '規程第6条（称号使用の制限）「本学発ベンチャー企業は、自社の製品、サービス等の内容及び品質を保証するために、称号を使用してはならない」。第7条（免責）第1項で本学は称号付与により製品・サービスの内容及び品質並びに経営状況を保証するものではなく、企業が負う法的責任について責任を負わないと定める。第7条第2項で称号付与又は取消しにより企業又は第三者に損害が生じても賠償義務を負わない。称号は「大阪公立大学発ベンチャー企業」（第3条第1項）。投資推奨の禁止条項と大学ロゴ・校章の使用条件は本規程に定めがない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_cancellation', 'established', '学長が4事由で取消、事前に意見聴取、返付規定なし', '規程第11条で学長は(1)企業活動の実態がなくなったとき(2)社会的信用を失墜する行為があったと認められるとき(3)第9条第1項の事業報告を拒否したとき又は第9条第2項の報告があったとき(4)その他称号付与の維持が適当でないとき、に認定を取り消し様式第7号で通知する。第12条で第11条第2号・第4号による取消しはスタートアップ創出・支援センターを通じて意見聴取を行い、根拠条項・原因事実・期日を書面通知、資料閲覧と陳述書提出を教示、所在不明時は掲示から2週間で到達とみなす。取消後の称号返付・表示削除・営業利用停止の義務規定は置かれていない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_report_change', 'established', '毎年9月末の事業報告と申請内容変更の随時届出', '規程第9条第1項で代表者は毎年9月末までに様式第5号により当該企業の活動に関する事業報告を学長へ提出する。第5条（申請内容の変更）で称号付与後に申請内容（様式第1号の企業名・代表者・所在地・事業内容等）に変更が生じたときは速やかに学長へ書面で届け出る。第9条第2項で会社法の解散、破産法の破産手続開始決定、民事再生法・会社更生法の手続開始決定、不正競争防止法違反の有罪確定、その他法令違反による処分確定に該当する場合、代表者又は清算人が速やかに学長へ報告する義務を負う。資本構成の変更届を名指しする条文はない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_support_request', 'established', '便宜措置は様式第3号で個別申請、学長が可否通知', '規程第8条第1項で便宜措置は代表者からの希望があった場合に必要に応じて行うものとされ、同条第3項で代表者は様式第3号により申請書を学長へ提出、第4項で学長は必要に応じて措置を行い様式第4号で通知する。認定・称号付与（第3条、様式第1号・第2号）とは別の申請・決定手続。施設利用はさらに大阪公立大学インキュベータ規程第5条で活用予定の研究を行う教員等の承諾と学長の承認を要し、利用細則第2条で別途入居申請を行う。KSAC-GAPファンドはSUCSUCを窓口とする公募申請・書類審査。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_facility_registration', 'established', 'インキュベータ入居中に限り登記面住所を施設内に', '規程第8条第1項第1号「本学の管理するインキュベータ等施設に入居している場合、入居期間中のみ、登記面住所を該当施設内とすること」。施設側は大阪公立大学インキュベータ規程（令和4年4月1日規程第91号）第3条でインキュベータオフィス・共同研究室・会議室等を設置し、第6条で入居期間2年以内、利用細則第3条で延長1年以内・2回を限度（発ベンチャー取扱要項に基づき学長が特に認める場合は例外）、第7条で認定企業は適用月から12か月間の利用料減免。登記の利用は入居に従属し、退去後の継続利用や登記のみの利用は認められていない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: KSAC部分は一致、NEDO覚書はページに記載なし］元の主張(established): KSAC経由でVC・金融機関へ、NEDO覚書あり。2026年度第4回KSAC-GAPファンド公募ページに、KSAC（関西スタートアップアカデミア・コアリション）は関西31大学と産業界・金融界・自治体等74機関が参画し、採択案件の成果発表の場としてデモデイを開催して金融機関やVC、事業会社等との連携を目指すと記載。STEP2のPMFプログラムは研究者とVCなど事業化推進機関の共同申請で、様式4（事業化推進機関の概要）・様式5（財務状況）の提出を求める。2025年3月にNEDOと起業家支援の相互協力の覚書を締結し、NEDOカタライザーの派遣とJOIC活動への人材受入れを受ける（公立大学として初）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_eir', 'unknown', null, '客員起業家（EIR）、起業家メンター、起業家人材の招聘を定める規程・要項・募集ページは公開情報で確認できなかった。発ベンチャー規程第8条第1項の便宜措置4号にもEIRに相当する措置はない（ただし第4号に「その他、学長が必要と認めること」の包括規定があるため限定列挙とは言えない）。スタートアップ創出・支援センター（SUCSUC）のプログラム一覧はGAPファンド、SUCSUC-TCAP、SUCSUC DETECT、SUCSUC-CONNECT、絵札（JQK）研究会、競争的資金獲得セミナーで、EIRの記載はない。NEDO覚書ではNEDOカタライザー（技術経営アドバイザー）の派遣を受ける枠組みがある。', 'official', 'https://www.omu.ac.jp/startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_cxo_pool', 'unknown', null, '外部CEO/CXO候補の人材プール、紹介・マッチングを定める規程や応募要項は公開情報で確認できなかった。2025年3月21日のNEDO覚書に関する大学の発表では、大阪公立大学は2024年度にSUCSUCを立ち上げ「競争的資金の獲得とライセンシング費用の確保、優秀な支援人材の確保・活用と起業の際の経営者候補の確保」などに取り組んでいると記載されており、経営者候補の確保は方針として明記されている。ただし応募方法、人材プールの構成、マッチングの手順を示す公開文書は見つからず、制度化の有無は判断できない。', 'official', 'https://www.omu.ac.jp/startup/info/news1/entry-76414.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_ip_equity', 'established', '特許移転型に限りライセンス対価を新株予約権化', '発ベンチャー規程第8条第1項第3号で便宜措置として「知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること」を定め、同条第2項で第2条第1号（特許による技術移転型）による認定かつ本学保有の知的財産権又は研究成果等について実施許諾を受けているものに限ると限定する。受入れ側は公立大学法人大阪における知的財産権の運用又は処分の対価として取得する株式等の取扱規程（令和6年9月2日規程第208号）が定め、同第4条で補償金の取扱いは知財規程第16条から第18条を準用し「株式等を売却し金銭を受領した場合」と読み替える。第5条で評価方法・管理・売却・権利行使は別に定める。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'pol_fund_investment', 'not_started', '知財対価の株式取得のみ、出資・ファンド組成の規程なし', '公立大学法人大阪における知的財産権の運用又は処分の対価として取得する株式等の取扱規程（規程第208号）第1条は対象を「法人が所有する知的財産権の運用又は処分の対価として取得する株式及び新株予約権」に限り、第2条も大学発認定ベンチャー企業から知的財産権の対価として取得する場面に限定する。現金出資、LP出資、指定ファンド、大学出資会社を定める規程は公立大学法人大阪規程集（内容現在 令和8年4月1日）の検索で見つからず、大学の産学官連携・スタートアップ各ページにも大学VCや認定VCの記載はない。資金供給はKSAC-GAPファンドという公的資金の配分が中心。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200788.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_regulation_owner', 'established', 'ハイブリッド：認定は学長、株式・兼業は理事長', '認定規程は「大阪公立大学発ベンチャー企業取扱規程」（規程第223号）として公立大学法人大阪規程集に登載され、体系上は第6章 大阪公立大学／第8節 産学官連携・知的財産・地域貢献に置かれる。認定・称号付与・便宜措置・取消の決定権者は一貫して学長。一方、株式等の取得（規程第208号）は理事長、教職員兼業規程（規程30）の承認も理事長、利益相反マネジメント規程（規程第96号）と知的財産権取扱規程（規程第87号）も法人規程で、いずれも認定の条件として参照される（発ベンチャー規程第4条第4号）。大学と設置法人の規程が組み合わさる構造。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_review_body', 'established', 'スタートアップ創出・支援センター（SUCSUC）', '規程第3条第3項「学長は、前項の申請があったときは、前条に規定する要件をもとにスタートアップ創出・支援センターの議を経て、認定及び称号付与の可否を決定する」。称号付与にあたり必要に応じて代表者へヒアリングを実施。第12条の取消時の意見聴取手続も同センターを通じて行い、第13条で事務も同センターが所管する。同センターは2024年4月1日に産学官民共創推進本部に設置され、Start Up Creation & Support Center（SUCSUC）と称する。株式等の取得は別途、産学官民共創推進本部の審査を経る（規程第208号第3条）。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_equity_decider', 'established', '理事長（産学官民共創推進本部の審査を経て決定）', '規程第208号第2条第1項「理事長は、大学発認定ベンチャー企業から、知的財産権の運用又は処分の対価としての株式等を取得するにあたり、次の各号のいずれかに該当するときは、次条に定める審査結果に基づいて、その全部又は一部の取得を決定することができる」。第3条第1項で産学官民共創推進本部の審査を経ることとし、産学官民共創担当理事は事前に財務担当理事へ審査の内容を通知する。第2条第2項で発行会社の社会的信用に問題があるとき、共益権を行使しないと経営に著しい影響を与えるとき、その他理事長が法人運営に支障があると判断したときは取得を禁じる。第5条で売却等と新株予約権の権利行使は別に定める。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200788.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_amendment_decider', 'established', '学長（教育研究の重要規程）と理事長（経営事案）', '公立大学法人大阪専決規程（規程第2号、平成31年4月1日施行、令和6年3月29日規程第74号まで改正）第3条第1項で法人の経営にかかわる事案の決裁権は理事長に属し、定款第16条各号の事項は役員会の議を経る。同条第2項で大学の教育研究にかかわる事案の決裁権は学長に属する。第4条第2項第1号で「学則（法人の経営に関する部分を除く。）その他の教育研究に係る重要な規程の制定又は改廃に関する事項は、学長又は校長が決裁する」、第2号でそれ以外の経営に係る重要規程を除く規程の制定改廃は局長専決とする。発ベンチャー規程は学長系統、株式等取扱規程は理事長系統。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200004.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_post_grad_limit', 'established', '1年以内（退職・卒業後1年以上経過は原則対象外）', '規程第2条第3号【人材移転型】「本学の教職員、学生等がベンチャー企業の設立者となる、又はその設立に深く関与した起業の場合（ただし、教職員の退職や学生の卒業後1年以上経過した者の場合は、原則として対象外とする。）」。「原則として」の留保があるため個別判断の余地は残る。他の3類型（第1号 特許による技術移転型、第2号 特許以外による技術移転型・研究成果活用型、第4号 その他関係型）には人的な期限の定めがなく、技術・研究成果との関係で判断される。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_renewal_rule', 'established', '期限なし（取消・返還まで有効、年次事業報告）', '規程第3条で学長が認定及び称号を付与した後、有効期間や更新申請を定める条文は全14条中に存在しない。認定は第11条の取消し（企業活動の実態消失、社会的信用の失墜、事業報告の拒否、第9条第2項の解散・破産等の報告、その他維持が適当でないとき）又は第10条の称号使用終了の申請と学長の許可があるまで継続する。維持確認の手段は第9条第1項の毎年9月末の事業報告（様式第5号）。附則第2項の経過措置でも旧両大学発ベンチャーを再審査なしで認定済みとみなしている。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_naming', 'established', '大学発ベンチャー（称号は大阪公立大学発ベンチャー企業）', '規程の題名は「大阪公立大学発ベンチャー企業取扱規程」で、第1条は対象を「大阪公立大学より発するベンチャー企業（以下「本学発ベンチャー企業」という。）」と定義し、第3条第1項で学長が「本学発ベンチャー企業の認定及び称号」を付与する。大学サイトの掲載欄も産学官連携の成果等「大学発ベンチャー」で、一覧の見出しは「大学発ベンチャー企業一覧」。一方、支援組織はスタートアップ創出・支援センターを名乗り、公募・イベント告知では「大阪公立大学発スタートアップ」の語も使うが、規程上の称号は「ベンチャー企業」で統一されている。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_support_period', 'established', '支援ごとに別に定める（称号は期限なし、入居2年以内）', '称号は有効期間の定めがなく取消・返還まで継続する（規程第3条、第10条、第11条）のに対し、支援は個別に期間が定められる。便宜措置は第8条第3項の様式第3号による申請と第4項の学長の通知ごとに措置され、包括的な支援期間の定めはない。インキュベータは規程第91号第6条で入居期間2年以内、利用細則第3条で延長1年以内・2回を限度、第7条で認定企業の利用料減免は適用月から12か月間。KSAC-GAPファンドはSTEP1が支援期間1年、STEP2（PMF）が2年。称号期間と支援期間は連動していない。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_support_contents', 'established', '登記面住所・事業紹介・対価の新株予約権化・入居料減免・GAPファンド', '規程第8条第1項の便宜措置は(1)インキュベータ等施設入居期間中のみ登記面住所を施設内とすること(2)本学主催イベント・ホームページ等での事業内容の紹介(3)知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること（第2条第1号の特許移転型かつ実施許諾を受けたものに限る）(4)その他学長が必要と認めること。施設面はインキュベータ入居と認定企業の利用料12か月減免（利用細則第7条）、共用研究機器センターOShaREの学外利用。資金面はKSAC-GAPファンド（IV・PSF・OD・BCB・PMF）。伴走はSUCSUCの起業相談窓口、SUCSUC-TCAP、SUCSUC DETECT、SUCSUC-CONNECT、競争的資金獲得セミナー。', 'official', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dbf1e574d1e5', 'attr_source_docs', 'established', 'https://www1.g-reiki.net/upc-osaka/reiki_honbun/u325RG00200790.html・https://www1.g-reiki.net/upc-osaka/reiki_honbun/u32…', '1本目は公立大学法人大阪規程集（Reiki-Base、内容現在 令和8年4月1日）の大阪公立大学発ベンチャー企業取扱規程本文で、認定要件・審査主体・便宜措置・報告・取消の全条文が読める。2本目は同規程集の知的財産権の運用又は処分の対価として取得する株式等の取扱規程本文で、株式・新株予約権の受入基準と決裁者が読める。3本目は大学サイトの産学官連携の成果等「大学発ベンチャー」ページで、規程PDF・関連様式・認定事前チェックシートの配布元であり認定企業一覧も掲載される。制度改廃の決裁は公立大学法人大阪専決規程（u325RG00200004）で確認できる。', 'official', 'https://www.omu.ac.jp/research/collaboration/result/venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_cert_update', 'established', '認定日から5年・更新審査あり・通算最長10年', '認定規程第6条第2項は称号を第5条第4項の認定決定日から5年間使用可とし、再申請を妨げず通算して最長10年間使用できると定める。第3項は更新を受けようとする者が期間終了の3か月前までに認定更新申請書に必要書類を添えて学長へ提出するとし、更新の審査手続は第5条第2項から第4項（審査委員会への附議、審議結果の報告、学長の可否決定と文書通知）を準用する。第3条第7号は認定後も同条各号の要件を満たし、学長が別に定める誓約事項と関係規則等を遵守することを求める。附則2の経過措置により、施行日に現に認定されている企業の使用期間は施行日から3年間又は従前の認定日起算の期間のいずれか遅い日まで。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_title_restriction', 'established', '品質を保証しない旨を明記・取消後は称号使用禁止', '認定規程第7条（本学の法的責任）第1項は、大学発ベンチャーが本学とは独立して経営を行う民間法人であり、称号の付与は本学に法的責任を生じさせるものではないと定める。第2項は本学が大学発ベンチャーの製品又はサービス等の内容及び品質についていかなる保証も行わないと明記する。称号の使用範囲は第6条第2項により認定決定日から5年間（通算最長10年）に限られ、第11条第3項は取消しを受けた者が称号記を返還し、取消日以降は認定を受けていた事実を事業活動において使用してはならないと定める。投資推奨や経営状態の保証について誤認を防ぐ明文の条項は置かれていない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_cancellation', 'established', '取消事由6類型・称号記返還と事実の使用禁止', '認定規程第11条第1項が取消事由を列挙する。買収・統廃合等による法人格の同一性の喪失、社会的信用を著しく失墜させる行為、事業報告書等の未提出・報告の懈怠・虚偽報告、第3条第2号の経済安全保障に係る誓約違反や虚偽申告、調査・資料提出に対する虚偽回答、その他審査委員会の審議を経て継続が適当でないと学長が認めた場合。手続は第5条第2項・第3項を準用する。第2項で認定取消通知書により代表者へ通知、第3項で称号記の速やかな返還と以後の事実使用の禁止、第4項で故意又は重過失を除く損害賠償責任の否認を定める。第10条は認定辞退申出書による辞退、第12条は取消し・辞退のホームページ等での公表を定める。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_report_change', 'established', '決算日から3か月以内の事業報告書等と重大事由報告', '認定規程第8条第1項は、代表者が事業年度ごとに自社で定めた決算日から3か月以内に事業報告書及び財務諸表等を学長へ提出する義務を定める。第2項は解散、破産・再生・更生の各手続開始決定、不正競争防止法違反の有罪確定、捜査機関の捜査や民事裁判の被告となったとき、新規株式公開又は事業譲渡を、速やかに報告すべき事由として列挙する。第3項は誓約違反のおそれ、情報管理に重大な影響を及ぼす事由、経済安全保障上懸念のある機関との関係の判明を報告事由とする。代表者・所在地・資本構成の定期的な変更届は置かれず、第3条第8号が主要株主・役員構成等を本学の求めに応じて開示する要件を定める。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_support_request', 'established', '施設利用は別途申請書提出と運営委員会の審査', '認定とは別建ての個別審査が施設利用にある。インキュベーション施設管理運営細則第8条は、使用を希望する企業の代表者又は教職員等が別に定める使用申請書を管理責任者（産学官連携センター長、第5条）に提出しなければならないと定め、第9条は管理責任者が産学官連携センター運営委員会の議を経て使用の可否を決定し、審査結果を速やかに通知するとする。第11条は使用目的又は使用形態の変更も管理責任者の承認事項、第12条は使用条件違反等による許可取消しを定める。認定手続自体は認定規程第5条により学長への申請と認定審査委員会の審議を経る。相談・企業紹介・広報には個別の申請様式や審査の定めが無い。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010C028.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_facility_registration', 'established', '施設貸与と当該住所での商業登記を規程で許容', '認定規程第13条第1号が事務室又は研究室としてのインキュベーション施設等の貸与を、第2号が第1号により貸与した施設について当該大学発ベンチャーの所在地としての商業登記を認めることを支援として明記する。施設は西11号館に置かれ、ベンチャー育成支援ルーム、プレインキュベーションルーム、コワーキングルーム、サーバールーム、会議室で構成（細則第4条）。使用資格は区分A（教職員等で設立を目指す者）と区分B（認定を受けた電通大発ベンチャー、準備段階の企業を含む）（細則第6条）。大学公式のインキュベーション施設ページも、登記に使用できる住所として大学所在地を掲載している。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_vc_connection', 'unknown', null, 'ベンチャーキャピタル・金融機関・自治体・外部支援機関への紹介を定めた条文は確認できなかった。認定規程第13条の支援列挙のうち紹介に当たるのは第4号のみで、対象は「他企業」であり、本学の信用・公平性、利益相反管理、日本政府又は米国政府が公表する制裁・規制対象リスト等に基づく経済安全保障上の観点から不適切と認められる場合を除くとされる。産学官連携センター規程第3条第3号と第7条もベンチャー支援部門の所掌を大学発ベンチャーの創出支援と記すにとどまる。首都圏プラットフォームGTIEにスタートアップ創出共同機関として参画しているが、資金提供者への接続を制度化した公開文書は確認できなかった。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_eir', 'unknown', null, '客員起業家、起業家メンター、起業家人材の招聘を定めた規程・公開ページは確認できなかった。認定規程第13条の支援列挙に人材の招聘・派遣は無く、第3号は本学の役職員が起業及び起業後の経営等に関する相談業務に対応するとの定めにとどまる。産学官連携センター規程第4条第3項はセンターに特任教員又は客員教員を置くことができると定めるが、起業家の招聘を目的とする制度としての記載は無い。インキュベーション施設管理運営細則も管理責任者の支援及び指導の受入れを使用条件とするのみ（第6条第2項第3号）。大学公式ページに掲載された人材面の取組は授業科目とU☆PoC（アイディア実証コンテスト）。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO・CXO候補）の紹介やマッチングを定めた規程・公開ページは確認できなかった。認定規程第13条第4号の紹介・仲介は他企業を対象としており、経営人材の紹介は列挙されていない。産学官連携センター規程第3条はセンターの業務を産学官連携事業、共同研究・受託研究、大学発ベンチャーの創出支援、知的財産の創出・取得・管理・活用等と定めるが、人材プールや人材紹介の記載は無い。大学公式のベンチャー支援ページ、電気通信大学発ベンチャー認定ページ、インキュベーション施設ページにも経営人材紹介の記載は無い。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/9999119B007.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得する要項', '「国立大学法人電気通信大学におけるライセンス等の対価として取得する株式等取扱要項」（令和6年6月21日要項第3号）。第1条はベンチャー活動の支援とイノベーション創出の促進を目的に掲げる。第3条は、ライセンス等を行った相手方が電通大発ベンチャーであり、第4条の審査を経て現金の支払を免除又は軽減することが企業等の経営の加速のために特に必要と学長が認めた場合に限り取得できると定める。第4条は産学官連携センター長が株式等による支払いの申込みを受けて財務状況その他必要な事項を審査し、取得の適否を学長に報告する。第2条はライセンス等に譲渡・提供・実施権設定・実施許諾・利用許諾を含め、第5条は発明者への実施補償金を換金後の支払とする。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2024D003.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'pol_fund_investment', 'unknown', null, '大学からの出資、認定ベンチャーキャピタルへの出資、ファンドへのLP出資、大学出資会社を定めた規程は確認できなかった。株式等管理規程第1条は対象を寄附により又はライセンス等の対価として取得した株式及び新株予約権に限定しており、出資による取得を対象としていない。同規程は取得後の管理を定めるもので、第3条は上場後に可能な限り速やかな売却を原則とし、第8条は発行会社に対する経営参加権等の共益権を原則として行使しないと定める。大学規程集の財務編・研究編にも出資やファンド組成の規程は見当たらない。資金面の外部導線としては首都圏プラットフォームGTIEのGAPファンドがある。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2024B011.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_regulation_owner', 'established', '大学規程（電気通信大学発ベンチャー認定規程）', '「国立大学法人電気通信大学規則等の制定に関する規則」第3条は規則等の区分を規則・規程・細則・要項とし、第9条は名称に法人名又は大学名を付すと定める。認定規程は大学名を冠する「電気通信大学発ベンチャー認定規程」（令和8年6月10日規程第9号）で、第5条第2項により規程は役員会の議を経て学長が定める。設置者は国立大学法人電気通信大学であり学校法人ではない。関連規程のうち株式等管理規程と職員兼業規程は法人名を冠する。附則3で従前の「電気通信大学発ベンチャー認定に関する申合せ」（平成24年3月27日役員会決定）を廃止し、申合せから規程へ格上げしている。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/99994A001.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_review_body', 'established', '大学発ベンチャー認定審査委員会（産学官連携センター）', '認定規程第4条第1項は、電気通信大学産学官連携センターに、大学発ベンチャーの認定及び取消しについて審議するため大学発ベンチャー認定審査委員会を置くと定める。第2項の構成員は産学官連携センター長、輸出管理マネージャー、産学官連携センターベンチャー支援部門長、産学官連携センター知的財産部門長、学術国際部長、その他センター長が指名する者。第3項により委員長はセンター長。第5条で学長が申請を委員会に附議し、委員会の審議結果の報告を踏まえて学長が可否を決定する。事務は学術国際部研究推進課（第14条）。施設使用の審査は産学官連携センター運営委員会が担う（細則第9条）。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_equity_decider', 'established', '取得は学長・管理と売却は財務責任者', '取得はライセンス等の対価として取得する株式等取扱要項第3条により、産学官連携センター長の審査（第4条）を経て学長が認めた場合に限り行う。取得後は株式等管理規程第2条により会計規則第5条第1項第2号の財務責任者が管理責任者となる。第3条は上場後に可能な限り速やかな売却、第4条は原則として有価証券処分信託による売却、第5条は第三者への売却が適当と認められる場合の売却、第6条は新株予約権の行使を、いずれも管理責任者の判断事項とする。第8条は経営参加権等の共益権を原則不行使、第9条はインサイダー取引防止のための措置を管理責任者に義務づける。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2024B011.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_amendment_decider', 'established', '役員会の議を経て学長', '「国立大学法人電気通信大学規則等の制定に関する規則」第2条第1項は、規則等の制定（改正及び廃止を含む）を、その区分に応じた手続を経て学長が行うと定める。第5条第2項は規程を役員会の議を経て学長が定めるとし、本学の経営又は教育研究に関する重要事項を定めるときは経営協議会又は教育研究評議会に諮る。第2条第2項は形式的又は軽微な改正について役員会等の審議を省略できるとし、細則・要項も役員会の議を経て学長が定める（第6条・第7条）。認定規程自体に改廃条項は無く、第15条が認定等に関し必要な事項を産学官連携センター長が別に定めるとする。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/99994A001.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_post_grad_limit', 'established', '1年以内（常勤職に就いていなければ期限なし）', '認定規程第2条第1項第4号は、本学の役職員であった者又は学生であった者が、退職し又は身分を喪失した後に本学由来の成果等に基づき起業したものについて、退職等の日から企業設立の日までの間に他の職（常勤の職に限る）に就いていない場合、又は退職等の日から1年以内に当該企業を設立した場合を認定対象とする。したがって退職後に常勤職に就いた場合は1年以内の設立が要件となり、常勤職に就いていない場合は年数の上限が置かれていない。第3号は在籍中の役職員・学生が設立者となるか設立に実質的に関与した場合、第5号は役職員が役員・顧問等として兼業する場合を対象とする。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_renewal_rule', 'established', '更新可（審査あり）・3か月前申請で通算最長10年', '認定規程第6条第3項は、称号の使用期間の更新を受けようとする者が期間終了の3か月前までに学長が別に定める認定更新申請書に必要書類を添えて学長に提出するものとし、更新の審査手続について第5条第2項から第4項までを準用すると定める。すなわち学長が認定審査委員会に附議し、委員会が審議結果を学長に報告し、学長が可否を決定して文書により通知する。届出のみで更新される仕組みではない。第2項により1回の使用期間は5年で、再申請を妨げず通算して最長10年間まで使用できる。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_naming', 'established', '大学発ベンチャー（称号は電気通信大学発ベンチャー）', '認定規程第2条第1項が「電気通信大学発ベンチャー」を定義し、規程内では「大学発ベンチャー」と略する。第6条第1項は学長が別に定める称号記により大学発ベンチャーの称号を付与すると定める。対象には特定非営利活動法人も含む。ライセンス等の対価として取得する株式等取扱要項第3条は「電通大発ベンチャー」の語を用い、別に定めるところにより本学から認定を受けた事業者と定義する。大学公式ページの名称も「電気通信大学発ベンチャー認定」「電気通信大学発ベンチャー一覧」。スタートアップという呼称の併記は規程上置かれていない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_support_period', 'established', '支援ごとに別に定める（称号5年・施設最長6年）', '称号の使用期間は認定規程第6条第2項により認定決定日から5年間、通算最長10年間。施設の使用期間はインキュベーション施設管理運営細則第7条が別に定め、ベンチャー育成支援ルームは1年以内で使用資格区分B（認定企業）は審査により原則として最長6年まで更新可、プレインキュベーションルームは1年以内で申請により1年以内の更新可、コワーキングルームとサーバールームは1年以内で更新回数の制限なし。認定規程第13条の相談・企業紹介・広報には期間の定めが無い。称号期間と支援期間は連動していない。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010C028.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_support_contents', 'established', '施設貸与・商業登記・起業経営相談・企業紹介仲介・広報', '認定規程第13条が、本学の関係規則等に基づき管理運営及び教育研究に支障のない範囲で行う支援として、第1号 事務室又は研究室としてのインキュベーション施設等の貸与、第2号 貸与した施設を当該大学発ベンチャーの所在地とする商業登記の許容、第3号 本学の役職員による起業及び起業後の経営等に関する相談業務への対応、第4号 本学の役職員による他企業への紹介又は仲介（信用・公平性、利益相反管理、日本政府又は米国政府が公表する制裁・規制対象リスト等に基づく経済安全保障上の観点から不適切と認められる場合を除く）、第5号 本学が主催し又は参加するイベント、広報誌若しくはホームページ等での広報、第6号 その他学長が必要と認める支援を列挙する。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_5dee3c5a2eea', 'attr_source_docs', 'established', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf・https://www.uec.ac.jp/about/basicinfo/rule/pdf/2010C028.pdf…', '制度を読む際の主要資料は3本。①電気通信大学発ベンチャー認定規程（令和8年6月10日規程第9号）が認定対象、要件、認定審査委員会、認定手続、称号と使用期間、法的責任、報告義務、辞退・取消し、公表、支援メニューを定める正本。②電気通信大学インキュベーション施設管理運営細則（平成23年1月18日制定、令和6年7月1日細則第1号最終改正）が施設区分、使用資格、使用期間、申請と許可の手続、実績報告を定める。③国立大学法人電気通信大学におけるライセンス等の対価として取得する株式等取扱要項（令和6年6月21日要項第3号）が知財対価の株式等取得を定め、株式等管理規程が取得後の管理を補完する。', 'official', 'https://www.uec.ac.jp/about/basicinfo/rule/pdf/2026B009.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_cert_update', 'established', '称号3年、更新条項なし・再申請可', '認定規程第6条第2項で称号は3年間使用でき、ただし再申請することを妨げないと定めるのみ。更新申請、更新審査、期間延長の条文はない。再申請は第5条の手続（申請書を学長へ提出、認定委員会及び戦略企画会議の議、学長の決定と文書通知）を改めて経ることになり、第3条の申請要件も再度確認される。期間中は第8条第1項で年度毎に決算日から3か月以内の事業報告書及び収支決算書の提出義務があり、未提出は第10条第1項第2号の取消事由。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_title_restriction', 'established', '法的責任を生じない旨を明記、取消後は使用禁止', '認定規程第7条は「第5条第2項の認定及び第6条第1項の称号の授与は，本法人に何ら法的責任を生じさせるものではない」と定める。品質保証、投資推奨、経営状態の保証を名指しで否定する条文はなく、この法的責任の否認条項が同じ役割を担う。称号の使用範囲は第6条第2項の3年間で、第10条第3項により取消しを受けた者は速やかに称号記を返付し、取消日以降は認定を受けていた事実を事業において使用してはならない。ロゴは別のコミュニケーションマーク取扱要領で学長許可制。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_cancellation', 'established', '取消3事由、称号記返付と認定事実の使用禁止', '認定規程第9条で代表者は認定解除申請書（別記様式3）により認定の解除と称号の返付を申し出ることができ、学長はこれを認める。第10条第1項で学長は認定委員会の議を経て、社会的信用を失墜する行為、第8条第1項の事業報告書等の未提出又は同条第2項の解散等の報告、その他本法人の不名誉となるおそれがある等称号の保持が適当でない場合に、認定及び称号の授与を取り消せる。第2項で別記様式4により通知、第3項で称号記の返付と取消日以降の認定事実の事業利用禁止を定める。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_report_change', 'established', '年次の事業報告書と決算書の提出、変更届の規定なし', '認定規程第8条第1項で代表者は年度毎に適宜の様式により、自社で定めた決算日から3か月以内に事業報告書及び収支決算書を学長へ提出しなければならない。第2項で会社法の解散、破産手続開始、民事再生、会社更生の各決定、不正競争防止法違反の有罪確定に該当した場合、代表者又は清算人が速やかに学長へ報告する。代表者、所在地、商号、資本構成の変更届の条文はない。提出書類は認定委員会細則第2条第4号で認定委員会が確認する。施設利用者は施設規程第12条の使用計画変更承認と第14条の年次進捗報告が別に必要。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_support_request', 'established', '支援は認定通知書で通知、施設等は個別に申請・審査', '認定規程第11条第1項柱書で、支援は認定委員会が本法人の管理運営及び教育研究に支障のないと認める範囲で行い、支援事業は認定通知書（別記様式5）により通知する。第2項は「前項の各号に規定する支援を行うときは，本法人における関係規則等によるものとする」と定め、個別の支援は各規則の手続による。施設はイノベーション施設規程第8条の使用計画書提出と第10条の審査会審査を経た第9条の施設長承認、新株予約権は取得等規程第5条の審査会諮問と第6条の学長決定。認定申請とは別の申請・審査がある。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_facility_registration', 'established', '施設を学内料金で貸与し所在地の商業登記を許可', '認定規程第11条第1項第1号で事務室又は研究室としてイノベーション施設等を学内料金で貸与、第2号で貸与した施設を大学発ベンチャーの所在地とする商業登記を認めると明記。施設側はイノベーション施設規程第2条第2項でインキュベーションスペースとオープンラボスペースを置き、第7条で創業後5年以内の個人・中小企業者、1年以内に創業しようとする個人等を使用資格とし、第8条の使用計画書提出、第10条の審査会審査、第9条の施設長承認を経る。第11条で使用期間は3年以内、1年単位2年を限度に延長でき、第2項でさらに1年単位の延長が可能。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/690.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: 幹事大学・東三河・内閣府の記述は当該ページに無い］元の主張(established): 規程は他企業紹介まで、VC接続はTongali経由。認定規程第11条第1項第5号は「本法人に所属する職員又は学生による他企業への紹介又は仲介」までで、VCや金融機関を名指しした条文はない。本学が幹事大学として参画するTongaliプロジェクトの起業・ベンチャー支援ページは、大学発ベンチャーに投資実績のあるVCと連携しシード・アーリーから出口まで資金調達のマッチング支援を行うこと、投資の専門家を含む支援者（メンター）の紹介、サポーター企業・団体の支援プログラムを掲げる。地域側は東三河スタートアップ推進協議会と産学官金の会議体（内閣府提出の構想調書）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_eir', 'unknown', null, '大学規程集の全一覧に客員起業家、EIR、起業家人材の招聘に関する規程は無い。認定規程第11条第1項の支援8項目にも招聘は含まれず、相談業務も第4号で「本法人に所属する職員又は学生」が担う建付け（第8号に学長が必要と認めることの受け皿はある）。客員教授等選考規程は置かれているが、起業家の招聘制度として運用されているかは公開情報では確認できない。Tongaliは支援者（メンター）を紹介するが、本学へ招く制度としての記載はない。スタートアップ推進室のサイトは本日サーバエラーで閲覧できず。', 'official', 'https://www.tut.ac.jp/gakusoku/listall.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_cxo_pool', 'unknown', null, '大学規程集の全一覧に経営人材（CEO/CXO候補）の紹介・マッチングに関する規程は無い。認定規程第11条第1項第4号の起業・経営相談も第5号の他企業への紹介・仲介も、担い手を「本法人に所属する職員又は学生」と限定しており、外部の経営人材を紹介する制度ではない。Tongaliの起業・ベンチャー支援ページも支援者（メンター）紹介までで、CxO候補の人材プールやマッチングの記載はない。スタートアップ推進室のサイトは本日サーバエラーで閲覧できず確認できなかった。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_ip_equity', 'established', 'ライセンス対価を新株予約権化可、株式取得の定めなし', '認定規程第11条第1項第7号で知的財産権のライセンス等の対価の全部又は一部を新株予約権とすることができる。新株予約権の取得等に関する規程第3条は、知的財産権のライセンス等とその他の支援業務の対価として新株予約権を取得できると定め、第2条第2号でライセンス等を知的財産権の譲渡、実施権の設定及び実施許諾、成果有体物の譲渡及び貸与と定義。第5条第3項で発行価額が無償であること等の経済条件を審議。株式そのものを対価として取得する定めはなく、株式は新株予約権の行使で取得したものを管理規程で扱う。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/776.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'pol_fund_investment', 'established', '東海5大学広域ベンチャーファンドの投資対象、大学出資規程なし', '名古屋大学学術研究・産学官連携推進本部の公式ページによれば、名古屋大学、岐阜大学、豊橋技術科学大学、名古屋工業大学、三重大学の5大学と日本ベンチャーキャピタル株式会社が、5大学に由来するベンチャー企業へ投資する「名古屋大学・東海地区大学広域ベンチャーファンド」の創設を平成27年10月に合意し、1号ファンドは平成28年度から同社、2号ファンドは令和元年度からBeyond Next Venturesが投資を開始。本学の大学規程集には出資、ファンド組成、LP出資の規程は無く、本学が出資者であることを示す公開記載も確認できない。', 'official', 'https://www.aip.nagoya-u.ac.jp/venture/entrepreneurship/venture-fund', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_regulation_owner', 'established', '大学規程（国立大学法人の規程第7号）', '認定規程は「国立大学法人豊橋技術科学大学における大学発ベンチャーの認定に関する規程（令和元（2019）年6月19日規程第7号）」で、国立大学法人が定める大学規程。第13条で改廃は規則の種類及び制定等に関する規程（平成16年度規程第1号）により戦略企画会議の議を経て学長が行うと定める。認定委員会細則、新株予約権の取得等に関する規程、同管理規程、イノベーション施設規程も同法人の規程・細則として大学規程集に収録されており、学校法人側の規程やそれとのハイブリッドではない。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_review_body', 'established', '大学発ベンチャー認定委員会（学長は戦略企画会議も経る）', '認定規程第4条第1項で認定を審議するため大学発ベンチャー認定委員会を置き、第5条第2項で学長が認定委員会及び戦略企画会議の議を経て認定を決定する。大学発ベンチャー認定委員会細則第2条で認定、認定の取消し、支援事業、提出された事業報告書及び収支決算書の確認を審議し学長へ答申。第3条で委員は研究推進アドミニストレーションセンター長（委員長）、同センター産学官連携推進室長、同センターのリサーチ・アドミニストレーターのうち必要と認めた者、人事課長、研究推進課長ほか。第4条で3分の2以上の出席と出席委員の過半数で議決。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/561.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_equity_decider', 'established', '取得は学長（審査会答申）、処分は財務担当理事', '新株予約権の取得等に関する規程第5条第1項で学長が取得の可否等を新株予約権取得等審査会に諮問し、審査会は事業計画、財務内容、経営体制及び技術的能力、資金計画及び経営戦略、取得の説明可能性、利益相反を審議して答申する。第6条で学長が答申を受け取得を決定し契約を締結。第4条第2項で審査会は研究推進アドミニストレーションセンター長、産学官連携推進室長、財務課長、研究推進課長等で構成。取得後は管理規程第3条で管理責任者を財務担当理事とし、第4条で権利行使と株式売却の決定、未上場で上場見込みがない場合等は審査会の意見を聴く。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.tut.ac.jp/gakusoku/rule/776.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_amendment_decider', 'established', '戦略企画会議の議を経て学長（細則は別建て）', '認定規程第13条で「この規程の改廃は，国立大学法人豊橋技術科学大学の規則の種類及び制定等に関する規程（平成16年度規程第1号）の規定により，戦略企画会議の議を経て学長が行う」と定める。新株予約権の取得等に関する規程第9条、同管理規程第8条、イノベーション施設規程第21条も同一の定め。下位の細則は別で、大学発ベンチャー認定委員会細則第7条は「研究推進アドミニストレーションセンター会議の議を経て学長が行う」と定める。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_post_grad_limit', 'established', '1年以内（他の職に就かない場合は期間の定めなし）', '認定規程第2条第3号。本法人の職員又は学生（過去に職員又は学生であった者を含む）が設立者となる又は設立に深く関与する等して起業したものを対象とし、括弧書で「ただし，職員又は学生が退職，卒業等した場合については，当該ベンチャー企業設立まで他の職に就かない又は退職，卒業等から起業までの期間が1年以内に限る」と定める。2要件は選択的で、退職・卒業から設立まで他の職に就いていなければ1年を超えても対象になりうる。第3条第5号で職員であった者は在職中の所要の手続・許可が適正になされていることを要する。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_renewal_rule', 'established', '更新不可・再申請（3年経過後に再申請可）', '認定規程第6条第2項は称号を3年間使用できるとし、ただし書で「再申請することを妨げないものとする」と定めるのみで、更新申請、更新審査、期間延長の条文は置かれていない。再申請する場合は第5条の認定手続（大学発ベンチャー認定申請書を必要書類とともに学長へ提出、認定委員会及び戦略企画会議の議、学長の決定と文書通知）を改めて経ることになり、第3条の申請要件も再度満たす必要がある。届出のみで継続できる仕組みではない。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_naming', 'established', '大学発ベンチャー（称号は豊橋技術科学大学発ベンチャー）', '規程名は「国立大学法人豊橋技術科学大学における大学発ベンチャーの認定に関する規程」で、第2条が「大学発ベンチャー」を定義する。第6条第1項で学長が称号記（別記様式2）により「豊橋技術科学大学発ベンチャー」の称号を授与し、第2項で3年間使用できる。大学公式サイトの一覧ページも「豊橋技術科学大学認定大学発ベンチャー」の名称。規程、様式名、公式ページのいずれにも「スタートアップ」を用いた称号は使われていない。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_support_period', 'established', '支援ごとに別に定める（称号3年、施設3年＋延長可）', '称号は認定規程第6条第2項で3年間。支援は第11条第1項柱書で認定委員会が管理運営及び教育研究に支障のないと認める範囲で行い認定通知書（別記様式5）で通知され、第2項で「本法人における関係規則等によるものとする」と定めるため、期間は各支援の規則による。イノベーション施設は施設規程第11条第1項で3年以内、施設長が特に必要と認めた場合に1年単位2年を限度で延長でき、第2項でさらに1年単位の延長も可能。称号の3年と施設の使用期間は別々に決まる。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_support_contents', 'established', '施設貸与・商業登記・設備使用・経営相談・企業紹介・広報・新株予約権化・学長裁量', '認定規程第11条第1項の8号。(1)事務室又は研究室としてイノベーション施設等を学内料金で貸与、(2)貸与した施設を大学発ベンチャーの所在地とする商業登記を認める、(3)本法人所有の研究設備等を学内料金で使用させる、(4)本法人に所属する職員又は学生が起業及び起業後の経営等に関する相談業務に対応、(5)職員又は学生による他企業への紹介又は仲介、(6)本法人が主催又は参加するイベント、広報誌又はホームページ等での広報、(7)知的財産権のライセンス等の対価の全部又は一部を新株予約権とすること、(8)その他学長が必要と認めること。資金の供与は列挙にない。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_ec744e776766', 'attr_source_docs', 'established', 'https://www.tut.ac.jp/gakusoku/rule/560.html・https://www.tut.ac.jp/gakusoku/rule/561.html・https://www.tut.ac.jp/gakusok…', '制度の中心は認定規程（令和元（2019）年6月19日規程第7号、大学規程集第8章）で、定義、申請要件、認定手続、称号、報告、解除・取消、支援8項目、事務、改廃を一本で定める。審査体制は大学発ベンチャー認定委員会細則（同日細則第3号、第3章）。株式性の対価は新株予約権の取得等に関する規程（令和4（2022）年規程第2号）と同管理規程（規程第3号）。施設と商業登記はイノベーション施設規程（令和2（2020）年規程第43号）と使用細則、認定企業一覧は大学公式ページ。', 'official', 'https://www.tut.ac.jp/gakusoku/rule/560.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_cert_update', 'established', '授与日から5年後の年度末まで、期間終了1か月前申請で更新可', '称号授与規則第5条第2項で横浜国立大学発ベンチャーの称号授与期間は授与した日から5年後の年度末までとし更新可、この場合第2条第1項第2号ただし書き（退職・卒業後3年以内）は適用しない。第3項で学生ベンチャーは学生の在学期間とし、在学期間を延長等した場合はその範囲で更新可。第4項で更新は期間終了の1か月前までに様式第5号により学長へ申請し、その審査は第4条第2項から第4項（研究推進機構運営会議への付議・審議・学長決定）を準用。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_title_restriction', 'established', '品質を保証しない旨の免責、取消後の称号使用禁止と称号記返付', '称号授与規則第9条第1項で本学は認定ベンチャーの製品、サービス等の内容及び品質を保証しないと定め、第2項で称号の授与又は取消しにより認定ベンチャー又は第三者に損害が生じても賠償義務を負わないとする。第7条第2項で取消しを受けた企業は速やかに称号記を返付し、取消日以後は称号を使用してはならない。第3条で称号は2種に限定。投資推奨や経営状態の保証と誤認させない旨の条項、広告・表示での称号使用範囲を定める細則は規則本文に無く、第12条で必要事項は別に定めるとするにとどまる。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_cancellation', 'established', '取消事由5号、称号記の返付、取消日以後の称号使用禁止と公表', '称号授与規則第7条第1項の取消事由は、本学又は当該企業の社会的信用を失墜させる行為、第6条第1項の事業報告書等の未提出又は同条第2項の報告があったとき、称号の辞退の申出、学生ベンチャーで発起人若しくは中心的役割の学生全員が卒業等により学生の身分を失ったとき、その他称号を保持させることが適当でないと学長が認めたときの5号。第2項で速やかに称号記を返付し取消日以後は称号を使用できない。第8条で取消しをホームページへの掲載等により公表。表示削除や営業利用停止の個別手続の定めは無い。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_report_change', 'established', '毎年度決算日から3月以内の事業報告、解散・破産等は随時報告', '称号授与規則第6条第1項で認定ベンチャーは毎年度、決算日から3月以内に様式第6号並びに事業報告書及び財務諸表等の財務状況を示す書類により学長へ活動内容を報告する義務。第2項で会社法の解散、破産手続開始決定、民事再生手続開始決定、会社更生手続開始決定、不正競争防止法第21条又は第22条の行為による有罪確定に該当したときは代表者又は清算人が速やかに学長へ報告。第7条第1項第2号でこれらを取消事由とする。代表者・所在地・資本構成の変更届は規則本文に定めが無い。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_support_request', 'established', '施設使用と株式等収納は個別申請・審査、称号付随の支援は様式なし', '称号授与規則第10条の支援は称号に付随する配慮として定められ、ロゴマーク使用・商業登記・知的財産権等の使用配慮に個別の申請様式は無い。施設は産学官連携研究施設使用規則第5条で別紙様式1の使用申請書を研究推進機構長へ提出し、第6条・第7条で産学官連携研究施設使用審査委員会の議を経て機構長が承認、第3条第6号・第7号の申請は毎年1月末日締切。知財等の対価を株式で収める場合は株式等取扱規則第4条で別記様式第1号により学長へ申請し研究推進機構運営会議の審議を経る。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2025/04/産学官連携研究施設使用規則R7.3.27（様式あり）.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_facility_registration', 'established', '起業後5年以内は実験室等を有償使用、同施設で商業登記可', '産学官連携研究施設使用規則第3条第6号が起業予定の教職員、第7号が本学シーズを基に設立した起業後5年以内のベンチャー企業の起業者を申請資格とする。対象は共同研究推進センター棟と総合研究棟E棟1階・2階の実験室等。第4条で使用期間は1年以内かつ年度末まで、2回まで更新（機構長が特別の事由を認めた場合4回まで）。第9条で使用料は同第6号・第7号につき3年度未満が1平米当たり月額700円、3年度以上5年度以下が同2,000円。称号授与規則第10条第3号で本学施設を所在地とする商業登記を認め、退去時は登記場所変更を示す書面の提出を求める。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2025/04/産学官連携研究施設使用規則R7.3.27（様式あり）.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: NEDO覚書は当該URLに記載なく別ページ依拠］元の主張(established): 自治体・金融機関の支援制度の案内とNEDO起業家支援覚書。成長戦略教育研究センター「その他の支援情報」ページが外部のベンチャー支援プログラムとして、神奈川県ベンチャー支援情報ポータル、KSAP、HATSU鎌倉、SHINみなとみらい、横浜市のSTART UP PORT YOKOHAMA、YOXO BOX／YOXO NEXT、TECH HUB YOKOHAMA、横浜銀行の創業・ベンチャー支援、神奈川産業振興センター、かながわサイエンスパークを案内。大学案内ページによればNEDOと2024年9月30日に起業家支援の相互協力覚書を締結。ベンチャーキャピタルや投資家への個別紹介を定めた規程は確認できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_eir', 'unknown', null, '称号授与規則、認定ベンチャー株式等取扱規則、産学官連携研究施設使用規則の全条文と、研究推進機構の大学発ベンチャー／学生ベンチャーページ及び称号授与企業一覧ページ、成長戦略教育研究センターのベンチャービジネス関連3ページを通読したが、客員起業家（Entrepreneur in Residence）、起業家メンター、起業家人材の招聘を定めた制度の記載は無かった。検索で表示される客員起業家募集は横浜市立大学の制度であり本学のものではない。', 'official', 'https://www.cseg.ynu.ac.jp/vb/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_cxo_pool', 'unknown', null, '研究推進機構と成長戦略教育研究センターの公開ページに、経営人材（CEO／CXO候補）の紹介・マッチングを行う制度の記載は無い。成長戦略教育研究センターの支援はフェーズⅠ（学部学生から博士課程後期学生・ポストドクター、活動経費最大10万円）とフェーズⅡ（法人設立を計画する大学院生・ポストドクター・教員、活動経費最大30万円）の2段階で、外部とのアライアンス探索は含むが経営人材の紹介は挙げていない。大学案内の2021年10月25日発表はGTIEの起業活動支援に経営者人材とのマッチングを挙げるが、本学は協力機関としての参画で当時は設置予定の記載。', 'official', 'https://www.cseg.ynu.ac.jp/vb/support/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_ip_equity', 'established', '知財の実施許諾等の対価を株式・新株予約権で収納可', '認定ベンチャー株式等取扱規則（令和3年3月17日規則第27号）第2条第3号が収益を伴う事業を、知的財産権に係る譲渡及び実施権の設定・実施許諾・使用許諾、研究成果有体物の提供及び使用許諾、学長が必要と認めた事業と定義。第2条第4号で株式等は株式及び新株予約権。第3条で対価相当の現金を保有しない、現金支払で資金繰りに窮する、経営に重要な影響を及ぼす、その他審議を経て学長が認めたときに対価を株式等で収納できる。第5条で契約書を取り交わして取得。第10条第2項で発明者等が当該企業の取締役・役員等として経営に深く関与する場合は補償金を支払わない。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'pol_fund_investment', 'unknown', null, '認定ベンチャー株式等取扱規則は第1条・第3条のとおり知的財産権等の対価を現金に代えて株式等で収納する場合の取扱いに限られ、大学から企業やファンドへ資金を出す規定は置いていない。研究推進機構の大学発ベンチャー／学生ベンチャーページ、称号授与企業一覧ページ、成長戦略教育研究センターのベンチャービジネス関連ページにも、大学系ベンチャーキャピタルの設立、産業競争力強化法に基づく認定ベンチャーキャピタルへの出資、LP出資、指定ファンド、大学出資会社経由の投資に関する記載は無かった。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_regulation_owner', 'established', '大学規程。国立大学法人横浜国立大学の規則として制定', '認定制度の根拠は国立大学法人横浜国立大学発ベンチャー称号授与規則（令和3年3月17日規則第26号、令和5年3月22日規則第38号改正、令和3年4月1日施行）で、国立大学法人横浜国立大学が定める法人規則。株式等の取扱いは認定ベンチャー株式等取扱規則（令和3年規則第27号）、施設は産学官連携研究施設使用規則（平成24年規則第134号、令和7年規則第44号改正）が定め、いずれも同じ法人規則の体系にある。称号授与規則第11条で事務は研究・学術情報部産学・地域連携課が処理する。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_review_body', 'established', '国立大学法人横浜国立大学研究推進機構運営会議', '称号授与規則第4条第2項で学長は申請を国立大学法人横浜国立大学研究推進機構運営会議に付議し、第3項で同運営会議が審議して結果を学長へ報告、第4項で学長が認定又は不認定を決定。第5条第4項により更新申請の審査も同手続を準用。株式等取扱規則第4条第2項・第3項でも同運営会議が審議主体。施設は産学官連携研究施設使用規則第7条の産学官連携研究施設使用審査委員会が担い、委員は研究推進機構長（委員長）、産学官連携推進部門長、研究支援室長、産学官連携支援室長、知的財産支援室長、研究・学術情報部長ほか。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_equity_decider', 'established', '学長。研究推進機構運営会議の審議と経理責任者の承認を経る', '認定ベンチャー株式等取扱規則第4条。第1項で認定ベンチャーの代表者が別記様式第1号の株式等による収益事業対価支払申請書により学長へ申請、第2項で学長が研究推進機構運営会議へ付議、第3項で同運営会議が収納方法について経理責任者の承認を得たうえで審議し学長へ報告、第4項で学長が承認又は不承認を決定。第6条で新株予約権の行使が可能となったときは同運営会議で行使の適否を審議したうえで行使し、権利の変更又は処分（放棄を含む）を求められた場合も同運営会議の審議による。第9条でインサイダー取引管理責任者は学長が別に指名する理事又は副学長。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学における認定ベンチャーを対象とした収益を伴う事業の対価として取得する株式等取扱規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_amendment_decider', 'unknown', null, '称号授与規則は第12条の雑則で認定ベンチャーの称号に関し必要な事項は別に定めるとするのみで、規則自体の制定改廃を決める主体の定めが無い。認定ベンチャー株式等取扱規則第11条も同様。国立大学法人横浜国立大学役員会規則第3条の審議事項は、中期目標についての意見及び年度計画、文部科学大臣の認可又は承認を要する事項、予算の作成及び執行並びに決算、大学・学部・学科その他の重要な組織の設置又は廃止、その他役員会が定める重要事項で、規則の制定改廃を明示していない。組織運営規則第8条も各会議の必要事項は別に定めるとするにとどまる。', 'official', 'https://somu-somu.ynu.ac.jp/gakugai/kisoku/act/print/print110000005.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_post_grad_limit', 'established', '3年以内。ただし称号期間の更新時は適用しない', '称号授与規則第2条第1項第2号ただし書きで、本学を退職又は卒業・修了後に起業した場合は退職又は卒業・修了後3年以内に限ると定める。対象は本学の役員若しくは教職員（過去に役員又は教職員であった者を含む）又は過去に本学の学生であった者が発起人又は起業時に中心的な役割を担い、本学で得られた研究成果又は本学で修得した技術等を活用している場合。第5条第2項により称号授与期間の更新時にはこのただし書きを適用しない。第2条第2項で学長が特に認めた企業は同項の資格によらず申請できる。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_renewal_rule', 'established', '更新可（審査あり）。期間終了1か月前までに様式第5号で申請', '称号授与規則第5条第4項で、称号の授与期間を更新しようとする者は期間終了の1か月前までに称号授与期間更新申請書（別記様式第5号）により学長へ申請しなければならないと定め、更新申請の審査は第4条第2項から第4項（研究推進機構運営会議への付議、同会議の審議と学長への報告、学長の認定又は不認定の決定）を準用する。第2項で更新時は第2条第1項第2号ただし書きを適用しない。第3項で学生ベンチャーは在学期間を延長等した場合にその範囲で更新できる。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_naming', 'established', '大学発ベンチャー。学生のみ該当時は横浜国立大学発学生ベンチャー', '称号授与規則第3条で授与する称号は横浜国立大学発ベンチャーとし、第2条第1項各号の申請資格のうち第3号（本学の学生が発起人又は起業時に中心的な役割）のみに該当する場合は横浜国立大学発学生ベンチャーとする。第6条で両者を総称して認定ベンチャーと定義。第5条第1項で称号記（別記様式第3号・第4号）の交付をもって授与する。研究推進機構の称号授与企業一覧ページもYNU大学発ベンチャーとYNU大学発学生ベンチャーの2区分で掲載し、2026年7月1日現在19社。スタートアップの語を用いた称号は置いていない。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_support_period', 'established', '支援ごとに別に定める。称号5年に対し施設は年度単位で更新', '称号授与規則第5条第2項で称号授与期間は授与日から5年後の年度末まで。これに対し産学官連携研究施設使用規則第4条は使用期間を1年以内かつ年度末までとし更新は2回（機構長が特別の事由を認めた場合4回）まで、第3条第7号で申請資格自体を起業後5年以内に限る。第9条の使用料も使用開始日から3年度未満と3年度以上5年度以下で単価が変わる。株式等の収納は株式等取扱規則第4条の個別申請と第5条の契約に基づき、称号期間と連動する定めは無い。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2025/04/産学官連携研究施設使用規則R7.3.27（様式あり）.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_support_contents', 'established', 'ロゴマーク使用・施設と研究用機器の貸付・商業登記・知財使用配慮', '称号授与規則第10条は、大学の管理運営及び教育研究に支障のない範囲で行う支援として、認定ベンチャーロゴマークの使用を認めること、本学の産学官連携研究施設又は本学の研究用機器等の貸付に配慮すること、本学の施設において当該認定ベンチャーの所在地とする商業登記を認めること、本学が所有する知的財産権又は研究成果等の使用に配慮すること、その他学長が必要と認めることの5号を掲げる。研究推進機構の称号授与企業一覧ページは支援をベンチャーシンボルマーク提供、大学施設等使用、商業登記の配慮、大学所有の知的財産・研究成果物等の専用実施等への支援と記載。', 'official', 'https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横浜国立大学発ベンチャー称号授与規則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_e99c8b4b8a8a', 'attr_source_docs', 'established', 'https://www.ripo.ynu.ac.jp/company/sangakukan/ynuventure/・https://www.ripo.ynu.ac.jp/wp-content/uploads/2023/04/国立大学法人横…', '1本目は研究推進機構の称号授与企業一覧ページで、支援メニュー、様式第1号から第6号、認定企業一覧（2026年7月1日現在19社）と規則PDFへの導線を持つ制度の入口。2本目は称号授与規則（令和3年規則第26号）で申請資格、審査主体、称号期間と更新、報告義務、取消し、免責、支援5号を定める中心文書。3本目は認定ベンチャー株式等取扱規則（令和3年規則第27号）で知財対価の株式・新株予約権による収納を定める。施設は産学官連携研究施設使用規則のPDFが別にある。', 'official', 'https://www.ripo.ynu.ac.jp/company/sangakukan/ynuventure/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_cert_update', 'unknown', null, '認定期間・更新可否・更新審査・要件再確認を定めた公開記載は確認できなかった。研究ポータル「大学発スタートアップ創出支援」の注記は「称号付与以外の支援については、支援期間中に限ります」とするのみで、称号自体の有効期間と更新手続には触れていない。本学発・認定企業一覧も「支援開始年月」だけを掲げ、終期・更新時期を示していない（2016年8月開始の企業が2026年9月時点でも掲載）。認定規程本文と申請手続は学内専用サイトに置かれ、外部からは403で閲覧できない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_title_restriction', 'unknown', null, '称号の使用範囲、使用停止、品質保証・投資推奨・経営状態保証と誤認させないための条項は、研究ポータルの大学発スタートアップ創出支援ページにも、公開されている関連規程（研究・産学連携推進センター設置規程、土地・建物長期貸付要領、定款、業務方法書）にも見当たらない。同ページは「本学の商標使用」を支援内容に挙げるのみで、商標の様式・表示方法・承認手続・免責の記載はない。称号使用条件を含む認定規程本文は学内専用サイトに限定されている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_cancellation', 'unknown', null, '認定の取消事由、称号の返付、表示削除、営業利用の停止を定めた公開記載は確認できなかった。研究ポータルの支援ページには認定の解除・取消に関する記述がなく、認定企業一覧も掲載終了の扱いを示していない。なお施設側の土地・建物長期貸付要領第9条は、使用者の責に帰すべき事由で貸付を取消した場合に貸付料を返還しないと定めるが、これは施設貸付の取消であって称号の取消ではない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_report_change', 'unknown', null, '年次報告、代表者・所在地・資本構成の変更届、解散時報告を求める公開記載は確認できなかった。研究ポータルの支援ページは認定後の報告義務に触れていない。土地・建物長期貸付要領第10条第3項は貸付料調整の判断材料として「貸付更新においては、使用状況と経営状況」をもとにするとし、施設を借りる場合に経営状況の提出が生じることは読み取れるが、認定ベンチャー全体に課される定期報告の制度ではない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_support_request', 'established', '施設貸付は別途申請書と審査、知財使用は事前協議', '施設は認定とは別の手続を持つ。土地・建物長期貸付要領第5条第2項が「公立大学法人横浜市立大学土地・建物長期貸付申請書」（別紙様式）の提出を求め、資力・信用・技能等を十分考慮して審査すると定め、同条第3項で理事長が使用者と契約を締結する。同第6条は更新時も同じ申請書と審査を要し、賃貸借は満了6か月前、使用貸借等は3か月前までの提出を課す。知財は研究ポータルの支援ページ注記が「知的財産権、ノウハウ等を使用する場合、申請の事前相談時にヒアリングを行い協議します」とする。登記住所・機器・広報の個別申請様式は公開されていない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/opilab/gjok7g0000001o94-att/a1754459180825.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_facility_registration', 'established', '居室・研究室の長期貸付と法人登記上の住所使用', '研究ポータルの大学発スタートアップ創出支援ページが、支援内容として「本学土地・建物長期貸付料（居室・研究室長期貸付）の優遇措置」と、本文で「法人登記上の住所使用」を明記し、施設利用と商業登記の両方を公式に掲げている。施設側の根拠は土地・建物長期貸付要領で、第2条が1月以上を長期と定義、第7条が賃貸借5年以内・使用貸借等3年以内、第8条第1項が有償原則、第10条第2項第5号が「本法人の教育・研究事業に密接な関係を有する企業又は団体」への2分の1を限度とする減額を定める。受け入れる建物・住所と手数料の細目は非公開。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_vc_connection', 'established', '外部有識者・ベンチャー支援者の紹介と個別相談', '研究ポータルの支援ページが支援内容として「外部有識者（市大卒の税理士、ベンチャー支援者等）のご紹介、個別相談の実施」を明記する。オフィスアワーのページも「外部連携に関する助言等も含め、実践的な伴走支援の場」と説明し、研究・産学連携推進センター スタートアップ推進部門が第2・第4水曜に開設している。同ページはベンチャー関連サイトとしてKANAGAWA STARTUPS、K-NIC、AMEDぷらっと、GTIE、NEDO、MEDISOへリンクする。ただしVC・金融機関を名指しした紹介制度や出資交渉の仲介手続は公開されていない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_eir', 'established', '客員起業家（EIR）を業務委嘱で招聘、概ね6か月', '客員起業家（Entrepreneur in Residence：EIR）募集ページが制度内容を公開している。目的は研究開発型スタートアップ創出の強化で、研究者と協働し経営候補人材として事業化を推進する役割。募集人数は2名（医学群1名、国際総合科学群1名）、「雇用契約ではなく、依頼書・委嘱状に基づく業務委嘱」、契約期間は「概ね6か月間を基本」とし6か月時点で更新の可否を判断する。応募先は研究推進部研究・産学連携推進課。2026年8月19日に募集終了と表示されている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/eir_startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_cxo_pool', 'drafting', '経営チーム組成の環境整備を推進中、EIRが経営候補人材', '名簿型の経営人材プールやマッチング制度は公開されていない。研究ポータルの支援ページは「今後は大学で学術的な研究に取り組んできた研究者と企業で事業開発に取り組んできた経営者候補のように異質な経験をしてきた人々が、対話し、共創するためのコミュニティづくりを進めて、大学発スタートアップの経営チームの組成や資金調達の実施がしやすい環境づくりに取り組んでいきます」と、これからの取組として記す。現時点で経営候補人材を充てる仕組みは客員起業家（EIR）だけで、EIR募集ページは「既存の大学発スタートアップに経営候補者として参画する場合」も想定に含めている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/venture_entrepreneur.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_ip_equity', 'not_started', '知財対価としての株式・新株予約権の定めなし', '公立大学法人横浜市立大学定款第22条（業務の範囲）は6号の限定列挙で、大学の設置経営、学生支援、受託・共同研究等の連携活動、公開講座、教育研究成果の普及・活用促進、附帯業務のみを掲げ、株式・新株予約権の取得を業務としていない。業務方法書も第27条で定款第22条の業務の一部委託を定めるにとどまり、持分取得に触れない。研究ポータルの支援ページの知財条項は「知的財産権、ノウハウ等の使用に関する優遇措置」と、事前相談時のヒアリング・協議を示すだけで、対価を株式で受ける選択肢は挙げられていない。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/teikan/tt534t0000000646-att/teikan250314.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'pol_fund_investment', 'not_started', '大学ファンド・LP出資の定めなし（業務の範囲外）', '定款第22条の業務の範囲は限定列挙で、研究成果活用事業者への出資、ファンド組成、LP出資、大学出資会社の設立を含まない。業務方法書（平成30年4月1日横浜市長認可）も同第27条で定款第22条の業務の一部委託を定めるのみで、出資規定を置いていない。研究ポータルの支援メニューにもファンドは無く、外部資金はGTIE経由のGAPファンド申請支援にとどまる。なおJ-PEAKSのスタートアッププロデューサー記事には「いずれは横浜市立大学独自のファンド立ち上げ」を目指すという本人の将来目標が載るが、制度化の検討段階を示す公式記載ではない。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/gyomuhouhousyo/tt534t0000000650-att/kitei00_02_180401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_regulation_owner', 'unknown', null, '［自動検証で否認: 規程名・法人規程との位置づけは典拠ページに記載なし］元の主張(established): 大学規程（公立大学法人横浜市立大学の法人規程）。認定の根拠規程名は「公立大学法人横浜市立大学発ベンチャーの支援に関する規程」で、設置者である公立大学法人が定める法人規程にあたる。同規程の存在は利益相反マネジメント規程第3条第4号が同規程第2条（対象企業等）・第4条（本学の支援）を引用することで確認できる。関連規程も法人名義（公立大学法人横浜市立大学利益相反ポリシー、同土地・建物長期貸付要領）と大学名義（横浜市立大学研究・産学連携推進センター設置規程）が併存するが、認定規程自体は法人規程。私立の学校法人規程や大学外の研究機関規程ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_review_body', 'established', '研究・産学連携推進センター スタートアップ推進部門（所管）', '横浜市立大学研究・産学連携推進センター設置規程（平成31年4月1日規程第53号、最近改正 令和8年6月1日規程第56号）第2条第7号が「アントレプレナーシップ教育及び大学発スタートアップ創出に関すること」を、第4条第7号が「スタートアップ推進部門」を掲げる（いずれも令和7年8月1日から適用）。部門長・副部門長はセンター長が指名し、センター長は学長が指名（第3条第2項、第4条第2項）。庶務は研究推進部（第9条）、窓口は研究推進部研究・産学連携推進課。第7条第2項のセンター会議の協議事項は部門間調整・特任教員等の受入・客員教員の称号付与で、ベンチャー認定審査は含まない。認定審査会の設置は公開されていない。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/kitei_nolimit/dr3e640000014q0f-att/kitei11_05_260601.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_equity_decider', 'not_started', '決裁者の定めなし（株式取得の制度自体が不存在）', '定款第22条（業務の範囲）が6号の限定列挙で株式・新株予約権の取得を含まず、第24条の資本金も横浜市からの出資を定めるにとどまるため、取得・処分の決裁者を置く前提がない。業務方法書にも持分の取得・処分に関する意思決定手続はなく、第8条が業務執行に係る意思決定と経費支出の承認手順の明確化を一般的に求めるのみ。研究ポータルの支援メニューにも株式・新株予約権は挙げられていない。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/teikan/tt534t0000000646-att/teikan250314.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_amendment_decider', 'established', '理事長（重要な規程は経営審議会が審議）', '定款第17条第3号が、経営審議会の審議事項として「重要な規程の制定及び改廃に関する事項」を明記する。経営審議会は理事長、副理事長及び理事で構成し（定款第14条第2項）、理事長又は理事長が指名する者が議長を務める（同第16条第1項）。経営審議会規程第7条も「経営審議会の議を経て、理事長が別に定める」と規定し、制定主体が理事長であることを示す。実際の規程は「規程第56号」のように法人の規程番号で公布されている。教育研究に関する事項は定款第21条により教育研究審議会が審議する。', 'official', 'https://www.yokohama-cu.ac.jp/univ/corp/teikan/tt534t0000000646-att/teikan250314.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_post_grad_limit', 'established', '3年以内（人材活用型、退職・卒業・修了後）', '研究ポータルの大学発スタートアップ創出支援ページ「※称号」欄の人材活用型の要件に「本学の教職員等又は学生等であった者が、退職、卒業又は修了の後、原則として３年以内にベンチャー企業等の設立者となる、若しくはその設立に深く関与するものであり、在学中に受講した講義、実習、課外活動、または大学環境から得た経験や発想を契機として起業に至ったもの」と明記。研究成果活用型には年数の要件がなく、本学で達成された研究成果や本学の教職員等・学生等が所有する知的財産権に基づくことを要件としている。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_renewal_rule', 'unknown', null, '称号の更新可否と方法を定めた公開記載は確認できなかった。研究ポータルの支援ページは称号の期間・更新に触れず、認定企業一覧も支援開始年月のみを示す。認定規程本文と申請手続は学内専用サイトに置かれ外部から閲覧できない。なお土地・建物長期貸付要領第6条は施設貸付契約の更新手続（申請書の再提出と審査、賃貸借は満了6か月前まで）を、同第7条は既存契約の始期から賃貸借5年・使用貸借等3年を超えて更新できないことを定めるが、これは施設契約の更新であって称号の更新ではない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_naming', 'established', '大学発ベンチャー（横浜市立大学発認定ベンチャー）', '称号は「横浜市立大学発認定ベンチャー（研究成果活用型）」「横浜市立大学発認定ベンチャー（人材活用型）」の2区分で、研究ポータルの支援ページ本文、支援内容の一覧、認定企業一覧のいずれもこの表記を用いる。一方、制度名・ページ名・所管部門名は「大学発スタートアップ創出支援」「スタートアップ推進部門」とスタートアップの語を使っており、称号（ベンチャー）と制度名（スタートアップ）で語が異なる。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_support_period', 'established', '支援ごとに別に定める（称号付与以外は支援期間中）', '研究ポータルの支援ページ注記が「称号付与以外の支援については、支援期間中に限ります」と明記し、称号と支援の期間を分けている。個々の支援の期間は各制度側で決まり、施設は土地・建物長期貸付要領第7条で賃貸借契約5年以内・使用貸借等3年以内、第6条で更新時に申請書の再提出と審査を求める。知的財産権・ノウハウの使用は同ページ注記により申請の事前相談時のヒアリングと協議で定まる。支援期間そのものの長さと起算点は公開されていない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_support_contents', 'unknown', null, '［自動検証で否認: オフィスアワーは支援内容欄になくニュース欄のみ］元の主張(established): 称号付与・商標使用・研究設備機器の優遇・土地建物長期貸付料の優遇・法人登記上の住所使用・知的財産権ノウハウ使用の優遇・外部有識者の紹介と個別相談・創出ナビゲーションセミナー・GAPファンド申請支援・オフィスアワー。研究ポータルの大学発スタートアップ創出支援ページ本文と「横浜市立大学の支援内容」の箇条書きに列挙されたもの。称号付与は研究成果活用型・人材活用型の2区分。注記により、優遇措置は利益相反等の観点から無償ではなく一定程度の費用を徴収し、知財・ノウハウ使用は申請の事前相談時にヒアリングして協議し、称号付与以外の支援は支援期間中に限る。オフィスアワーは第2・第4水曜13時から15時、横浜ランドマークタワー7階で、起業・事業化、GAPファンド申請準備、研究成果の社会実装、起業後の経営・運営の相談に対応する。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_85fe74ab12b9', 'attr_source_docs', 'established', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html・https://www.yokohama-cu.ac.jp/univ/corp/kitei_…', '1本目の研究ポータル「大学発スタートアップ創出支援」が、称号2区分の要件、支援メニュー、有償・支援期間の注記、認定企業一覧を載せる唯一の公開一次資料。2本目の研究・産学連携推進センター設置規程（最近改正 令和8年6月1日規程第56号）が所管事項とスタートアップ推進部門の設置根拠。3本目の定款が業務の範囲（第22条）と経営審議会の審議事項（第17条）を定め、出資・株式取得の可否と規程改廃の決裁を判断する根拠になる。補助として土地・建物長期貸付要領と客員起業家募集ページがある。認定規程本文と申請手続は学内専用サイトにあり外部からは403で閲覧できない。', 'official', 'https://www.yokohama-cu.ac.jp/res-portal/collaboration/univ_venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_cert_update', 'not_started', '称号の有効期間・更新審査の定めなし', '「公立大学法人会津大学の研究成果等を活用したベンチャーへの称号の授与について」（平成24年4月1日適用・施行）は第1目的、第2称号、第3申請資格、第4申請、第5選考、第6称号記の授与等、第7称号授与の取消し、第8本学からの支援、第9雑則で構成され、認定期間、更新可否、更新審査、要件の再確認を定める条はない。会津大学における起業支援に関する規程（reg142）にも称号の期間の定めはなく、第7条の取消しがあるまで存続する立て付け。期間と更新が定められているのは施設側で、会津大学産学イノベーションセンター使用規程第7条が1許可1年以内・年度ごと更新と定める。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_title_restriction', 'established', '法的責任の不負担条項のみ。使用範囲・停止の定めなし', '称号の授与について第6第2項が「本学は、前項の称号を授与したことにより法的責任を負うものではない。」と定め、これが唯一の免責条項。第3のただし書は「会津大学として称号を授与するにふさわしい事業内容であり、社会規範に反しないものに限る」と申請資格を絞る。品質保証・投資推奨・経営状態の保証と誤認させない旨の条項、称号の使用範囲や使用停止の手続は、同定めにも起業支援に関する規程（reg142）にも見当たらない。第8は学長が学内外のイベントやセミナー等を通じて称号を授与したベンチャー企業である旨をPRすると定める。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_cancellation', 'established', '取消事由と称号記の返還を規定。表示削除の定めなし', '称号の授与について第7は、称号を授与された者が社会的信用を失墜する行為や公序良俗に反する行為を行った場合、その他称号を保持させるに値しないと学長が判断した場合に、称号の授与を取消し、称号記を返還させると定める。起業支援に関する規程（reg142）第7条は支援決定の取消事由を五号列挙し、社会的信用の失墜または公序良俗違反、事業活動の実態消滅、本人からの取消申出、第6条の事業報告の不履行、その他継続が適当でないとセンター長が認めた場合とし、第2項で学長への報告を義務づける。取消後のウェブ表示削除や称号の営業利用停止の手続は定めがない。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_report_change', 'established', '事業報告の請求権と申請時の営業報告書。変更届なし', '起業支援に関する規程（reg142）第6条は、UBICセンター長が称号付与・研究開発室・UBICインキュベーションスペース・本学住所での法人登記の支援を受ける者に対し、損益計算書、貸借対照表等の提出などの事業報告を求めることができると定め、復興創生支援センター長にも準用する。第7条第4号で事業報告を行わなかった場合は支援決定を取り消せる。称号申請書（様式1）の添付書類は、事業概要が分かる資料、法人は登記簿謄本・個人は住民票、営業報告書の3点。代表者・所在地・資本構成の変更届や解散時報告の条項は、称号の授与についてにも同規程にもない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_support_request', 'established', '支援種別ごとに様式申請、センター長が可否決定', '起業支援に関する規程（reg142）第4条は、称号付与・研究開発室・UBICインキュベーションスペース・本学住所での法人登記の支援を受けようとする者はUBICセンター長へ、先端ICTラボのプロジェクトルームとリソースの利用は復興創生支援センター長へ、別に定める様式により申請しなければならないと定める。第5条でセンター長が別に定める場合を除き可否を決定して申請者へ通知し、学長に報告する。称号は「別に定める場合」に当たり、称号の授与について第4・第5により会津大学長へ申請し学長が可否を決定する。広報・紹介については個別申請の定めがない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_facility_registration', 'established', '研究開発室等の使用中に限り本学住所で法人登記可', '起業支援に関する規程（reg142）第3条第6号は、起業者が第2号の研究開発室又は第3号の先端ICTラボのプロジェクトルームを使用するときは、本学の住所地を法人登記の住所として利用することができると定め、登記に関して必要な事項は別に定めるとする。施設側の条件はUBICインキュベーション施設ページが示し、会津大学の教員又は学生が起業した法人（設立後5年以内）又は起業しようとする個人を対象に、毎年度更新で最長3年、教員・学生は最長5年。産学イノベーションセンター使用規程第7条も1許可1年以内・年度更新と定める。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_vc_connection', 'not_started', '制度なし。外部支援機関のリンク集掲載のみ', '起業支援に関する規程（reg142）第3条は本学が行う支援を八号で限定列挙し、VC・金融機関・自治体・外部支援機関への紹介や取次ぎは含まれない。第8号は学部生・院生として在籍する起業者に限り、UBIC専任教員等が経営戦略の相談、事業計画書の作成支援、税理士等の専門家の紹介を行うと定めるにとどまる。UBIC「スタートアップ・起業支援」ページは、福島県内の支援機関、特許関連団体、資金調達関連の公的機関や財団、みちのくアカデミア発スタートアップ共創プラットフォーム等へのリンク集を掲載するが、紹介の手続や窓口は示していない。', 'official', 'https://www.ubic-u-aizu.jp/incubation/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_eir', 'not_started', '客員起業家・起業家人材の招聘制度なし', '起業支援に関する規程（reg142）第3条の八号の限定列挙に、客員起業家（EIR）や起業家メンターの招聘はない。第8号のUBIC専任教員等による起業支援は、学部生又は院生として在籍する起業者を対象に経営戦略の相談、事業計画書の作成支援、専門家の紹介を行うもので、外部の起業家人材を大学に受け入れる制度ではない。UBICトップページ、スタートアップ・起業支援ページ、起業に向けた支援ページ、大学の大学発ベンチャー創出ページのいずれにも、EIRの募集・委嘱・配置に関する記載はない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_cxo_pool', 'not_started', '経営人材プール・CXOマッチング制度なし', '起業支援に関する規程（reg142）第3条の限定列挙に、経営人材の紹介・マッチングはない。第8号で学部生・院生の起業者にUBIC専任教員等が税理士等の専門家を紹介すると定めるが、CEO・CXO候補の人材プールや経営チーム組成の支援ではない。UBICトップページとスタートアップ・起業支援ページにも、経営人材の紹介、人材バンク、副業人材のマッチングに関する記載はない。株式等の取扱規程（reg165）第10条第2項も、大学は議決権等の経営参加権を原則として行使しないと定めており、大学が経営に関与しない設計になっている。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得可（2025年4月施行）', '会津大学における大学発ベンチャーに対する対価として取得する株式等の取扱規程（2025年4月1日施行）第3条は、ライセンス等の相手方が大学発ベンチャーで、対価相当の現金を保有しない、現金払いで資金繰りに窮する、現金払いが経営に重要な影響を及ぼす、その他理事長が認める、のいずれかに該当するとき、対価の一部又は全部を株式等（第2条第3号で株式及び新株予約権）で取得できると定める。第2条第4号は大学発ベンチャーを起業支援に関する規程第2条第1号の起業者と定義。別紙様式1が対価支払申請書。起業支援に関する規程第3条第7号も同規程に基づく措置を求められると規定。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg165_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'pol_fund_investment', 'not_started', '出資・ファンド規程なし。対価としての株式取得のみ', '公立大学法人会津大学の法人規程一覧に、大学VC、認定VC、LP出資、指定ファンド、大学出資会社の設立を定める規程は掲載されていない。株式等の取扱規程（reg165）は第1条の趣旨で「ライセンス等の対価として株式等を取得する場合の取扱い」に限定し、第3条もライセンス等の対価の代替としての取得のみを認めるため、金銭を拠出する出資は対象外。第11条は原則として換金可能な状態になった時点で売却するものとし、保有継続は職務発明審査会の議を経た例外扱い。資金供給面はMASPのみちのくGAPファンドなど外部制度に依存している。', 'official', 'https://www.u-aizu.ac.jp/intro/outline/corporate/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_regulation_owner', 'established', '大学規程（公立大学法人会津大学の法人規程）', '称号の細目は「公立大学法人会津大学の研究成果等を活用したベンチャーへの称号の授与について」（平成24年4月1日適用・施行）で、第9雑則により必要な事項は学長が別に定める。支援本体は会津大学における起業支援に関する規程（平成27年3月31日規程第3号、最終改正2025年4月1日）で、法人規程一覧にreg142として収載。公立大学法人会津大学における法人規程に関する規程（平成18年4月1日規程第57号）第2条第1号が規程を法人の管理運営及び会津大学の教育研究に関する基本事項について理事長が制定するものと定義する。設置形態は公立大学法人で、学校法人ではない。', 'official', 'https://www.u-aizu.ac.jp/intro/outline/corporate/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_review_body', 'established', '学長が称号を選考。支援はUBIC等センター長が決定', '称号の授与について第5（選考）は「学長は、第4の申請があった場合は、称号授与の可否を決定し、当該申請者へ通知するものとする」と定め、認定委員会や審査会は置いていない。起業支援に関する規程（reg142）第5条は、称号付与を含む四つの支援について会津大学産学イノベーションセンター（UBIC）センター長が、先端ICTラボ関係は復興創生支援センター長が可否を決定し学長へ報告すると定める。株式等の取得のみ、株式等の取扱規程第4条第3項により会津大学職務発明審査会が審査を行う。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_equity_decider', 'established', '理事長が決定。会津大学職務発明審査会が審査', '株式等の取扱規程（reg165）第4条は、株式等によるライセンス等の対価支払申請書（別紙様式1）を受けた理事長が財務状況・事業計画等の情報を収集し、取得の可否と取得株式数の妥当性を審査すると定め、第2項で必要に応じ外部専門家から意見を聴取、第3項でその審査を会津大学職務発明審査会において行わせる。第5条で理事長が審査結果を踏まえ取得の可否を決定。第7条第2項は管理責任者を理事（総務・財務担当）とする。第9条第3項・第4項、第10条第1項、第11条第2項は、新株予約権の売却、経済的利益に係る権利行使、保有継続の決定に職務発明審査会の議を要求する。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg165_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_amendment_decider', 'established', '理事長（役員会・経営審議会等の議を経る）', '公立大学法人会津大学における法人規程に関する規程（平成18年4月1日規程第57号、最終改正平成21年4月1日）第2条第1号は、規程を「法人の管理運営及び会津大学の教育研究に関する基本事項について、法令、定款等に基づき、理事長が役員会又は経営審議会、教育研究審議会の議を経て制定するもの」と定義する。同条第2号で規則又は細則は理事長又は各組織の長が制定、第3号で要綱・要項・要領は理事長又は各組織の長が定める。第3条は制定改廃の際に担当課長等が理事長等の決裁後に原議書を事務局総務予算課長へ回付すると定め、第5条は法人ホームページ掲載により公布する。', 'official', 'https://www.u-aizu.ac.jp/files/page/intro/regulations/reg074_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_post_grad_limit', 'established', '期限なし（在籍中かどうかを問わない）', '称号の授与について第3cは、申請資格の一つを「本学の教職員や学生（学部生、院生を問わない。また在籍中であるかどうかは問わない）等がベンチャーの設立者となったり、その設立に深く関与して起業した場合（人材移転型）」と定め、退職・卒業後の年数制限を置いていない。第3第2項のdは本学で学んだ内容をもとに創業した場合、eは本学でベンチャービジネス論等を学んで起業を決意した場合を挙げ、いずれも年限がない。年数が現れるのはfの「県内に設立してから5年程度以内に本学と共同研究等を行った場合」だけで、これは会社設立後の年数であり卒業・退職後の期限ではない。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_renewal_rule', 'established', '期限なし。施設利用のみ1許可1年以内・年度更新', '称号の授与について第1から第9に有効期間と更新の条はなく、第7の取消しがあるまで称号は存続する。起業支援に関する規程（reg142）にも称号の期間の定めはない。更新が定められているのは施設側で、会津大学産学イノベーションセンター使用規程（reg099）第7条が1回の許可を1年以内とし年度ごとの更新、研究開発室の使用期間の上限を教員及び学生は最長5年、その他の使用者は最長3年と定める。UBICインキュベーション施設ページも「毎年度更新、最長3年以内で利用可能」「毎年度更新、最長5年以内で利用可能」と記載する。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_naming', 'established', '大学発ベンチャー（称号「会津大学発ベンチャー」）', '称号の授与について第2は「本学がベンチャー企業に授与する称号は、『会津大学発ベンチャー』とする」と定める。申請様式の標題も『会津大学発ベンチャー』称号申請書。起業支援に関する規程（reg142）第3条第1号も「会津大学発ベンチャーの称号付与」と表記する。公立大学法人会津大学固定資産使用料規則は減免対象を「認証会津大学発ベンチャー」と表記する。UBICのページ名は「スタートアップ・起業支援」でスタートアップの語を用い、同ページの用語集でスタートアップとベンチャーを区別しているが、称号自体にスタートアップの語は使われていない。', 'official', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_support_period', 'established', '支援ごとに別に定める（施設は最長3〜5年）', '起業支援に関する規程（reg142）第3条は八つの支援それぞれについて「…に関して必要な事項は別に定める」と結び、期間を含む細目を支援ごとの個別の定めへ委ねている。称号は有効期間の定めがなく無期限、施設は会津大学産学イノベーションセンター使用規程第7条で1許可1年以内・年度更新、研究開発室の上限は教員及び学生が最長5年、その他の使用者が最長3年。本学住所での法人登記は第3条第6号により研究開発室又はプロジェクトルームを使用する期間に限られる。称号期間と支援期間を一致させる条項はない。', 'official', 'https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 四号UBICインキュベーションスペースが値に欠落］元の主張(established): 称号・研究開発室・LICTiA室・先端ICTラボ・法人登記・知財措置・教員支援。起業支援に関する規程（reg142）第3条が支援を八号で限定列挙する。一 会津大学発ベンチャーの称号付与、二 産学イノベーションセンターの研究開発室の利用、三 先端ICTラボ（LICTiA）のプロジェクトルームの利用、四 UBICインキュベーションスペースの利用、五 先端ICTラボのデータセンタークラウドサービスやサイバーセキュリティウォールーム等のリソースの利用、六 本学の住所を法人登記の住所として利用、七 知的財産権の使用許諾に関する措置（株式等による対価支払と実施料の減免）、八 UBIC専任教員等による起業支援（経営戦略の相談、事業計画書の作成支援、専門家の紹介。学部生・院生に限る）。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_628eea47a36e', 'attr_source_docs', 'established', 'https://www.ubic-u-aizu.jp/images/stories/pdf/h24kijyun.pdf・https://u-aizu.ac.jp/files/page/intro/regulations/reg142_j.…', '1本目は称号の細目を定める「公立大学法人会津大学の研究成果等を活用したベンチャーへの称号の授与について」で、UBIC「大学発ベンチャー紹介」ページからリンクされ、申請様式（様式1）も同ページにある。2本目は支援メニュー本体の会津大学における起業支援に関する規程（reg142）。3本目は2025年4月施行の株式等の取扱規程（reg165）。2本目と3本目は公立大学法人会津大学の法人規程一覧から辿れる。1本目はPDFの文字埋め込みが壊れており、画像化して本文を確認した。', 'official', 'https://www.u-aizu.ac.jp/intro/outline/corporate/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_cert_update', 'established', '認定に期限なし、支援期間5年を審査会付議で延長', 'ベンチャー規則(平成28年規則第51号、令和8年3月10日施行)第11条第2項が、施設・設備の貸付、クリエイティブ産業創出拠点施設の貸付、バーチャルオフィス利用の支援期間を原則として認定後5年に達する日の属する年度末までとし、1年を単位に通算10年まで延長できるとする。第3項で学長が必要と認めれば10年経過後も延長可。第4項は延長申請に第3条第2項の認定手続(大学発ベンチャー認定審査会への付議と学長決定)を準用し、学長が可否決定に必要な書類の提出を求められるとする。認定と称号自体の有効期間を定めた条文はなく、継続要件は第8条の定期モニタリングと第10条の取消しで確認する建て付け。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_title_restriction', 'established', '第6条で法的責任を否認、使用範囲・停止の条項なし', '同規則第6条(本学の法的責任)は、第3条第2項の認定および第5条の称号授与が本学に何ら法的責任を生じさせるものではないと定める。認定申請書別紙「希望する支援内容等について」(別記様式第1号)にも、称号を使用したことによって生じた損失および損害について大学はいかなる法的責任も負わない旨を明記。一方、称号が品質保証・投資推奨・経営状態の保証を意味しない旨を正面から示した条項、称号の使用範囲や表示方法を定めた条項、使用停止を命じる条項は、規則にも申請様式にも見当たらない。学章・マスコットの使用のみ第11条第9項が学章に関する規則等に従うとする。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_cancellation', 'established', '第10条に取消事由4号と支援打切り、称号返付は自主申出のみ', '同規則第10条第1項は、学長が認定および称号授与を取り消せる場合として、(1)事業活動が第2条の定義に該当しなくなった場合、(2)社会的信用を失墜する行為を行った場合、(3)申請内容に虚偽がみつかった場合または債務不履行がある場合、(4)その他本学の不名誉となるおそれがあり認定・支援が適当でないと学長が認める場合の4号を列挙する。第2項は取消しを行った認定ベンチャーへの支援を打ち切ることができるとする。第9条は代表者が称号の返付を学長に申し出ることができるとするのみで、取消時の称号記の返付義務、Webサイト等の表示削除、称号の営業利用停止を命じる条項は置かれていない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_report_change', 'established', '年次事業報告書と解散・破産等の報告義務、変更届は規定なし', '同規則第7条第1項は、認定ベンチャーの代表者が毎年度、別記様式第3号「鹿児島大学認定ベンチャー事業報告書」により、決算報告終了後3月以内に事業報告書と収支決算書を学長へ提出しなければならないと定める。第2項は、会社法の解散、破産法の破産手続、民事再生法の再生手続、会社更生法の更生手続、不正競争防止法第21条・第22条の罰則が裁判で確定した場合に、速やかに学長へ報告する義務を課す。代表者、所在地、資本構成の変更届を求める条項も様式もなく、様式第3号は提出書類を列挙するだけの簡素な体裁。ほかに第8条でセンター長による定期モニタリングを置く。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_support_request', 'established', '認定申請書の別紙で支援を項目ごとに申請、審査で不許可もあり', '同規則第3条第1項は、認定申請書に「希望する支援内容等」の必要書類を添えて学長に提出させる。別記様式第1号には別紙「希望する支援内容等について」が付き、居室の貸付、研究設備等の利用、法人登記上の住所の使用、知的財産権・ノウハウ使用の優遇措置、広報、学章・マスコットの使用、その他の各項目ごとに希望の有無と具体的事項を記入させ、支援希望期間、支援希望の理由、当初出資金総額、黒字化目標時期まで書かせる。同別紙は「審査の結果、希望に沿えない場合もあります」と明記。支援は認定と別枠の申請書ではないが項目ごとに審査され、認定後の相談は事業化支援相談窓口が受ける。', 'official', 'https://www.kagoshima-u.ac.jp/research/b-form001_20240314.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_facility_registration', 'established', '産学交流プラザ棟の居室とバーチャルオフィスの双方で登記可', '同規則第11条第1項第1号アが「産学交流プラザ棟の居室(法人登記上の住所の使用を含む。)」を有償貸付の対象とし、第2号で鹿児島市クリエイティブ産業創出拠点施設の無償貸付、第3号で本学のバーチャルオフィスの利用を支援に挙げる。第7項は第1号アの居室利用と第3号のバーチャルオフィス利用における法人登記上の住所を産学交流プラザの住所とすると定め、居室に入居しなくても学内住所で商業登記できる。第5項で居室の施設使用料は不動産管理規程(平成16年規則第77号)により、第8項でバーチャルオフィス利用料は別表により支援利用開始前に一括納入。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_vc_connection', 'established', '認定コーディネーターに県内11金融機関、PARKS・NEDO覚書に参画', 'イノベーションセンター「4.認定コーディネーター制度」ページによれば、2015年10月開始の同制度で県内金融機関の職員をコーディネーターとして認定し、2026年3月末現在11金融機関計27名が登録されている。ただし制度の趣旨は本学の研究シーズを地域企業へ提供し企業ニーズを本学へ橋渡しすることで、認定ベンチャーを投資家へ紹介する導線とは書かれていない。ほかにPARKSページで九州・沖縄20機関のプラットフォーム参画(構成機関にFFGベンチャービジネスパートナーズを含む)、KSPページでNEDOとの起業家支援に係る相互協力の覚書を確認。ベンチャー規則第11条の支援メニューに紹介条項はない。', 'official', 'https://www.krcc.kagoshima-u.ac.jp/regi-coop/coordinatorsystem/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_eir', 'not_started', '客員起業家の招聘制度なし、客員教授は産学連携従事者向け', 'イノベーションセンター組織規則(令和4年規則第11号)第3条はセンターの業務を10号に列挙し、第9号に「起業家教育に関すること」を置くが、起業家の招聘・常駐、客員起業家(EIR)、起業家メンターの派遣に当たる業務はない。第9条の客員教授等は客員教授等選考規則(平成16年規則第73号)に基づき「センターの産学連携活動に従事する者」へ称号を付与する仕組みで、EIRとは目的が異なる。センターの「起業」メニューは共通教育科目、大学院MOT、事業化支援相談、認定ベンチャー称号・支援、事業化支援プロジェクト、PARKS、KADAI STARTER''s PITCHの7件で、EIRは含まれない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00002341.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_cxo_pool', 'not_started', '経営人材の紹介・マッチング制度なし', 'ベンチャー規則第11条第1項の支援は、施設・設備の有償貸付、拠点施設の無償貸付、バーチャルオフィス、知財使用の優遇措置、広報、学章・マスコットの使用、その他学長が必要と認めた支援の7号に限られ、CEO・CXO候補の紹介やマッチングは含まれない。イノベーションセンター組織規則第3条の業務10号にも経営人材の確保・派遣に当たる業務はなく、センターの「起業」メニュー7件、認定ベンチャー称号・支援ページの支援一覧にも該当がない。参画するPARKSの起業活動支援プログラムは技術シーズ発掘から起業家とのマッチングまでを掲げるが、プラットフォーム側の事業で本学独自の人材プールではない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_ip_equity', 'established', 'ライセンス対価を現金に代え株式・新株予約権で取得可', '「ライセンス等の対価として取得する株式等取扱規則」(令和3年4月22日規則第25号)第1条が、本学が保有する研究成果に係る知的財産権のライセンス等の対価を現金に代えて株式等で取得する場合の取扱いを定める。第2条はライセンス等を知的財産権の譲渡・提供、実施権の設定、実施許諾、利用許諾と定義し、株式等を株式および新株予約権(新株予約権付社債を含む)とする。第3条は、ベンチャー企業が希望し本学が成果の普及・活用促進を特に必要と認め、事業の有望性が高いこと、現金支払の免除・軽減が経営加速に特に必要なこと、経営体制・株主構成に反社会的勢力等との関係がないことの3要件をすべて満たす場合に限定。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00001098.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'pol_fund_investment', 'not_started', '出資・ファンド組成規程なし、PARKSがVC設立を構想', '鹿児島大学例規集の体系目次(第1編第2章第7節 社会連携)と第1章 基本規則を確認したが、大学の出資やファンド組成に関する規程は置かれていない。業務方法書(平成16年5月24日文部科学大臣認可)にも出資に関する記載はない。ベンチャー規則第11条第1項の支援メニューにも資金供給は含まれず、資金面の制度は知財ライセンス対価としての株式等取得(令和3年規則第25号)にとどまる。イノベーションセンターのPARKSページは、参画するPARKSが2026年度末までに独自のVCやPoCファンドを運用する「PARKSインターユニバーシティ」の設立を目指すと記載するが、これはプラットフォーム側の目標。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_taikei/r_taikei_01_02_07.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_regulation_owner', 'established', '大学規程（国立大学法人鹿児島大学 平成28年規則第51号）', '認定制度の根拠は「国立大学法人鹿児島大学発ベンチャーの認定及び支援に関する規則」(平成28年5月26日規則第51号)で、鹿児島大学例規集の第1編 規則、細則／第2章 全学規則／第7節 社会連携に収録された国立大学法人の全学規則。学校法人規程でも外部の研究機関規程でもない。関連する株式等取扱規則(令和3年規則第25号)、知的財産規則(平成16年規則第41号)、職員兼業規則(平成16年規則第63号)、産学官連携に係る利益相反マネジメント規則(平成18年規則第6号)もいずれも同法人の規則で、認定制度は単一法人の規程体系で完結している。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_review_body', 'established', '大学発ベンチャー認定審査会（イノベーションセンター設置）', 'ベンチャー規則第3条第2項は、学長が申請を受けたとき南九州・南西諸島域イノベーションセンターに設置する「大学発ベンチャー認定審査会」に付議し、その審議結果を踏まえて認定を決定し、結果を文書で申請者に通知すると定める。第3項で審査会の運営等は別に定めるとするが、その内規は例規集にも大学サイトにも公開されていない。第12条により事務は研究推進部社会連携課が処理し、大学の「大学発ベンチャー支援」ページは申請先を同課産学・地域連携係とする。株式等の取得審査は別系統で、株式等取扱規則第4条により、イノベーションセンター運営委員会規則第8条の専門部会として置かれる知的財産審査会が行う。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_equity_decider', 'established', '学長（知的財産審査会の審査結果に基づき決定）', '株式等取扱規則第4条第1項は、ライセンス等の対価を株式等で支払う申込を受けた場合、イノベーションセンター運営委員会規則(令和4年規則第12号)第8条に基づき設置する知的財産審査会が取得の審査を行うとし、第2項で財務状況・事業計画等から取得の可否を審査、第3項でセンター長が審査結果を学長へ速やかに報告する。第5条第1項で学長が審査結果に基づき取得の可否を決定し、第2項で契約書等を取り交わす。処分側は第8条が換金可能になり次第の売却、第9条第4項が新株予約権の権利行使・変更・処分について審査会の審査と学長の承認を求める。第10条で利益相反マネジメント委員会がインサイダー取引を個別調査。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00001098.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_amendment_decider', 'unknown', null, '［自動検証で否認: 学長明記なし、注記自身が決裁根拠不明と認める］元の主張(established): 学長（重要規則の改廃は教育研究評議会・経営協議会が審議）。ベンチャー規則には制定改廃の決裁を定めた条文がなく、第13条(雑則)が必要な事項は別に定めるとするにとどまる。同規則は国立大学法人鹿児島大学の全学規則として発令され、平成28年規則第51号から令和8年3月10日規則第20号まで10回の改正が沿革に記録されている。教育研究評議会規則(平成16年規則第4号)第3条第3号が「学則(経営に関する部分を除く。)その他の教育研究に係る重要な規則の制定又は改廃に関する事項」を審議事項とし、経営に係る部分は経営協議会が担う。役員会規則(平成16年規則第2号)第3条は規則の制定改廃を明示列挙せず第6号の包括条項のみ。決裁者を名指しした公開条文は確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_post_grad_limit', 'established', '3年以内（退職・卒業・修了・退学から設立まで）', 'ベンチャー規則第2条第3号が、本学を退職、卒業、修了または退学した者で、退職等から設立までの期間が3年以内の者が、本学もしくは当該者が所有する知的財産権または本学において達成した研究成果、習得した技術等を活用して設立した、もしくは設立に深く関与した企業等を大学発ベンチャーの一類型とする。認定申請書別記様式第1号の記入要領(5)も、⑬「ベンチャー設立形態」の選択肢ウとして同じ文言を掲げる。第4号・第5号は設立後5年以内の共同研究等または技術移転を要件とするが、これは退職・卒業後の期限とは起算点が異なる。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_renewal_rule', 'established', '更新可（審査あり）。支援期間を1年単位で通算10年まで', 'ベンチャー規則第11条第2項が支援期間を原則として認定後5年に達する日の属する年度末までとし、必要な場合は1年を単位として通算10年に達する日の属する年度末まで延長できると定める。第3項は学長が必要と認めた場合に10年経過後も学長が認めた期間まで延長できるとする。第4項は延長申請に第3条第2項の認定手続(大学発ベンチャー認定審査会への付議と学長の決定)を準用し、学長が延長の可否決定に必要な書類の提出を求められるとしており、届出のみの更新ではない。認定と称号自体には有効期間の定めも更新手続もない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_naming', 'established', '独自名称「鹿児島大学認定ベンチャー」、規則名は大学発ベンチャー', 'ベンチャー規則第5条が、学長は認定した大学発ベンチャーに対し別に定める称号記(別記様式第2号)により「鹿児島大学認定ベンチャー」の称号を授与すると規定する。規則の題名と第2条の定義は「大学発ベンチャー」を用いるが、授与される称号は大学名を冠した独自呼称。イノベーションセンターのページ名も「鹿児島大学認定ベンチャー称号・支援」で、2026年4月1日現在18社を同称号として一覧公開している。「大学発スタートアップ」の語は、参画するプラットフォームPARKSの紹介ページなど別文脈で使われ、称号としては用いられていない。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_support_period', 'established', '支援ごとに別に定める（施設系のみ5年・通算10年、称号は無期限）', 'ベンチャー規則第11条第2項は期間の定めを第1項第1号から第3号(施設・設備等の有償貸付、鹿児島市クリエイティブ産業創出拠点施設の無償貸付、バーチャルオフィス利用)に限って置き、原則5年、1年単位で通算10年まで延長できるとする。第4号の知財使用の優遇措置、第5号の広報、第6号の学章・マスコット使用には期間の定めがない。認定と称号自体にも有効期間の条文はなく、第10条の取消しがあるまで続く。認定申請書別紙は申請者に「支援希望期間」を開始日と終了日で記入させる。大学の支援ページは支援の有効期間を授与日から5年間と案内。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_support_contents', 'established', '施設・設備の有償貸付・拠点施設の無償貸付・バーチャルオフィス・法人登記住所・知財使用の優遇措置・広報・学章及びマスコット使用・学長が認める支援', '同規則第11条第1項が7号に列挙する。第1号は本学施設・設備等の有償貸付で、ア産学交流プラザ棟の居室(法人登記上の住所の使用を含む)とイ研究設備等。第2号は本学が貸与を受けている鹿児島市クリエイティブ産業創出拠点施設の無償貸付、第3号は本学のバーチャルオフィスの利用(起業支援に関する要項第4のサービスを含む)、第4号は本学が所有する知的財産権・ノウハウ等の使用に関する優遇措置、第5号は本学の広報誌またはWebサイト等における広報、第6号は学章及びマスコットキャラクターの使用、第7号はその他学長が必要と認めた支援。センターの称号・支援ページは第7号の例として郵便物等の収受の便宜を挙げる。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_847658f9e871', 'attr_source_docs', 'established', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html・https://www1.g-reiki.net/kagoshima-u/reiki_honbun…', '1本目は認定、称号、支援、事業報告、モニタリング、取消しを1本で定める「国立大学法人鹿児島大学発ベンチャーの認定及び支援に関する規則」(平成28年規則第51号、令和8年3月10日施行)の例規集本文。2本目は知財ライセンス対価を株式・新株予約権で受け取る「ライセンス等の対価として取得する株式等取扱規則」(令和3年規則第25号)。3本目は南九州・南西諸島域イノベーションセンターの「鹿児島大学認定ベンチャー称号・支援」ページで、支援メニューの運用上の説明と認定18社の一覧を載せる。申請様式と提出先は大学サイトの「大学発ベンチャー支援」ページにまとまる。', 'official', 'https://www1.g-reiki.net/kagoshima-u/reiki_honbun/x890RG00000888.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_cert_update', 'established', '3年、社会連携推進機構会議の議を経て更新可', '称号授与規程第4条第2項「認定企業が称号を保持できる期間は、称号を授与された日から3年間とする。ただし、保持期間は、更新することができる」。同条第4項で更新を希望する認定企業は別記様式第1号の称号授与申請書により学長へ申請し、審査は第3条第2項（社会連携推進機構会議の議を経た学長決定）を準用する。更新時に要件を再確認する具体的手続や更新回数の上限を定めた条文は置かれていない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_title_restriction', 'established', '品質保証目的の称号使用を禁止、学長が使用停止命令', '称号授与規程第5条第1項は製品・サービス等の内容及び品質を保証するために称号を使用することを禁じ、第2項で学長は当該使用を停止させることができると定める。第8条第1項は本法人が認定企業の製品等の安全性・有効性等を担保するものではなく何ら法的責任を負わないとし、第2項で授与又は取消しによる損害の賠償義務を否定する。第6条第2項は取消し後に称号を保持していた事実を事業に利用してはならないとする。投資推奨や経営状態の保証に触れた条文はない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_cancellation', 'established', '3事由で学長が取消し、称号記返還と事実利用の禁止', '称号授与規程第6条第1項は、(1)第2条の申請資格を喪失したとき、(2)社会的信用を失墜させる行為があったとき、(3)その他学長が不適当と判断したとき、に学長が称号を取り消すことができると定める。同条第2項で取消しを受けた企業は称号記を返還し、称号を保持していた事実を事業に利用してはならない。第7条第1項で取消しも授与と同様に本学ウェブサイトへの掲載等により公表する。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_report_change', 'not_started', '年次報告・変更届の定めなし', '称号授与規程は趣旨、申請資格、申請と決定、称号授与と保持期間・更新、使用制限、取消し、公表、免責、事務の全10条と別記様式2種で構成され、認定企業に年次報告、代表者・所在地・資本構成の変更届、解散時報告を求める条文は置かれていない。第6条第1項第1号が申請資格の喪失を取消事由に挙げるが、企業側の届出義務としては規定されていない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_support_request', 'established', '施設貸付・共用機器は各別規程で申請と承認', '称号授与規程第4条第3項は認定企業にロゴマーク使用と施設・設備の利用を包括的に認め、支援ごとの個別申請条項を置いていない。実際の施設利用は固定資産貸付け及び譲与細則第5条で資産管理責任者が使用目的・貸付期間・使用計画等を記載した申請書を徴し、第6条で200万円未満の資産は資産管理責任者、不動産及び200万円以上の資産は総括資産管理責任者が貸付けを決定し通知書を交付する。広報掲載や外部紹介の個別申請手続は公開規程で確認できなかった。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000193.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_facility_registration', 'established', '創業準備含む研究成果活用事業へ有償貸付、登記の定めなし', '固定資産貸付け及び譲与細則第2条第1項第4号ニは、本学の研究成果を活用した事業（創業準備を含む。）を行う中小企業又は個人にその事業の用に供するため本学の固定資産を使用させることが必要と認められるときの貸付けを認める。同項本文で貸付期間は1年を限度（特別な事由があるときは1年を超えることができる）、第2項で原則として有償。建物の所有を目的とする土地等は第5条で定期借地契約等を締結する。本店所在地としての商業登記に関する記載はない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000193.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_vc_connection', 'unknown', null, 'ベンチャリング・センター規程第3条第1号は業務として「本学の教員又は学生が関与する大学発ベンチャーの育成・創出及びそのための学外機関との連携等」を掲げるが、VC・金融機関・自治体・外部支援機関への紹介導線を定めた条文はない。社会連携推進機構の機構概要、中長期行動戦略、大学発ベンチャーの各ページにも紹介制度の記載がなく、中長期行動戦略は関係部局及び新潟県との連携のもとベンチャリング・センターが核となって推進するとだけ述べる。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002480.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_eir', 'unknown', null, 'ベンチャリング・センター規程第4条は組織としてセンター長、副センター長、その他必要な者を置き、第2項で特任教員及びその他必要な職員を置くことができると定めるにとどまり、客員起業家（EIR）、起業家メンター、起業家人材の招聘を制度として定めた条文はない。社会連携推進機構の機構概要、中長期行動戦略、大学発ベンチャーの各ページにも該当する記載を確認できなかった。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002480.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO/CXO候補）の人材プールや紹介・マッチングを定めた規程は新潟大学規程集の目次で確認できず、ベンチャリング・センター規程第3条が列挙する業務5項目（育成・創出と学外機関との連携、学内ネットワークの構築・運営、研究調査と社会への発信、関連資金の獲得及び運営、その他必要な業務）にも含まれない。社会連携推進機構の各公開ページにも記載がない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002480.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得可', '国立大学法人新潟大学におけるベンチャー企業を対象としたライセンス等の対価として取得する株式等取扱規程（令和7年1月24日規程第2号、令和7年2月1日施行、全13条）。第2条第4号で株式等を株式及び新株予約権と定義し、知的財産権の譲渡、実施権の設定、実施許諾等の対価を株式等で取得できるとする。第4条で発明審査委員会が取得の可否を審査して学長へ報告、第5条で学長が決定して契約書を取り交わす。第12条で事務は取得前が研究企画推進部、受入決定後が財務部。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002835.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'pol_fund_investment', 'unknown', null, '新潟大学規程集の目次に、出資、ファンド組成、大学出資会社の設立、認定特定研究成果活用支援事業者（認定VC）への出資に関する規程は見当たらない。社会連携推進機構の機構概要、中長期行動戦略、大学発ベンチャーの各ページにも出資やファンドの記載がない。ベンチャリング・センター規程第3条第4号は「大学発ベンチャーの育成・創出に関連した資金の獲得及び運営に関すること」を業務に掲げるが、出資の根拠規定ではない。経済産業省の出資一覧ページは403で開けなかった。', 'official', 'https://public1.legalcrud.com/niigata_univ/aggregate/catalog/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_regulation_owner', 'established', '大学規程（国立大学法人新潟大学の学長制定規程）', '国立大学法人新潟大学の諸規程の区分，制定の手続等に関する規程第3条は諸規程を学則・規則・規程・細則に区分し、第6条で規程は学長又は部局長が定めるとする。第8条は学長が定める規程に「国立大学法人新潟大学」又は「新潟大学」を冠すると定める。認定の正本は「国立大学法人新潟大学における新潟大学発ベンチャーの称号授与に関する規程」であり、学長制定の法人規程に当たる。学校法人の寄附行為に基づく規程ではない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000066.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_review_body', 'established', '新潟大学社会連携推進機構会議', '称号授与規程第3条第2項「学長は、前項の申請があったときは、社会連携推進機構会議の議を経て、称号の授与の決定を行う」。社会連携推進機構会議規程第2条第6号は協議事項に「大学発ベンチャーの育成・創出に関する事項」を掲げる。同規程第3条の構成員は機構長、副機構長、各部門長、ベンチャリング・センター長、産業安全文化協創センター長、各学系選出教員、研究企画推進部長等。第5条で議長は機構長、第7条で事務は研究企画推進部が処理する。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002467.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_equity_decider', 'established', '学長（発明審査委員会の審査を経て決定）', '株式等取扱規程第4条で発明審査委員会が株式等の取得の可否に係る審査を行い結果を学長に報告、第5条で学長が審査結果に基づき取得の可否を決定し契約書を取り交わす。第7条第4項の新株予約権の取扱いも発明審査委員会の審査と学長の承認による。第9条で取得した株式は換金可能な状態になり次第速やかに売却するものとし、処分の判断主体を学長以外へ委譲する規定は置かれていない。第10条でインサイダー取引防止と株式処分信託の利用を定める。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110002835.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_amendment_decider', 'established', '学長（経営の重要事項は経営協議会の議）', '諸規程の区分，制定の手続等に関する規程第6条「規程は、学長又は部局長が定めるものとする。ただし、法人の経営に関する重要な事項に係るものにあっては、経営協議会の議を経るものとする」。第5条で規則は経営協議会又は教育研究評議会の議を経て学長が定め、軽微な改正は学長が定めることができる。第7条で細則は学長又は部局長が定める。第10条で制定時は関係部局及び総務部総務課と協議し、部局長制定の規程・細則は学長へ速やかに報告する。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110000066.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_post_grad_limit', 'established', '3年以内（教職員は退職、学生は卒業・修了から起算）', '称号授与規程第2条第3号は教職員について退職の日から企業設立の日までの期間が3年以内の者を含むとし、第4号は学生について卒業又は修了の日から企業設立の日までの期間が3年以内の者を含むとする。いずれも当該企業を設立し又は設立に深く関与したことを要件とする。第5号は学長が前4号に準ずると認めたものを対象に加えるため、期限を超える案件は第5号の判断に委ねられる。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_renewal_rule', 'established', '更新可（審査あり）。申請書提出、機構会議の議を準用', '称号授与規程第4条第2項ただし書で保持期間は更新することができる。同条第4項は、更新を希望する認定企業は別記様式第1号の称号授与申請書により学長へ申請し、審査については第3条第2項（社会連携推進機構会議の議を経た学長決定）を準用すると定める。届出のみで足りる簡易更新や更新回数の上限を定めた条文はない。公開一覧に認定期間が6年、9年に及ぶ企業があるのは更新の累積による。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_naming', 'established', '大学発ベンチャー（「新潟大学発ベンチャー」の称号）', '称号授与規程第1条は本法人の研究成果又は人的資源を活用して起業したベンチャー企業に「新潟大学発ベンチャー」の称号を授与すると定め、規程名も「新潟大学発ベンチャーの称号授与に関する規程」。第4条第1項で学長が称号記（別記様式第2号）を交付して授与する。社会連携推進機構の公開ページも「新潟大学発ベンチャー認定制度」として掲載しており、スタートアップの語を用いた併記や独自名称は使用していない。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_support_period', 'established', '称号期間と同じ（3年）、施設貸付は1年ごと', '称号授与規程第4条第2項で保持期間は3年、第3項で「認定企業は、本学の管理運営及び教育研究に支障のない範囲において、本学のロゴマークの使用及び施設・設備の利用ができる」とし、支援を受けられる地位を認定企業であることに結び付けている。支援ごとに別の期間を定めた条文はない。ただし実際の施設貸付けは固定資産貸付け及び譲与細則第2条第1項で1年を限度とし、特別な事由があると認めるときに限り1年を超えることができる。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_support_contents', 'established', '称号記の交付・ロゴマーク使用・施設設備の利用・大学サイトでの公表', '称号授与規程第4条第1項で学長が称号記（別記様式第2号）を交付して称号を授与、第3項でロゴマークの使用及び施設・設備の利用を認める。第7条第1項で授与と取消しを本学ウェブサイトへの掲載等により公表する。社会連携推進機構の大学発ベンチャーページも、称号を授与するとともに事務及び研究に要する施設・設備等の使用を支援し、本学のロゴの使用を許可すると記載し、認定企業14社を認定期間付きで掲載している。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_b294f39bda4b', 'attr_source_docs', 'established', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html・https://public1.legalcrud.com/niigata_univ/act/110002835.…', '1本目は称号授与規程の正本で、申請資格、学長決定と社会連携推進機構会議の議、保持期間3年と更新、ロゴマーク使用と施設設備利用、使用制限、取消し、公表、免責、事務までを一つの規程で定める。2本目は令和7年制定の株式等取扱規程で、ライセンス対価の株式・新株予約権による取得手続を定める。3本目は社会連携推進機構の大学発ベンチャーページで、支援内容の説明と認定企業一覧・認定期間を掲載する。', 'official', 'https://public1.legalcrud.com/niigata_univ/act/110001659.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_cert_update', 'not_started', '無、称号は原則永年使用で更新審査の定めなし', '「名古屋工業大学発ベンチャーに関する規程」第3条第2項「名工大発ベンチャーの称号は，原則として永年使用することができる」。有効期間の年限、更新申請、更新審査、要件の再確認を定める条文は同規程に置かれていない。称号の存続に関わるのは第6条の重大事象の報告義務と第8条の学長による取消しのみで、期間満了による失効や定期の要件再確認の仕組みはない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_title_restriction', 'established', '有、称号授与は大学に法的責任を生じさせない旨を明記', '発ベンチャー規程第5条「名工大発ベンチャーの称号の授与は，本学に法的責任を生じさせるものではない」。称号に伴う使用権の範囲は第10条第1号のロゴ使用権の付与にとどまる。第8条第2項は、取消しを受けた者は速やかに称号を返付し、取消日以後は称号授与を受けていた事実を事業に使用してはならないと定める。品質保証・投資推奨・経営状態の保証と誤認させない旨を名指しした条項はなく、第5条の責任否定条項が実質的にその役割を負っている。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_cancellation', 'established', '有、取消事由・称号返付・取消後の使用禁止を規定', '発ベンチャー規程第8条第1項の取消事由は、第2条の定義から著しく逸脱したとき、社会的信用を失墜する行為があったとき、本学の不名誉となるおそれがあるとき。第2項で取消しを受けた者は速やかに称号を返付し、取消日以後は称号授与を受けていた事実を事業に使用してはならない。第7条は代表者が自ら返付を希望する場合に学長へ申し出て返付する手続を定める。ロゴの使用停止や表示削除を独立して定めた条文は置かれていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_report_change', 'established', '解散・破産等の随時報告義務、年次報告と変更届なし', '発ベンチャー規程第6条は、会社法に定める解散、破産宣告、民事再生手続・会社更生手続の開始、不正競争防止法違反による罰金刑の確定、企業活動の実態の消滅、その他重要な影響を及ぼす事象が生じたときに、代表者が速やかに学長へ報告する義務を定める。解散時報告はこの随時報告に含まれる。定期の年次報告や、代表者・所在地・資本構成の変更届を求める条文は、同規程にも別記様式第1号にも置かれていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_support_request', 'established', '施設利用のみ別途申請と推進会議審査、他は手続の定めなし', '発ベンチャー規程第10条は8号の支援を列挙するが、各支援を受けるための申請様式や審査手続を同条は定めていない。独立した個別手続を持つのはインキュベーション施設だけで、名古屋工業大学インキュベーション施設細則第3条により、使用希望者が学長に申請し、産学官金連携機構推進会議の審査を経て使用許可の可否と使用期間が決定される。推進会議は必要に応じ面接と資料提出を求めうる。商業登記の認容、共用設備の学内料金適用、情報提供、知的財産の譲渡には申請・審査の条文がない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E6%96%BD%E8%A8%AD%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_facility_registration', 'established', '有、施設の有償貸与と本学所在地での商業登記を併せて認容', '発ベンチャー規程第9条で産学官金連携機構にインキュベーション施設を置き機構長が管理運営を統括、第10条第2号で施設内の事務室貸与、第3号で本学所在地を名工大発ベンチャーの所在地とする商業登記の認容を支援に挙げる。施設細則第2条の使用資格は称号を受けた大学発ベンチャー、または使用資格付与が大学にとって有益と判断される者。第3条で学長申請と推進会議審査、第8条別表第一で光熱水料を含む月額使用料、第9条で原状回復義務。施設細則に登記の条項はなく、登記の認容は発ベンチャー規程側で完結する。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E3%82%A4%E3%83%B3%E3%82%AD%E3%83%A5%E3%83%99%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E6%96%BD%E8%A8%AD%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: 東海広域ファンド関与の記載は当該URLに無い］元の主張(established): 有、機構渉外部門が金融機関連携、東海広域ファンドに関与。産学官金連携機構の組織概要ページで、機構は渉外部門・事業創造人財育成部門・設備共用部門の3部門からなり、渉外部門の所掌に金融機関等との連携が明記されている。発ベンチャー規程第10条第5号は法人が関与するベンチャーファンド及び法人の出資の対象とすることを支援に挙げる。名古屋大学の公式ページによれば「名古屋大学・東海地区大学広域ベンチャーファンド」には名古屋大学、岐阜大学、豊橋技術科学大学、名古屋工業大学、三重大学が関与し、1号は日本ベンチャーキャピタル、2号はBeyond Next Venturesが運営する。個別企業へのVC・自治体紹介の手続を定めた規程は見当たらない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_eir', 'unknown', null, '発ベンチャー規程第10条の支援の列挙、産学官金連携機構規則第2条の業務、機構の組織概要ページに示された3部門の所掌、起業支援サイト「NITech ENTREPRENEURSHIP」に掲載された育成プログラム（アントレプレナー育成塾、Second Up）のいずれにも、客員起業家（EIR）、起業家メンター、起業家人材の招聘を制度として定めた記述は見当たらなかった。大学規則集の規程一覧にも該当する名称の規程はない。公開情報だけでは制度の有無を確定できない。', 'official', 'https://tongali.web.nitech.ac.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_cxo_pool', 'unknown', null, '発ベンチャー規程第10条の支援は、ロゴ使用、事務室貸与、商業登記の認容、共用設備の学内料金、ファンド・出資対象化、情報提供、知的財産の譲渡、その他の8号で、経営人材の紹介・マッチングを挙げていない。産学官金連携機構規則第2条の業務、機構の組織概要ページの3部門、大学発ベンチャー企業紹介ページにも、CEO・CXO候補の人材プールや紹介制度の記述はない。第8号に「その他必要と認めるもの」があるため制度の不存在を断定できず、公開情報では確定できない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_ip_equity', 'not_started', '無、株式等の取得は寄附経路のみ、知財対価の定めなし', '大学規則集で株式を扱う規程は「名古屋工業大学における寄附による株式等取得取扱細則」（平成26年7月22日制定、平成28年12月21日細則第4号改正）のみで、第1条が対象を寄附により取得する株式、新株予約権及び新株予約権付社債に限り、第5条は速やかに売却することを原則とする。知的財産ポリシー第6条は実施・許諾・処分等の収益から発明者へ相当の利益を付与すると定めるにとどまり、大学が実施許諾の対価として株式・新株予約権を取得する条文はない。発ベンチャー規程第10条にも株式対価の号はなく、第7号は知的財産の譲渡である。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%AF%84%E9%99%84%E3%81%AB%E3%82%88%E3%82%8B%E6%A0%AA%E5%BC%8F%E7%AD%89%E5%8F%96%E5%BE%97%E5%8F%96%E6%89%B1%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'pol_fund_investment', 'established', '規程に法人の出資・関与ファンド対象化を明記、組成規程なし', '発ベンチャー規程第10条第5号「法人が関与するベンチャーファンド及び法人の出資対象とすること」を支援に列挙し、第2条第4号は法人が出資したベンチャー企業を大学発ベンチャーの定義に含める。名古屋大学の公式ページによれば、名工大は名古屋大学・岐阜大学・豊橋技術科学大学・三重大学とともに「名古屋大学・東海地区大学広域ベンチャーファンド」に関与し、1号は日本ベンチャーキャピタル、2号はBeyond Next Venturesが運営する。大学のLP出資の有無、出資決定の手続、持株比率、ファンド組成を定める学内規程は大学規則集に見当たらない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_regulation_owner', 'established', '大学規程（名古屋工業大学発ベンチャーに関する規程）', '認定制度の根拠は「名古屋工業大学発ベンチャーに関する規程」（平成28年3月24日規程第28号、平成28年4月1日施行。平成29年9月27日規程第7号、2021年2月17日規程第19号、2021年6月23日規程第4号改正）で、全11条と別記様式2種からなる。設置者は国立大学法人名古屋工業大学だが、規程名は大学名を冠し大学規則集に収録された大学の規程である。施設運用は同日制定のインキュベーション施設細則、審査主体の設置根拠は産学官金連携機構規則が受け持つ三層構成。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_review_body', 'established', '産学官金連携機構推進会議（学長が同会議の審査を経て決定）', '発ベンチャー規程第4条第2項で、学長は産学官金連携機構推進会議の審査を経て称号授与を決定し、同会議は必要に応じ面接の実施と関連資料の提出を求めることができる。推進会議の設置根拠は「名古屋工業大学産学官金連携機構規則」（平成29年9月27日規則第3号）第8条で、機構長、副機構長、学長指名の理事、リサーチアドミニストレーション室長、機構長指名の教員らで構成し、第9条で機構長が委員長、第10条で事務は研究支援課が処理する。認定審査に特化した独立の委員会や審査基準表は公開されていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E7%94%A3%E5%AD%A6%E5%AE%98%E9%87%91%E9%80%A3%E6%90%BA%E6%A9%9F%E6%A7%8B%E8%A6%8F%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_equity_decider', 'established', '学長（寄附株式等の受入可否）、出資決裁の規程なし', '寄附による株式等取得取扱細則第2条は、寄附者または発行会社の信用に問題があるとき、経営支配につながるとき、学長が支障があると認めたときは受け入れないことができると定め、受入可否の判断を学長に置く。第4条で出納主任が管理し、保有中の共益権は原則として行使しない。第5条は速やかな売却を原則とし、配当金の原資とする場合や上場時のロックアップ期間を例外とする。第6条で現金化に必要な場合の新株予約権の行使を認める。寄附以外の経路での株式・新株予約権の取得や処分を決裁する主体を定めた規程は見当たらない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%AF%84%E9%99%84%E3%81%AB%E3%82%88%E3%82%8B%E6%A0%AA%E5%BC%8F%E7%AD%89%E5%8F%96%E5%BE%97%E5%8F%96%E6%89%B1%E7%B4%B0%E5%89%87.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_amendment_decider', 'established', '学長（規程として審議機関に付議のうえ決定）', '「国立大学法人名古屋工業大学規則等の制定改廃に関する事務処理要領」は規則等を学則・規則・規程・細則・基準に分類し、規程・細則・基準は学長または部局長等が決定するとしたうえで、第9条で制定改廃にあたっては当該規則等を審議すべき審議機関に付議した上で決定するものとする（軽微な改正は除く）と定め、第13条で手続の実行部署を定める。発ベンチャー規程は規程第28号、インキュベーション施設細則は細則第9号としていずれも学長名で公布されている。産学官金連携機構規則第11条は、機構に関し必要な事項を推進会議の議を経て機構長が定めるとする。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E8%A6%8F%E5%89%87%E7%AD%89%E3%81%AE%E5%88%B6%E5%AE%9A%E6%94%B9%E5%BB%83%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E4%BA%8B%E5%8B%99%E5%87%A6%E7%90%86%E8%A6%81%E9%A0%98.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_post_grad_limit', 'not_started', '規定なし、第2条は在職者・在学者と知財・技術移転先に限定', '発ベンチャー規程第2条は対象を4号に列挙する。第1号は職員就業規則上の教員・一般職員、特定有期雇用職員、パートタイマー、再雇用職員または本学の学生が設立者もしくは設立に深く関与した者となって起業した企業、第2号は法人所有の知的財産をもとに起業した企業、第3号は法人から技術移転を受けた企業、第4号は法人が出資した企業。退職者・卒業生を対象に含める条文も、退職・卒業後何年以内という期限の定めもない。ただし第2号から第4号は在籍要件を課さないため、知財や技術移転の関係があれば卒業後の起業でも該当しうる。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_renewal_rule', 'established', '期限なし（第3条第2項で原則として永年使用）', '発ベンチャー規程第3条第2項は「名工大発ベンチャーの称号は，原則として永年使用することができる」と定め、有効期間の年限、更新申請、更新審査のいずれも置いていない。称号が失われる経路は第7条の代表者の申出による返付と第8条の学長による取消しに限られる。インキュベーション施設の使用期間は施設細則第3条により推進会議の審査を経て個別に決定されるが、更新の可否や更新手続を定めた条文はない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_naming', 'established', '大学発ベンチャー（称号は「名工大発ベンチャー」）', '規程名は「名古屋工業大学発ベンチャーに関する規程」、第3条第1項で学長が授与する称号は「名工大発ベンチャー」。スタートアップの語は規程本文に用いられていない。産学官金連携機構のサイトも「大学発ベンチャーについて」「大学発ベンチャー企業紹介」と表記する。学生向けの育成事業は「NITech ENTREPRENEURSHIP」の名称で別サイトを持つが、称号の呼称としては用いられていない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_support_period', 'established', '支援ごとに別に定める（称号は永年、施設は推進会議が決定）', '称号は発ベンチャー規程第3条第2項により原則として永年使用でき、期間の定めがない。これに対しインキュベーション施設の使用は、施設細則第3条で学長が推進会議の審査を経て使用許可の可否と使用期間を決定するため、称号期間とは切り離して個別に定まる。第10条の他の支援（ロゴ使用、商業登記の認容、共用設備の学内料金適用、情報提供、知的財産の譲渡）には期間の定めが置かれておらず、称号を保有する間の継続的な支援として構成されている。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_support_contents', 'established', 'ロゴ使用・事務室貸与・本店登記・共用設備学内料金・出資対象化・情報提供・知財譲渡', '発ベンチャー規程第10条は、本学の管理運営及び教育研究に支障のない範囲で行う支援として8号を列挙する。第1号ロゴを使用する権利の付与、第2号インキュベーション施設内の事務室の貸与、第3号本学所在地を所在地とする商業登記の認容、第4号共用設備の利用料金への学内料金の適用、第5号法人が関与するベンチャーファンド及び法人の出資の対象とすること、第6号情報提供、第7号法人が所有する知的財産の譲渡、第8号その他必要と認めるもの。GAP資金の配分、伴走メンタリング、経営人材紹介は同条に含まれない。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d8f97d74f01a', 'attr_source_docs', 'established', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%9…', '1本目は認定制度の正本「名古屋工業大学発ベンチャーに関する規程」で、定義・称号・申請審査・責任否定・報告・返付・取消し・施設設置・支援8号を1本で押さえられる。2本目は「名古屋工業大学インキュベーション施設細則」で、唯一の個別申請審査手続と使用料・原状回復を定める。3本目は産学官金連携機構の「大学発ベンチャー企業紹介」ページで、称号授与日つきの認定企業一覧が読める。審査主体の構成を確認する場合は産学官金連携機構規則を追加で開く。', 'official', 'https://kisoku.web.nitech.ac.jp/kisoku/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%B7%A5%E6%A5%AD%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%99%E3%83%B3%E3%83%81%E3%83%A3%E3%83%BC%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B%E8%A6%8F%E7%A8%8B.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_cert_update', 'established', '認定日から無期限、更新審査なし、6か月ごと報告で確認', '認定規程（令和2年6月18日令和2規程第3号、直近改正令和7規程第27号）第5条は、第一号から第四号の条件のいずれにも該当することを要件として認定の日から有効とし、発行する有価証券が金融商品取引所に上場した場合等支援の必要がなくなった場合に失効すると規定する。有効年数、更新申請、更新審査、要件の再確認手続に当たる条文はない。継続確認は第8条第1項の6か月ごとの事業状況報告と、第9条第1項第一号（第5条の要件を満たさなくなった場合の取消し）が担う建て付け。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_title_restriction', 'established', '第7条で法的責任を否定、取消後は称号使用禁止', '認定規程第7条（研究所の法的責任）は「ＮＩＢＮ発ベンチャーの認定及び称号の付与は、研究所に何ら法的責任を生じさせるものではない」と規定する。第9条第2項は取消しを受けた者が取消日以降、称号および認定を受けていた事実を利用して事業を行うことを禁止する。称号と併せて使う商標等は第6条第1項第五号の使用許可と第3項の実施許諾契約で範囲を定める。品質保証・投資推奨・経営状態の保証と誤認させない旨を名指しした条文はない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_cancellation', 'established', '取消4事由と取消後の称号利用禁止、本人からの解除申出可', '認定規程第9条第1項は理事長が認定を取り消せる場合として、第5条の要件を満たさなくなった場合、企業活動が研究所の事業活動の円滑な実施に支障を来たすと判断した場合、社会的信用を失墜する行為を行った場合、研究所の不名誉となるおそれがある場合等の4号を列挙する。第9条第2項は取消日以降の称号および認定事実の営業利用を禁止。第10条は認定の解除申出を認める。認定証の返付や表示物の削除を求める条文はない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_report_change', 'established', '6か月ごとの事業報告、増減資・解散等は速やかに報告', '認定規程第8条第1項は、認定時にあらかじめ指定した日およびその後6か月を経過するごとに、任意の形式で事業の状況を理事長へ報告する義務を課す。第8条第2項は増資、減資、解散、破産、再生手続、更生手続等の事実があった場合に速やかに理事長へ報告することを求める。年次ではなく6か月周期で、資本構成の変動と解散は第2項が拾う。代表者の交代や所在地の変更を届け出る条文はない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_support_request', 'established', '支援ごとに許可・契約が必要、申請様式は非公開', '認定規程第6条第1項は研究所が「貸与すること」「利用を許可すること」等の支援を行うことができると定め、第2項は事務室・研究室の貸与に研究所資産貸付取扱要領（平成28年要領第6号）に基づく契約、第3項は実施許諾等に職務発明等規程に基づく実施許諾契約の締結を求める。公開されている様式1は認定申請用のみで、支援ごとの申請様式と審査基準は第13条により別に定めるとされ非公開。株式等の取得だけは株式等取得保有規程第4条で個別の申込みと審議の手続がある。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_facility_registration', 'established', '所内に事務室・研究室を貸与、商業登記の可否は非公開', '認定規程第6条第1項第一号は「事務室又は研究室として研究所内に場所を確保し、貸与すること」を支援に掲げ、第2項で研究所資産貸付取扱要領（平成28年要領第6号）に基づく契約を締結するとする。同要領は各種規程等ページに掲載がなく、貸付期間、貸付料、本店所在地としての商業登記の可否は公開情報から判定できない。産官学連携トップと企業の方へページにも、起業用インキュベーション施設の入居要項に当たる記載はない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_vc_connection', 'not_started', '規程の支援メニューに紹介の定めなし', '認定規程第6条第1項の支援は、場所の貸与、研究設備等の利用許可、シーズ開発支援、優先的実施許諾、商標等の使用許可、および第六号「その他、理事長が科学技術・イノベーション創出の活性化のために必要と認める支援」の6号で、ベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介は挙がっていない。産官学連携トップ、法人発ベンチャーの認定について、企業の方への3ページにも紹介導線の記載がない。第六号は包括規定のため個別対応の余地は残る。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_eir', 'not_started', '客員起業家の招聘制度なし', '認定規程第6条第1項の支援メニューに人材の招聘や派遣は含まれない。各種規程等ページの人事関係には職員就業規則のほか任期付研究員、事務補助員及び技術補助員、研究調整専門員等、特任研究員、プロジェクト研究員、栽培管理技術員、再雇用職員の各就業規則が並ぶが、客員起業家や起業家メンターに当たる区分はない。産官学連携トップと企業の方へページにも記載がない。ただし同ページに載らない内規（利益相反管理規程、資産貸付取扱要領）が現に存在するため、非公開の運用まで否定するものではない。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_cxo_pool', 'not_started', '経営人材の紹介・マッチング制度なし', '認定規程第6条第1項の支援メニューに経営人材の紹介や派遣は含まれない。産官学連携トップページの項目は研究シーズ・産官学連携ニーズ、各種データベースと資源バンク、食環境整備推進のための産学官等連携共同研究プロジェクト、主要な協定一覧、特許＆品種、医薬品等の開発振興、知財ポリシー、法人発ベンチャーの認定についての8件で、CEO・CXO候補の人材プールに当たる項目はない。企業の方へページにも記載がない。', 'official', 'https://www.nibn.go.jp/sankangaku/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_ip_equity', 'established', '実施許諾料等の現金支払免除・軽減の対価に株式等取得可', '認定規程第6条第4項は、第1項の支援または第3項の実施許諾等を行った場合、株式等取得保有規程（令和5年2月1日令和5規程第6号）第3条第1項に基づき研究所が株式または新株予約権を取得できると規定する。同規程第3条第1項は、ベンチャーが希望し、事業の有望性が高いこと、および現金による支払を免除または軽減することが経営の加速のために特に必要と考えられることの両方に該当する場合に取得できるとし、実施許諾料の現金対価に代えて株式等を受け取る建て付けを明示する。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'pol_fund_investment', 'established', '業務方法書第10条の2に出資規定、実施規程は未公表', '研究業務関係業務方法書（令和5年3月14日厚生労働大臣認可）第10条の2（出資並びに人的及び技術的支援）は、研究成果を事業活動において活用し又は活用しようとする者のうち適当と認められる者に対し、科学技術・イノベーション創出の活性化に関する法律第34条の6第1項による出資又は人的・技術的援助を実施できると規定し、第2項で所要の規程等を整備するとする。出資業務の実施規程は各種規程等ページに掲載がない。ファンド組成やLP出資の条文はなく、開発振興業務関係業務方法書第39条の承継業務は承継した株式の処分に限られる。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/gyomuhoho-kenkyuu_20230314.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_regulation_owner', 'established', '研究機関規程（理事長が制定する国立研究開発法人の規程）', '認定規程は「国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーの認定に関する規程」（令和2年6月18日令和2規程第3号）として研究所が定める内部規程で、大学規程でも学校法人規程でもない。株式等取得保有規程（令和5規程第6号）、職務発明等規程（平成17年規程第44号）、職員就業規則（平成17年規程第2号）も同じ規程番号体系。同一内容の認定規程が産官学連携ページと各種規程等ページの2か所に掲載され、本文が完全に一致することを確認した。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_review_body', 'established', 'ベンチャー認定委員会（主管は戦略研究支援部）', '認定規程第3条は「ＮＩＢＮ発ベンチャーの認定、認定の取消し及びその他の検討事項を審議するため、研究所にベンチャー認定委員会を置く」と規定する。第4条第2項で理事長が申請の審査を同委員会に諮問し、第3項で委員会が審査と必要に応じた面接を行い理事長へ答申する。第12条は主管部署を戦略研究支援部（健都に関するものは健都戦略研究支援部）とする。株式等取得保有規程第4条第1項は、株式等の取得審査では必要に応じて外部専門家を委員に加えた同委員会に審議させるとする。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_equity_decider', 'established', '理事長（ベンチャー認定委員会の審議と総務部長の意見）', '株式等取得保有規程第5条第1項は、理事長が第4条第1項のベンチャー認定委員会の審議を経て株式等の取得等に適切に対応すると規定し、第3項は契約書も同委員会の審議を経て締結するとする。第7条の売却は理事長が必要に応じて同委員会の審議を経て行い、第2項の場合は総務部長から意見を徴する。第9条第3項の新株予約権の変更・処分も総務部長の意見と同委員会の審議を要する。第6条は取得した株式等の管理責任者を総務部長とする。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/venture_shien.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_amendment_decider', 'established', '理事長決裁（文書決裁規程別表第1）', '文書決裁規程（平成17年4月1日17規程第22号、直近改正令和7年7月1日7規程第50号）第2条は、決裁文書を別表第1に定める決裁事項の区分に応じた決裁権者までの決裁に付すと規定する。別表第1（医薬基盤研究所決裁区分）の共通事項2「規程、細則等の正規及びそれに準ずるものの制定並びに改廃に関する事項」は決裁権者が理事長、施行者も理事長で、総務部長と戦略研究部が経由先。業務方法書の変更のみ共通事項1により厚生労働大臣の認可を要する。', 'official', 'https://www.nibn.go.jp/introduction/disclosure/regulations/bunnsyokanrikiteibeppyou1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_post_grad_limit', 'established', '規定なし（人的属性の要件を置かず成果活用で判断）', '認定規程第2条はＮＩＢＮ発ベンチャーを「研究所の所有する知的財産又は研究所に関連する技術・知識等の研究成果を活用するベンチャー企業」と定義し、職員、退職者、学生といった人的属性の要件を置かない。第5条の認定条件も、研究所の研究成果の活用が期待できること、研究所の業務に支障を与えないこと、事業内容等が公序良俗に反しないこと、その他不適当なものでないことの4号で、退職後や卒業後の年数制限に当たる条文はない。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_renewal_rule', 'established', '期限なし（更新手続の定めなし、失効・取消しで管理）', '認定規程第5条は認定の日から有効とし、発行する有価証券が金融商品取引所に上場した場合等支援の必要がなくなった場合に失効すると規定するのみで、有効年数、更新申請、更新審査、再申請の条文はない。認定の終了は第5条の失効、第9条の理事長による取消し、第10条の本人からの解除申出の3経路。第8条第1項の6か月ごとの事業状況報告が要件の継続確認の役割を担う。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_naming', 'established', '独自名称（ＮＩＢＮ発ベンチャー）', '認定規程の題名は「国立研究開発法人医薬基盤・健康・栄養研究所発ベンチャーの認定に関する規程」で、第2条が略称「ＮＩＢＮ発ベンチャー」を定義し、本規程に基づき同称号を認められたものと規定する。大学ではないため大学発ベンチャー、大学発スタートアップの語は用いない。公式サイトの掲載ページ名は「医薬基盤・健康・栄養研究所発ベンチャーの認定について」。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_support_period', 'established', '個別契約（資産貸付契約と実施許諾契約で定める）', '認定規程第5条の称号は期限を定めず失効まで継続する一方、支援の期間は契約側で決まる。第6条第2項は事務室・研究室の貸与について研究所資産貸付取扱要領（平成28年要領第6号）に基づく契約、第3項は実施許諾等について職務発明等規程に基づく実施許諾契約の締結を求める。第6条第1項第四号は知的財産権を基にした事業への優先的実施許諾を「一定期間」とするが年数は示さず、個々の契約期間は非公開。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_support_contents', 'established', '場所の貸与・設備利用許可・シーズ開発支援・優先実施許諾・商標使用許可', '認定規程第6条第1項の各号。第一号は事務室又は研究室として研究所内に場所を確保し貸与すること、第二号は研究設備等の利用を許可すること、第三号は研究成果の実用化に向けたシーズ開発の支援を行うこと、第四号は研究所の知的財産権を基にした事業について一定期間優先的に実施許諾を行うこと、第五号は研究所が所有する商標等の使用を許可すること、第六号はその他理事長が科学技術・イノベーション創出の活性化のために必要と認める支援。第3項により理事長が適当と認めるときは実施許諾料を減免できる。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_260332f7323a', 'attr_source_docs', 'established', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf・https://www.nibn.go.jp/introduction/disclosure/regulatio…', '1本目は認定規程（令和2規程第3号、直近改正令和7規程第27号）で、認定手続、条件、支援内容、報告、取消しを全13条で定める正本。各種規程等ページの同名PDFと本文が完全一致することを確認済み。2本目は株式等取得保有規程（令和5規程第6号、直近改正令和7規程第55号）で、取得基準、審査、取得の決定、売却、議決権、インサイダー取引防止を定める。3本目は認定企業の一覧を載せる公式ページ。出資の根拠は研究業務関係業務方法書第10条の2、規程改廃の決裁は文書決裁規程別表第1にある。', 'official', 'https://www.nibn.go.jp/sankangaku/documents/venture_nintei.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_cert_update', 'established', '1年間、不延長通知がなければ自動延長、通算10年', 'JAXAパートナースタートアップ支援約款第5条。支援期間は名称の使用許可の日より1年間（第1項）。満了の1か月前までに機構又は被支援会社のいずれかが書面で不延長を通知しない限り1年間自動的に延長され、以後も同様（第2項）。延長後の期間は名称使用許可の日から10年、又は被支援会社の設立から10年（休業期間を証明できる場合はその期間を加算）を超えない（第3項）。更新時に許可要件を再審査する条文は置かれていない。第12条による名称使用許可の取消時はその時点で支援期間が終了（第4項）。やむを得ない事情による中断期間は通算期間に加算しない（第5項）。旧JAXAベンチャー支援規程第8条も認定期間を最大10年としていた。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_title_restriction', 'established', '認定はしない旨を明示、ガイドライン準拠で使用', '2025年8月28日のプレスリリースに「新制度における『JAXAスタートアップ』『JAXAパートナースタートアップ』に対しては、名称を付与しますが、その企業や事業内容に関してJAXAとして『認定』をすることは致しません」と明記されている。約款第6条第2項は名称とロゴの使用にあたり機構が別途提示する「名称使用ガイドライン」及び「ロゴデザインマニュアル」に従うことを義務づけ、第6条第1項は支援期間終了後又は第12条の取消後の使用中止を定める。第14条（事業の責任）は、機構が行った事業支援について機構はいかなる場合も一切の責任を負わず、被支援会社が全ての事業遂行を自らの判断で行うと規定。ガイドライン本体は非公開。', 'official', 'https://www.jaxa.jp/press/2025/08/20250828-1_j.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_cancellation', 'established', '約款第12条に取消事由、名称使用中止と資料返還', '約款第12条。第1項は許可要件の不充足、社会的背信行為や機構の名誉・信用を害する行為、支援が困難な状況、株式上場、上場会社等の子会社化又は発行済株式の過半数取得の5事由で名称使用許可を取消し、その時点で支援終了。第2項は約款違反、機構の信用や知的財産の価値の毀損、申請時の不正・虚偽申告等について是正を催告し、是正されなければ取消。第3項は破産・民事再生等の申立、財産状況の悪化、暴力団員等該当で催告なく取消。取消後は第6条第1項で名称とロゴの使用を中止し、第11条第2項で機構の秘密情報を含む資料等を指示に従い返還又は廃棄して処理結果を書面報告。第16条により沿革等、過去の事実としての使用のみ存続。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_report_change', 'established', '随時の報告要求と定款・役員変更等の事前通知義務', '約款第8条（報告・調査等）は、機構が必要に応じ、報告時点の会社概要等、報告時点の事業内容概要等、将来の事業計画および成長戦略についての概要等、これらを補完する情報等の報告を求めることができ、被支援会社はこれに協力すると規定する。定時の年次報告を課す条文は現行約款にない。第9条（通知義務）は、定款の変更、役員の変更、事業譲渡等、約款に基づく支援履行や許可要件に影響する可能性のある行為をしようとする場合に、遅滞なく機構へ報告することを義務づける。解散を名指しした条文はないが第9条に含まれ得る。旧JAXAベンチャー支援規程第9条は毎事業年度の事業報告書と翌年度の事業計画書の提出を求めていた。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_support_request', 'established', '伴走支援は包括、設備・知財・出資は別途申請と審査', '約款第4条は機構が第7条に定める内容の支援措置を講ずると包括的に定め、支援ごとの個別申請・個別審査の条文は置かれていない。名称使用許可の申請は新事業促進部の問い合わせフォームからの随時募集。一方で併存する他制度はそれぞれ別の申請と審査を持つ。試験設備等供用制度は年2回の定期募集（2月上旬・9月上旬頃）と随時募集で、契約金額1000万円未満は設備等利用承諾書、1000万円以上は契約書を用いる。知的財産の実施許諾は申請書の提出から締結まで1か月以上を要する。出資は出資業務規程第8条・第9条の出資委員会と出資審査会の審議を経る。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_facility_registration', 'not_started', '試験設備の有償供用のみ、起業用施設と登記の受入なし', '試験設備等供用制度は民間企業・大学・研究機関等に風洞やエンジン試験設備等を有償で供用する制度で、平成27年4月1日の改定により技術料が導入された。同ページに起業用の事務室・インキュベーション施設・オフィススペースの貸与の記載も、商業登記に住所を使える旨の記載もない。約款第7条第1項の支援措置の列挙にも施設の提供と登記の受入はない。なお旧JAXAベンチャー支援規程第3条第1項第3号は、職員がJAXAベンチャーの業務を遂行するために必要な機構内連絡事務所を設置し使用料と光熱水費を無償とすると定めていたが、現行のJAXAスタートアップ支援規程は非公開で承継の有無を確認できない。', 'official', 'https://aerospacebiz.jaxa.jp/solution/facility/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_vc_connection', 'established', '資金調達支援と投資家対応、連携ファンドの紹介', '約款第7条第1項第1号が、行政および外部提携機関による各種スタートアップ支援策に関する情報提供およびこれらへの推薦、資金調達支援、投資家による技術的質問への対応を支援措置として規定する。2025年8月28日のプレスリリースは、資金獲得・アクセラレーション支援に加え、連携ファンドの紹介と提携機関への推薦を挙げる。出資業務規程に基づく間接出資ではFrontier Innovations 1号ファンドへアンカーLPとして出資し、文部科学省提出資料（新事業促進部、2026年1月28日）によればLPにはSMBC、日本政策投資銀行、中小企業基盤整備機構、紀陽銀行等の金融機関が並ぶ。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_eir', 'not_started', '客員起業家・起業家招聘の定めなし', '約款第7条第1項は支援措置を列挙し、第1号は情報提供・推薦、資金調達支援、投資家による技術的質問への対応、販売販路および提携企業開拓支援、専門家の紹介、会社経営に関するセミナーについての情報の提供、広報支援、第2号はその他各種相談事項への対応にとどまる。客員起業家（EIR）、起業家メンター、起業家人材の招聘はこの列挙にない。出資業務規程第3条第6号の人的及び技術的援助も、研究開発の成果の実用化に関する専門人材の紹介と、機構職員による実用化に向けた試験の支援及び助言に限られる。新事業促進部の公開メニューにもEIR制度は掲載されていない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_cxo_pool', 'not_started', '経営人材の紹介制度なし、育成講座を出資先が開催', '約款第7条第1項第1号の支援措置は「専門家の紹介」にとどまり、CEO・CXO候補を紹介しマッチングする人材プールの定めはない。出資業務規程第3条第6号の人的及び技術的援助も、研究開発の成果の実用化に関する専門人材の紹介である。関連するものとして、JAXAが出資するFrontier Innovations株式会社が「宇宙スタートアップ 起業家・CXO育成プログラム（第2クール）」を無料・全4回（2026年10月22日開講）で開催し、宇宙領域での起業や宇宙スタートアップへのCXO参画に関心がある者を対象とするが、これは育成プログラムであり機構による経営人材の紹介制度ではない。', 'official', 'https://aerospacebiz.jaxa.jp/topics/event/20261022_startup/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_ip_equity', 'established', '知財の現物出資で株式・新株予約権を取得可', '出資業務規程（令和3年3月31日 規程令和第3-17号）第3条第2号ウが知的財産権を出資財産に含め、同条第3号が「株式等」を株式、新株予約権、投資事業有限責任組合契約等に基づく権利と定義する。第11条第3項第3号は出資契約に「知的財産権を現物出資する場合にあっては、当該知的財産権の取扱いに関する事項」を定めるとしており、知財の現物出資と引換えに株式・新株予約権を取得する経路が規程上ある。他方、実施許諾（ライセンス）の対価を株式・新株予約権とする定めはない。旧JAXAベンチャー支援規程第3条第1項第2号は認定企業への実施料の猶予・免除・無償を認めていた。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2022/04/%E5%8F%82%E8%80%83%E8%B3%87%E6%96%99%E4%B8%80%E5%BC%8F.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'pol_fund_investment', 'established', '出資業務規程で直接・間接・TLOの3類型を整備', '出資業務規程（令和3年3月31日 規程令和第3-17号、令和3年4月1日施行）が科学技術・イノベーション活性化法第34条の6に基づく出資等を定める。第4条が出資対象の法人形態（株式会社、合同会社、投資事業有限責任組合、国立大学法人、学校法人等）と十分な社会的信用を要件とし、第11条が出資契約、第12条が株主間契約、第16条が利益相反マネジメント規程（規程第26-12号）による管理を定める。運用は直接出資（1号）、ベンチャーキャピタルファンドへの間接出資（2号）、成果活用等支援法人（3号）の3類型。2024年3月に文部科学大臣認可を経てFrontier Innovations 1号ファンドへアンカーLPとして出資し、研究開発法人では初の間接出資となった。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2022/04/%E5%8F%82%E8%80%83%E8%B3%87%E6%96%99%E4%B8%80%E5%BC%8F.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_regulation_owner', 'established', '研究機関規程（JAXAスタートアップ支援規程）', '国立研究開発法人宇宙航空研究開発機構が自ら定める機構規程が根拠。JAXAパートナースタートアップ支援約款第1条は「本約款は、国立研究開発法人宇宙航空研究開発機構が定めるJAXAスタートアップ支援規程に基づき実施するスタートアップへの支援に関し」と規定し、第2条第1号・第2号が同規程第6条の許可要件と第7条の名称使用許可を引用する。旧制度も機構規程で、JAXAベンチャー支援規程（平成16年3月16日 規程第16-19号、令和3年3月31日 規程令和第3-20号改正）。出資は出資業務規程（規程令和第3-17号）。大学規程・学校法人規程ではない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_review_body', 'established', '新事業促進部、認定審査の委員会は廃止', '2025年8月28日の制度改正で事業計画の綿密な審査と認定制度を廃止し、要件に適合する企業へ名称を付与する方式へ移行した。約款は「国立研究開発法人宇宙航空研究開発機構 新事業促進部長」名義で、申請窓口は新事業促進部の問い合わせフォーム。旧JAXAベンチャー支援規程では第6条の委員会（委員長は新事業促進部長、委員は同部長が指名、機構内有識者1名以上の意見聴取）が審査し、第7条で新事業促進部担当理事が認定を決定していた。現行のJAXAスタートアップ支援規程は非公開で、名称使用許可の機構内決裁者は確認できない。出資は出資委員会と出資審査会が審議する。', 'official', 'https://www.jaxa.jp/press/2025/08/20250828-1_j.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_equity_decider', 'established', '理事長（出資委員会の審議と理事会議の審議を経る）', '出資業務規程第5条第1項は、理事長が出資委員会の審議の結果を踏まえ、出資先の選定と出資条件その他の出資の実施に必要となる事項を決定すると規定する。第2項は機構が保有する株式等の処分と株主の権利の行使に関する事項も理事長が決定するとし、第3項はこれらの決定に当たり理事会議の審議を経ること、新事業促進部担当理事が出資統括者からの報告を踏まえ理事会議に附議することを定める。第15条は株式等の処分を理事長が行うとする。出資統括者は新事業促進部担当理事（第6条）、出資管理者は新事業促進部長（第7条）。出資委員会は外部有識者4名以内と機構役職員1名で構成（出資委員会設置規程第4条）。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2022/04/%E5%8F%82%E8%80%83%E8%B3%87%E6%96%99%E4%B8%80%E5%BC%8F.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_amendment_decider', 'established', '機構が約款を単独変更、規程の改廃決裁者は非公開', '約款第17条第1項は、変更が被支援会社の一般の利益に適合すると認められる場合、又は支援の目的に反せず変更の必要性・変更後の内容の相当性・被支援会社に与える不利益の内容と程度等に照らし合理的と認められる場合に、機構が被支援会社の個別の承諾を得ることなく約款の内容を変更できると規定する。第2項は効力発生日の相当期間前までに変更後の内容と効力発生日を適切な方法で周知すること、第3項は周知された効力発生日から適用されることを定める。約款の名義は新事業促進部長。JAXAスタートアップ支援規程本体の制定改廃の決裁者は、同規程が非公開でJAXAの規程公開ページにも掲載がないため確認できない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_post_grad_limit', 'established', '規定なし。在職職員の取締役関与が要件', 'JAXAスタートアップの要件は、機構の知的財産又は業務により獲得した知見を利用した製品・サービスの市場提供を主たる事業とし、当該知財・知見に必要な知識を有するJAXA職員が取締役（合同会社は業務執行社員）として経営に関与することで、在職中の関与を前提とする。退職後何年以内の起業を対象とするかという期限の定めは、2025年8月28日のプレスリリースにも約款にもない。JAXAパートナースタートアップは職員の関与を要件とせず、共創・共同研究成果の活用、特許の許諾契約、開発機器の譲受け、事業移管のいずれかを主たる事業とすることを要件とするため、退職後の期限という概念自体がない。学生・卒業生の区分もない。', 'official', 'https://www.jaxa.jp/press/2025/08/20250828-1_j.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_renewal_rule', 'established', '更新可（届出のみ）。不延長通知がなければ自動延長', '約款第5条第2項は、支援期間満了の1か月前までに機構又は被支援会社のいずれかが書面により支援期間を延長しない旨の通知を行わない限り、支援期間は1年間自動的に延長され以後も同様と定める。更新のための申請書提出や再審査を課す条文はなく、被支援会社の側から手続を要しない自動更新であり、延長を止めるときにのみ書面の通知が要る。第3項により延長後の期間は名称使用許可の日から10年、又は被支援会社の設立から10年（休業期間を証明できる場合はその期間を加算）を超えない。上限到達後の再申請に関する定めは約款にない。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_naming', 'established', '独自名称。JAXAスタートアップ／同パートナー', '称号は「JAXAスタートアップ」と「JAXAパートナースタートアップ」の2区分。約款第6条第1項は後者の英語表記を「JAXA Partner Startup」とし、別添1に「JAXAパートナースタートアップシンボルロゴマーク」を掲げる。大学発ベンチャー・大学発スタートアップという呼称は用いない。2025年8月28日の改正前の称号は「JAXAベンチャー」（旧JAXAベンチャー支援規程第2条第3号が第7条に基づき機構が認定した会社と定義）で、改正により名称と付与方式の双方が変わった。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_support_period', 'established', '称号期間と同じ。名称使用許可の日から起算', '約款第5条第1項は支援期間を名称の使用許可の日より1年間と定め、称号の期間と支援の期間を同一の起算点・同一の長さで運用する。第5条第4項は第12条により名称使用許可を取り消したときはその時点で支援期間が終了すると規定し、称号が消えれば支援も終わる構造になっている。支援措置ごとに別の期間を定める条文はない。ただし試験設備等供用と知的財産の実施許諾は本制度の外の別契約であり、それぞれ設備等利用承諾書・契約書や実施契約で期間が定まる。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_support_contents', 'established', '情報提供・推薦・資金調達支援・投資家対応・販路開拓・専門家紹介・広報支援', '約款第7条第1項第1号が支援措置を列挙する。行政および外部提携機関による各種スタートアップ支援策に関する情報提供およびこれらへの推薦、資金調達支援、投資家による技術的質問への対応、販売販路および提携企業開拓支援、専門家の紹介、会社経営に関するセミナーについての情報の提供、広報支援。第2号はその他各種相談事項への対応。第2項によりこれらは無償で提供され、被支援会社の求めにより機構が別途専門家等に依頼した場合の実費のみ被支援会社の負担。別制度として宇宙イノベーションパートナーシップ（J-SPARC）、試験設備等供用、知的財産の実施許諾、出資がある。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_dba93faa0485', 'attr_source_docs', 'established', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf・https://www.jaxa.jp/press/…', '1本目はJAXAパートナースタートアップ支援約款（文書番号25宇航新事業0912001、全19条＋別添1、新事業促進部長名義）で、支援期間、名称の使用、支援措置と対価、報告・調査、通知義務、解除事由、存続条項、約款の内容変更を定める現行の中核文書。2本目は2025年8月28日のプレスリリースで、認定制度の廃止と名称使用許可制への移行、2区分の定義、認定をしない旨を示す。3本目は出資関連の参考資料一式で、出資業務規程、出資委員会設置規程、出資審査会設置規程、旧JAXAベンチャー支援規程と申請様式を収録する。JAXAスタートアップ支援規程の本体は非公開。', 'official', 'https://aerospacebiz.jaxa.jp/wp-content/uploads/2025/10/b8420f34c6336cc226e3bb69f68012ee.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_cert_update', 'established', '認定期間原則5年、制度全体で最長10年', '2009年5月29日機構プレスリリース脚注に「認定期間は原則5年間」と明記。令和6年度業務実績等報告書（項目別-132）は「最長10年間の支援制度として、平成17年度にスタートをした」とし、同（項目別-134）は令和6年度改正で「５年目を事業性・成長性評価の一つの区切りとし、新株予約権を行使するか放棄するか決定するものとしている」と記載。認定企業一覧では株式会社フォーキャスト・オーシャン・プラスが2009年6月1日認定・2019年3月31日満了で5年を超えて継続している。更新審査の手続や要件再確認の条項は、規程本文が非公開のため確認できない。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_title_restriction', 'unknown', null, '称号「JAMSTECベンチャー」の使用範囲、品質保証・投資推奨・経営状態保証と誤認させないための条項、使用停止に関する記載は、知的財産情報「JAMSTECベンチャーの紹介」、2009年5月29日機構プレスリリース脚注、令和6年度業務実績等報告書、令和6年度事業報告書のいずれにもない。JAMSTECベンチャー支援規程の条文は公開されておらず、称号の対外使用は認定企業一覧の掲載とニュース告知という運用として確認できるにとどまる。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_cancellation', 'unknown', null, '取消事由、称号の返付、表示削除、営業利用の停止に関する記載は公開文書にない。知的財産情報ページの認定企業一覧は「認定満了日」欄を持ち、株式会社オーシャンアイズ2023年11月24日、株式会社フォーキャスト・オーシャン・プラス2019年3月31日を掲載しており、期間満了による終了は運用されている。ただし期間満了と取消の区別、取消後の処理を定めた条文は、規程本文が非公開のため確認できない。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_report_change', 'unknown', null, '年次報告、代表者・所在地・資本構成の変更届、解散時報告に関する記載は、知的財産情報ページ、2009年5月29日機構プレスリリース、令和6年度業務実績等報告書、令和6年度事業報告書、業務方法書のいずれにもない。令和6年度業務実績等報告書（項目別-134）は5年目に事業性・成長性を評価するとしているが、機構側の評価時点の記述であり、認定企業に課される報告義務としては書かれていない。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_support_request', 'established', '支援は申請ベース、施設は課題選定と使用契約', '知的財産情報「JAMSTECベンチャー制度」に「認定とともに、申請に基づく各種支援内容（実施許諾における優遇措置、研究施設等の利用における優遇措置等）により事業活動を一定期間支援していくものです」とあり、支援内容が申請に基づくことが明示される。施設は業務方法書第21条が共用課題の選定を、第22条が「機構以外の者が共用施設等を利用する場合には、共用する者との間に、共用施設等の使用契約を締結するものとする」と定める。認定と別立ての審査体の明文は非公開。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_facility_registration', 'established', '共用実験設備の使用料優遇、本店登記は実例のみ', '「特定共用施設の外部共用について」はJAMSTECベンチャー認定企業が事業実施を目的に使用する場合の使用料優遇を定め、機構と使用者の間で使用契約を締結するとする。起業用の居室やインキュベーション施設の貸与を示す記載はない。商業登記は、JAMSTECニュース2018年5月10日が合同会社オフショアテクノロジーズの本店を「神奈川県横浜市金沢区昭和町3173-25」と公表し、機構横浜研究所の所在地と一致する実例があるが、登記受入れを定めた規程は確認できない。', 'official', 'https://www.jamstec.go.jp/j/about/equipment/yokosuka/faci.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_vc_connection', 'unknown', null, '中長期計画（18頁）は「支援にあたっては、専門機関・企業等との協業によりスタートアップ支援エコシステムを構築し、相談段階から起業化までのワンストップの伴走支援により」と記載し、令和6年度業務実績等報告書（項目別-134）は対外戦略課が外部専門家と共に資金計画の精査を行ったとする。ただしベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介を制度として定めた記載は確認できない。産業連携ページの連携メニュー10項目にも紹介導線はない。', 'official', 'https://www.jamstec.go.jp/j/about/project/pdf/keikaku2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_eir', 'unknown', null, '客員起業家（EIR）、起業家メンター、起業家人材の招聘制度を示す記載は、中長期計画、令和6年度業務実績等報告書、令和6年度事業報告書、産業連携ページのいずれにもない。中長期計画と業務方法書第26条が定める「人的及び技術的援助」は、機構から成果活用事業者に対する援助であり、外部の起業家を機構へ招く制度ではない。役職員向けの施策は「アントレプレナーシップ養成塾」セミナーの開催と実践講習の予定にとどまる。', 'official', 'https://www.jamstec.go.jp/j/about/project/pdf/keikaku2026.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO/CXO候補）の人材プールや紹介・マッチング制度を示す記載は公開文書にない。令和6年度業務実績等報告書（項目別-134）は、対外戦略課が中心となり外部専門家と共に将来的な出口戦略も視野に入れた資金計画の精査を行い、機構初となるスタートアップ型ビジネスプランの策定に至ったとするが、経営人材の紹介ではなく事業計画づくりの伴走支援として記述されている。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_ip_equity', 'established', '支援の対価に新株予約権、知財の現物出資も可', '令和6年度業務実績等報告書（項目別-134）に「JAMSTECベンチャー認定の要件の１つに『ベンチャーが機構に対し新株予約権を付与すること』を新設」「５年目を事業性・成長性評価の一つの区切りとし、新株予約権を行使するか放棄するか決定する」制度への規程改正を実施と記載。同（項目別-156）も「認定し支援する条件として、機構に新株予約権を発行し、将来的な株主になる選択肢を付与すること」とする。業務方法書第26条は知的財産権の出資を認める。実施許諾単独の対価を株式とする明文はない。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'pol_fund_investment', 'established', '活性化法に基づく機構の直接出資（業務方法書26条）', '業務方法書第26条（出資並びに人的及び技術的援助の方法）が「機構の研究開発成果を事業活動において活用し、又は活用しようとする者のうち適当であると認められる者に対し、金銭若しくは機構の所有する知的財産権若しくは設備を出資し、又は人的若しくは技術的援助を実施することができる」「出資により取得した株式を処分することが適当であると認められるときは、その全部又は一部を処分することができる」と定める。中長期計画も活性化法に基づく出資を明記。ファンド組成やLP出資の記載はない。', 'official', 'https://www.jamstec.go.jp/j/about/disclosure/data/gyoumuhouhousho.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_regulation_owner', 'established', '研究機関規程（国立研究開発法人の内部規程）', '2009年5月29日機構プレスリリース本文が「当機構は、JAMSTECベンチャー支援規程に基づき、平成18年6月1日付で海流予測LLPをJAMSTECベンチャー第1号として認定しました」と記し、根拠規程が国立研究開発法人海洋研究開発機構の内部規程であることを示す。同脚注は平成18年4月25日発足とする。令和6年度業務実績等報告書も令和6年度に同制度の規程改正を実施したと記載。大学規程・学校法人規程には該当しない。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_review_body', 'unknown', null, '認定委員会や審査会の正式名称を示す公開文書は確認できない。令和6年度業務実績等報告書（項目別-134）は伴走支援について「対外戦略課が中心となり、外部専門家と共に」事業性の評価と資金計画の精査を行ったとする。知的財産ポリシー4.は知的財産管理・活用の担当部門を「イノベーション・事業推進部イノベーション推進課」と明示。2009年プレスリリースの認定に関する問合せ先は事業推進部推進課。いずれも事務担当の記載であり、審査主体や決裁体制の記載ではない。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_equity_decider', 'unknown', null, '業務方法書第26条は出資と取得株式の処分の主語をいずれも「機構」とし、決裁権者や決裁手続を定めていない。令和6年度業務実績等報告書は新株予約権の付与を認定要件に加えたことと、5年目に行使か放棄かを決定する制度としたことを記すが、決定主体は書かれていない。理事長、理事会、委員会のいずれが決裁するかを示す公開文書は確認できなかった。', 'official', 'https://www.jamstec.go.jp/j/about/disclosure/data/gyoumuhouhousho.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_amendment_decider', 'unknown', null, 'JAMSTECベンチャー支援規程の制定改廃を決める主体を示す公開文書は確認できない。令和6年度業務実績等報告書（項目別-134、156）は令和6年度に「制度に規程改正を実施した」「新たな制度を規程に盛り込む改正を行った」と記すのみで、決裁主体の記載がない。業務方法書は独立行政法人通則法第28条第1項に基づくもので文部科学大臣の認可を要するが、これは業務方法書自体の手続であり、内部規程の改廃手続ではない。', 'official', 'https://www.jamstec.go.jp/j/about/research_assessment/pdf/r6_eval_rep.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_post_grad_limit', 'unknown', null, '対象要件は2009年5月29日機構プレスリリース脚注の「機構の知的財産を活用して事業を行うベンチャー企業等（ただし、設立中又は設立後5年以内のものに限る）」であり、企業の設立後年数で線を引いている。起業する研究者本人が退職後何年以内かを定めた記載は公開文書にない。国立研究開発法人であり学生・卒業生の区分もない。規程本文が非公開のため、退職後期限の規定の有無自体を確認できない。', 'official', 'https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_renewal_rule', 'unknown', null, '更新の可否と方法を定めた条文は公開されていない。認定期間は原則5年（2009年プレスリリース脚注）だが、令和6年度業務実績等報告書（項目別-132）は制度全体を「最長10年間の支援制度」と説明し、知的財産情報ページの一覧では株式会社フォーキャスト・オーシャン・プラスが2009年6月1日認定・2019年3月31日満了で5年を超えて継続している。延長または更新の運用は実在するが、審査を伴うのか届出のみかは確認できない。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_naming', 'established', '独自名称「JAMSTECベンチャー」', '知的財産情報ページは「JAMSTECベンチャーとは、JAMSTECの知的財産を活用して事業活動を行う企業又は個人等の申請に基づき、JAMSTECベンチャーとして認定を受けた企業です」と定義し、表の見出しも「JAMSTECベンチャー認定企業一覧」。JAMSTECニュース2018年5月10日も「JAMSTECベンチャーとして認定されました」と告知する。大学発ベンチャー、大学発スタートアップの呼称は用いていない。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_support_period', 'established', '称号期間と同じ（施設使用は別途使用契約）', '知的財産情報「JAMSTECベンチャー制度」に「認定とともに、申請に基づく各種支援内容（実施許諾における優遇措置、研究施設等の利用における優遇措置等）により事業活動を一定期間支援していくものです」とあり、認定と支援を一体で一定期間とする。認定期間は原則5年、制度全体で最長10年。ただし特定共用施設の使用は業務方法書第22条により機構と使用者の間で個別に使用契約を締結するため、施設支援の実施期間は契約ごとに定まる。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_support_contents', 'established', '実施許諾優遇・施設使用料減免・伴走支援・養成塾・出資', '知的財産情報ページは支援内容を「実施許諾における優遇措置、研究施設等の利用における優遇措置等」とする。2009年プレスリリース脚注は「知的財産に対する実施等許諾権の優遇」「研究施設等の使用料減免　など」を列挙。特定共用施設ページは認定企業の基本使用料を50%または無償とする。令和6年度業務実績等報告書はワンストップ伴走支援の強化と「アントレプレナーシップ養成塾」セミナーを記載。中長期計画は活性化法に基づく出資並びに人的及び技術的援助を掲げる。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d161837b6c47', 'attr_source_docs', 'established', 'https://www.jamstec.go.jp/ip/j/venture.html・https://www.jamstec.go.jp/j/about/press_release/archive/2009/20090529_2.pdf…', '制度の骨格はこの3点で読める。知的財産情報「JAMSTECベンチャーの紹介」は定義、支援内容、認定企業一覧と認定満了日。2009年5月29日機構プレスリリース脚注は根拠規程名、対象、認定期間原則5年、優遇措置、平成18年4月25日発足。令和6年度業務実績等報告書（項目別-132〜134、156）は最長10年、令和6年度の規程改正と新株予約権付与要件、伴走支援、養成塾。補助として業務方法書第26条（出資）と中長期計画18頁。', 'official', 'https://www.jamstec.go.jp/ip/j/venture.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_cert_update', 'established', '有効期間の定めなし、毎年6月末の活動報告で継続確認', '取扱要領に認定（支援決定）の有効期間・更新・更新審査の規定は無い。第9条で支援決定を受けた企業に毎年6月末日までの活動内容報告書の提出を義務づけ、第10条で届出事項の変更や解散・破産・再生・更生・罰金刑確定・訴訟関与・第4条抵触の報告を義務づけ、第11条で定義からの著しい逸脱、社会的信用の失墜、名誉毀損のおそれ、企業活動実態の消滅、本人からの申出等の場合に機構長が支援決定を取り消せると定める。要件の再確認は年次報告と取消規定で担保する設計で、期間を区切った更新審査は置かない。期間の定めがあるのは第3条第1項第3号の学内本店登記のみ。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_title_restriction', 'not_started', '称号の使用範囲・誤認防止・使用停止の条項なし', '取扱要領全13条、支援申請書、活動内容報告書の様式を通読したが、「宮崎大学発ベンチャー」の称号について、大学が品質や経営状態を保証するものではない旨の注意書き、投資推奨と誤認させない条項、使用できる媒体や範囲の限定、使用停止の手続を定めた条項は無い。第3条第1項第1号は称号を称することを認めるとだけ規定し、第3条第2項は支援によって生じた損失及び損害に大学が法的責任を負わない旨の免責規定で、第三者の誤認を防ぐ条項ではない。活動内容報告書はパンフレット・名刺・企業ホームページ・プレスリリース・製品外装への使用状況を事後報告させるにとどまる。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_cancellation', 'established', '取消事由6項目を規定、取消後の措置は規定なし', '要領第11条で、(1)第2条の定義から著しく逸脱、(2)本学の社会的信用を失墜する行為、(3)本学の名誉が傷つけられた又はそのおそれ、(4)企業活動の実態がなくなった、(5)企業からの取消しの申出、(6)その他支援継続が適当でないと機構長が認めた場合のいずれかで、機構長が支援の決定を取り消せると規定。取消しの主体は機構長で、支援を決定する第7条の連携推進会議とは別建て。称号の返付、名刺・パンフレット・製品外装等からの表示削除、営業利用の停止といった取消後の措置は、要領にも申請書にも定めが無い。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_report_change', 'established', '毎年6月末の活動報告、変更・解散等は速やかに報告', '要領第9条で支援決定企業に毎年6月末日までの活動内容報告書の提出を義務づけ、様式は企業名・ホームページ・連絡先・認定日・主な活動内容・称号の使用状況を記載する。第10条第1項で届出事項に変更等があった場合の速やかな報告、第2項で会社法の解散、破産宣告、民事再生手続、会社更生手続、不正競争防止法の罰金刑確定、訴訟当事者としての紛争関与、第4条抵触の報告を義務づける。申請書の記載事項は企業名・設立年月日・代表者・企業形態・住所連絡先・主な事業・大学の関与・大学関係者で、資本構成の欄は無い。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_support_request', 'established', '支援申請書1通で申請、施設利用等は別途所要の手続き', '要領第5条第1項で支援を受けようとする者は別紙の申請書により機構長に申請、第6条で機構長が可否を判定、第7条で連携推進会議が審議・決定し機構長が書面で通知する。認定と支援は分かれておらず、支援申請書1通で称号使用の希望、施設利用（研究スペース・事務所スペース）、大学住所での登記希望を選択する。第5条第2項で施設利用・登記住所・その他の支援は本要領の手続のほか関係規則等の所要の手続によるとされ、施設利用申請者は各施設の利用規程の遵守を申請時に誓約する。施設利用希望は申請前に当該部局長の了承が必要。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/mediafile/venture_request.docx', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_facility_registration', 'established', '施設利用の承認を前提に最大3年＋2年の学内登記可', '要領第3条第1項第2号で共同研究や技術指導を受けた研究、研究成果や習得技術の事業化を行う場合に本学施設の利用等を認め、第3号でその場合に最大3年間、登記の住所を当該施設の住所とすることを認める（企業の申出があり機構長が適当と認めれば更に2年を限度に延長）。受け皿は研究・産学地域連携推進施設利用規程で、第2条第8号「大学発ベンチャーの研究及びそのオフィス業務」を利用範囲、第3条第5号「大学発ベンチャーの役職員」を利用者資格に明記。第4条で機構長への利用申請と承認、第8条で承認の取消し、第11条で使用料と1か月以上利用時の光熱水費実費を負担。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-6.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_vc_connection', 'unknown', null, '取扱要領第3条第1項の支援は称号使用、施設利用、学内本店登記、機構による起業・起業後経営の相談業務、その他機構長が必要と認める支援で、ベンチャーキャピタル、金融機関、自治体、外部支援機関への紹介は挙がっていない。機構規則第3条第4項が定める産学・地域連携部門の業務にも、金融機関との連携や資金調達支援の号は無い。産学共創会議は県内企業の会員組織で紹介制度の記載が無く、大学の研究・産学官連携ポータルにも該当ページが無い。第3条第1項第5号の包括条項があるため制度が無いとは断定しない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_eir', 'unknown', null, '取扱要領、機構規則、公開規程集（令和6年10月10日現在）、機構および産学・地域連携部門のサイトのいずれにも、客員起業家（EIR）、起業家メンター、起業家人材の招聘に関する規定やプログラムは見当たらない。機構規則第3条第4項が定める産学・地域連携部門の業務は、広報と企画立案、共同研究・受託研究の推進、大学発ベンチャーの育成及び支援、情報提供、技術相談・技術指導・研修、共同研究等の推進で、起業家人材の招聘は含まれない。推進施設利用規程第3条第2号の「機構の客員教授等」は施設の利用者資格の区分で、起業家招聘制度ではない。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_cxo_pool', 'unknown', null, '経営人材（CEO・CXO候補）の人材プールや紹介・マッチングを定めた規定は、取扱要領、機構規則、公開規程集、機構サイトのいずれにも見当たらない。要領第3条第1項第4号の支援は「研究・産学地域連携推進機構が起業や起業後の経営等について相談業務にあたること」で、相談にとどまり人材の紹介までは含まない。支援申請書の様式も「8.宮崎大学の関係者」で学内の関与者と兼任している役職名を記入させる欄があるだけで、外部の経営人材を想定した欄は無い。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', 'ライセンス等の対価として取得する株式等取扱規程（平成29年1月26日制定、令和4年10月1日改正施行）第1条で、知的財産権の譲渡・提供・実施許諾等の対価を現金に代えて株式等で取得する場合の取扱いを定め、第2条第4号で株式等を株式及び新株予約権、第5号で大学発ベンチャー企業を職務発明等の事業化を目的として起業された会社と定義。第3条で現金を保有していない等4事由のいずれかに該当するとき対価の一部又は全部を株式等で取得できる。第5条で新株予約権は行使可能次第行使、第6条で議決権は原則不行使、第8条で換金可能になり次第売却。職務発明等規程第18条は優先ライセンス・条件優遇・権利譲渡を認める。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-5-52.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'pol_fund_investment', 'established', '基本規則に出資業務の規定、個別の出資規程はなし', '国立大学法人宮崎大学基本規則第5条（業務の範囲）第6号から第9号で、施設・設備・知的基盤の利用促進事業を実施する者への出資、国立大学法人法施行令第3条第1項の研究成果活用事業者への出資、同条第2項の技術に関する研究成果の活用促進事業者への出資、産業競争力強化法第21条の規定による出資並びに人的及び技術的援助を業務として規定する。ただし出資の手続・対象・決裁を定める個別規程、大学ベンチャーキャピタル、認定VCやファンドへの出資は、公開規程集（令和6年10月10日現在）と機構サイトに無い。取扱要領第2条第4号は本学の出資・出資斡旋を認定要件の一つに挙げるにとどまる。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/kihonkisoku.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_regulation_owner', 'established', '大学規程（国立大学法人宮崎大学の取扱要領）', '「国立大学法人宮崎大学における大学発ベンチャーの取扱要領」（平成30年2月14日決定、同日実施）が認定と支援の根拠で、主体は国立大学法人宮崎大学。学校法人や外部の研究機関の規程ではない。要領は公開規程集（国立大学法人宮崎大学規程集、令和6年10月10日現在）には収載されておらず、研究・産学地域連携推進機構 産学・地域連携部門の「宮崎大学発ベンチャー企業」ページに全13条と附則が掲載されている。実施規程である推進施設利用規程や株式等取扱規程は規程集に収載。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_review_body', 'established', '宮崎大学研究・産学地域連携推進会議（議長は機構長）', '要領第6条で研究・産学地域連携推進機構長が支援の可否を判定し、第7条第1項で研究・産学地域連携推進会議が審議・決定、第2項で機構長が書面で通知する。連携推進会議は機構規則第15条に基づき置かれ、推進会議規程第3条で機構長、副機構長、機構長補佐、部門長、専任教員、教育学部・医学部・農学部・地域資源創成学部・工学教育研究部の教授又は准教授各1人等で組織、第4条で議長は機構長、第5条で委員の3分の2以上の出席で成立し出席委員の過半数で決する。事務は第8条で機構事務部産学・地域連携課。認定審査専用の委員会は置いていない。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/8-2-2.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_equity_decider', 'established', '学長（機構長への諮問を経て取得の可否を決定）', '株式等取扱規程第4条第1項で、学長は大学発ベンチャー企業からライセンス等の対価として株式等による支払いの申込みを受けたとき、当該会社の財務状況その他取得の妥当性の判断に必要な事項について研究・産学地域連携推進機構長に諮問したうえで、取得の可否を決定すると規定。第2項で適当と判断したとき法人が契約を締結して取得、第3項で不適当なら取得しない。第3条第1項第4号と第2項第3号でも学長の判断を要件に置く。処分は第8条で換金可能になり次第売却、第9条で収入から必要経費を控除した額の50%を発明者等が請求可能。事務は第13条で財務部財務課。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-5-52.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_amendment_decider', 'unknown', null, '取扱要領には制定改廃の決裁者を定めた条項が無い。第13条第1項は「本要領に定めるもののほか、大学発ベンチャーの支援に関し必要な事項は、研究・産学地域連携推進機構長が別に定める」と補足事項の委任を定めるにとどまり、要領自体の改廃には触れない。附則は平成30年2月14日から実施することと、施行時に既に認められている企業を支援決定済みとみなすことのみ。役員会規程第2条の議決事項にも規則等の制定改廃は挙がらず、基本規則にも規則等の制定手続の条項は見当たらない。要領の頭書は「平成30年2月14日決定」で決定主体を記していない。', 'official', 'https://www.miyazaki-u.ac.jp/kitei/gakugai/koukaikitei/2-1-1.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_post_grad_limit', 'established', '1年以内（退職・卒業から起業までの期間）', '要領第2条第3号のただし書に「本学の教職員等が退職、卒業等した後に起業をする場合、退職及び卒業等から起業までの期間が1年以内のものに限る」と規定し、支援申請書の「7.宮崎大学の関与」3)にも同じ文言がある。第2条第2項で、本学の職務又は本学で得た知識・経験等から著しく離れて発想した技術やアイデアに基づく起業は第1号から第3号に該当しないとして除く。なお第4号（本学の出資・出資斡旋）と第5号（機構長が認めたもの）には退職後の期間制限が付いていない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_renewal_rule', 'established', '期限なし（更新の規定はなく年次報告で継続確認）', '取扱要領に認定（支援決定）の有効期間、更新、再申請の規定は無く、第9条の毎年6月末日までの活動内容報告書と第11条の取消事由で継続を管理する。活動内容報告書の様式には「宮崎大学発ベンチャー認定日」欄があり、有効期限や更新申請の欄は無い。期間を区切っているのは第3条第1項第3号の学内本店登記だけで、最大3年、企業の申出があり機構長が適当と認める場合に更に2年を限度として延長できる。この延長は称号の更新ではなく登記住所の利用期間の延長。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_naming', 'established', '大学発ベンチャー（称号は「宮崎大学発ベンチャー」）', '要領の題名が「国立大学法人宮崎大学における大学発ベンチャーの取扱要領」、第2条が「大学発ベンチャー」を定義し、第3条第1項第1号で「宮崎大学発ベンチャー」と称することを認めると規定する。スタートアップの語は要領、支援申請書、活動内容報告書のいずれにも使われていない。公表ページの見出しと企業一覧の表記は「宮崎大学発ベンチャー企業」で、要領本文の「宮崎大学発ベンチャー」と語尾が一致しない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_support_period', 'established', '支援ごとに別に定める（登記は最大3年＋2年）', '称号使用（第3条第1項第1号）には期間の定めが無く、施設利用（第2号）は各施設が定める利用規程によるとされ、推進施設利用規程も第4条の利用申請と第5条の承認で扱い規程本体に期限を置かない。学内本店登記（第3号）だけが最大3年、機構長が適当と認めれば更に2年という上限を持ち、支援申請書にも「大学施設の住所を登記に使用する期限は、原則、採択後最大3年間」と明記されている。称号期間と支援期間を一括して定める条項は無く、支援の種類ごとに扱いが分かれる。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_support_contents', 'established', '称号使用・施設利用・学内登記最大3年＋2年・起業と経営の相談・その他', '要領第3条第1項各号: (1)「宮崎大学発ベンチャー」と称することを認める、(2)本学教職員との共同研究若しくは技術指導等を受けて研究を実施する場合、研究成果の事業化を行う場合、習得した技術若しくは手法等に基づいて事業化を行う場合に本学施設の利用等を認める、(3)前号の場合に最大3年間（機構長が適当と認めれば更に2年）登記の住所を当該施設の住所とすることを認める、(4)機構が起業や起業後の経営等について相談業務にあたる、(5)その他機構長が必要と認める支援。ただし書で支援内容に応じ一定の対価等を要求でき、第2項で支援により生じた損失及び損害に法的責任を負わない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_d86b5f801c06', 'attr_source_docs', 'established', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html・https://www.miyazaki-u.ac.jp/kscrs/sangaku/mediafile/ve…', '取扱要領の全13条と附則、認定企業一覧は産学・地域連携部門の「宮崎大学発ベンチャー企業」ページに掲載。支援申請書のWordファイルには申請様式と活動内容報告書の様式が同梱され、登記住所の期限や施設利用の遵守事項も記載されている。国立大学法人宮崎大学規程集（令和6年10月10日現在）には職務発明等規程、株式等取扱規程、推進施設利用規程、職員兼業規程、利益相反マネジメント規程、機構規則、連携推進会議規程が収載されているが、要領そのものは収載されていない。', 'official', 'https://www.miyazaki-u.ac.jp/kscrs/sangaku/activity/post-1.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910')
